  @override
  String get synthetic_cannabinoidsWithdrawalReference =>
      'การถอนแคนนาบินอยด์สังเคราะห์\n\nแหล่งที่มา: Craft และคณะ (2022), Psychopharmacology, PMC\n\nจากผู้เข้าร่วม 284 คนที่ใช้สารกระตุ้นตัวรับแคนนาบินอยด์สังเคราะห์มากกว่าสิบครั้งในปีก่อนและเคยพยายามหยุด 82.7% รายงานอาการถอนอย่างน้อยหนึ่งอย่างหลังหยุดใช้เกินหนึ่งวัน อาการที่พบบ่อยที่สุดคือปัญหาการนอน (59.2%) หงุดหงิด (55.6%) และอารมณ์ตก (54.2%) รวมทั้งมีรายงานเหงื่อออก ใจสั่น ความอยากใช้ กระสับกระส่าย และสั่น การใช้บ่อยและมากสัมพันธ์กับจำนวนอาการที่มากขึ้น และเมื่อเปรียบเทียบโดยตรง ผู้เข้าร่วมประเมินว่าการถอนแคนนาบินอยด์สังเคราะห์รุนแรงกว่าการถอนกัญชาฤทธิ์สูง';

  @override
  String get synthetic_cannabinoidsRiskReference =>
      'การถอนและความเสี่ยงเฉียบพลันของแคนนาบินอยด์สังเคราะห์\n\nแหล่งที่มา: Cooper (2016), Current Psychiatry Reports, PMC\n\nรายงานทางคลินิกอธิบายอาการถอนหลังใช้ทุกวันที่อาจเริ่มไม่นานหลังโดสสุดท้าย เช่น วิตกกังวลรุนแรง นอนไม่หลับ คลื่นไส้อาเจียน เหงื่อออก ใจสั่น สั่น กระสับกระส่าย และอยากใช้ กรณีรุนแรงมีทั้งอาการชักซ้ำและปัญหาหัวใจหลอดเลือดหรือการหายใจ บททบทวนยังอธิบายภาวะพิษที่คาดเดาได้ยากและบางครั้งรุนแรง เช่น โรคจิต อาการชัก เหตุการณ์ทางหัวใจ และไตบาดเจ็บ อาการรุนแรงหรือแย่ลงต้องได้รับการประเมินทางการแพทย์อย่างรวดเร็ว';

