  @override
  String get synthetic_cannabinoidsLongTermReference =>
      'แคนนาบินอยด์สังเคราะห์: สิ่งที่หลักฐานรองรับ\n\nแหล่งข้อมูล: แนวทางฉันทามติของ British Association for Psychopharmacology ว่าด้วยการพึ่งพาสาร (2026), PMC\n\nแนวทางระบุว่าแคนนาบินอยด์สังเคราะห์อาจทำให้เกิดอาการถอนที่รุนแรงกว่ากัญชา และบางกรณีอาจต้องล้างพิษแบบผู้ป่วยใน นอกจากนี้ยังระบุว่ายังไม่มีเภสัชบำบัดที่มีหลักฐานรองรับสำหรับการรักษาระยะคงสภาพหรือการป้องกันการกลับไปใช้ซ้ำ\n\nแนวทางไม่ได้กำหนดว่า 2, 3, 4 หรือ 5 ปีเป็นเกณฑ์การฟื้นตัวทางชีวภาพ ดังนั้นหมุดหมายเหล่านี้จึงใช้เพื่อฉลองความก้าวหน้าที่ยั่งยืน โดยไม่อ้างเส้นตายทางการแพทย์ที่หลักฐานไม่ได้รองรับ';

