      'เลือดของคุณกำลังหายใจอีกครั้ง!ภายใน 24 ชั่วโมง ระดับคาร์บอนมอนอกไซด์จะลดลงสู่ระดับปกติและระดับออกซิเจนจะเพิ่มขึ้นหัวใจของคุณไม่จำเป็นต้องทำงานล่วงเวลาเพื่อสูบฉีดเลือดที่เป็นพิษไปทั่วร่างกายอีกต่อไป';

  @override
  String get smokingMilestone3Title => 'อาการถอนนิโคตินถึงจุดสูงสุด';

  @override
