  @override
  String get smokingMilestone180Description =>
      'หกเดือนปลอดบุหรี่คือชัยชนะที่ชัดเจนของภูมิคุ้มกันปอด ในการศึกษาระหว่างการผ่าตัด การตอบสนองต้านแบคทีเรียของแมคโครฟาจถุงลมหลังเลิกบุหรี่ 3–12 เดือนใกล้เคียงกับรูปแบบของผู้ไม่เคยสูบมากกว่าตอนเลิกได้สองเดือน เซลล์ด่านหน้าของปอดมีเวลาหลายเดือนในการฟื้นตัว';

  @override
  String get smokingMilestone365Title => 'ความเสี่ยงโรคหลอดเลือดสมองลดลง';

  @override
