      'อาการถอนนิโคตินมักถึงจุดสูงสุดราววันที่สาม แล้วค่อย ๆ ลดลงในช่วง 3–4 สัปดาห์ถัดไป คุณขึ้นมาถึงยอดเนินแล้ว — จากนี้แนวโน้มโดยรวมคือขาลง';

  @override
  String get nicotinePouchesReferenceDay1 =>
      'วันที่หนึ่ง: อาการถอนนิโคตินเริ่มขึ้น\n\nแหล่งที่มา: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nบททบทวนเกี่ยวกับการหยุดใช้ผลิตภัณฑ์ที่มีนิโคตินหลังใช้เรื้อรังรายงานว่า กลุ่มอาการถอนสามารถเริ่มได้ภายใน 4–24 ชั่วโมงหลังหยุด ดังนั้นวันแรกที่ไม่มีซองนิโคตินจึงเป็นหลักหมายทางสรีรวิทยาที่แท้จริง\n\nต่อจากนี้\nอาการมักถึงจุดสูงสุดราววันที่ 3 แล้วค่อย ๆ ลดลงในช่วง 3–4 สัปดาห์ถัดไป ความรุนแรงแตกต่างตามวิธีที่ได้รับนิโคติน จึงอาจแตกต่างกันไปในแต่ละคน';

  @override
  String get nicotinePouchesReferenceDay3 =>
      'วันที่สาม: จุดสูงสุดของอาการถอนนิโคติน\n\nแหล่งที่มา: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nบททบทวนระบุว่าจุดสูงสุดโดยทั่วไปของอาการถอนนิโคตินอยู่ราววันที่สามหลังหยุดการใช้นิโคตินเรื้อรัง\n\nกราฟจากจุดนี้\nหลังจุดสูงสุด อาการมักค่อย ๆ ลดลงในช่วง 3–4 สัปดาห์ถัดไป บททบทวนยังระบุว่าความรุนแรงแตกต่างตามวิธีที่ได้รับนิโคติน ดังนั้นระดับที่แน่นอนจึงต่างกันในแต่ละคน\n\nวันที่สามคือหลักหมายที่คุณฝ่ามาถึงด้วยตัวเอง: คุณอยู่บนยอดของกราฟอาการถอนช่วงต้นตามปกติแล้ว';

  @override
  String get nicotinePouchesMilestone7Title => '1 สัปดาห์: อาการถอนกำลังเบาลง';

  @override
  String get nicotinePouchesMilestone7Description =>
      'หนึ่งสัปดาห์โดยไม่ใช้ถุงนิโคตินหมายความว่าคุณผ่านจุดสูงสุดของอาการถอนนิโคตินที่มักอยู่ราววันที่ 3 แล้ว อาการมักค่อย ๆ ลดลงในช่วง 3–4 สัปดาห์ถัดไป — ตอนนี้คุณอยู่บนช่วงขาลงแล้ว';

  @override
  String get nicotinePouchesMilestone14Title => '2 สัปดาห์: อาการถอนยังคงเบาลง';

  @override
  String get nicotinePouchesMilestone14Description =>
      'สองสัปดาห์โดยไม่ใช้ถุงนิโคตินทำให้คุณอยู่ลึกเข้าไปในช่วง 3–4 สัปดาห์ที่อาการมักลดลงหลังจุดสูงสุดราววันที่ 3 เส้นโค้งยังลงต่อ — การฟื้นตัวกำลังเกิดขึ้นจริง';

  @override
  String get nicotinePouchesReferenceDay7 =>
      '1 สัปดาห์: อาการถอนกำลังเบาลง\n\nแหล่งที่มา: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nบทความทบทวนรายงานว่าอาการถอนหลังใช้ผลิตภัณฑ์ที่มีนิโคตินเป็นเวลานานเริ่มภายใน 4–24 ชั่วโมงหลังหยุด สูงสุดราววันที่ 3 แล้วค่อย ๆ ลดลงตลอด 3–4 สัปดาห์ถัดไป\n\nชัยชนะหนึ่งสัปดาห์ที่จับต้องได้\nเมื่อครบหนึ่งสัปดาห์ คุณผ่านจุดสูงสุดตามปกติมาหลายวันและเข้าสู่ช่วงที่อาการกำลังลดลงแล้ว บทความยังระบุว่าความรุนแรงของอาการถอนแตกต่างกันตามวิธีที่ได้รับนิโคติน จึงต่างกันในแต่ละคน\n\nหนึ่งสัปดาห์โดยไม่ใช้ถุงนิโคตินหมายความว่าช่วงที่ชันที่สุดของเส้นโค้งอาการถอนระยะแรกตามปกติอยู่ข้างหลังคุณแล้ว';

  @override
  String get nicotinePouchesReferenceDay14 =>
      '2 สัปดาห์: อาการถอนยังคงเบาลง\n\nแหล่งที่มา: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nบทความทบทวนระบุว่าจุดสูงสุดของอาการถอนนิโคตินโดยทั่วไปอยู่ราววันที่ 3 และอาการจะค่อย ๆ ลดลงในช่วง 3–4 สัปดาห์ถัดไป\n\nอยู่ลึกเข้าไปในช่วงขาลง\nเมื่อครบสองสัปดาห์ คุณอยู่ลึกเข้าไปในช่วงหลังจุดสูงสุดที่อาการกำลังลดลง บทความครอบคลุมการใช้ผลิตภัณฑ์ที่มีนิโคตินเป็นเวลานานและระบุว่าความรุนแรงของอาการถอนแตกต่างกันตามวิธีได้รับนิโคติน\n\nสองสัปดาห์โดยไม่ใช้ถุงนิโคตินเป็นจุดสำคัญที่ชัดเจนบนเส้นโค้งขาลง: อาการถอนโดยทั่วไปยังคงเบาลง';

  @override
  String get nicotinePouchesMilestone730Title => '2 ปี: พลังไร้ถุงนิโคติน';

  @override
  String get nicotinePouchesMilestone730Description =>
      'ครบสองปีเต็มโดยไม่ใช้ถุงนิโคติน งานวิจัยยังไม่พบเกณฑ์การฟื้นตัวพิเศษที่สองปี ดังนั้นหมุดหมายนี้จึงฉลองสองปีที่ไม่มีการรับนิโคตินซ้ำจากถุง และการเปลี่ยนแปลงที่รักษาไว้ได้ต่อเนื่อง';

  @override
  String get nicotinePouchesReferenceDay730 =>
      '2 ปี: พลังไร้ถุงนิโคติน\n\nแหล่งข้อมูล: Rungraungrayabkul และคณะ (2024) การทบทวนอย่างเป็นระบบเรื่องถุงนิโคตินและสุขภาพช่องปาก\n\nการทบทวนพบงานวิจัยในคนเพียง 3 งาน รวม 190 คน และทั้งหมดมีความเสี่ยงต่ออคติสูง งานวิจัยไม่ได้ระบุเกณฑ์การฟื้นตัวเฉพาะที่สองปีหลังหยุดใช้\n\nสองปีโดยไม่ใช้ถุงยังคงเป็นหมุดหมายใหญ่ของการเปลี่ยนแปลงที่ต่อเนื่อง ข้อความนี้ฉลองความสำเร็จนั้นโดยไม่สร้างเส้นเวลาทางการแพทย์ขึ้นมาเอง';

  @override
  String get nicotinePouchesMilestone1095Title => '3 ปี: อิสรภาพยังมั่นคง';

  @override
  String get nicotinePouchesMilestone1095Description =>
