  @override
  String get nicotinePouchesReferenceDay1095 =>
      '3 ปี: อิสรภาพยังมั่นคง\n\nแหล่งข้อมูล: CDC — ถุงนิโคติน\n\nCDC ระบุว่ายังต้องมีงานวิจัยเพิ่มเติมเพื่อทำความเข้าใจผลต่อสุขภาพทั้งระยะสั้นและระยะยาวของถุงนิโคติน และไม่ได้ระบุการเปลี่ยนแปลงทางการแพทย์เฉพาะที่สามปีหลังหยุดใช้\n\nสามปีโดยไม่ใช้ถุงควรค่าแก่การฉลองในตัวมันเอง: สามปีแห่งอิสรภาพจากนิโคตินในถุงอย่างต่อเนื่อง';

  @override
  String get nicotinePouchesMilestone1460Title => '4 ปี: เปลี่ยนแปลงได้ยาวนาน';

  @override
  String get nicotinePouchesMilestone1460Description =>
      'สี่ปีโดยไม่ใช้ถุงนิโคตินแสดงถึงความสม่ำเสมอจริง ไม่มีการเปลี่ยนแปลงทางการแพทย์ที่ยืนยันว่าเกิดขึ้นพอดีเมื่อครบสี่ปี แต่มีความสำเร็จที่ชัดเจนมาก: สี่ปีโดยไม่กลับไปสู่พฤติกรรมเดิม';

  @override
  String get nicotinePouchesReferenceDay1460 =>
      '4 ปี: เปลี่ยนแปลงได้ยาวนาน\n\nแหล่งข้อมูล: Rungraungrayabkul และคณะ (2024) การทบทวนอย่างเป็นระบบเรื่องถุงนิโคตินและสุขภาพช่องปาก\n\nการทบทวนสรุปว่าหลักฐานเกี่ยวกับผลต่อสุขภาพช่องปากทั้งระยะสั้นและระยะยาวยังมีจำกัดและต้องมีการศึกษาเพิ่มเติม ไม่ได้แสดงว่าทุกคนจะมีการฟื้นตัวเฉพาะอย่างเกิดขึ้นพอดีเมื่อครบสี่ปี\n\nสี่ปีโดยไม่ใช้ถุงคือหมุดหมายของการเปลี่ยนแปลงที่ต่อเนื่อง โดยไม่ต้องอาศัยคำกล่าวอ้างทางการแพทย์ที่ยังไม่มีหลักฐานรองรับ';

  @override
  String get nicotinePouchesMilestone1825Title => '5 ปี: ชัยชนะครั้งใหญ่';

  @override
