  String get ssriMilestone3Description =>
      'อาการถอนยามักรุนแรงที่สุดราววันที่ 2–4 SSRI เปลี่ยนการทำงานของระบบเซโรโทนิน ดังนั้นหลังหยุดยาสมองต้องใช้เวลาปรับตัว อาจมีอาการคล้ายไข้หวัด เวียนศีรษะ นอนไม่หลับ คลื่นไส้ และความรู้สึกคล้ายไฟช็อตในศีรษะหรือ “brain zaps” พาร็อกซีทีนมักทำให้อาการถอนรุนแรงกว่า ส่วนฟลูออกซีทีนอยู่ในร่างกายนานกว่ามากและโดยทั่วไปอาการจะเบากว่า';

  @override
  String get ssriMilestone7Title => '1 สัปดาห์: ระยะเฉียบพลันเริ่มดีขึ้น';

  @override
  String get ssriMilestone7Description =>
      'อาการทางกายที่รุนแรงที่สุดเริ่มทุเลา สมองกำลังปรับการส่งสัญญาณเซโรโทนินให้ทำงานได้โดยไม่มียา การนอนหลับและความอยากอาหารเริ่มคงที่';

  @override
  String get ssriMilestone14Title => '2 สัปดาห์: อาการทางกายลดลง';

  @override
  String get ssriMilestone14Description =>
      'อาการทางกายเฉียบพลันจากการหยุดยาส่วนใหญ่ลดลงอย่างชัดเจนหรือหายไป Brain zaps คลื่นไส้ และเวียนศีรษะค่อย ๆ ลดลง ความไวทางอารมณ์อาจยังสูงอยู่ระหว่างที่สมองปรับสมดุลระบบเซโรโทนินต่อไป';

  @override
  String get ssriMilestone30Title => '1 เดือน: อารมณ์และพลังงานคงที่ขึ้น';

  @override
  String get ssriMilestone30Description =>
      'หนึ่งเดือนเป็นหมุดหมายสำคัญ คุณภาพการนอนดีขึ้น ระดับพลังงานเริ่มคงที่ และหลายคนสังเกตว่าอารมณ์เริ่มพบสมดุลใหม่ สมองยังคงปรับการควบคุมเซโรโทนินตามธรรมชาติ';

  @override
  String get ssriMilestone90Title => '3 เดือน: อาการถอนถึงจุดเปลี่ยน';

  @override
  String get ssriMilestone90Description =>
      'ในการทดลอง ANTLER ความแตกต่างของอาการถอนหลังหยุดยาต้านซึมเศร้าที่ใช้ระยะยาวมากที่สุดที่ 12 สัปดาห์ และลดลงในการติดตามครั้งหลัง ๆ ทำให้สามเดือนเป็นจุดเปลี่ยนที่ชัดเจนของเส้นทางอาการถอนที่วัดได้';

  @override
  String get ssriMilestone180Title => 'หกเดือน: 65% ยังคงสบายดี';

  @override
  String get ssriMilestone180Description =>
      'ในการติดตามหกเดือนหลังหยุดยาต้านซึมเศร้าในผู้ที่โรคสงบ ผู้เข้าร่วมที่มีข้อมูลผลลัพธ์ 54 จาก 83 คน — 65% — ยังคงมีอาการคงที่และสบายดี หกเดือนจึงเป็นหลักหมายที่ชัดเจนของความมั่นคงระยะยาว';

  @override
  String get ssriMilestone365Title => 'หนึ่งปี: หมุดหมายครั้งใหญ่';

  @override
  String get ssriMilestone365Description =>
      'ครบหนึ่งปีโดยไม่ใช้ยาเป็นหมุดหมายครั้งใหญ่ ใน ANTLER ผู้ใช้ยาต้านซึมเศร้าระยะยาวจำนวนมากที่หยุดยาใช้เวลา 52 สัปดาห์โดยไม่เกิดการกำเริบ แม้ว่าการกำเริบจะพบได้บ่อยกว่าหลังหยุดยาเมื่อเทียบกับการรักษาต่อเนื่อง หากครบหนึ่งปีแล้วคุณยังไปได้ดี นั่นคือความก้าวหน้าจริงที่ควรฉลอง';

