  @override
  String get snriSubtitleStarted =>
      'ติดตามความคืบหน้าของคุณและเฉลิมฉลองแต่ละเหตุการณ์สำคัญ';

  @override
  String get snriSubtitleNotStarted => 'ดูว่าเกิดอะไรขึ้นเมื่อคุณลดลง';

  @override
  String get snriMilestone3Title => 'วันที่ 3: อาการถอนยารุนแรงสุด';

  @override
  String get snriMilestone3Description =>
      'SNRI โดยเฉพาะ venlafaxine (Effexor) เกี่ยวข้องกับอาการหยุดยาต้านซึมเศร้าที่รุนแรงได้ ครึ่งชีวิตของ venlafaxine สั้นมากประมาณ 5 ชั่วโมง จึงอาจทำให้อาการรุนแรงกว่า SSRI ส่วนใหญ่ อาการ FINISH (อาการคล้ายไข้หวัด นอนไม่หลับ คลื่นไส้ เสียสมดุล ความผิดปกติทางประสาทสัมผัส และภาวะตื่นตัวมากเกินไป) เกี่ยวข้องกับทั้งระบบเซโรโทนินและนอร์อะดรีนาลีนพร้อมกัน';

  @override
  String get snriMilestone7Title => '1 สัปดาห์: สองระบบกำลังปรับตัว';

  @override
  String get snriMilestone7Description =>
      'SNRI มีผลต่อการเก็บกลับทั้งเซโรโทนินและนอร์เอพิเนฟริน ทั้งสองระบบจึงปรับตัวพร้อมกัน อาการทางกายที่รุนแรงที่สุดเริ่มลดลง แต่กลไกสองระบบอาจทำให้การปรับตัวยุ่งยากกว่า SSRI เพียงอย่างเดียว';

  @override
  String get snriMilestone14Title => 'สองสัปดาห์: อาการทางกายภาพจางลง';

  @override
  String get snriMilestone14Description =>
      'อาการทางกายเฉียบพลันจากการหยุดยาส่วนใหญ่ลดลงอย่างชัดเจน อาการ brain zaps คลื่นไส้ และเวียนศีรษะเริ่มจางลง การปรับตัวของระบบนอร์เอพิเนฟรินยังอาจทำให้วิตกกังวลหรือความดันโลหิตผันผวนได้ ซึ่งโดยทั่วไปจะค่อยๆ ดีขึ้นในอีกไม่กี่สัปดาห์';

  @override
  String get snriMilestone30Title => '1 เดือน: นอร์อะดรีนาลีนคงที่';

  @override
  String get snriMilestone30Description =>
      'หนึ่งเดือนเป็นหมุดหมายสำคัญ ระบบเซโรโทนินและนอร์เอพิเนฟรินยังคงปรับสมดุล คุณภาพการนอนและระดับพลังงานเริ่มคงที่ หลายคนสังเกตว่าช่วงอารมณ์กว้างขึ้นเมื่ออาการทื่อทางอารมณ์จากยาค่อยๆ ลดลง';

  @override
  String get snriMilestone90Title => 'สามเดือน: พ้นช่วงถอนยาตามปกติ';

  @override
  String get snriMilestone90Description =>
      'อาการถอนยา SNRI มักเริ่มภายในไม่กี่วันและกินเวลาหลายสัปดาห์ เมื่อถึงวันที่ 90 ช่วงอาการตามปกตินั้นผ่านไปไกลแล้ว — เป็นหมุดหมายการฟื้นตัวที่ชัดเจน';

  @override
  String get snriMilestone180Title => 'หกเดือน: การฟื้นฟูระบบประสาท';

  @override
  String get snriMilestone180Description =>
      'หกเดือนทำให้ระบบเซโรโทนินและนอร์เอพิเนฟรินมีเวลาปรับตัวอย่างมาก แกน HPA ซึ่ง SNRI มีอิทธิพลผ่านนอร์เอพิเนฟรินกำลังกลับสู่ภาวะปกติ หลายคนรายงานว่าสามารถรับมือกับความเครียดในชีวิตประจำวันได้ดีขึ้นอย่างชัดเจนในช่วงนี้';

  @override
  String get snriMilestone365Title => 'หนึ่งปี: ฟื้นตัวได้สำเร็จ';

  @override
  String get snriMilestone365Description =>
      'หนึ่งปีเป็นวัฏจักรเต็มของการปรับตัวของระบบเซโรโทนินและนอร์เอพิเนฟริน งานวิจัยโดยรวมชี้ว่าผู้ที่หยุด SNRI สำเร็จภายใต้การดูแลของแพทย์และได้รับการสนับสนุนด้านจิตใจมักยังคงมีผลลัพธ์ที่ดีเมื่อครบหนึ่งปี';

  @override
  String get snriMilestone730Title => '2 ปี: ก้าวที่มั่นคง';

  @override
  String get snriMilestone730Description =>
      'สองปีหลังจากลดและหยุด SNRI สำเร็จเป็นช่วงเวลาที่ควรฉลอง ประสบการณ์อาการถอนยาแตกต่างกันไป ดังนั้นวันครบรอบนี้จึงสะท้อนความก้าวหน้าที่ต่อเนื่อง ไม่ใช่เส้นตายการฟื้นตัวทางชีวภาพสำหรับทุกคน';

  @override
  String get snriReferenceDay730 =>
      'สองปีหลังหยุด SNRI: หมุดหมายแห่งความก้าวหน้า\n\nแหล่งข้อมูล: Royal College of Psychiatrists — การหยุดยาต้านซึมเศร้า\n\nโดยทั่วไปไม่ควรหยุดยาต้านซึมเศร้าทันที การลดขนาดยาควรปรับตามแต่ละคน และ duloxetine หรือ venlafaxine อาจต้องลดช้าลงเป็นเวลาหลายเดือนหรือนานกว่านั้น\n\nคำแนะนำไม่ได้กำหนดว่าสองปีเป็นเกณฑ์การฟื้นตัวทางชีวภาพ วันครบรอบนี้ฉลองความก้าวหน้าที่ต่อเนื่อง';

  @override
  String get snriMilestone1095Title => '3 ปี: ก้าวหน้าต่อเนื่อง';

  @override
  String get snriMilestone1095Description =>
      'สามปีเป็นช่วงเวลาสำคัญหลังจากลดและหยุดยา ฉลองกิจวัตร การสนับสนุน และการตัดสินใจที่ช่วยให้คุณก้าวมาถึงจุดนี้ เพราะการแพทย์ไม่ได้กำหนดวันนี้เป็นเกณฑ์พิเศษของการฟื้นตัว';

  @override
  String get snriReferenceDay1095 =>
      'สามปีหลังหยุด SNRI: ความก้าวหน้าที่คงอยู่\n\nแหล่งข้อมูล: Royal College of Psychiatrists — การหยุดยาต้านซึมเศร้า\n\nประสบการณ์อาการถอนยาแตกต่างกัน ความเร็วในการลดยาควรพิจารณาจากบุคคล ระยะเวลารักษา อาการเดิม และยาที่ใช้\n\nไม่มีแนวทางทางคลินิกที่กำหนดว่าสามปีเป็นเส้นตายการฟื้นตัวจาก SNRI สำหรับทุกคน หมุดหมายนี้ยอมรับความก้าวหน้าของคุณ';

  @override
