  @override
  String get snriReferenceDay1460 =>
      'สี่ปีหลังหยุด SNRI: ความก้าวหน้าระยะยาว\n\nแหล่งข้อมูล: Royal College of Psychiatrists — การหยุดยาต้านซึมเศร้า\n\nRoyal College แนะนำให้ลดขนาดยาแบบค่อยเป็นค่อยไปและเหมาะกับแต่ละคน Duloxetine และ venlafaxine มีความเสี่ยงต่ออาการถอนสูงกว่า\n\nหลักฐานนี้ไม่ได้สร้างหมุดหมายทางระบบประสาทที่สี่ปี วันนี้เป็นการฉลองความก้าวหน้าที่ต่อเนื่อง';

  @override
