      'ห้าปีหลังหยุด SNRI: หมุดหมายห้าปี\n\nแหล่งข้อมูล: Royal College of Psychiatrists — การหยุดยาต้านซึมเศร้า\n\nแนวทางมุ่งที่การลดขนาดยาอย่างปลอดภัยและเหมาะกับแต่ละคน รวมถึงการตอบสนองต่ออาการ แทนการกำหนดตารางเดียวให้ทุกคน\n\nไม่มีเกณฑ์การฟื้นตัวจาก SNRI ที่ห้าปีซึ่งอิงหลักฐาน แต่ห้าปียังคงเป็นวันครบรอบส่วนตัวที่มีความหมาย';

