  @override
  String get tcaMilestone3Title => 'วันที่ 3: ภาวะโคลิเนอร์จิกรีบาวด์';

  @override
  String get tcaMilestone3Description =>
      'การหยุด TCA อาจทำให้เกิดอาการถอนยาจริง โดยภาวะการทำงานของระบบโคลิเนอร์จิกมากเกินเป็นหนึ่งในกลไกที่เสนอไว้ คลื่นไส้ ท้องเสีย ปวดท้อง นอนไม่หลับ วิตกกังวล กระสับกระส่าย และปวดศีรษะอาจเกิดเร็ว โดยเฉพาะหลังหยุดทันทีหรือลดยาเร็วเกินไป วันที่ 3 คือหมุดหมาย โดยช่วงเวลาและความรุนแรงของอาการแตกต่างกันในแต่ละคน';

  @override
