  @override
  String get tcaMilestone7Description =>
      'อาการถอนยาต้านซึมเศร้ามักเริ่มภายในไม่กี่วันและมักกินเวลาหลายสัปดาห์ หลังหนึ่งสัปดาห์ อาการคลื่นไส้ เหงื่อออก นอนไม่หลับ ใจสั่น และเวียนศีรษะอาจยังมีอยู่ เจ็ดวันคือความก้าวหน้าจริง และการฟื้นตัวอาจดำเนินต่อไปด้วยจังหวะที่แตกต่างกัน';

  @override
