  @override
  String get tcaMilestone14Description =>
      'อาการถอนยาต้านซึมเศร้าที่พบบ่อย เช่น คลื่นไส้ นอนไม่หลับ เสียสมดุล อาการทางประสาทสัมผัส และภาวะตื่นตัวสูง มักกินเวลาหนึ่งถึงสองสัปดาห์ เมื่อถึงวันที่ 14 หลายคนกำลังเข้าสู่ปลายช่วงถอนยาเฉียบพลันนี้';

  @override
  String get tcaMilestone30Title => '1 เดือน: ระยะเฉียบพลันสงบลงแล้ว';

  @override
  String get tcaMilestone30Description =>
      'อาการหยุดยาต้านซึมเศร้าโดยทั่วไปมักอยู่นานหนึ่งถึงสองสัปดาห์ เมื่อครบ 30 วัน คนส่วนใหญ่มักพ้นช่วงเฉียบพลันนี้แล้ว และอาการคล้ายไข้หวัด คลื่นไส้ เสียการทรงตัว นอนไม่หลับ ความผิดปกติทางประสาทสัมผัส และภาวะตื่นตัวมากเกินไปมักลดลงมากหรือหายไป';

  @override
  String get tcaMilestone90Title => '3 เดือน: ระยะเฉียบพลันผ่านไปแล้ว';

  @override
  String get tcaMilestone90Description =>
      'อาการหยุดยาต้านซึมเศร้าโดยทั่วไปมักอยู่นานหนึ่งถึงสองสัปดาห์ เมื่อครบ 90 วัน คุณผ่านพ้นขอบบนของช่วงเฉียบพลันโดยทั่วไปมาแล้วมากกว่าสิบสัปดาห์ และอาการคล้ายไข้หวัด คลื่นไส้ เสียการทรงตัว นอนไม่หลับ ความผิดปกติทางประสาทสัมผัส และภาวะตื่นตัวมากเกินไปมักลดลงมากหรือหายไปนานแล้ว';

  @override
  String get tcaMilestone180Title => 'หกเดือน: คนส่วนใหญ่ยังไม่กลับเป็นซ้ำ';

  @override
  String get tcaMilestone180Description =>
      'ในผู้ที่หยุดยาต้านซึมเศร้าหลังรักษาโรคซึมเศร้ารุนแรง การวิเคราะห์อภิมาน 35 การทดลองพบอัตราการกลับเป็นซ้ำรวมที่หกเดือน 34.8% — ประมาณ 65% ยังไม่กลับเป็นซ้ำ นี่คือช่วงความมั่นคงที่ยาวนานมาก';

  @override
  String get tcaMilestone365Title => 'หนึ่งปี: คนส่วนใหญ่ยังไม่กลับเป็นซ้ำ';

  @override
  String get tcaMilestone365Description =>
      'ในผู้ที่หยุดยาต้านซึมเศร้าหลังรักษาโรคซึมเศร้ารุนแรง การวิเคราะห์อภิมานจาก 35 การทดลองพบอัตราการกลับเป็นซ้ำรวมที่ 12 เดือน 45.12% — ประมาณ 55% ยังไม่กลับเป็นซ้ำตลอดหนึ่งปีเต็ม นี่คือหมุดหมายสำคัญของความมั่นคงระยะยาว';

  @override
  String get tcaMilestone730Title => '2 ปี: ฐานที่มั่นคง';

  @override
  String get tcaMilestone730Description =>
      'สองปีหลังจากลดและหยุด TCA อย่างค่อยเป็นค่อยไปเป็นหมุดหมายสำคัญ ประสบการณ์หลังหยุดยาแตกต่างกันในแต่ละคน ดังนั้นหมุดหมายนี้จึงฉลองความก้าวหน้าที่ต่อเนื่องโดยไม่อ้างว่ามีเส้นชัยทางชีววิทยาแบบเดียวสำหรับทุกคน';

  @override
  String get tcaReferenceDay730 =>
      'สองปีหลัง TCA: ความก้าวหน้าต่อเนื่อง\n\nแหล่งที่มา: NICE NG222 — Depression in adults: treatment and management\n\nNICE ระบุชัดว่า TCA เป็นยาต้านซึมเศร้ากลุ่มหนึ่งที่อาจเกิดอาการหลังหยุดยาได้ ประสบการณ์แตกต่างกันในแต่ละคน และควรลดขนาดยาอย่างค่อยเป็นค่อยไปพร้อมปรับความเร็วตามการตอบสนองของแต่ละคน\n\nแนวทางไม่ได้กำหนดสองปีเป็นเกณฑ์การฟื้นตัวทางชีววิทยา วันครบรอบนี้ฉลองความก้าวหน้าตลอดสองปีโดยไม่สร้างเส้นชัยแบบเดียวสำหรับทุกคน';

  @override
  String get tcaMilestone1095Title => '3 ปี: ความก้าวหน้าคงอยู่';

  @override
  String get tcaMilestone1095Description =>
      'สามปีคือช่วงเวลายาวนานของความก้าวหน้าที่รักษาไว้ได้ แนวทางทางคลินิกไม่ได้กำหนดวันนี้เป็นจุดสิ้นสุดพิเศษของการฟื้นตัวหลัง TCA สิ่งที่ควรฉลองคือความมั่นคง กิจวัตร และการตัดสินใจที่รักษาไว้ตลอดช่วงเวลานี้';

  @override
  String get tcaReferenceDay1095 =>
      'สามปีหลัง TCA: ความก้าวหน้ายังคงอยู่\n\nแหล่งที่มา: NICE NG222 — Depression in adults: treatment and management\n\nNICE ระบุชัดว่า TCA เป็นยาต้านซึมเศร้ากลุ่มหนึ่งที่อาจเกิดอาการหลังหยุดยาได้ ประสบการณ์แตกต่างกันในแต่ละคน และควรลดขนาดยาอย่างค่อยเป็นค่อยไปพร้อมปรับความเร็วตามการตอบสนองของแต่ละคน\n\nแนวทางไม่ได้กำหนดสามปีเป็นกำหนดเวลาการฟื้นตัวแบบเดียวสำหรับทุกคน หมุดหมายนี้ยกย่องความมั่นคงและความก้าวหน้าที่รักษาไว้ตลอดสามปี';

  @override
  String get tcaMilestone1460Title => '4 ปี: ก้าวหน้าอย่างยั่งยืน';

  @override
  String get tcaMilestone1460Description =>
      'สี่ปีสะท้อนความก้าวหน้าที่มั่นคงซึ่งสร้างขึ้นตามเวลา ประสบการณ์หลังหยุด TCA แตกต่างกันในแต่ละคน และหมุดหมายนี้ยกย่องสิ่งที่รักษาไว้ได้โดยไม่สร้างตารางเวลาทางระบบประสาทแบบตายตัว';

  @override
  String get tcaReferenceDay1460 =>
      'สี่ปีหลัง TCA: ความก้าวหน้าระยะยาว\n\nแหล่งที่มา: NICE NG222 — Depression in adults: treatment and management\n\nNICE ระบุชัดว่า TCA เป็นยาต้านซึมเศร้ากลุ่มหนึ่งที่อาจเกิดอาการหลังหยุดยาได้ ประสบการณ์แตกต่างกันในแต่ละคน และควรลดขนาดยาอย่างค่อยเป็นค่อยไปพร้อมปรับความเร็วตามการตอบสนองของแต่ละคน\n\nแนวทางไม่มีเกณฑ์ทางชีววิทยาที่สี่ปี แต่สี่ปียังคงเป็นหมุดหมายที่มีความหมายของความก้าวหน้าระยะยาว';

  @override
  String get tcaMilestone1825Title => '5 ปี: ความก้าวหน้าที่ยืนยาว';

  @override
  String get tcaMilestone1825Description =>
      'ห้าปีเป็นวันครบรอบส่วนตัวที่สำคัญ เป็นเครื่องหมายของการเปลี่ยนแปลงที่ต่อเนื่องหลังหยุด TCA พร้อมยอมรับว่าการหยุดยาและการฟื้นตัวไม่ได้เดินตามตารางเดียวกันสำหรับทุกคน';

  @override
  String get tcaReferenceDay1825 =>
      'ห้าปีหลัง TCA: วันครบรอบสำคัญ\n\nแหล่งที่มา: NICE NG222 — Depression in adults: treatment and management\n\nNICE ระบุชัดว่า TCA เป็นยาต้านซึมเศร้ากลุ่มหนึ่งที่อาจเกิดอาการหลังหยุดยาได้ ประสบการณ์แตกต่างกันในแต่ละคน และควรลดขนาดยาอย่างค่อยเป็นค่อยไปพร้อมปรับความเร็วตามการตอบสนองของแต่ละคน\n\nหลักฐานไม่ได้กำหนดเกณฑ์การฟื้นตัวจาก TCA ที่ห้าปี แต่ห้าปียังคงเป็นวันครบรอบส่วนตัวที่สำคัญและเป็นเครื่องหมายของการเปลี่ยนแปลงที่ยั่งยืน';

