  @override
  String get maoiPageTitle => 'การกู้คืน MAOI';

  @override
  String get maoiHeaderStarted => 'การเดินทางเพื่อการฟื้นฟูของคุณ';

  @override
  String get maoiHeaderNotStarted => 'ประโยชน์ของการลดขนาด MAOI';

  @override
  String get maoiSubtitleStarted =>
      'ติดตามความคืบหน้าของคุณและเฉลิมฉลองแต่ละเหตุการณ์สำคัญ';

  @override
  String get maoiSubtitleNotStarted => 'ดูว่าเกิดอะไรขึ้นเมื่อคุณลดลง';

  @override
  String get maoiMilestone3Title => 'วันที่ 3: ช่วงเสี่ยงสูงสุด';

  @override
  String get maoiMilestone3Description =>
      'MAOIs มีความเสี่ยงที่ร้ายแรงที่สุดในการหยุดยาในกลุ่มยาต้านอาการซึมเศร้าการหยุดกะทันหัน โดยเฉพาะฟีเนลซีนและทรานิลไซโปรมีน อาจทำให้เกิดอาการปั่นป่วน สับสน ภาพหลอน กล้ามเนื้อกระตุก และอุณหภูมิร่างกายสูงเกินไปหากคุณมีอาการเหล่านี้ ให้ไปพบแพทย์ทันทีMAOI ทำงานโดยการปิดการใช้งานเอนไซม์ MAO อย่างถาวรการฟื้นฟูร่างกายต้องสังเคราะห์เอนไซม์ใหม่ ซึ่งใช้เวลาประมาณ 14 วัน';

  @override
  String get maoiMilestone7Title => 'หนึ่งสัปดาห์: สร้างเอนไซม์ MAO';

  @override
  String get maoiMilestone7Description =>
      'MAOIs ทำลายโมเลกุลของเอนไซม์ MAO อย่างถาวรการฟื้นตัวจำเป็นต้องสังเคราะห์เอนไซม์ใหม่ทั้งหมดภายในหนึ่งสัปดาห์ กิจกรรม MAO ปกติประมาณ 50% อาจฟื้นตัวได้อาการหยุดเฉียบพลันอย่างรุนแรง (เพ้อ, myoclonus, hyperthermia) จะลดลงอย่างมากการดูแลทางการแพทย์อย่างใกล้ชิดยังคงมีความสำคัญ';

  @override
  String get maoiMilestone14Title => 'สองสัปดาห์: MAO ฟื้นตัวมาก';

  @override
  String get maoiMilestone14Description =>
      'สองสัปดาห์เป็นกรอบเวลาทางคลินิกมาตรฐานสำหรับการฟื้นฟูเอนไซม์ MAO หลังจากหยุดยาประมาณวันที่ 14 กิจกรรมของ MAO-A และ MAO-B จะได้รับการฟื้นฟูเป็นส่วนใหญ่ และเมตาบอลิซึมของไทรามีนตามปกติจะถูกสร้างขึ้นอีกครั้งข้อจำกัดด้านอาหารที่จำเป็นระหว่างการรักษา MAOI โดยทั่วไปสามารถผ่อนคลายได้โดยปรึกษากับผู้สั่งจ่ายยาของคุณ';

  @override
  String get maoiMilestone30Title => 'หนึ่งเดือน: สมดุลเคมีสมอง';

  @override
  String get maoiMilestone30Description =>
      'หนึ่งเดือนหลังจากหยุด MAOI เอนไซม์ MAO จะทำงานอีกครั้ง และสมองจะจัดการกับเซโรโทนิน นอร์อะดรีนาลีน โดปามีน และไทรามีนตามธรรมชาติระยะเวลาการโต้ตอบกับอาหารและยาแบบพิเศษสิ้นสุดลงแล้ว แต่คุณควรแจ้งให้ผู้สั่งจ่ายยาทราบเกี่ยวกับการใช้ MAOI ก่อนหน้านี้';

  @override
  String get maoiMilestone90Title => 'สามเดือน: การทำให้เคมีในสมองเป็นปกติ';

  @override
  String get maoiMilestone90Description =>
      'สามเดือนทำให้ระบบอารมณ์และพลังงานของสมองมีเวลาอย่างมากในการปรับตัวหลังจาก MAOIอารมณ์ พลังงาน และการคิดที่ชัดเจนจะมีเสถียรภาพในขณะที่สมองจัดการกับสารเคมีเหล่านี้ตามธรรมชาติอีกครั้ง';

  @override
  String get maoiMilestone180Title => 'หกเดือน: การฟื้นฟูระยะยาว';

  @override
  String get maoiMilestone180Description =>
      'หกเดือนแสดงถึงช่วงเวลาสำคัญของการทำงานของโมโนเอมีนตามธรรมชาติSerotonin, norepinephrine และ dopamine receptor มีจำนวนเป็นปกติวิถีทางฟีนเอทิลเอมีน (PEA) ที่ได้รับผลกระทบจาก MAOI ได้กลับคืนสู่ระดับธรรมชาติ ซึ่งเป็นแง่มุมของการฟื้นตัวที่มักถูกมองข้ามซึ่งมีส่วนช่วยในการฟื้นฟูทางอารมณ์';

  @override
  String get maoiMilestone365Title => 'หนึ่งปี: ฟื้นตัวได้สำเร็จ';

  @override
  String get maoiMilestone365Description =>
      'หนึ่งปีหลังจากการหยุดยา MAOI จะทำให้สมองและร่างกายปลอดจากยาได้หนึ่งปีเต็มอารมณ์ พลังงาน การคิดที่ชัดเจน และการควบคุมสารเคมีในสมองตามปกติ มีเวลาพอสมควรในการปรับตัวและฟื้นตัว';

