  @override
  String get adderallReferenceDay1 =>
      'การถอนแอมเฟตามีน: สิ่งที่เกิดขึ้นในระยะแรก\n\nแหล่งที่มา: MedlinePlus (U.S. National Library of Medicine)\n\nแอมเฟตามีนคืออะไร?\nแอมเฟตามีนเป็นสารกระตุ้น ซึ่งรวมทั้งสารผิดกฎหมาย เช่น “สปีด” ที่ขายตามท้องถนน และยาตามใบสั่งแพทย์ที่ใช้รักษา ADHD และโรคลมหลับ เช่น Adderall และ Vyvanse ยาเหล่านี้เพิ่มโดปามีนและนอร์เอพิเนฟรินอย่างรวดเร็ว จึงอาจทำให้มีสมาธิ พลังงาน และความรู้สึกเคลิบเคลิ้มอย่างมาก เมื่อใช้ในปริมาณมากเป็นประจำ สมองจะปรับตัวต่อการเพิ่มขึ้นซ้ำ ๆ เหล่านี้ ดังนั้นเมื่อหยุดใช้ อารมณ์ พลังงาน และแรงจูงใจอาจลดลงชั่วคราว\n\nอาการถอนยาที่พบบ่อย\nMedlinePlus ระบุอาการที่มักพบเมื่อหยุดแอมเฟตามีน ได้แก่:\n• อยากใช้ยาอย่างรุนแรง\n• อารมณ์แปรปรวน ตั้งแต่ซึมเศร้า กระสับกระส่าย ไปจนถึงวิตกกังวล\n• เหนื่อยตลอดทั้งวัน\n• มีสมาธิยาก\n• ประสาทหลอน (เห็นหรือได้ยินสิ่งที่ไม่มีอยู่จริง)\n• อาการทางกาย เช่น ปวดศีรษะ ปวดเมื่อย อยากอาหารมากขึ้น และนอนหลับไม่ดี\n\nการถอนยาอันตรายหรือไม่?\nMedlinePlus ไม่ได้อธิบายว่าการถอนแอมเฟตามีนมีอันตรายทางการแพทย์ในตัวมันเอง แต่ระบุว่าอาการรุนแรงอาจต้องเข้ารับการรักษาแบบพักอาศัย และปัญหาด้านอารมณ์จากการใช้แอมเฟตามีน — รวมถึงภาวะซึมเศร้า — อาจรุนแรงและต้องการการช่วยเหลือ\n\nการขอความช่วยเหลือ\nMedlinePlus แนะนำให้ติดต่อบุคลากรทางการแพทย์ หากคุณหรือคนที่คุณรู้จักมีภาวะพึ่งพาแอมเฟตามีนและต้องการความช่วยเหลือในการหยุดใช้ หากมีความคิดทำร้ายตนเอง แหล่งข้อมูลนี้แนะนำให้ใช้บริการช่วยเหลือฉุกเฉิน เช่น 988 หรือ 911';

  @override
  String get adderallReferenceDay3 =>
      'การดูแลอาการถอนแอมเฟตามีน: วันที่ 3\n\nแหล่งที่มา: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), NCBI Bookshelf\n\nวันที่ 3 อยู่ตรงไหนของช่วงถอนยา?\nแนวทางของ WHO ระบุว่าอาการถอนสารกระตุ้น “เริ่มภายใน 24 ชั่วโมงหลังใช้สารกระตุ้นครั้งสุดท้ายและคงอยู่ 3–5 วัน” วันที่ 3 จึงอยู่ในช่วงเฉียบพลันนี้พอดี และมักเป็นหนึ่งในวันที่ยากที่สุดก่อนที่อาการจะเริ่มลดลง\n\nอาการ\nสำหรับสารกระตุ้นกลุ่มแอมเฟตามีน แนวทางระบุ:\n• กระสับกระส่ายและหงุดหงิด\n• ซึมเศร้า\n• นอนมากขึ้นและอยากอาหารมากขึ้น\n• ปวดกล้ามเนื้อ\nผู้ที่ใช้ในปริมาณมากอาจมีอาการทางจิต เช่น หวาดระแวง ความคิดสับสน หรือประสาทหลอน\n\nความท้าทายส่วนใหญ่เป็นด้านจิตใจ\nต่างจากการถอนแอลกอฮอล์หรือโอปิออยด์ การถอนสารกระตุ้นไม่ได้มีอาการอาเจียน สั่น หรือชักเป็นลักษณะเด่น ความยากหลักมักเป็นด้านจิตใจ เช่น อารมณ์ต่ำ ความรู้สึกเพลิดเพลินลดลง และความอยากใช้ยา\n\nแนวทางการดูแล\nWHO แนะนำการดูแลแบบประคับประคอง:\n• ดื่มน้ำอย่างน้อย 2–3 ลิตรต่อวัน\n• รับประทานวิตามินรวมที่มีวิตามินบีกลุ่มและวิตามินซี\n• ใช้ยาตามอาการสำหรับอาการปวดและวิตกกังวล\n• หากกระสับกระส่ายรุนแรง ให้ใช้วิธีด้านพฤติกรรมก่อน และใช้ไดอะซีแพมเพื่อสงบอาการเฉพาะเมื่อจำเป็น\n\nหลังช่วงเฉียบพลัน\nแนวทางระบุว่าช่วงถอนยาที่หนักที่สุดกินเวลาเพียงไม่กี่วัน จากนั้นอาจมีช่วงฟื้นตัวที่เบาลงต่ออีกประมาณหนึ่งถึงสองเดือน';

  @override
  String get adderallReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่มี Adderall: ช่วงที่ยากที่สุดกำลังผ่านไป\n\nแหล่งที่มา: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), PubMed Central\n\nช่วงเฉียบพลันเริ่มคลี่คลาย\nการทบทวนหลักฐานนี้แบ่งการถอนสารกระตุ้นจิตออกเป็นหลายระยะ ในระยะเฉียบพลัน อาการ “รุนแรงที่สุดหลัง 2–3 วันแรก” และ “ความไม่สบายหลักจากอาการเหล่านี้มักหายไปภายใน 4–7 วัน” เมื่อสิ้นสุดสัปดาห์แรก คนส่วนใหญ่ผ่านช่วง crash ที่ยากที่สุดแล้ว พลังงานและความอยากอาหารเริ่มคงที่ และการนอนเริ่มเป็นระเบียบขึ้น\n\nต่อจากนี้จะเป็นอย่างไร?\nการทบทวนระบุว่าอาการที่เหลือส่วนใหญ่ยังคงลดลงในอีกสองถึงสามสัปดาห์ถัดไป ในวันที่ 7 การฟื้นตัวกำลังดำเนินไปแล้ว\n\nอาการที่ยังอาจมีในวันที่ 7\nอาการด้านจิตใจมักอยู่นานกว่าช่วง crash ทางกาย:\n• แรงจูงใจต่ำและรู้สึกเพลิดเพลินน้อยลง\n• มีสมาธิยาก\n• อารมณ์ยังต่ำกว่าปกติ\nอาการเหล่านี้สะท้อนว่าระบบโดปามีนกำลังปรับตัวใหม่ ซึ่งเป็นส่วนหนึ่งของการฟื้นตัวที่พบได้และเป็นชั่วคราว\n\nสัญญาณของการฟื้นตัว\nยังไม่มียาที่ FDA อนุมัติโดยเฉพาะสำหรับรักษาการถอนสารกระตุ้น ดังนั้นการดูแลแบบประคับประคอง กิจวัตรที่เป็นระบบ การนอน โภชนาการ และการสนับสนุนด้านจิตใจจึงเป็นหัวใจของระยะนี้';

  @override
  String get adderallReferenceDay14 =>
      'สองสัปดาห์โดยไม่มี Adderall: เข้าสู่ช่วงฟื้นตัวที่ยาวขึ้น\n\nแหล่งที่มา: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), NCBI Bookshelf\n\nผ่านช่วงเฉียบพลันแล้ว\nWHO ระบุว่าช่วงถอนสารกระตุ้นที่หนักที่สุดกินเวลาประมาณ 3–5 วัน แล้วตามด้วยช่วงฟื้นตัวที่เบากว่าประมาณหนึ่งถึงสองเดือน เมื่อครบสองสัปดาห์ ช่วง crash แรกได้ผ่านไปไกลแล้ว\n\nช่วงฟื้นตัวที่ยาวขึ้นเป็นอย่างไร?\nการนอนมาก กระสับกระส่าย และปวดกล้ามเนื้อลดลงเป็นส่วนใหญ่ สิ่งที่ยังเหลือมักเบากว่า เช่น อารมณ์ต่ำหรือแปรปรวน แรงจูงใจลดลง และความอยากใช้ยาที่เกิดเป็นครั้งคราวในขณะที่ระบบรางวัลของสมองกำลังปรับตัว\n\nการนอนและความอยากอาหาร\nการนอนและความอยากอาหารที่เพิ่มขึ้นในช่วงเฉียบพลันเริ่มกลับสู่ปกติ เมื่อการนอนคงที่ อารมณ์ สมาธิ และพลังงานก็มักดีขึ้นตาม\n\nความเสี่ยงกลับไปใช้และ ADHD\nช่วงนี้ยังมีความเสี่ยงกลับไปใช้สูงกว่าปกติ โดยเฉพาะหากอาการ ADHD เดิมกลับมาเมื่อไม่ได้ใช้ยา แนวทาง WHO เน้นการสนับสนุนด้านจิตใจและทักษะป้องกันการกลับไปใช้ สำหรับผู้ที่เคยใช้ Adderall รักษา ADHD นี่เป็นช่วงที่เหมาะจะพูดคุยกับแพทย์เรื่องวิธีที่ไม่ใช้สารกระตุ้นหรือทางเลือกอื่น';

  @override
  String get adderallReferenceDay30 =>
      'หนึ่งเดือนโดยไม่มี Adderall: อาการส่วนใหญ่ผ่านไปแล้ว\n\nแหล่งที่มา: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), PubMed Central\n\nหนึ่งเดือนอยู่ตรงไหน?\nการทบทวนพบว่าอาการถอนยาส่วนใหญ่ค่อย ๆ ลดลงในสองถึงสามสัปดาห์แรก เมื่อครบ 30 วัน อาการส่วนใหญ่เบาลง และอารมณ์กับแรงจูงใจมักดีกว่าสัปดาห์แรกมาก\n\nช่วงฟื้นตัวระยะต่อมา\nตั้งแต่หนึ่งถึงหกเดือน ความจำ การวางแผน สมาธิ และการตัดสินใจอาจยังดีขึ้นต่อเนื่อง เมื่อครบหนึ่งเดือน ช่วง crash จบลงแล้วและการฟื้นตัวเหล่านี้กำลังดำเนินอยู่\n\nอารมณ์และแรงจูงใจ\nความรู้สึกไม่เพลิดเพลินอย่างมากในช่วง crash มักลดลงไปมาก กิจกรรมที่เคยรู้สึกไร้ความสุขในสัปดาห์แรกอาจเริ่มให้ความพึงพอใจอีกครั้ง เมื่อการส่งสัญญาณโดปามีนตามธรรมชาติฟื้นตัว\n\nสำหรับผู้ที่มี ADHD\nหาก Adderall ถูกสั่งเพื่อรักษา ADHD อาการพื้นฐานอาจเห็นชัดขึ้นในช่วงนี้ การทำงานร่วมกับบุคลากรทางการแพทย์เพื่อพิจารณาวิธีที่ไม่ใช้สารกระตุ้นหรือทางเลือกอื่นจึงสำคัญ';

  @override
  String get adderallReferenceDay60 =>
      'สองเดือนโดยไม่มี Adderall: ช่วงฟื้นตัวที่ยาวขึ้นใกล้สิ้นสุด\n\nแหล่งที่มา: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), NCBI Bookshelf\n\nสองเดือนอยู่ตรงไหน?\nWHO อธิบายช่วงฟื้นตัวที่เบากว่าซึ่งกินเวลาประมาณหนึ่งถึงสองเดือนหลังช่วง crash แรก เมื่อครบ 60 วัน คุณอยู่ปลายช่วงนี้และอาการที่เหลือส่วนใหญ่กำลังคลี่คลาย\n\nอะไรดีขึ้น?\nอาการกระสับกระส่าย อารมณ์ซึมเศร้า และปัญหาการนอนกับความอยากอาหารที่แนวทางระบุไว้ มักลดลงมากในคนส่วนใหญ่:\n• อารมณ์ในชีวิตประจำวันคงที่ขึ้นและแปรปรวนน้อยกว่าช่วงฟื้นตัวแรก\n• การนอนและความอยากอาหารกลับเป็นปกติ\n• ระบบรางวัลตอบสนองต่อความสุขในชีวิตประจำวัน เช่น อาหาร การออกกำลังกาย และความสัมพันธ์ ได้ง่ายขึ้น\n\nสัญญาณของการฟื้นตัว\nการใช้ขนาดสูงหรือเป็นเวลานานอาจทำให้การฟื้นตัวใช้เวลามากขึ้น การงดใช้ต่อเนื่องช่วยให้อารมณ์ แรงจูงใจ และความคิดที่ชัดเจนค่อย ๆ เข้าใกล้ภาวะปกติในเดือนต่อ ๆ ไป\n\nสุขภาพกาย\nเมื่อยาไม่เป็นส่วนหนึ่งของชีวิตประจำวันอีกต่อไป ผลกระตุ้นต่ออัตราการเต้นของหัวใจ ความอยากอาหาร และน้ำหนักจะลดลง รวมถึงภาระต่อระบบหัวใจและหลอดเลือดจากการใช้สารกระตุ้นด้วย';

  @override
  String get adderallReferenceDay90 =>
      'สามเดือนโดยไม่มี Adderall: ช่วงที่ยากที่สุดผ่านไป การฟื้นตัวยังดำเนินต่อ\n\nแหล่งที่มา: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), PubMed Central\n\n90 วันอยู่ตรงไหน?\nเมื่อครบสามเดือน อาการระยะแรกผ่านไปนานแล้ว ขณะที่ความจำ การวางแผน สมาธิ การตัดสินใจ และระบบรางวัลยังสามารถดีขึ้นต่อเนื่อง\n\nความคิดและความจำยังฟื้นตัว\nการทบทวนพบว่าความจำ การวางแผน สมาธิ และการตัดสินใจเกี่ยวกับความเสี่ยงอาจดีขึ้นต่อเนื่องหลายเดือน ในวันที่ 90 หากยังงดใช้ สมาธิและความจำยังคงเคลื่อนไปในทิศทางที่ดี\n\nทำไมช่วงนี้ยังสำคัญ?\nยังไม่มียาที่ FDA อนุมัติโดยเฉพาะสำหรับการถอนสารกระตุ้น กิจวัตร การบำบัด การออกกำลังกาย การนอน และการสนับสนุนจึงเป็นเครื่องมือสำคัญที่ช่วยให้ผ่านระยะนี้ การสร้างนิสัยเหล่านี้ตอนนี้ช่วยพาการฟื้นตัวไปต่อ\n\nภาพรวม\nสามเดือนเป็นความสำเร็จจริง ช่วงทางกายและอารมณ์ที่ยากที่สุดอยู่ข้างหลังแล้ว และหากยังงดใช้ต่อเนื่อง การฟื้นตัวสามารถค่อย ๆ ดีขึ้นต่อไป';

  @override
  String get adderallReferenceDay180 =>
      'หกเดือนโดยไม่มี Adderall: ผ่านช่วงที่ยากที่สุดมาไกลแล้ว\n\nแหล่งที่มา: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nStatPearls กล่าวถึงสารกระตุ้นอย่างไร?\nเอกสารอ้างอิงทางคลินิกนี้อธิบายการฟื้นตัวจากสารกระตุ้นว่าเป็นช่วง crash ตามด้วยการดีขึ้นอย่างค่อยเป็นค่อยไป ปัญหาที่พบบ่อย ได้แก่ ซึมเศร้า นอนมาก หิวมากขึ้น อารมณ์ต่ำ และการเคลื่อนไหวกับความคิดที่ช้าลง ภาวะซึมเศร้าอาจคงอยู่หลายสัปดาห์ และหลังจากนั้นยังมีการฟื้นตัวที่เบากว่าต่อไป\n\nหกเดือนอยู่ตรงไหน?\nเมื่อครบหกเดือน คุณผ่านทั้งช่วงเฉียบพลันและระยะซึมเศร้าหลายสัปดาห์ที่ StatPearls อธิบายมาไกลแล้ว การฟื้นตัวแบบค่อยเป็นค่อยไปมีเวลาพัฒนาอย่างมาก และสำหรับคนส่วนใหญ่ อารมณ์ การนอน ความอยากอาหาร และแรงจูงใจในชีวิตประจำวันมีแนวโน้มมั่นคงขึ้น\n\nสัญญาณของการฟื้นตัว\nStatPearls อธิบายว่าการฟื้นตัวยังค่อย ๆ ดำเนินต่อหลังสัปดาห์แรก ๆ เมื่อครบหกเดือน ช่วง crash เฉียบพลันและระยะซึมเศร้าหลายสัปดาห์อยู่ไกลข้างหลัง และอารมณ์ การนอน ความอยากอาหาร และแรงจูงใจที่มั่นคงกลายเป็นรูปแบบหลัก\n\nความเกี่ยวข้องกับ ADHD\nสำหรับผู้ที่เคยใช้ Adderall รักษา ADHD หกเดือนเป็นช่วงที่เหมาะจะทบทวนอาการปัจจุบันกับแพทย์อย่างชัดเจน และดูว่าวิธีที่ไม่ใช้สารกระตุ้น เช่น การออกกำลังกาย การนอน กิจวัตร การบำบัด หรือยาทางเลือก ตอบโจทย์ความต้องการหรือไม่';

  @override
  String get adderallReferenceDay365 =>
      'หนึ่งปีโดยไม่มี Adderall: การฟื้นตัวอย่างมากในกรอบที่ไม่เกินจริง\n\nแหล่งที่มา: Berman et al., \"Potential Adverse Effects of Amphetamine Treatment on Brain and Behavior: A Review,\" Molecular Psychiatry (2008), PubMed Central\n\nเกี่ยวกับการทบทวนนี้\nการทบทวนนี้พิจารณาผลที่การได้รับแอมเฟตามีนขนาดสูงหรือเป็นเวลานานอาจมีต่อสมอง และบันทึกการฟื้นตัวที่วัดได้ระหว่างการงดใช้\n\nสิ่งที่พบเกี่ยวกับการฟื้นตัว\nการทบทวนบันทึกการฟื้นตัวของการไหลเวียนเลือดในสมองและโปรตีนที่นำโดปามีนกลับมาใช้ใหม่หลังงดใช้เป็นเวลานาน สมองบางส่วนฟื้นตัวเร็วกว่าส่วนอื่น แต่ทิศทางโดยรวมชัดเจนว่า สมองฟื้นตัวหลังหยุดใช้\n\nการฟื้นตัวระยะยาว\nการทบทวนบันทึกการฟื้นตัวที่วัดได้ของการไหลเวียนเลือดในสมองและการนำโดปามีนกลับมาใช้ใหม่หลังงดใช้เป็นเวลานาน เมื่อครบหนึ่งปี ระบบสมองเหล่านี้มีเวลาฟื้นตัวมาเต็มปี\n\nหนึ่งปีหมายถึงอะไร?\nสำหรับคนส่วนใหญ่ — โดยเฉพาะผู้ที่ใช้ Adderall ตามขนาดที่แพทย์สั่ง — หนึ่งปีโดยไม่ใช้สามารถตรงกับช่วงที่ระบบรางวัล ความสนใจ และแรงจูงใจทำงานได้ดีในชีวิตประจำวัน ผู้ที่ใช้มากกว่าหรือนานกว่าอาจต้องใช้เวลาฟื้นตัวมากขึ้น แต่การฟื้นตัวยังดำเนินต่อ ความเสี่ยงกลับไปใช้ต่ำกว่าช่วงฟื้นตัวระยะแรกมาก';

  @override
  String get alcoholReferenceDay1 =>
      'จะเกิดอะไรขึ้นกับการนอนหลับของคุณเมื่อคุณหยุดดื่ม?\n\nที่มา: \"แอลกอฮอล์กับสมองที่กำลังหลับ\" (Colrain, Nicholas & Baker), คู่มือวิทยาคลินิก - ตรวจสอบโดยผู้ทรงคุณวุฒิ และจัดทำโดย NIH\n\nสถาปัตยกรรมแอลกอฮอล์และการนอนหลับ\nแอลกอฮอล์ทำให้รู้สึกสงบ จึงช่วยลดระยะเวลาในการนอนหลับและเพิ่มการนอนหลับลึกในช่วงครึ่งแรกของคืนแต่ก็ต้องแลกมาด้วยค่าใช้จ่าย: แอลกอฮอล์ไปกดการนอนหลับ REM (การเคลื่อนไหวของดวงตาอย่างรวดเร็ว) ซึ่งเป็นขั้นตอนการฟื้นฟูที่เกี่ยวข้องกับการรวมความทรงจำและการควบคุมอารมณ์ และการนอนหลับเป็นชิ้น ๆ ในช่วงครึ่งหลังของคืนขณะที่มันถูกเผาผลาญ\n\nคืนแรกงดแอลกอฮอล์\nเนื่องจากแอลกอฮอล์ไประงับการนอนหลับฝัน REM คืนแรกที่ไม่มีแอลกอฮอล์มักจะทำให้ REM ฟื้นตัวขึ้นได้ ความฝันที่ชัดเจนและการนอนหลับที่เบาลงและแตกสลาย ในขณะที่รูปแบบการนอนปกติกลับมาอีกครั้งนี่เป็นเรื่องปกติของการฟื้นฟูชั่วคราว\n\nการกู้คืนเริ่มต้นขึ้น\nเมื่อสมองปรับตัวในช่วงวันและสัปดาห์ต่อมา REM และคุณภาพการนอนหลับโดยรวมจะดีขึ้นการรบกวนการนอนหลับเป็นหนึ่งในอาการที่เกี่ยวข้องกับการถอนตัวอย่างต่อเนื่องมากที่สุด แต่มีแนวโน้มเข้าสู่ภาวะปกติด้วยการงดเว้นอย่างต่อเนื่อง\n\nหมายเหตุเกี่ยวกับการดื่มหนัก\nสำหรับผู้ที่ดื่มหนักหรือดื่มเป็นเวลานานในแต่ละวัน ในช่วง 24 ชั่วโมงแรกอาจทำให้เกิดอาการถอนยาได้ (วิตกกังวล เหงื่อออก ตัวสั่น คลื่นไส้)การถอนตัวอย่างรุนแรงอาจเป็นอันตรายได้ หากคุณดื่มหนักทุกวัน ให้ปรึกษาแพทย์ก่อนที่จะหยุดกะทันหัน';

  @override
  String get alcoholReferenceDay3 =>
      'วันที่สาม: ช่วงพีคของอาการถอน\n\nแหล่งที่มา: \"Alcohol Withdrawal\", StatPearls — ผ่านการทบทวนโดยผู้ทรงคุณวุฒิ, NIH National Library of Medicine\n\nประมาณ 72 ชั่วโมง\nอาการถอนแอลกอฮอล์อาจเริ่มภายในไม่กี่ชั่วโมงและมักถึงจุดสูงสุดราว 72 ชั่วโมง StatPearls ระบุอาการสั่น นอนไม่หลับ กระสับกระส่าย เหงื่อออก ความดันโลหิตสูง หัวใจเต้นเร็ว และชัก เป็นสัญญาณของภาวะตื่นตัวมากเกินนี้\n\nสามวันที่แข็งแกร่ง\nการมาถึง 72 ชั่วโมงเป็นหมุดหมายใหญ่ เพราะตรงกับช่วงพีคที่มีหลักฐานบันทึกไว้ของอาการเฉียบพลันหลายอย่าง\n\nอาการถอนรุนแรงอาจมาทีหลัง\nภาวะเพ้อจากการถอนแอลกอฮอล์ (delirium tremens) อาจเกิดในช่วง 3–8 วันหลังหยุดดื่มและอาจถึงแก่ชีวิตได้ อาการถอนรุนแรงเป็นภาวะฉุกเฉินทางการแพทย์ ผู้ที่ดื่มหนักทุกวันหรือเคยมีอาการชักหรือภาวะเพ้อจากการถอนควรขอคำแนะนำทางการแพทย์ แทนการหยุดทันทีโดยไม่มีการช่วยเหลือ\n\nอาการที่ต้องเฝ้าระวัง\nไข้ กระสับกระส่ายรุนแรง เหงื่อออกมาก ประสาทหลอน สับสน ชัก หัวใจเต้นเร็วมาก หรือความดันโลหิตสูงมาก ต้องได้รับการดูแลทางการแพทย์อย่างเร่งด่วน';

  @override
  String get alcoholReferenceDay7 =>
      'ระบบภูมิคุ้มกันฟื้นตัวได้อย่างไร\n\nที่มา: \"แอลกอฮอล์และระบบภูมิคุ้มกัน\" (Sarkar, Jung & Wang), การวิจัยแอลกอฮอล์: บทวิจารณ์ปัจจุบัน - ตรวจสอบโดยผู้ทรงคุณวุฒิ และจัดทำโดย NIH\n\nแอลกอฮอล์ทำให้ภูมิคุ้มกันอ่อนแอลงอย่างไร\nแอลกอฮอล์ทำให้ระบบภูมิคุ้มกันอ่อนแอลงได้หลายวิธีแม้แต่การดื่มหนักเพียงครั้งเดียวก็สามารถลดความสามารถในการต่อสู้กับการติดเชื้อได้นานถึง 24 ชั่วโมงการใช้ในระยะยาวจะช่วยลดเซลล์เม็ดเลือดขาว รบกวนสัญญาณภูมิคุ้มกัน และทำลายการป้องกันของลำไส้และปอด เพิ่มความเสี่ยงของการติดเชื้อและทำให้บาดแผลหายช้า\n\nการลบคำสบประมาท\nผลกระทบหลายอย่างจะดีขึ้นเมื่อแอลกอฮอล์หมดไปเซลล์เม็ดเลือดขาวและการส่งสัญญาณภูมิคุ้มกันเริ่มฟื้นตัว ในขณะที่การป้องกันลำไส้และทางเดินหายใจเริ่มซ่อมแซมภายในสัปดาห์แรก ระบบภูมิคุ้มกันของคุณจะไม่ถูกทำลายลงทุกวันอีกต่อไป และความต้านทานต่อการติดเชื้อทั่วไปก็เริ่มดีขึ้น\n\nกระบวนการที่ค่อยเป็นค่อยไป\nการฟื้นฟูภูมิคุ้มกันโดยสมบูรณ์จะใช้เวลานานกว่าหนึ่งสัปดาห์ และระดับของการซ่อมแซมขึ้นอยู่กับว่าการดื่มหนักและยาวนานเพียงใด แต่การงดแอลกอฮอล์ในสัปดาห์แรกคือจุดเริ่มต้นของการสร้างใหม่';

  @override
  String get alcoholReferenceDay14 =>
      'การฟื้นตัวระยะแรกของสมองระหว่างการงดแอลกอฮอล์\n\nที่มา: Bartsch AJ และคณะ, \"Manifestations of early brain recovery associated with abstinence from alcoholism\", Brain (2007) — ผ่านการทบทวนโดยผู้ทรงคุณวุฒิ\n\nการวัดการฟื้นตัว\nการศึกษานี้ใช้ MRI ติดตามผู้ที่เพิ่งผ่านการถอนพิษและมีภาวะพึ่งพาแอลกอฮอล์ในช่วงสัปดาห์แรก ๆ ของการงดดื่ม แล้วเปรียบเทียบกับกลุ่มควบคุมที่มีสุขภาพดี จึงเห็นการฟื้นตัวทางกายภาพของสมองหลังหยุดดื่ม\n\nปริมาตรสมองเพิ่มกลับขึ้น\nการดื่มแอลกอฮอล์เรื้อรังทำให้สมองหดตัว ส่วนหนึ่งเกิดจากขนาดเซลล์ที่ลดลงแบบย้อนกลับได้ ไม่ใช่เพียงการสูญเสียเซลล์ถาวร เมื่อหยุดดื่ม นักวิจัยวัดพบว่าปริมาตรสมองโดยรวมเพิ่มขึ้นเฉลี่ยเกือบ 2% โดยเด่นบริเวณสมองน้อย สมองส่วนกลาง โพรงสมอง และกลีบหน้า การฟื้นตัวส่วนมากเกิดขึ้นตั้งแต่ช่วงต้น โดยเฉพาะสองสามสัปดาห์แรกที่งดแอลกอฮอล์\n\nสมองน้อยและความสนใจ\nการฟื้นตัวเห็นได้ชัดเป็นพิเศษในบริเวณที่เกี่ยวข้องกับการเคลื่อนไหวและความสนใจ ตัวชี้วัดสุขภาพของเซลล์สมองเพิ่มขึ้นพร้อมกับความสนใจที่ดีขึ้นอย่างวัดผลได้ จึงเป็นการฟื้นตัวทางกายภาพที่มาพร้อมการคิดที่ดีขึ้นจริง\n\nเป็นรากฐาน ไม่ใช่เส้นชัย\nความสามารถระดับสูง เช่น การใช้เหตุผลที่ซับซ้อน ฟื้นตัวอย่างค่อยเป็นค่อยไป แต่สองสัปดาห์แรกแสดงให้เห็นว่าสมองเริ่มฟื้นตัวได้เร็วหลังหยุดแอลกอฮอล์.';

  @override
  String get alcoholReferenceDay30 =>
      'ความดันโลหิตลดลงเมื่อคุณงดแอลกอฮอล์\n\nที่มา: Roerecke และคณะ \"ผลของการลดการบริโภคเครื่องดื่มแอลกอฮอล์ต่อความดันโลหิต: การทบทวนอย่างเป็นระบบและการวิเคราะห์เมตา\" Lancet Public Health (2017) - ตรวจสอบโดยผู้ทรงคุณวุฒิ\n\nหลักฐาน\nการวิเคราะห์เมตานี้รวบรวมการทดลองแบบสุ่ม 36 รายการ (ผู้เข้าร่วมประมาณ 2,865 คน) เพื่อทดสอบว่าจะเกิดอะไรขึ้นกับความดันโลหิตเมื่อผู้คนดื่มน้อยลงพบผลลัพธ์ที่ชัดเจนและขึ้นอยู่กับขนาดยา ยิ่งมีคนลดความดันโลหิตลงมากเท่าไร\n\nผลกระทบใหญ่แค่ไหน?\nผู้ที่ดื่มสองแก้วหรือน้อยกว่าต่อวันพบว่าไม่มีการเปลี่ยนแปลงความดันโลหิตอย่างมีนัยสำคัญจากการลดปริมาณลงผู้ที่ดื่มเครื่องดื่มตั้งแต่ 6 แก้วขึ้นไปต่อวันจะลดการบริโภคลงประมาณครึ่งหนึ่ง โดยที่ความดันโลหิตซิสโตลิกลดลงประมาณ 5.5 มิลลิเมตรปรอท และความดันโลหิตล่างโดยเฉลี่ยประมาณ 4.0 มิลลิเมตรปรอทการลดขนาดนั้นมีความหมายทางคลินิก เทียบได้กับยาลดความดันโลหิตบางชนิด และเพียงพอที่จะลดความเสี่ยงต่อโรคหลอดเลือดสมองและโรคหัวใจในระยะยาวได้\n\nทำไมหนึ่งเดือนจึงมีความสำคัญ\nแอลกอฮอล์ทำให้ความดันโลหิตเพิ่มขึ้นโดยกระตุ้นการตอบสนองต่อความเครียด เพิ่มคอร์ติซอล และทำให้หลอดเลือดแข็งตัวการทดลองในการทบทวนนี้แสดงให้เห็นว่าคุณประโยชน์จะเกิดขึ้นในช่วงหลายสัปดาห์ของการลดลงอย่างต่อเนื่อง ดังนั้น เมื่องดเว้นประมาณหนึ่งเดือน ความดันโลหิตของผู้ที่ดื่มหนักก็จะมีเวลาปรับตัวไปสู่ระดับที่ดีต่อสุขภาพมากขึ้น\n\nผลกระทบจากเกณฑ์\nการทบทวนพบเกณฑ์ที่ชัดเจน: ประโยชน์มุ่งเน้นไปที่ผู้ที่ดื่มมากกว่าสองแก้วต่อวัน และจะเพิ่มมากขึ้นเรื่อยๆ เมื่อดื่มครั้งก่อนหากคุณเป็นคนที่ดื่มน้อย อย่าคาดหวังว่าจะได้รับประโยชน์จากความดันโลหิตโดยเฉพาะเจาะจงนี้ แต่ผู้ที่ดื่มหนักกว่าจะได้รับผลตอบแทนที่แท้จริงและวัดผลได้จากการหยุดดื่ม';

  @override
  String get alcoholReferenceDay60 =>
      'การฟื้นฟูตับหลังจากที่คุณหยุดดื่ม\n\nที่มา: สถาบันแห่งชาติว่าด้วยการใช้แอลกอฮอล์ในทางที่ผิดและโรคพิษสุราเรื้อรัง (NIAAA), \"ผลกระทบของแอลกอฮอล์ต่อร่างกาย\"\n\nแอลกอฮอล์ทำลายตับอย่างไร\nตับประมวลผลแอลกอฮอล์ส่วนใหญ่ที่คุณดื่ม และได้รับความเสียหายหนักNIAAA อธิบายถึงการลุกลามของอาการบาดเจ็บที่ตับจากแอลกอฮอล์ โดยเริ่มจากไขมันสะสมในตับ (ไขมันสะสมในเซลล์ตับ) อาจลุกลามไปสู่โรคตับอักเสบจากแอลกอฮอล์ (การอักเสบ) และเมื่อใช้หนักเป็นเวลานานจนเกิดภาวะพังผืดและโรคตับแข็ง (แผลเป็น)\n\nระยะแรกสามารถย้อนกลับได้\nจุดสำคัญคือตับมีการฟื้นฟูอย่างมาก และความเสียหายในระยะเริ่มแรกสามารถดีขึ้นได้เมื่อหยุดดื่มโดยเฉพาะภาวะไขมันพอกตับมักจะหายไปได้ด้วยการงดเว้นอย่างต่อเนื่องเมื่อปราศจากแอลกอฮอล์ประมาณสองเดือน ตับจะมีเวลาจริงในการล้างไขมันที่สะสม บรรเทาอาการอักเสบ และฟื้นฟูการทำงานที่ดีต่อสุขภาพ ซึ่งโดยทั่วไปจะสะท้อนให้เห็นในระดับเอนไซม์ตับที่ลดลง (ALT และ AST)\n\nเกินตับ\nNIAAA ตั้งข้อสังเกตว่าแอลกอฮอล์ยังทำให้หัวใจ ตับอ่อน และระบบภูมิคุ้มกันเกิดความเครียดอีกด้วยการให้ร่างกายหยุดพักจากแอลกอฮอล์อย่างต่อเนื่องจะช่วยให้ระบบเหล่านี้ฟื้นตัวได้เช่นกัน ซึ่งส่งผลให้มีพลังงานคงที่มากขึ้นและสุขภาพโดยรวมดีขึ้นที่หลายคนสังเกตเห็นในระยะนี้';

  @override
  String get alcoholReferenceDay90 =>
      'การคิดและความทรงจำหลังจากมีสติสามเดือน\n\nที่มา: การทบทวนอย่างเป็นระบบของการฟื้นตัวของระบบประสาทวิทยาหลังจากการเลิกดื่มแอลกอฮอล์ (PubMed Central, 2024) - ทบทวนโดยผู้ทรงคุณวุฒิ\n\nสิ่งที่แสดงหลักฐาน\nการทบทวนนี้รวมการศึกษาที่ติดตามการฟื้นตัวของความคิดและความทรงจำหลังจากที่คนหยุดดื่มทักษะส่วนใหญ่จะเข้าสู่ภาวะปกติภายในเวลาประมาณหกถึงสิบสองเดือน และบางส่วนจะดีขึ้นเร็วขึ้น\n\nอะไรจะปรับปรุงก่อน\nความสามารถเฉพาะสองอย่างโดดเด่นจากการฟื้นตัวเร็วกว่าที่เหลือ: ความเร็วในการประมวลผลขั้นพื้นฐาน (จากการตรวจสอบพบว่าโดยทั่วไปจะฟื้นตัวได้ประมาณหนึ่งเดือน แม้ว่าความแม่นยำในงานที่ซับซ้อนจะล้าหลังก็ตาม) และการอัปเดตหน่วยความจำในการทำงานเมื่อผ่านไปประมาณสามเดือน หลายๆ คนก็สังเกตเห็นความเปลี่ยนแปลงเหล่านี้แล้ว\n\nสิ่งที่ใช้เวลานานกว่า\nความสนใจ การวางแผน การตัดสินใจ การควบคุมแรงกระตุ้น การรับรู้ และความทรงจำ มีการปรับปรุงอย่างต่อเนื่องตลอดกรอบเวลาการกู้คืนหกถึงสิบสองเดือน\n\nสิ่งที่มีอิทธิพลต่อการฟื้นตัว\nบันทึกการทบทวนการฟื้นตัวนั้นขึ้นอยู่กับปัจจัยต่างๆ เช่น อายุ สถานะการสูบบุหรี่ และความสามารถก่อนเกิดโรค แต่ที่น่ายินดีคือปริมาณที่เมาทั้งหมดไม่สอดคล้องกันการฟื้นตัวเป็นวิถีที่คาดหวัง\n\nทำไมมันถึงสำคัญ\nการคิดที่ชัดเจนขึ้นคือการฟื้นฟูในทางปฏิบัติ: การเอาใจใส่และการตัดสินใจที่ดีขึ้นช่วยให้ผู้คนอยู่ในการรักษาและหลีกเลี่ยงการกำเริบของโรค';

  @override
  String get alcoholReferenceDay180 =>
      'การฟื้นตัวของสมองหลังงดแอลกอฮอล์หกเดือน\n\nที่มา: บททบทวนที่ผ่านการประเมินโดยผู้ทรงคุณวุฒิเกี่ยวกับการฟื้นตัวของสมองทั้งด้านโครงสร้างและการทำงานระหว่างการงดใช้สาร (PubMed Central)\n\nการฟื้นตัวยังคงดำเนินต่อ\nการเพิ่มกลับของปริมาตรสมองในช่วงสัปดาห์แรกเป็นเพียงจุดเริ่มต้น บททบทวนนี้พบว่าเมื่อหยุดใช้สารอย่างต่อเนื่อง สมองยังฟื้นตัวได้ทั้งด้านโครงสร้างและการทำงาน เนื้อเทาฟื้นตัว และทางเดินเนื้อขาวที่เสียหายซึ่งเชื่อมการสื่อสารระหว่างบริเวณสมองค่อย ๆ ซ่อมแซมในช่วงหลายเดือน\n\nสมองส่วนหน้า\nการฟื้นตัวของสมองส่วนหน้ามีความสำคัญเป็นพิเศษ เพราะบริเวณนี้เกี่ยวข้องกับการตัดสินใจ การวางแผน และการควบคุมตนเอง เมื่อบริเวณนี้ดีขึ้น ความสามารถในการตัดสินใจและควบคุมแรงกระตุ้นก็แข็งแรงขึ้น\n\nการจัดระบบใหม่และการทำงานของสมอง\nนอกจากการซ่อมแซมทางกายภาพแล้ว การทำงานและการเชื่อมต่อของสมองก็ฟื้นตัวด้วย สมองสามารถจัดระบบการเชื่อมต่อใหม่และเรียนรู้ใหม่ได้ ทำให้ช่วงที่งดแอลกอฮอล์ต่อเนื่องเหมาะต่อการบำบัดและสร้างนิสัยใหม่\n\nสัญญาณของการฟื้นตัว\nเมื่อถึงหกเดือน โครงสร้างและการทำงานของสมองกำลังเคลื่อนไปสู่ภาวะที่สุขภาพดีกว่าอย่างชัดเจน การงดแอลกอฮอล์ต่อไปจะเปิดเวลาให้การฟื้นตัวสะสมมากขึ้น.';

  @override
  String get alcoholReferenceDay365 =>
      'แอลกอฮอล์ ความเสี่ยงมะเร็ง และการหยุด\n\nที่มา: สถาบันมะเร็งแห่งชาติ (NCI), \"ความเสี่ยงจากแอลกอฮอล์และมะเร็ง\"\n\nแอลกอฮอล์ทำให้เกิดมะเร็ง\nNCI ระบุว่ามีความเห็นพ้องต้องกันทางวิทยาศาสตร์ว่าการดื่มแอลกอฮอล์สามารถก่อให้เกิดมะเร็งได้แอลกอฮอล์เชื่อมโยงกับมะเร็งในช่องปาก (ช่องปาก) หลอดลม (คอ) กล่องเสียง (กล่องเสียง) หลอดอาหาร ตับ เต้านม ลำไส้ใหญ่และทวารหนักยิ่งใครดื่มมากเท่าไร และยิ่งดื่มนานเท่าไร ความเสี่ยงก็จะยิ่งสูงขึ้นเท่านั้น\n\nแอลกอฮอล์ขับมะเร็งได้อย่างไร\nกลไกต่างๆ ได้แก่ อะซีตัลดีไฮด์ ซึ่งเป็นผลิตภัณฑ์แอลกอฮอล์ที่เป็นพิษซึ่งทำลาย DNA;ความเครียดจากปฏิกิริยาออกซิเดชั่นและการอักเสบการดูดซึมสารอาหารป้องกันบกพร่องและสำหรับมะเร็งเต้านม ระดับฮอร์โมนเอสโตรเจนเพิ่มขึ้น\n\nความเสี่ยงจะลดลงหลังจากที่คุณหยุด\nที่สำคัญ NCI รายงานว่าการเลิกดื่มมีความสัมพันธ์กับความเสี่ยงที่ลดลงเมื่อเวลาผ่านไป การศึกษาต่างๆ แสดงให้เห็นความเสี่ยงที่เพิ่มขึ้นของโรคมะเร็งในช่องปากและหลอดอาหารลดลงหลังจากหยุด แม้ว่าอาจต้องใช้เวลาหลายปีกว่าจะเสี่ยงกับคนที่ไม่เคยดื่มก็ตามการงดแอลกอฮอล์หนึ่งปีถือเป็นก้าวที่มีความหมายบนเส้นทางนั้น\n\nผลประโยชน์ทับซ้อน\nการมีอายุถึงหนึ่งปียังล็อคการเพิ่มขึ้นของการงดเว้นหัวใจและหลอดเลือดและตับ — ลดความดันโลหิต ลดความเสี่ยงภาวะหัวใจเต้นผิดจังหวะ และการรักษาตับอย่างต่อเนื่อง — ควบคู่ไปกับความเสี่ยงมะเร็งลดลง';

  @override
  String get benzodiazepineReferenceDay7 =>
      'การถอนยาเบนโซไดอะซีพีน: สัปดาห์แรก\n\nที่มา: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings\" องค์การอนามัยโลก (2009), NCBI Bookshelf\n\nความปลอดภัยมาก่อน\nการถอนยาเบนโซไดอะซีพีนอาจทำให้เกิดอาการชักได้ WHO ระบุว่าวิธีที่ปลอดภัยที่สุดคือค่อย ๆ ลดปริมาณเบนโซไดอะซีพีน ซึ่งช่วยบรรเทาอาการถอนและช่วยป้องกันอาการชัก หลังใช้เป็นเวลานานอย่าหยุดยาอย่างกะทันหัน — ควรลดขนาดยาร่วมกับบุคลากรทางการแพทย์\n\nอาการถอนเริ่มเมื่อใด\nช่วงเวลาตาม WHO ขึ้นอยู่กับระยะเวลาการออกฤทธิ์ของยา:\n• ออกฤทธิ์สั้น (oxazepam, alprazolam, temazepam): มักเริ่ม 1–2 วันหลังขนาดสุดท้าย และต่อเนื่อง 2–4 สัปดาห์หรือนานกว่า\n• ออกฤทธิ์ยาว (diazepam, nitrazepam): มักเริ่ม 2–7 วันหลังขนาดสุดท้าย และต่อเนื่อง 2–8 สัปดาห์หรือนานกว่า\nสัปดาห์แรกจึงครอบคลุมช่วงเริ่มอาการตามปกติแม้สำหรับเบนโซไดอะซีพีนออกฤทธิ์ยาว\n\nอาการที่อาจพบ\nWHO ระบุความวิตกกังวล นอนไม่หลับ กระสับกระส่าย กระวนกระวายหรือหงุดหงิด สมาธิหรือความจำลดลง และกล้ามเนื้อตึงหรือปวด\n\nการติดตาม\nความรุนแรงของอาการถอนอาจขึ้นลงอย่างมาก WHO แนะนำให้ติดตามอาการและภาวะแทรกซ้อนอย่างสม่ำเสมอ; ในแนวทางสำหรับสถานที่ปิด บุคลากรทางการแพทย์พูดคุยกับผู้ป่วยทุก 3–4 ชั่วโมง และให้คำอธิบายหรือความมั่นใจตามความจำเป็น';

  @override
  String get benzodiazepineReferenceDay14 =>
      'การถอนเบนโซไดอะซีพีน: สองสัปดาห์\n\nแหล่งที่มา: Poyares และคณะ, \"Chronic benzodiazepine usage and withdrawal in insomnia patients\", Journal of Psychiatric Research (2004), PubMed\n\nสัญญาณการฟื้นตัวจริงในราวสองสัปดาห์\nนักวิจัยติดตามผู้ที่มีอาการนอนไม่หลับเรื้อรังและใช้เบนโซไดอะซีพีนทุกคืนมาหลายปี จากนั้นวัดการนอนอีกครั้ง 15 วันหลังการค่อย ๆ ถอนยา เมื่อเทียบกับช่วงที่ใช้เบนโซไดอะซีพีนเรื้อรัง การหลับแบบคลื่นช้า กิจกรรมเดลตาใน EEG ระหว่างนอน และคุณภาพการนอนที่ผู้เข้าร่วมรายงานดีขึ้นทั้งหมด\n\nการหลับลึกกำลังกลับมา\nการหลับแบบคลื่นช้าเป็นระยะที่ลึกที่สุดของการนอนแบบ non-REM เมื่อถึงวันที่ 15 การหลับแบบคลื่นช้าและกิจกรรมเดลตาเพิ่มขึ้น ขณะที่การนอน non-REM ระยะที่ 2 ลดลงไปในทิศทางของรูปแบบที่พบในกลุ่มควบคุมสุขภาพดี\n\nการฟื้นตัวระยะแรกที่วัดได้\nในผู้เข้าร่วมที่ถอนยาสำเร็จ การนอนแย่ลงทันทีหลังหยุดยา แต่เมื่อถึงการติดตามวันที่ 15 ตัวชี้วัดการหลับลึกแบบวัดได้และคุณภาพการนอนที่รายงานดีขึ้น ทำให้ช่วงสองสัปดาห์เป็นหลักหมายการฟื้นตัวที่เกิดขึ้นจริงและวัดได้';

  @override
  String get benzodiazepineReferenceDay60 =>
      'เบนโซไดอะซีพีน: การทำงานช่วงกลางวันที่แปดสัปดาห์\n\nแหล่งที่มา: Tsunoda และคณะ, \"Effects of discontinuing benzodiazepine-derivative hypnotics on postural sway and cognitive functions in the elderly\", International Journal of Geriatric Psychiatry (2010), PubMed\n\nสัญญาณการฟื้นตัวที่วัดได้ในแปดสัปดาห์\nนักวิจัยติดตามผู้ใหญ่อายุ 60 ปีขึ้นไปที่อาศัยในสถานดูแลและใช้ยานอนหลับกลุ่มเบนโซไดอะซีพีน โดยค่อย ๆ ลดขนาดยาจนหยุดภายในสามสัปดาห์ แล้วทำแบบทดสอบการรับรู้และการทรงตัวอีกครั้งเมื่อสิ้นสุดสัปดาห์ที่แปด\n\nสมาธิและความจำดีขึ้น\nในผู้เข้าร่วม 26 คนที่ทำการศึกษาจนครบ คะแนนความจำทันที สมาธิ และภาษาเพิ่มขึ้นอย่างมีนัยสำคัญ เป็นการพัฒนาการทำงานช่วงกลางวันที่วัดได้จริงหลังหยุดเบนโซไดอะซีพีน\n\nยืนได้มั่นคงขึ้น\nค่าการแกว่งของร่างกายขณะหลับตาก็ดีขึ้นอย่างมีนัยสำคัญเช่นกัน ผู้วิจัยสรุปว่าการหยุดยานอนหลับกลุ่มเบนโซไดอะซีพีนในกลุ่มผู้สูงอายุนี้สัมพันธ์กับความมั่นคงของร่างกายที่ดีขึ้นและการฟื้นตัวของการทำงานด้านการรับรู้ในช่วงกลางวัน\n\nการนอนยังคงมั่นคง\nผู้ที่ทำการศึกษาจนครบไม่ได้รายงานว่าการนอนแย่ลงจากแบบสอบถามการนอนที่ใช้ เมื่อสิ้นสุดสัปดาห์ที่แปด การศึกษาพบการพัฒนาช่วงกลางวันที่วัดได้โดยไม่มีการลดลงของคุณภาพการนอนตามที่ผู้เข้าร่วมรายงาน';

  @override
  String get benzodiazepineReferenceDay90 =>
      'สามเดือนหลังหยุดเบนโซไดอะซีพีน: คิดไวขึ้น อาการง่วงซึมลดลง\n\nแหล่งที่มา: Rickels และคณะ งานวิจัยเรื่องสมรรถนะด้านการเคลื่อนไหวและการคิดของผู้ใช้เบนโซไดอะซีพีนระยะยาวก่อน ระหว่าง และหลังหยุดยา ตีพิมพ์ในวารสาร Journal of Clinical Psychopharmacology ปี 1999 และบันทึกใน PubMed\n\nสัญญาณการฟื้นตัวที่วัดได้ใน 12 สัปดาห์\nนักวิจัยทดสอบผู้ใช้เบนโซไดอะซีพีนระยะยาวก่อนเริ่มค่อย ๆ ลดยา และทดสอบอีกครั้งที่ 5 และ 12 สัปดาห์หลังการลดยา มีข้อมูลที่ 12 สัปดาห์จาก 77 คน และผู้ที่หยุดยาได้สำเร็จได้รับการยืนยันว่าไม่ใช้เบนโซไดอะซีพีนด้วยการตรวจเลือดทุกสัปดาห์\n\nการทำงานด้านการรู้คิดเร็วขึ้น\nผู้ที่หยุดเบนโซไดอะซีพีนได้สำเร็จทำแบบทดสอบคัดลอกสัญลักษณ์และแทนตัวเลขด้วยสัญลักษณ์ได้เร็วกว่าผู้เข้าร่วมที่ยังใช้เบนโซไดอะซีพีน ความแตกต่างยังมีนัยสำคัญเมื่อคำนึงถึงอายุ การศึกษา และคะแนนตั้งต้น\n\nอาการง่วงซึมทางความคิดและทางกายลดลง\nผู้ที่หยุดยาได้สำเร็จยังรายงานอาการง่วงซึมทางความคิดและทางกายน้อยกว่าผู้ที่ยังใช้เบนโซไดอะซีพีน\n\nสามเดือนอาจเป็นอย่างไร\nสำหรับผู้ที่หยุดยาได้สำเร็จในงานวิจัยนี้ เมื่อครบ 12 สัปดาห์หลังการลดยา พบว่าความเร็วในการประมวลผลดีขึ้นอย่างวัดได้ และอาการง่วงซึมทางความคิดกับทางกายลดลง ความคิดไวขึ้นและความรู้สึกมึนซึมเบาลง.';

  @override
  String get benzodiazepineReferenceDay180 =>
      'การคิดและความจำที่หกเดือน: การดีขึ้นที่วัดผลได้\n\nแหล่งที่มา: Tata et al., \"Lack of cognitive recovery following withdrawal from long-term benzodiazepine use,\" Psychological Medicine (1994), PubMed\n\nการศึกษาทำอะไร\nงานวิจัยนี้ทดสอบผู้ใช้เบนโซไดอะซีพีนระยะยาว 21 คน ก่อนหยุดยา หลังหยุดยาทันที และอีกครั้งหลังหยุดยาได้หกเดือน โดยเปรียบเทียบกับกลุ่มควบคุมที่ใกล้เคียงกัน\n\nพบอะไร\nก่อนหยุดยา ผู้เข้าร่วมมีปัญหาด้านการเรียนรู้ด้วยคำพูด ความจำ ความเร็วการเคลื่อนไหว การประสานงานทางสายตา และการใช้เหตุผลทางสายตา หลังหยุดยาทันทีแทบไม่มีการเปลี่ยนแปลง แต่เมื่อครบหกเดือน หลายด้านดีขึ้นอย่างวัดผลได้\n\nความหมาย\nเมื่อครบหกเดือน การเรียนรู้ด้วยคำพูด ความจำ ความเร็วการเคลื่อนไหว และการประสานงานทางสายตาฟื้นตัวอย่างวัดผลได้ การดีขึ้นเห็นได้ชัดแล้วและยังอาจดำเนินต่อไป\n\nภาพรวม\nหากยังรู้สึกสมองล้าเมื่อครบหกเดือน ผลการศึกษานี้สอดคล้องกับการที่การฟื้นตัวต้องใช้เวลา งานวิจัยระยะยาวชี้ว่าการดีขึ้นสามารถดำเนินต่อไปหลังช่วงนี้ได้';

  @override
  String get benzodiazepineReferenceDay365 =>
      'หนึ่งปีหลังเบนโซไดอะซีพีน: การคิดและความจำยังฟื้นตัว\n\nแหล่งที่มา: Barker et al., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), PubMed\n\nหลักฐานที่แข็งแรงที่สุดที่มี\nนักวิจัยรวมการศึกษาที่ทดสอบผู้ใช้เบนโซไดอะซีพีนระยะยาวอีกครั้งหลังหยุดยาอย่างน้อยหกเดือน ผลรวมแสดงการฟื้นตัวที่ชัดเจนของการคิดและความจำหลังหยุดยา\n\nข่าวดี\nการศึกษารวมพบการดีขึ้นจริงและวัดผลได้ในหลายด้านของการคิดและความจำ ประมาณหนึ่งปี การฟื้นตัวกว้างขึ้นเมื่อเทียบกับช่วงยังใช้ยา\n\nการฟื้นตัวยังดำเนินต่อ\nหลักฐานรวมแสดงการฟื้นตัวกว้างของการคิดและความจำ เมื่อครบหนึ่งปี คุณอยู่ไกลตามแนวโน้มการฟื้นตัวที่เริ่มวัดได้ตั้งแต่หกเดือน\n\nหนึ่งปีหมายถึงอะไร\nประมาณหนึ่งปี การคิด ความจำ และความชัดเจนทางความคิดมักดีขึ้นมาก หากบางด้านยังตามหลังอยู่ก็ยังสอดคล้องกับหลักฐาน และการฟื้นตัวอาจดำเนินต่อไป';

  @override
  String get benzodiazepineReferenceDay540 =>
      '18 เดือนหลังเบนโซไดอะซีพีน: ฟื้นตัวช้าแต่เกิดขึ้นจริง\n\nแหล่งที่มา: Ashton, \"Protracted withdrawal syndromes from benzodiazepines,\" Journal of Substance Abuse Treatment (1991), PubMed\n\nเหตุใดการฟื้นตัวจึงใช้เวลานาน\nเบนโซไดอะซีพีนออกฤทธิ์ต่อ GABA ซึ่งเป็นระบบสำคัญที่ช่วยให้สมองสงบ การใช้ระยะยาวเปลี่ยนการตอบสนองของระบบนี้ และการเปลี่ยนแปลงอาจใช้เวลาหลายเดือนในการย้อนกลับ จึงมักมองการฟื้นตัวเป็นเดือนมากกว่าสัปดาห์\n\n18 เดือนอยู่ตรงไหน\nAshton อธิบายอาการถอนยาที่ยืดเยื้อซึ่งอาจใช้เวลาหลายเดือนจึงค่อย ๆ ลดลง เมื่อครบ 18 เดือน ช่วงที่หนักที่สุดมักอยู่ไกลแล้วสำหรับคนส่วนใหญ่ และความวิตกกังวล การเปลี่ยนแปลงทางประสาทสัมผัส และภาวะสมองล้าที่เหลืออยู่มักลดลงมาก\n\nค่อย ๆ ย้อนกลับได้\nAshton อธิบายการเปลี่ยนแปลงพื้นฐานว่าเป็น \"การเปลี่ยนแปลงการทำงานของระบบประสาทส่วนกลางที่ค่อย ๆ ย้อนกลับได้\" ระยะเวลาที่ยาวสะท้อนความลึกของการปรับตัวต่อยา ไม่ใช่ความเสียหายถาวรในคนส่วนใหญ่\n\nสัญญาณการฟื้นตัว\nเมื่อครบ 18 เดือน ระบบ GABA ของสมองมีเวลาปรับตัวมานาน ทิศทางโดยรวมคือการฟื้นตัวต่อไปสู่การทำงานที่เป็นปกติมากขึ้น';

  @override
  String get benzodiazepineReferenceDay730 =>
      'สองปีหลังเบนโซไดอะซีพีน: ความก้าวหน้าครั้งใหญ่และยั่งยืน\n\nแหล่งที่มา: Barker et al., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), PubMed\n\nหมุดหมายสำคัญของการฟื้นตัว\nสองปีเป็นหมุดหมายสำคัญ โดยเฉพาะหลังช่วงถอนยาที่ยาวนาน ระยะอาการช่วงต้นและอาการยืดเยื้อมักอยู่ไกลแล้ว และความก้าวหน้าจากปีแรกมีเวลาอีกปีให้มั่นคงขึ้น\n\nหลักฐานสนับสนุนอะไร\nการศึกษารวมแสดงการฟื้นตัวในหลายด้านหลังหยุดยา เมื่อครบสองปี หลักฐานสนับสนุนภาพของการฟื้นตัวต่อเนื่องด้านการนอน อารมณ์ ความจำ และความคิดที่ชัดเจน แม้ความเร็วในการฟื้นตัวจะแตกต่างกันในแต่ละคน\n\nสัญญาณการฟื้นตัว\nการศึกษารวมแสดงการฟื้นตัวในหลายด้านของการคิดและความจำ เมื่อครบสองปี การฟื้นตัวอย่างต่อเนื่องเป็นสิ่งที่หลักฐานสนับสนุน\n\nรักษามุมมอง\nสองปีให้เวลานานแก่การนอน อารมณ์ ความจำ และความชัดเจนทางความคิดในการฟื้นตัว หลักฐานแสดงความก้าวหน้าที่มีนัยสำคัญ และการดีขึ้นยังอาจดำเนินต่อไป';

  @override
  String get benzodiazepineReferenceDay1095 =>
      'สามปีหลังเบนโซไดอะซีพีน: การฟื้นตัวระยะยาว\n\nแหล่งที่มา: Barker et al., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), PubMed\n\nมุมมองระยะยาว\nสามปีอยู่ไกลบนเส้นทางการฟื้นตัวหลังเบนโซไดอะซีพีน สำหรับคนส่วนใหญ่ แม้เคยมีอาการถอนยารุนแรงและยืดเยื้อ อาการที่รบกวนชีวิตมักอยู่ไกลแล้ว และคุณภาพชีวิตอาจแตกต่างจากช่วงใช้ยาอย่างมาก\n\nผลจากการวิเคราะห์อภิมาน\nการศึกษารวมของผู้ใช้ระยะยาวแสดงการฟื้นตัวในหลายด้านหลังหยุดยา ตลอดหลายปี แนวโน้มหลักคือการดีขึ้นกว้างของการคิด ความจำ และการทำงานในชีวิตประจำวัน\n\nสัญญาณการฟื้นตัว\nงานวิจัยระยะยาวแสดงการฟื้นตัวในหลายด้านของการคิดและความจำ เมื่อครบสามปี ระยะถอนยาช่วงต้นและช่วงยืดเยื้อมักอยู่ไกลแล้ว และความก้าวหน้าเดิมมีเวลาหลายปีให้มั่นคงขึ้น\n\nข้อความแห่งความหวัง\nการฟื้นตัวหลังเบนโซไดอะซีพีนอาจเป็นเส้นทางที่ยาวและยาก สามปีของการเปลี่ยนแปลงต่อเนื่องเป็นความสำเร็จครั้งใหญ่ และการดีขึ้นอาจดำเนินต่อไปตามเวลา';

  @override
  String get benzodiazepineReferenceDay1460 =>
      'สี่ปีหลังเบนโซไดอะซีพีน: ความก้าวหน้าที่ยั่งยืน\n\nแหล่งที่มา: แนวทางเวชปฏิบัติร่วมเรื่องการค่อย ๆ ลดยาเบนโซไดอะซีพีน แนวทางสหสาขาวิชาชีพที่นำโดย ASAM (2025)\n\nสิ่งที่แนวทางสนับสนุน\nแนวทางระบุว่าการปรับตัวหลังหยุดเบนโซไดอะซีพีนอาจกินเวลานานกว่าช่วงที่ยาถูกกำจัดออกจากร่างกายมาก บางคนอาจมีอาการถอนยาที่ยืดเยื้อนานหลายเดือนหรือหลายปี จึงควรติดตามและสนับสนุนการฟื้นตัวเป็นรายบุคคล\n\nสี่ปีหมายถึงอะไร\nแนวทางไม่ได้กำหนดจุดสิ้นสุดทางชีวภาพที่เหมือนกันสำหรับทุกคนเมื่อครบสี่ปี ดังนั้นหมุดหมายนี้จึงฉลองสี่ปีของการเปลี่ยนแปลงที่ต่อเนื่องโดยไม่กล่าวเกินจริง และยอมให้การฟื้นตัวดำเนินไปตามจังหวะของแต่ละคน\n\nหมุดหมายที่ควรฉลอง\nสี่ปีคือ 1,460 วัน นี่คือความสำเร็จที่ยั่งยืน ไม่ว่าการฟื้นตัวจะราบรื่น ขึ้นลง หรืออยู่ระหว่างนั้น';

  @override
  String get benzodiazepineReferenceDay1825 =>
      'ห้าปีหลังเบนโซไดอะซีพีน: ความสำเร็จระยะยาว\n\nแหล่งที่มา: แนวทางเวชปฏิบัติร่วมเรื่องการค่อย ๆ ลดยาเบนโซไดอะซีพีน แนวทางสหสาขาวิชาชีพที่นำโดย ASAM (2025)\n\nไม่มีเส้นชัยเดียว\nแนวทางเน้นว่าการถอนเบนโซไดอะซีพีนและการปรับตัวหลังหยุดยาแตกต่างกันในแต่ละคน และไม่ได้กำหนดจุดห้าปีที่ใช้กับทุกคนเพื่อประกาศว่าสมองหรือร่างกายฟื้นตัวเต็มที่แล้ว\n\nห้าปีแสดงถึงอะไร\nห้าปีคือวันครบรอบระยะยาวอย่างแท้จริง: 1,825 วันของการเปลี่ยนแปลงที่ต่อเนื่อง พร้อมเวลาหลายปีให้กิจวัตร การสนับสนุน และชีวิตประจำวันหยั่งราก\n\nให้เครดิตกับงานที่ทำจริง\nหมุดหมายนี้ฉลองความพยายามที่เกิดขึ้นจริง ไม่ใช่เส้นตายทางการแพทย์ที่แต่งขึ้น ความก้าวหน้าต่อเนื่องห้าปีมีความหมายในตัวเอง';

  @override
  String get cocaineReferenceDay1 =>
      'การถอนโคเคน: 24 ชั่วโมงแรก\n\nแหล่งที่มา: \"Withdrawal Syndromes\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nโคเคนกับสมอง\nโคเคนยับยั้งการนำโดปามีนและสารสื่อประสาทโมโนเอมีนอื่นกลับเข้าสู่เซลล์ในวงจรรางวัลของสมอง ทำให้โดปามีนสะสมและก่อให้เกิดความรู้สึกเคลิบเคลิ้มและพลังงานอย่างมาก เมื่อใช้เป็นประจำ สมองจะปรับตัวโดยลดการทำงานของระบบนี้ ทำให้กิจกรรมปกติอาจให้ความรู้สึกจืดชืดเมื่อไม่มีสาร\n\nช่วง \"crash\"\nStatPearls อธิบายว่าการถอนสารกระตุ้นเริ่มด้วยช่วง \"crash\" หลังหยุดใช้ ซึ่งมีลักษณะเด่นคือซึมเศร้ามาก นอนมาก หิว อารมณ์ตก และการเคลื่อนไหวกับความคิดช้าลงอย่างชัดเจน ใน 24 ชั่วโมงแรกมักพบ:\n• อ่อนเพลียอย่างมากและต้องการนอนมากขึ้น\n• อารมณ์ซึมเศร้า รวมถึงการเคลื่อนไหวและการคิดที่ช้าลง\n• ความอยากอาหารเพิ่มขึ้น เพราะโคเคนกดความอยากอาหาร\n\nวรรณกรรมด้านการเสพติดโดยรวมยังรายงานความอยากใช้โคเคนอย่างมาก ความหงุดหงิด และความวิตกกังวลได้บ่อยในช่วงนี้ แม้ StatPearls จะไม่ได้ระบุอาการเหล่านี้เป็นส่วนของช่วง crash โดยเฉพาะ\n\nแตกต่างจากสารบางชนิด\nStatPearls ระบุว่าการถอนสารกระตุ้นรักษาด้วยการสังเกตอาการและการดูแลแบบประคับประคอง โดยทั่วไปไม่ทำให้เกิดอาการชักหรือภาวะเพ้อเหมือนการถอนแอลกอฮอล์หรือเบนโซไดอะซีพีน อันตรายสำคัญอยู่ที่ด้านจิตใจ เพราะอาจเกิดภาวะซึมเศร้า และในผู้ใช้หนักอาจมีความคิดฆ่าตัวตายในช่วง crash จึงควรมีการสนับสนุนและติดตามอาการ\n\nยังไม่มียาที่ได้รับอนุมัติ\nปัจจุบันยังไม่มียาที่ได้รับอนุมัติสำหรับรักษาการถอนโคเคนโดยเฉพาะ การดูแลจึงเป็นแบบประคับประคอง และแนวทางที่ไม่ใช้ยา เช่น การจัดการแรงเสริมตามเงื่อนไข เป็นการรักษาที่มีหลักฐานสนับสนุนสำหรับความผิดปกติจากการใช้สารที่เป็นต้นเหตุ.';

  @override
  String get cocaineReferenceDay3 =>
      'สามวันโดยไม่ใช้โคเคน: ช่วงที่ท้าทายที่สุด\n\nแหล่งที่มา: \"Cocaine Toxicity\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nโคเคนส่งผลต่อร่างกายอย่างไร\nStatPearls ระบุว่าโคเคนยับยั้งการนำโดปามีน นอร์อิพิเนฟริน และเซโรโทนินกลับเข้าสู่เซลล์ ทำให้การกระตุ้นระบบซิมพาเทติกยาวนานขึ้น กลไกนี้เป็นทั้งที่มาของความเคลิบเคลิ้มและอันตราย เพราะโคเคนสามารถกระทบอวัยวะได้เกือบทุกระบบ\n\nวันที่ 2–4: จุดสูงสุดของการถอนทางจิตใจ\nเมื่อถึงวันที่สาม ช่วง crash เฉียบพลันมักเปลี่ยนเป็นช่วงที่อาการถอนทางจิตใจรุนแรงที่สุด:\n• อารมณ์ตกและซึมเศร้ารุนแรงที่สุด\n• สูญเสียความรู้สึกเพลิดเพลิน\n• ความอยากใช้รุนแรงเมื่อเจอตัวกระตุ้น\n• วิตกกังวลและกระสับกระส่าย\n• การนอนผิดปกติ บางคนนอนมากเกินไป บางคนนอนไม่หลับ\n\nอันตรายต่อหัวใจและหลอดเลือดเริ่มลดลง\nStatPearls ระบุว่าความเป็นพิษต่อหัวใจและหลอดเลือดเป็นผลที่อันตรายถึงชีวิตที่สุดของโคเคน ได้แก่ อัตราการเต้นของหัวใจและความดันโลหิตที่สูงขึ้น ความต้องการออกซิเจนของกล้ามเนื้อหัวใจที่เพิ่มขึ้น การหดเกร็งของหลอดเลือดหัวใจ และการกระตุ้นเกล็ดเลือด ซึ่งเพิ่มความเสี่ยงต่อหัวใจเต้นผิดจังหวะ กล้ามเนื้อหัวใจตาย และโรคหลอดเลือดสมองแม้ในคนอายุน้อย โคเคนเองมีครึ่งชีวิตสั้นประมาณหนึ่งชั่วโมง และภายในวันที่สามตัวยาได้ออกจากร่างกายแล้ว อย่างไรก็ตาม StatPearls ระบุว่าเมแทบอไลต์ยังอาจทำให้หลอดเลือดหดตัวได้หลายชั่วโมงหลังใช้ และเมแทบอไลต์ชนิดหนึ่งอาจคงอยู่นานหลายสัปดาห์ ดังนั้นภาระต่อหัวใจและหลอดเลือดบางส่วนอาจอยู่นานกว่าตัวยาเอง\n\nเส้นทางต่อจากนี้\nช่วงเฉียบพลันรุนแรง แต่โดยทั่วไปอาการทางจิตใจ เช่น ภาวะซึมเศร้า ความอยากใช้ และการสูญเสียความรู้สึกเพลิดเพลิน เป็นอาการที่ต้องการการสนับสนุนมากที่สุดและอาจคงอยู่นานที่สุด.';

  @override
  String get cocaineReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่ใช้โคเคน: เริ่มฟื้นตัวทางกาย\n\nแหล่งที่มา: \"Withdrawal Syndromes\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nช่วงเฉียบพลันกำลังสิ้นสุด\nStatPearls อธิบายว่าการถอนโคเคนเปลี่ยนจากช่วง crash แรกไปสู่ระยะฟื้นตัวที่ยาวขึ้น เมื่อสิ้นสัปดาห์แรก อาการที่แย่ที่สุดมักเริ่มทุเลา ขณะที่ระบบโดปามีนยังคงฟื้นตัว\n\nการฟื้นตัวทางกายกำลังดำเนินต่อ\nเมื่อการกระตุ้นระบบซิมพาเทติกจากโคเคนหยุดลง ผลกระทบต่อหัวใจและหลอดเลือด ความอยากอาหาร การนอน และทางเดินหายใจจะเริ่มย้อนกลับในช่วงวันและสัปดาห์ถัดไป:\n• อัตราการเต้นของหัวใจและความดันโลหิตค่อย ๆ กลับเข้าใกล้ภาวะปกติ\n• ความอยากอาหารค่อย ๆ กลับมา เพราะโคเคนกดความอยากอาหารอย่างมาก\n• รูปแบบการนอนเริ่มคงที่\n• ช่องจมูกเริ่มสมาน หากใช้โคเคนโดยการสูดเข้าจมูก\n\nอาการทางจิตใจอาจยังคงอยู่\nStatPearls ระบุว่าภาวะซึมเศร้าและการสูญเสียความรู้สึกเพลิดเพลินเป็นลักษณะของการถอนสารกระตุ้นและอาจอยู่นานกว่าอาการทางกาย:\n• อารมณ์ยังคงต่ำ แต่โดยทั่วไปไม่รุนแรงเท่าช่วงสูงสุด\n• ความอยากใช้เมื่อเจอตัวกระตุ้นยังคงรุนแรง\n• สมาธิและแรงจูงใจยังได้รับผลกระทบ\n\nระยะหลังช่วงถอนเฉียบพลัน\nจากนั้นการฟื้นตัวจะดำเนินต่อเป็นเวลาหลายสัปดาห์หรือหลายเดือน โดยอารมณ์ ความอยากใช้ และความชัดเจนในการคิดค่อย ๆ ดีขึ้นอย่างสม่ำเสมอ การเข้าใจรูปแบบนี้ช่วยให้มองช่วงฟื้นตัวที่ช้ากว่าได้ชัดเจนขึ้น.';

  @override
  String get cocaineReferenceDay14 =>
      'สองสัปดาห์โดยไม่ใช้โคเคน: เริ่มมั่นคงขึ้น\n\nแหล่งที่มา: \"Withdrawal Syndromes\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nครบสองสัปดาห์\nเมื่อถึงสองสัปดาห์ อาการ crash ที่รุนแรง เช่น ภาวะซึมเศร้าลึก นอนมาก และการเคลื่อนไหวกับความคิดที่ช้าลง มักทุเลาลงมากแล้ว การฟื้นตัวจึงมุ่งไปที่การฟื้นฟูสุขภาพสมองและอารมณ์มากขึ้น\n\nอารมณ์และสภาวะทางใจ\nเมื่อครบสองสัปดาห์ อารมณ์อาจยังต่ำกว่าปกติขณะที่ระบบโดปามีนฟื้นตัว เมื่อเทียบกับสัปดาห์แรก การสูญเสียความรู้สึกเพลิดเพลินอย่างมากเริ่มลดลง และช่วงเวลาที่รู้สึกดีอย่างแท้จริงเริ่มกลับมา\n\nความอยากใช้และตัวกระตุ้น\nความอยากใช้ที่ถูกกระตุ้นจากสถานการณ์ยังเป็นความท้าทายสำคัญในช่วงนี้ สมองได้สร้างความเชื่อมโยงที่แน่นแฟ้นระหว่างการใช้โคเคนกับสถานที่ ผู้คน อารมณ์ และกิจกรรมบางอย่าง การพบตัวกระตุ้นเหล่านี้อาจทำให้เกิดความอยากใช้อย่างรุนแรงแม้อารมณ์โดยรวมจะดีขึ้น การหลีกเลี่ยงสภาพแวดล้อมที่มีความเสี่ยงสูงและสร้างความเชื่อมโยงใหม่จึงมีความสำคัญ\n\nการนอนดีขึ้น\nโดยทั่วไปการนอนจะคงที่และฟื้นฟูร่างกายได้มากขึ้นเมื่อครบสองสัปดาห์ เทียบกับช่วงถอนเฉียบพลัน การนอนที่ดีขึ้นช่วยเรื่องอารมณ์ ความชัดเจนในการคิด และความสามารถในการรับมือกับความอยากใช้\n\nสร้างรากฐาน\nเนื่องจากการรักษาความผิดปกติจากการใช้สารกระตุ้นที่มีหลักฐานสนับสนุนเป็นแนวทางด้านพฤติกรรม เช่น การจัดการแรงเสริมตามเงื่อนไข การบำบัด และการสนับสนุนจากเพื่อนร่วมประสบการณ์ ช่วงสองสัปดาห์จึงเป็นเวลาสำคัญในการเชื่อมต่อกับระบบสนับสนุนที่จะช่วยการฟื้นตัวในระยะยาว.';

  @override
  String get cocaineReferenceDay60 =>
      'สองเดือนโดยไม่ใช้โคเคน: อารมณ์และระบบรางวัลเริ่มฟื้นตัว\n\nแหล่งที่มา: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\nสมองกำลังทำอะไร\nบททบทวนนี้สรุปงานวิจัยในมนุษย์และสัตว์เกี่ยวกับสิ่งที่เกิดขึ้นกับสมองเมื่อหยุดใช้โคเคน การใช้โคเคนเรื้อรังเปลี่ยนแปลงระบบโดปามีนและลดกิจกรรมในเปลือกสมองส่วนหน้า การฟื้นตัวของระบบเหล่านี้เป็นพื้นฐานของการดีขึ้นด้านอารมณ์และแรงจูงใจที่ผู้คนสังเกตได้ในช่วงแรกของการงดใช้\n\nความก้าวหน้าของระบบรางวัล\nในการศึกษาในสัตว์ การเปลี่ยนแปลงของตัวรับโดปามีนและโปรตีนขนส่งที่เกี่ยวข้องกับโคเคนค่อย ๆ กลับเข้าใกล้ระดับปกติเมื่อมีการงดใช้อย่างต่อเนื่อง เมื่อระบบรางวัลฟื้นตัว การสูญเสียความรู้สึกเพลิดเพลินอย่างมากจะลดลง และรางวัลในชีวิตประจำวัน เช่น อาหาร ความสัมพันธ์ และความสำเร็จ จะกลับมารู้สึกมีคุณค่าอีกครั้ง\n\nสัญญาณของการฟื้นตัว\nเมื่อครบสองเดือน อารมณ์ดีขึ้นและการนอนคงที่มากขึ้น ขณะที่ระบบโดปามีนและเปลือกสมองส่วนหน้ายังคงฟื้นตัว งานวิจัยในไพรเมตแสดงให้เห็นว่าการเปลี่ยนแปลงของตัวรับ D1 และตัวขนส่งที่เกี่ยวข้องกับโคเคนค่อย ๆ กลับเข้าใกล้ระดับของกลุ่มควบคุมเมื่อมีการงใช้อย่างต่อเนื่อง.';

  @override
  String get cocaineReferenceDay90 =>
      'สามเดือนโดยไม่ใช้โคเคน: ตัวบ่งชี้โดปามีนฟื้นตัว\n\nแหล่งที่มา: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\nเหตุใด 90 วันจึงมีความหมาย\nบททบทวนนี้ชี้ว่าช่วงสามเดือนมีความหมายทางชีววิทยา ในไพรเมตที่ไม่ใช่มนุษย์ ตัวรับโดปามีน D1 และตัวขนส่งที่เพิ่มขึ้นจากโคเคนแสดงหลักฐานการกลับเข้าใกล้ระดับของกลุ่มควบคุมหลังงดใช้ประมาณ 90 วัน ซึ่งเป็นหลักฐานโดยตรงว่าระบบรางวัลสามารถปรับตัวกลับได้เมื่อหยุดใช้สาร\n\nส่วนหน้าของสมอง\nผู้เขียนเน้นการฟื้นตัวของสมองส่วนหน้าเป็นหนึ่งในสัญญาณสำคัญของการงดใช้ต่อเนื่อง พื้นที่นี้เกี่ยวข้องกับการควบคุมแรงกระตุ้น การตัดสินใจ และการควบคุมตนเอง และความสามารถเหล่านี้จะแข็งแรงขึ้นเมื่อพื้นที่ดังกล่าวฟื้นตัว\n\nสิ่งที่ 90 วันแสดงให้เห็น\nเมื่อครบ 90 วัน งานวิจัยในไพรเมตพบว่าความหนาแน่นของ D1, D2 และตัวขนส่งโดปามีนไม่แตกต่างอย่างมีนัยสำคัญจากกลุ่มควบคุมที่ไม่ได้รับสารอีกต่อไป แม้หลังได้รับโคเคนเป็นเวลานาน การฟื้นตัวของระบบโดปามีนในระดับมากก็เห็นได้แล้วในช่วงนี้และดำเนินต่อไปเมื่อยังคงงดใช้.';

  @override
  String get cocaineReferenceDay180 =>
      'หกเดือนโดยไม่ใช้โคเคน: คิดได้ชัดเจนขึ้น\n\nแหล่งที่มา: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies\", PubMed Central\n\nการฟื้นตัวที่เห็นได้จากภาพสมอง\nบททบทวนนี้รวบรวมงานวิจัยภาพสมองแบบติดตามระยะยาว ซึ่งสแกนคนเดิมซ้ำเมื่อระยะเวลางดใช้ยาวขึ้น สำหรับโคเคน งานวิจัยรายงานว่าการทำงานของสมองฟื้นตัวในระดับที่วัดได้เมื่อมีการงดใช้อย่างต่อเนื่อง\n\nหลักฐานจากภาพสมอง\nงานวิจัย fMRI สองชิ้นติดตามผู้ใช้โคเคนตามเวลา และทั้งสองพบการกระตุ้นที่ดีขึ้นในสมองส่วนกลางและทาลามัสเมื่อระยะเวลางดใช้ยาวขึ้น ในหนึ่งการศึกษา หลังงดใช้ประมาณหกเดือน รูปแบบการกระตุ้นของสมองใกล้เคียงกับกลุ่มควบคุมสุขภาพดีที่ไม่ได้มีภาวะเสพติด เมื่อพิจารณาสารหลายชนิด บททบทวนยังระบุว่าผลการถ่ายภาพทางเวชศาสตร์นิวเคลียร์ชี้ไปที่การฟื้นตัวของระบบโดปามีนเมื่อมีการงดใช้\n\nความหมายเมื่อครบหกเดือน\nการดีขึ้นด้านการทำงานเหล่านี้สอดคล้องกับการเปลี่ยนแปลงในชีวิตจริงที่ผู้คนรายงานในช่วงนี้:\n• สมาธิและความจำใช้งานดีขึ้น\n• การตัดสินใจและการควบคุมแรงกระตุ้นดีขึ้น\n• อารมณ์คงที่และควบคุมอารมณ์ได้ดีขึ้น\n\nสัญญาณของการฟื้นตัว\nเมื่อประมาณหกเดือน กลุ่มติดตาม fMRI หนึ่งกลุ่มแสดงรูปแบบการกระตุ้นที่ใกล้เคียงกับกลุ่มควบคุมสุขภาพดีที่ไม่ได้มีภาวะเสพติด ขณะที่การกระตุ้นของสมองส่วนกลางและบริเวณสมองส่วนลึกดีขึ้นเมื่อระยะเวลางดใช้ยาวขึ้น นี่คือการฟื้นตัวด้านการทำงานของสมองที่เห็นได้โดยตรงจากภาพถ่าย.';

  @override
  String get cocaineReferenceDay365 =>
      'หนึ่งปีโดยไม่ใช้โคเคน: หยุดความเครียดซ้ำต่อหัวใจและหลอดเลือด\n\nแหล่งที่มา: \"Cocaine Toxicity\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nเหตุใดหัวใจจึงสำคัญ\nStatPearls ระบุว่าความเป็นพิษต่อหัวใจและหลอดเลือดเป็นผลของโคเคนที่อันตรายถึงชีวิตที่สุด การใช้แต่ละครั้งเพิ่มอัตราการเต้นของหัวใจ ความดันโลหิต และความต้องการออกซิเจนของกล้ามเนื้อหัวใจ พร้อมกับทำให้หลอดเลือดหัวใจหดเกร็งและส่งเสริมการเกิดลิ่มเลือด ปัจจัยเหล่านี้ร่วมกันเพิ่มความเสี่ยงของภาวะหัวใจวาย หัวใจเต้นผิดจังหวะ และโรคหลอดเลือดสมองแม้ในคนอายุน้อย\n\nสิ่งที่หายไปเมื่อครบหนึ่งปี\nทุกวันที่ไม่มีโคเคนคือวันที่ไม่มีการกระทบเฉียบพลันเหล่านี้ ตลอดหนึ่งปี การพุ่งขึ้นซ้ำของความดันโลหิตและอัตราการเต้นของหัวใจจากการใช้จะไม่เกิดขึ้น ความเสี่ยงของหลอดเลือดหัวใจหดเกร็งและกล้ามเนื้อหัวใจตายเฉียบพลันจากการใช้ครั้งใหม่จะหมดไป และหัวใจไม่ถูกผลักซ้ำ ๆ ให้เกิดความไม่สมดุลระหว่างความต้องการและปริมาณออกซิเจน\n\nสัญญาณของการฟื้นตัว\nการหยุดโคเคนหยุดการหดเกร็งของหลอดเลือดหัวใจซ้ำ ภาวะหัวใจเต้นเร็ว ความดันโลหิตสูง การส่งเสริมการแข็งตัวของเลือด และความไม่สมดุลของออกซิเจนที่ทำให้เกิดการบาดเจ็บของหัวใจเฉียบพลัน พังผืดหรือกล้ามเนื้อหัวใจอักเสบที่มีอยู่เดิมยังคงเป็นปัญหาทางการแพทย์ แต่การทำร้ายซ้ำจากโคเคนหยุดลง\n\nสมองก็ฟื้นตัวด้วย\nเมื่อครบหนึ่งปี ระบบรางวัลและการควบคุมตนเองมีเวลาฟื้นตัวนานขึ้น ซึ่งสนับสนุนการควบคุมแรงกระตุ้นที่ดีขึ้น อารมณ์ที่คงที่ขึ้น และการตอบสนองต่อรางวัลในชีวิตประจำวันได้ดีขึ้น.';

  @override
  String get cocaineReferenceDay730 =>
      'สองปีโดยไม่ใช้โคเคน: การฟื้นตัวอย่างต่อเนื่อง\n\nแหล่งที่มา: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\nมุมมองระยะยาว\nบททบทวนนี้รวบรวมผลจากการศึกษาในมนุษย์และสัตว์เกี่ยวกับการงดใช้โคเคนเป็นเวลานาน ข้อสรุปสำคัญคือการคงไว้และการฟื้นตัวของการทำงานของเปลือกสมองส่วนหน้าเป็นหนึ่งในตัวบ่งชี้สำคัญของการงดใช้ระยะยาว ผู้ที่งดใช้มานานกว่า 10 เดือนมีการทำงานของเปลือกสมองส่วนหน้าสูงกว่าผู้ที่งดใช้ในช่วงเวลาสั้นกว่า\n\nสิ่งที่ยังคงฟื้นตัว\n• ตัวบ่งชี้โดปามีนที่เปลี่ยนแปลงจากโคเคนยังคงเคลื่อนเข้าใกล้ระดับปกติเมื่อมีการงดใช้อย่างต่อเนื่อง\n• ความสมบูรณ์ของเนื้อเทาและเนื้อขาวที่ลดลงซึ่งพบในผู้ที่กำลังใช้และผู้ที่เพิ่งเริ่มงด อาจดีขึ้นเมื่อหยุดใช้นานขึ้น ซึ่งอาจเกี่ยวข้องกับการเจริญของไมอีลินที่ดำเนินต่อไป\n• วงจรควบคุมของสมองส่วนหน้าที่เกี่ยวข้องกับการควบคุมแรงกระตุ้น การตัดสินใจ และการควบคุมอารมณ์แข็งแรงขึ้น\n\nสัญญาณของการฟื้นตัว\nผู้เขียนชี้ให้เห็นข้อควรระวังทางวิทยาศาสตร์ที่สำคัญ: ความแตกต่างบางส่วนในผู้ที่งดใช้ระยะยาวอาจสะท้อน \"ผลของผู้รอดชีวิต\" ผู้ที่มีความสมบูรณ์ของสมองดีกว่าตั้งแต่แรกอาจรักษาการงดใช้ได้ง่ายกว่า ดังนั้นจึงไม่อาจอธิบายความแตกต่างทั้งหมดด้วยการฟื้นตัวเพียงอย่างเดียว สิ่งที่ชัดเจนคือการไม่ใช้โคเคนเป็นเวลาสองปีสนับสนุนการทำงานของสมองที่ใกล้เคียงกับผู้ไม่ใช้มากขึ้นอย่างมาก และชีวิตที่ไม่ได้มีเพียงการงดใช้ แต่ได้รับการสร้างขึ้นใหม่อย่างมีนัยสำคัญ';

  @override
  String get cocaineReferenceDay1095 =>
      'สามปีที่ไม่ใช้โคเคน: รากฐานแข็งแรง\n\nแหล่งข้อมูล: SAMHSA, Treatment of Stimulant Use Disorders\n\nแนวทางของ SAMHSA ครอบคลุมโคเคนโดยตรงและเน้นวิธีที่มีหลักฐานรองรับเพื่อสนับสนุนการฟื้นตัวระยะยาว โดยไม่ได้กำหนดเส้นตายทางชีววิทยาสากลที่สามปี\n\nสามปีเป็นความสำเร็จที่มั่นคงในตัวมันเอง รักษากิจวัตร การสนับสนุน และกลยุทธ์ที่ทำให้การฟื้นตัวดำเนินต่อไปได้';

  @override
  String get cocaineReferenceDay1460 =>
      'สี่ปีที่ไม่ใช้โคเคน: แรงส่งที่ยั่งยืน\n\nแหล่งข้อมูล: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA อธิบายแนวทางที่มีหลักฐานรองรับสำหรับความผิดปกติจากการใช้สารกระตุ้น รวมถึงโคเคน และการสนับสนุนการฟื้นตัวระยะยาว โดยไม่ได้ระบุจุดสิ้นสุดทางการแพทย์สากลที่สี่ปี\n\nสี่ปีคือการเปลี่ยนแปลงที่ผ่านทั้งวันธรรมดา ช่วงเวลายาก และเหตุการณ์สำคัญมาได้';

  @override
  String get cocaineReferenceDay1825 =>
      'ห้าปีที่ไม่ใช้โคเคน: ความเปลี่ยนแปลงมั่นคง\n\nแหล่งข้อมูล: SAMHSA, Treatment of Stimulant Use Disorders\n\nแนวทางของ SAMHSA สนับสนุนการดูแลที่มีหลักฐานรองรับเพื่อการฟื้นตัวระยะยาวจากความผิดปกติจากการใช้สารกระตุ้น รวมถึงโคเคน และไม่ได้ถือว่าห้าปีเป็นเส้นชัยทางชีววิทยา\n\nห้าปีคือครึ่งทศวรรษของการเปลี่ยนแปลงที่รักษาไว้ได้ ความสม่ำเสมอนั้นและชีวิตที่สร้างขึ้นรอบ ๆ มันคือสิ่งที่ควรฉลอง';

  @override
  String get ghbReferenceDay1 =>
      'การถอน GHB: ชั่วโมงแรก ๆ\n\nแหล่งที่มา: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\n⚠ นี่คือภาวะฉุกเฉินทางการแพทย์\nการถอน GHB เป็นหนึ่งในการถอนสารที่อันตรายที่สุด และอาจรุนแรงพอ ๆ กับการถอนแอลกอฮอล์หรือเบนโซไดอะซีพีนอย่างรุนแรง หากไม่ได้รับการรักษา มากกว่าครึ่งของผู้ป่วยอาจเกิดอาการเพ้อ พร้อมความผันผวนของอัตราการเต้นหัวใจและความดันโลหิตที่เป็นอันตราย รวมถึงอาการชัก ผู้ที่พึ่งพา GHB, GBL หรือ 1,4-butanediol ควรรับการถอนยาแบบผู้ป่วยในภายใต้การดูแล ไม่ควรหยุดเองตามลำพัง\n\nทำไมอาการจึงเริ่มเร็วมาก\nGHB มีครึ่งชีวิตเพียง 30–60 นาที ผู้ที่เกิดการพึ่งพามักต้องใช้ซ้ำทุก 2–3 ชั่วโมงเพียงเพื่อหลีกเลี่ยงอาการถอน ซึ่งถี่กว่าแอลกอฮอล์หรือเบนโซไดอะซีพีนมาก เภสัชจลนศาสตร์ที่รวดเร็วนี้ทำให้อาการสามารถเกิดเร็วกว่าการถอนยากลุ่มกดประสาทและยานอนหลับชนิดอื่นมาก\n\nอาการระยะแรก\nวิตกกังวล นอนไม่หลับ สั่น เหงื่อออก หัวใจเต้นเร็ว และความดันโลหิตสูงขึ้น';

  @override
  String get ghbReferenceDay3 =>
      'การถอน GHB: วันที่หนักที่สุด\n\nแหล่งที่มา: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nช่วงที่หนักที่สุด\nการศึกษานี้พบว่าอาการถอนหลักหลายอย่าง — ปวดกล้ามเนื้อ กล้ามเนื้อกระตุก ความรู้สึกตึงเครียด หัวใจเต้นเร็ว และปวดเกร็งท้อง — รุนแรงที่สุดในสามวันแรก และภายในวันที่สี่ความรุนแรงของอาการหลายอย่างลดลงมากกว่า 70% ช่วงต้นนี้โดยทั่วไปเป็นช่วงที่มีความเสี่ยงสูงสุด ซึ่งการถอนที่ไม่ได้รับการรักษามีโอกาสลุกลามเป็นอาการเพ้อ ชัก หรือความผันผวนของอัตราการเต้นหัวใจและความดันโลหิตที่เป็นอันตรายมากที่สุด\n\nอาการรุนแรง\n• กระสับกระส่ายและวิตกกังวลอย่างรุนแรง\n• ประสาทหลอนทางเสียงและภาพ รวมถึงความหวาดระแวง\n• สั่น เหงื่อออก ใจสั่น และความดันโลหิตสูง\n• เสี่ยงต่ออาการชัก\n\nการรักษา\nการศึกษานี้อธิบายการค่อย ๆ ลดเบนโซไดอะซีพีนและ GHB ที่ใช้ทางการแพทย์ว่าเป็นสองวิธีถอนยาที่ใช้กันทั่วไป และมีหลักฐานบางส่วนว่าการค่อย ๆ ลด GHB อาจควบคุมอาการได้ดีกว่าใช้เบนโซไดอะซีพีนเพียงอย่างเดียว ทั้งสองวิธีต้องมีการเฝ้าระวังอย่างใกล้ชิด — ไม่ปลอดภัยที่จะจัดการเองที่บ้าน';

  @override
  String get ghbReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่มี GHB\n\nแหล่งที่มา: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nอาการส่วนใหญ่กำลังลดลง\nอาการถอนหลักหลายอย่างลดลงมากกว่า 70% ทั้งด้านความรุนแรงหรือความชุกในสี่วันแรก ภายใต้การค่อย ๆ ลดขนาดยาที่มีผู้ดูแล ระยะลดขนาดยาใช้เวลาเฉลี่ย 11 วัน ตามด้วยระยะฟื้นตัวประมาณหกวัน ดังนั้นเมื่อครบหนึ่งสัปดาห์ หลายคนจึงเข้าสู่ช่วงที่ดีขึ้นมากแล้ว แม้กระบวนการจะยังไม่เสร็จสิ้นทั้งหมด\n\nอาการที่อาจยังคงอยู่\n• เหงื่อออก สั่น และมือสั่น\n• นอนมาก หรือในทางกลับกันคือนอนไม่หลับและกระสับกระส่าย\n• ความอยากใช้ GHB\n\nการศึกษาพบว่าอาการเหล่านี้เปลี่ยนแปลงค่อนข้างน้อยแม้ถึงวันที่ 11 ดังนั้นการที่ยังมีอาการในสัปดาห์นี้จึงไม่ใช่เรื่องผิดปกติ ควรอยู่ภายใต้การดูแลทางการแพทย์ต่อไปจนกว่าอาการจะสงบลงอย่างชัดเจน';

  @override
  String get ghbReferenceDay14 =>
      'สองสัปดาห์โดยไม่มี GHB\n\nแหล่งที่มา: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nผ่านระยะเฉียบพลัน\nเมื่อครบสองสัปดาห์ กลุ่มอาการทางกายระยะเฉียบพลันที่อธิบายในการศึกษานี้มักหายไปแล้วหรือใกล้หายมาก ภายใต้การรักษาที่มีผู้ดูแล ระยะค่อย ๆ ลดขนาดยาและระยะฟื้นตัวรวมกันใช้เวลาเฉลี่ยประมาณ 17 วัน อัตราการเต้นหัวใจ ความดันโลหิต และอาการทางกายส่วนใหญ่ควรเริ่มเสถียร\n\nสิ่งที่อาจยังเหลืออยู่\nการศึกษาระบุเป็นพิเศษว่าผู้ป่วยบางรายยังมีความอยากใช้และนอนไม่หลับเมื่อออกจากโรงพยาบาล และอาการเหล่านี้อาจเพิ่มความเสี่ยงต่อการกลับไปใช้ซ้ำ การสนับสนุนและกิจวัตรที่มีโครงสร้างจึงยังสำคัญ แม้ช่วงต้นที่อันตรายจะผ่านไปแล้ว';

  @override
  String get ghbReferenceDay30 =>
      'หนึ่งเดือนโดยไม่มี GHB\n\nแหล่งที่มา: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nหนึ่งเดือนอยู่ตรงไหนของการฟื้นตัว\nเมื่อครบหนึ่งเดือน ระยะเฉียบพลันที่อันตรายตามที่การศึกษานี้อธิบายได้ผ่านไปนานแล้ว ระยะดังกล่าวกระจุกตัวอยู่ในวันแรก ๆ แล้วตามด้วยช่วงค่อย ๆ ลดขนาดยาและฟื้นตัวภายใต้การดูแล ซึ่งใช้เวลาเฉลี่ยประมาณสองสัปดาห์ครึ่ง ความอยากใช้และนอนไม่หลับเป็นความเสี่ยงต่อการกลับไปใช้ซ้ำที่ยังเหลืออยู่และถูกระบุเมื่อออกจากโรงพยาบาล\n\nทำไมการสนับสนุนยังมีประโยชน์\nหากเมื่อครบหนึ่งเดือนยังมีความอยากใช้ อารมณ์ต่ำ หรือปัญหาการนอน สิ่งเหล่านี้สอดคล้องกับปัจจัยเสี่ยงต่อการกลับไปใช้ซ้ำที่ผู้เขียนการศึกษาระบุ นั่นคือเหตุผลที่การสนับสนุนต่อเนื่องและกิจวัตรที่มีโครงสร้างยังสำคัญ';

  @override
  String get ghbReferenceDay90 =>
      'สามเดือนโดยไม่มี GHB\n\nแหล่งที่มา: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nสามเดือนของการฟื้นตัว\nเมื่อครบสามเดือน กลุ่มอาการถอน GHB ระยะเฉียบพลันได้ผ่านไปนานแล้ว ความเสี่ยงที่ยังเหลืออยู่เมื่อออกจากโรงพยาบาลคือความอยากใช้และนอนไม่หลับ ดังนั้นสามเดือนที่ไม่ใช้ GHB จึงให้เวลามากพอแก่การนอน ความเสถียรของระบบประสาทอัตโนมัติ และกิจวัตรป้องกันการกลับไปใช้ซ้ำในการตั้งหลัก\n\nสิ่งที่มักรายงาน\n• อารมณ์โดยรวมสงบขึ้น\n• การนอนสม่ำเสมอขึ้น\n• คิดชัดเจนขึ้นและความอยากใช้ลดลง\n\nหากยังมีความวิตกกังวล นอนไม่หลับ หรืออารมณ์ต่ำอย่างชัดเจนเมื่อครบสามเดือน ควรปรึกษาแพทย์หรือบุคลากรทางการแพทย์ แทนที่จะคิดว่าจะหายเอง';

  @override
  String get ghbReferenceDay180 =>
      'หกเดือนโดยไม่มี GHB\n\nแหล่งที่มา: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nครึ่งปีต่อมา\nเมื่อครบหกเดือน กลุ่มอาการถอน GHB ระยะเฉียบพลันได้ผ่านไปนานแล้ว และการฟื้นตัวเปลี่ยนจากการล้างพิษไปสู่การนอนที่มั่นคง การจัดการความอยากใช้ และการป้องกันการกลับไปใช้ซ้ำอย่างเต็มที่ ช่วงที่ระบบประสาทอัตโนมัติแปรปรวนและเสี่ยงต่ออาการเพ้อเป็นช่วงวันและสัปดาห์แรก ๆ ไม่ใช่ระยะนี้\n\nภาพรวมระยะยาว\nการผ่านการถอน GHB อย่างปลอดภัยและไม่ใช้เป็นเวลาครึ่งปีเป็นความสำเร็จครั้งใหญ่ เมื่อคำนึงถึงอันตรายในช่วงแรกและความเสี่ยงต่อการกลับไปใช้ซ้ำที่ยังมีจริง ซึ่งส่วนหนึ่งเกี่ยวข้องกับความอยากใช้และนอนไม่หลับที่อาจคงอยู่ กิจวัตรและการสนับสนุนที่พาคุณมาถึงตรงนี้ยังคุ้มค่าที่จะรักษาไว้';

  @override
  String get inhalantsReferenceDay1 =>
      'หยุดใช้สารระเหย: วันแรก\n\nแหล่งที่มา: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse\", The Permanente Journal (2023), PubMed Central\n\nเหตุใดจึงเกิดอาการถอนสาร\nการใช้สารระเหยเรื้อรังทำให้เกิดการปรับตัวของระบบประสาท ระบบประสาทจึงเคยชินกับการมีสารอยู่ สารระเหยหลายชนิดส่งผลต่อวงจรสมองคล้ายแอลกอฮอล์ เมื่อหยุดใช้ สมองจึงอาจเสียสมดุลชั่วคราว สารเคมีออกจากเลือดได้เร็วแต่สะสมในไขมันร่างกายได้ ทำให้ช่วงเวลาของอาการถอนสารคาดเดาได้ยาก\n\nอาการช่วงแรก\nบททบทวนนี้อธิบายว่าอาการถอนสารระเหยคล้ายการถอนแอลกอฮอล์หรือเบนโซไดอะซีพีน โดยมีอาการที่รายงาน เช่น:\n• คลื่นไส้ อาเจียน และเหงื่อออก\n• มือสั่นและหัวใจเต้นเร็ว\n• นอนไม่หลับและการนอนผิดปกติ\n• วิตกกังวลและหงุดหงิด\n\nข้อควรระวังด้านความปลอดภัย\nในกรณีที่รุนแรงกว่านั้น บททบทวนยังระบุอาการประสาทหลอน ความหลงผิด และชัก แต่ไม่ได้กำหนดตารางอาการแบบวันต่อวันอย่างตายตัว จึงควรมองว่าเป็นอาการที่อาจเกิดขึ้น ไม่ใช่ลำดับเวลาที่แน่นอน การมีบุคลากรทางการแพทย์ดูแลระหว่างการถอนสารเหมาะสมอย่างยิ่ง โดยเฉพาะผู้ที่ใช้หนักหรือใช้มานาน.';

  @override
  String get inhalantsReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่ใช้สารระเหย\n\nแหล่งที่มา: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse\", The Permanente Journal (2023), PubMed Central\n\nช่วงเฉียบพลัน\nวรรณกรรมทางคลินิกอธิบายการถอนสารระเหยว่าคล้ายการถอนแอลกอฮอล์หรือเบนโซไดอะซีพีน แต่โดยทั่วไปมีระยะสั้นกว่า เมื่อสิ้นสุดสัปดาห์แรก อาการทางกายเฉียบพลัน เช่น คลื่นไส้ มือสั่น เหงื่อออก และนอนไม่หลับ มักเริ่มทุเลาในคนส่วนใหญ่\n\nสิ่งที่อาจยังเหลืออยู่\n• เหนื่อยล้าและคิดไม่ชัด\n• อารมณ์ต่ำหรือไม่คงที่\n• ความอยากใช้สาร\n\nหมายเหตุเกี่ยวกับช่วงต้นของการงดใช้\nอาการคิดไม่ชัดในช่วงนี้ไม่ได้หมายความว่ามีความเสียหายถาวร สมองยังอยู่ระหว่างการปรับตัว งานวิจัยเกี่ยวกับการฟื้นตัวของความคิดและความจำในสัปดาห์และเดือนถัดไปจะกล่าวถึงในหมุดหมายต่อ ๆ ไป.';

  @override
  String get inhalantsReferenceDay14 =>
      'สองสัปดาห์โดยไม่ใช้สารระเหย\n\nแหล่งที่มา: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse\", The Permanente Journal (2023), PubMed Central\n\nผ่านระยะเฉียบพลัน\nบททบทวนทางคลินิกอธิบายการถอนสารระเหยว่าคล้ายการถอนแอลกอฮอล์หรือเบนโซไดอะซีพีน แต่สั้นกว่า เมื่อครบสองสัปดาห์ อาการคลื่นไส้ มือสั่น นอนไม่หลับ และวิตกกังวลมักทุเลาแล้ว\n\nเส้นทางต่อจากนี้\nสมาธิ ความจำ การเคลื่อนไหว และการประสานงานจะฟื้นตัวอย่างค่อยเป็นค่อยไปในช่วงหลายเดือนถัดมา การงดใช้ต่อเนื่องช่วยให้ระบบเหล่านี้มีเวลาฟื้นตัว โภชนาการที่ดี ซึ่งสำคัญเพราะการใช้สารระเหยอาจทำให้วิตามิน B12 ลดลง ร่วมกับการงดใช้ต่อเนื่อง ช่วยสร้างเงื่อนไขที่เอื้อต่อการฟื้นตัว.';

  @override
  String get inhalantsReferenceDay30 =>
      'หนึ่งเดือนโดยไม่ใช้สารระเหย\n\nแหล่งที่มา: Dingwall และคณะ, \"Cognitive recovery during and after treatment for volatile solvent abuse\", Drug and Alcohol Dependence (2011), PubMed\n\nหนึ่งเดือนอยู่ตรงไหนของการฟื้นตัว\nระยะถอนสารช่วงต้นผ่านไปนานแล้ว ในการศึกษานี้ ทักษะการเรียนรู้บางอย่างดีขึ้นภายในหกสัปดาห์ ขณะที่การประสานงานด้านการมองเห็น ความจำ การวางแผน และการตัดสินใจดีขึ้นอย่างค่อยเป็นค่อยไปในช่วงหลายเดือนต่อมา\n\nสิ่งที่อาจดีขึ้น\n• สมาธิและงานเรียนรู้บางอย่าง\n• อารมณ์และการนอนเมื่อร่างกายเริ่มคงที่\n• ความเร็วในการเคลื่อนไหวอย่างค่อยเป็นค่อยไป\n\nสัญญาณการฟื้นตัว\nข้อสรุปของการศึกษาชัดเจนว่า ความจำ การวางแผน และการตัดสินใจดีขึ้นทีละน้อยตลอดหลายเดือนถึงหลายปีของการงดใช้ การงดใช้อย่างต่อเนื่องเป็นปัจจัยสำคัญที่สุดที่สนับสนุนการฟื้นตัวนี้.';

  @override
  String get inhalantsReferenceDay90 =>
      'สามเดือนโดยไม่ใช้สารระเหย\n\nแหล่งที่มา: Dingwall และคณะ, \"Cognitive recovery during and after treatment for volatile solvent abuse\", Drug and Alcohol Dependence (2011), PubMed\n\nกระบวนการที่ไม่สม่ำเสมอและยาวนานกว่า\nการศึกษานี้ติดตามผู้เข้าร่วมต่อจากโปรแกรมรักษาแปดสัปดาห์ และประเมินบางคนอีกครั้งราวหนึ่งปีต่อมา ทักษะการเรียนรู้บางอย่างดีขึ้นภายในหกสัปดาห์ ขณะที่การประสานงานด้านการมองเห็น ความจำ การวางแผน และการตัดสินใจยังคงดีขึ้นในช่วงเวลาที่ยาวกว่า\n\nเดินหน้าต่อ\nการศึกษาแสดงให้เห็นว่าความสามารถที่ฟื้นช้ากว่าสามารถดีขึ้นทีละน้อยตลอดหลายเดือนถึงหลายปี เมื่อครบสามเดือน การงดใช้อย่างต่อเนื่องยังคงเป็นปัจจัยสำคัญที่สุดในการเพิ่มการฟื้นตัวจากเดือนหนึ่งสู่อีกเดือนหนึ่ง.';

  @override
  String get inhalantsReferenceDay365 =>
      'หนึ่งปีโดยไม่ใช้สารระเหย\n\nแหล่งที่มา: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse\", PubMed\n\nการฟื้นตัวที่วัดได้จริง\nการศึกษาระยะยาวพบว่าปัญหาด้านสมองและการคิดที่เกี่ยวข้องกับการใช้สารระเหยเรื้อรังฟื้นตัวอย่างมากหลังงดใช้สองปี เมื่อครบหนึ่งปี คุณได้เดินมาไกลบนเส้นทางการฟื้นตัวนั้นแล้ว\n\nความหมายของผลนี้\nความจำ สมาธิ และการทำงานด้านการเคลื่อนไหวยังคงดีขึ้น การงดใช้ระยะยาวช่วยให้สมองฟื้นตัวได้จริง: เมื่อครบสองปี คะแนนด้านการทำงานของสมอง ความจำ และการคิดส่วนใหญ่กลับสู่ช่วงปกติในผู้ใช้เรื้อรังที่ไม่มีความเสียหายต่อสมองจากสารตะกั่ว.';

  @override
  String get inhalantsReferenceDay730 =>
      'สองปีโดยไม่ใช้สารระเหย\n\nแหล่งที่มา: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse\", PubMed\n\nหมุดหมายสองปี\nนี่คือจุดสำคัญของงานวิจัย: ความบกพร่องที่สะท้อนความเสียหายของสมองจากการใช้ตัวทำละลายระยะยาวฟื้นตัวอย่างมากหลังงดใช้สองปี ผู้วิจัยสรุปว่า หากไม่มีความเสียหายต่อสมองจากน้ำมันเบนซินที่มีสารตะกั่ว การงดใช้ระยะยาวอาจทำให้การทำงานของสมองกลับสู่ปกติได้\n\nสัญญาณการฟื้นตัว\nข้อยกเว้นสำคัญคือความเสียหายจากการใช้น้ำมันเบนซินที่มีสารตะกั่วในทางที่ผิด ซึ่งอาจทำให้เกิดความบกพร่องถาวรได้ นอกเหนือจากกรณีนั้น สองปีที่งดใช้เป็นโอกาสในการฟื้นตัวของสมองที่มีหลักฐานบันทึกไว้ดีที่สุด ควบคู่กับชีวิตที่สร้างขึ้นใหม่.';

  @override
  String get ketamineReferenceDay1 =>
      'หยุดคีตามีน: วันแรก\n\nที่มา: “Ketamine-Induced Cystitis: A Comprehensive Review of the Urologic Effects of This Psychoactive Drug” บน PubMed Central\n\nอาการถอนส่วนใหญ่เป็นด้านจิตใจ\nต่างจากโอปิออยด์หรือแอลกอฮอล์ คีตามีนแทบไม่ทำให้เกิดอาการถอนทางกายที่รุนแรง โดยทั่วไปการหยุดใช้มีความปลอดภัย คนมักเผชิญกับความอยากใช้และการพึ่งพาทางจิตใจมากกว่าอาการเจ็บป่วยทางกาย\n\nสิ่งที่อาจรู้สึก\n• อารมณ์แปรปรวนและอารมณ์ต่ำ\n• ความอยากใช้คีตามีน\n• เหงื่อออกหรือใจสั่นเป็นครั้งคราว\n\nขั้นตอนสำคัญ\nสำหรับผู้ที่มีอาการทางกระเพาะปัสสาวะ การหยุดใช้ทันทีและโดยสมบูรณ์เป็นจุดเริ่มต้นที่จำเป็นของการฟื้นตัว ดังนั้นการตัดสินใจในวันแรกจึงสำคัญที่สุด';

  @override
  String get ketamineReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่ใช้คีตามีน\n\nที่มา: “Ketamine-Induced Cystitis: A Comprehensive Review” บน PubMed Central\n\nระยะด้านจิตใจ\nความท้าทายหลักในช่วงแรกของการหยุดคีตามีนคือด้านจิตใจ ได้แก่ ความอยากใช้ อารมณ์แปรปรวนหรือต่ำ และภาวะสมองล้า อาการถอนทางกายหากมีก็มักไม่รุนแรง\n\nภาวะสมองล้าพบได้บ่อยในช่วงนี้ — การมีสมาธิอาจต้องใช้ความพยายามมากขึ้น เวลาตอบสนองช้าลง และความจำระยะสั้นอาจไม่น่าเชื่อถือ ผลต่อการคิดและความจำเหล่านี้ดีขึ้นเมื่อไม่ใช้คีตามีน: การศึกษาติดตามผู้ใช้คีตามีน 114 คนพบว่าหลัง 12 สัปดาห์โดยไม่ใช้คีตามีน ความจำด้านคำพูด ความจำด้านภาพ ความเร็วในการประมวลผล การวางแผน สมาธิ และการตัดสินใจดีขึ้นอย่างมีนัยสำคัญ\n\nอาการทางกระเพาะปัสสาวะ\nหากมีโรคกระเพาะปัสสาวะอักเสบจากคีตามีน (ปวดปัสสาวะฉับพลัน ปัสสาวะบ่อย ปวด หรือมีเลือดในปัสสาวะ) การหยุดตอนนี้ให้โอกาสกระเพาะปัสสาวะฟื้นตัวดีที่สุด ความเจ็บปวดอาจทำให้บางคนกลับไปใช้คีตามีนเพื่อรักษาตัวเอง จึงควรตัดวงจรนี้ด้วยการดูแลอาการปวดอย่างเหมาะสม';

  @override
  String get ketamineReferenceDay14 =>
      'สองสัปดาห์โดยไม่ใช้คีตามีน\n\nที่มา: “Ketamine-Induced Cystitis: A Comprehensive Review” บน PubMed Central\n\nความคิดชัดเจนขึ้น\nเมื่อยาถูกกำจัดออกจากร่างกายหมดแล้ว ภาวะสมองล้าและความคิดที่รู้สึกแยกขาดซึ่งเกี่ยวข้องกับการใช้คีตามีนเป็นประจำเริ่มลดลง ความจำและสมาธิดีขึ้น และอารมณ์คงที่ขึ้น\n\nการฟื้นตัวของกระเพาะปัสสาวะเริ่มต้น\nสำหรับโรคกระเพาะปัสสาวะอักเสบระยะแรก บททบทวนเน้นว่าการหยุดคีตามีนเป็นขั้นตอนสำคัญที่สุดในการทำให้อาการดีขึ้น และยิ่งหยุดเร็วก็ยิ่งมีโอกาสฟื้นตัวก่อนความเสียหายจะถาวร สองสัปดาห์โดยไม่ใช้คีตามีนคือจุดเริ่มต้นของกระบวนการนี้';

  @override
  String get ketamineReferenceDay30 =>
      'หนึ่งเดือนโดยไม่ใช้คีตามีน\n\nที่มา: “Prevalence and Natural History of Urinary Symptoms Among Recreational Ketamine Users”, Winstock และคณะ, BJU International (2012)\n\nการฟื้นตัวของกระเพาะปัสสาวะ\nการรักษาที่สำคัญที่สุดสำหรับโรคกระเพาะปัสสาวะอักเสบจากคีตามีนคือการหยุดคีตามีน การศึกษาในผู้ใช้คีตามีนเพื่อสันทนาการพบว่า 51% ของผู้ที่มีอาการทางปัสสาวะรายงานว่าอาการดีขึ้นหลังหยุดใช้ ขณะที่น้อยกว่า 4% มีอาการแย่ลง ยิ่งหยุดเร็วผลลัพธ์ยิ่งดี\n\nความคิดและอารมณ์\nการรับรู้และอารมณ์ยังคงดีขึ้นเมื่อครบหนึ่งเดือน การสนับสนุนด้านจิตใจและสังคมช่วยเพิ่มโอกาสที่จะหยุดต่อได้อย่างมีนัยสำคัญ — การหยุดใช้ทำได้ดีกว่าเมื่อมีการสนับสนุน';

  @override
  String get ketamineReferenceDay90 =>
      'สามเดือนโดยไม่ใช้คีตามีน\n\nที่มา: “Ketamine-Induced Cystitis: A Comprehensive Review” บน PubMed Central\n\nการฟื้นตัวยังคงดำเนินต่อ\nการฟื้นตัวของกระเพาะปัสสาวะหลังคีตามีนมักค่อยเป็นค่อยไป บททบทวนอธิบายว่าอาการอาจดีขึ้นหลังหยุดใช้ แต่ระยะเวลาการฟื้นตัวอาจยาวและแตกต่างกัน สามเดือนให้ทางเดินปัสสาวะมีเวลาฟื้นตัวอย่างต่อเนื่องในกรณีที่ตอบสนองต่อการหยุดใช้\n\nความคิด\nความคิดและอารมณ์ชัดเจนกว่าช่วงแรกของการหยุดมาก และความอยากใช้คีตามีนเกิดน้อยลง หากอาการทางกระเพาะปัสสาวะยังคงอยู่หรือรุนแรง ควรรับการประเมินจากแพทย์ระบบทางเดินปัสสาวะ';

  @override
  String get ketamineReferenceDay180 =>
      'หกเดือนโดยไม่ใช้คีตามีน\n\nที่มา: “Ketamine-Induced Cystitis: A Comprehensive Review” บน PubMed Central\n\nผ่านไปครึ่งปี\nเมื่อไม่ใช้คีตามีนต่อเนื่อง อาการของกระเพาะปัสสาวะจะยังดีขึ้นในกรณีที่ตอบสนองต่อการหยุดใช้ ขณะที่ความคิด ความจำ และอารมณ์คงที่ ความอยากกลับไปใช้ลดลงมาก\n\nสัญญาณของการฟื้นตัว\nความเสียหายของกระเพาะปัสสาวะที่เกิดขึ้นแล้วอาจฟื้นตัวได้ไม่สมบูรณ์ จึงสำคัญมากที่จะหยุดตั้งแต่เนิ่น ๆ ไม่ว่าคุณหยุดในระยะใด การไม่กลับไปใช้คีตามีนช่วยให้กระเพาะปัสสาวะมีโอกาสได้ผลลัพธ์ที่ดีที่สุด';

  @override
  String get ketamineReferenceDay365 =>
      'หนึ่งปีโดยไม่ใช้คีตามีน\n\nที่มา: “Ketamine-Induced Cystitis: A Comprehensive Review” บน PubMed Central\n\nผ่านไปหนึ่งปี\nสิบสองเดือนโดยไม่ใช้คีตามีนทำให้กระเพาะปัสสาวะในกรณีที่ตรวจพบตั้งแต่ระยะแรกมีโอกาสฟื้นตัวได้มากที่สุด และทำให้ความคิด ความจำ และอารมณ์คงที่และชัดเจน การพึ่งพาทางจิตใจที่เคยทำให้หยุดได้ยากลดลงไปมาก\n\nภาพรวมที่กว้างขึ้น\nหนึ่งปีโดยไม่ใช้คีตามีนคือการเปลี่ยนแปลงครั้งใหญ่ในสุขภาพกาย ความชัดเจนของความคิด และการกำหนดทิศทางชีวิตด้วยตนเอง การรักษาแรงสนับสนุนที่พาคุณมาถึงจุดนี้ช่วยปกป้องความก้าวหน้าดังกล่าว';

  @override
  String get ketamineReferenceDay730 =>
      'สองปีโดยไม่ใช้คีตามีน\n\nแหล่งข้อมูล: บททบทวนปี 2022 เรื่องกระเพาะปัสสาวะอักเสบจากคีตามีน (PubMed Central)\n\nบททบทวนแนะนำอย่างชัดเจนให้หยุดคีตามีน และระบุว่าโรคระยะแรกมักดีขึ้นหลังหยุดใช้ ขณะที่ความเสียหายที่มากขึ้นอาจฟื้นตัวได้ไม่สมบูรณ์ บททบทวนไม่ได้กำหนดสองปีเป็นเส้นชัยทางชีวภาพสำหรับทุกคน หมุดหมายนี้จึงเป็นการฉลองความก้าวหน้าที่ต่อเนื่องโดยไม่รับประกันผลทางการแพทย์แบบเดียวกัน';

  @override
  String get ketamineReferenceDay1095 =>
      'สามปีโดยไม่ใช้คีตามีน\n\nแหล่งข้อมูล: บททบทวนปี 2022 เรื่องกระเพาะปัสสาวะอักเสบจากคีตามีน (PubMed Central)\n\nบททบทวนแนะนำอย่างชัดเจนให้หยุดคีตามีน และระบุว่าโรคระยะแรกมักดีขึ้นหลังหยุดใช้ ขณะที่ความเสียหายที่มากขึ้นอาจฟื้นตัวได้ไม่สมบูรณ์ บททบทวนไม่ได้ระบุเกณฑ์การฟื้นตัวพิเศษที่สามปี สามปีคือความก้าวหน้าที่มั่นคง แต่ผลลัพธ์ยังแตกต่างกันในแต่ละคน';

  @override
  String get ketamineReferenceDay1460 =>
      'สี่ปีโดยไม่ใช้คีตามีน\n\nแหล่งข้อมูล: บททบทวนปี 2022 เรื่องกระเพาะปัสสาวะอักเสบจากคีตามีน (PubMed Central)\n\nบททบทวนแนะนำอย่างชัดเจนให้หยุดคีตามีน และระบุว่าโรคระยะแรกมักดีขึ้นหลังหยุดใช้ ขณะที่ความเสียหายที่มากขึ้นอาจฟื้นตัวได้ไม่สมบูรณ์ บททบทวนไม่ได้ผูกปีที่สี่กับเหตุการณ์ทางชีวภาพเฉพาะ สี่ปีคือฐานการฟื้นตัวที่แข็งแรง ไม่ใช่คำรับประกันทางการแพทย์';

  @override
  String get ketamineReferenceDay1825 =>
      'ห้าปีโดยไม่ใช้คีตามีน\n\nแหล่งข้อมูล: บททบทวนปี 2022 เรื่องกระเพาะปัสสาวะอักเสบจากคีตามีน (PubMed Central)\n\nบททบทวนแนะนำอย่างชัดเจนให้หยุดคีตามีน และระบุว่าโรคระยะแรกมักดีขึ้นหลังหยุดใช้ ขณะที่ความเสียหายที่มากขึ้นอาจฟื้นตัวได้ไม่สมบูรณ์ บททบทวนไม่ได้กำหนดห้าปีเป็นจุดสิ้นสุดทางชีวภาพสำหรับทุกคน หมุดหมายนี้ฉลองความก้าวหน้าระยะยาวครั้งใหญ่โดยไม่อ้างว่าหายขาดแน่นอน';

  @override
  String get kratomReferenceDay1 =>
      'อาการถอนกระท่อม: วันแรก\n\nแหล่งข้อมูล: Swogger และคณะ (2022), “Understanding Kratom Use: A Guide for Healthcare Providers,” Frontiers in Pharmacology\n\nเหตุใดจึงเกิดอาการถอน\nสารออกฤทธิ์ของกระท่อมจับกับตัวรับโอปิออยด์ชนิดเดียวกับโอปิออยด์แบบดั้งเดิม เมื่อใช้เป็นประจำร่างกายจะปรับตัว ดังนั้นการหยุดจึงอาจทำให้เกิดอาการถอนคล้ายโอปิออยด์ได้ คู่มือทางคลินิกนี้ระบุว่าการพึ่งพาและอาการถอนเป็นความเสี่ยงที่ได้รับการยอมรับจากการใช้กระท่อมเป็นประจำ\n\nหลักฐานบอกอะไรเกี่ยวกับช่วงเริ่มต้น\nการศึกษาในสัตว์ที่คู่มืออ้างถึงพบสัญญาณทางกายของอาการถอนภายในประมาณ 12 ชั่วโมง และผลคล้ายความวิตกกังวลเห็นได้ภายใน 24 ชั่วโมง ช่วงเวลาเริ่มต้นที่แน่นอนในมนุษย์ยังไม่ชัดเจนเท่าไร แต่อาการแรกที่รายงานบ่อย ได้แก่:\n• กระสับกระส่าย วิตกกังวล และหงุดหงิด\n• ปวดกล้ามเนื้อและน้ำมูกไหล\n• เหงื่อออกและน้ำตาไหล\n• ความอยากใช้\n\nหมายเหตุเรื่องความรุนแรง\nคู่มือระบุว่าระยะเวลาที่ใช้นานขึ้นและขนาดที่สูงขึ้นสัมพันธ์กับอาการถอนที่รุนแรงและยาวนานขึ้น การได้รับการดูแลทางการแพทย์ภายใต้การกำกับอาจมีประโยชน์ โดยเฉพาะหากใช้กระท่อมในขนาดสูงหรือร่วมกับโอปิออยด์';

  @override
  String get kratomReferenceDay3 =>
      'อาการถอนกระท่อม: วันที่ยากที่สุด\n\nแหล่งข้อมูล: Singh และคณะ (2014), Drug and Alcohol Dependence — การสำรวจผู้ใช้กระท่อมเป็นประจำ 293 คนในมาเลเซีย\n\nหลักฐานบอกอะไร\nแทนที่จะมี “วันพีค” เดียวที่กำหนดตายตัว การสำรวจพบว่าความรุนแรงของอาการถอนสัมพันธ์กับทั้งปริมาณและระยะเวลาที่ใช้ ผู้ที่ดื่มกระท่อมวันละสามแก้วขึ้นไปมีโอกาสพึ่งพารุนแรงและมีอาการถอนที่ยากกว่ามาก สำหรับคนส่วนใหญ่ ช่วงสองสามวันแรกหลังหยุดจะยากที่สุด\n\nอาการที่รายงานบ่อย\n• ปวดกล้ามเนื้อและข้อ ขากระสับกระส่าย\n• นอนไม่หลับแม้อ่อนเพลีย\n• คลื่นไส้ ปวดเกร็งท้อง และท้องเสีย\n• วิตกกังวล อารมณ์ตก และหงุดหงิด\n• ความอยากใช้อย่างมาก\n\nผ่านช่วงนี้ไป\nการดื่มน้ำให้เพียงพอ การพักผ่อน และการดูแลตามอาการช่วยได้ หากอาการถอนรู้สึกรุนแรงจนถึงตอนนี้ มักสอดคล้องกับการใช้ในปริมาณมากกว่าหรือนานกว่า มากกว่าจะหมายถึงว่ามีสิ่งผิดปกติ และโดยทั่วไปมีแนวโน้มจะค่อย ๆ ทุเลาจากจุดนี้';

  @override
  String get kratomReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่ใช้กระท่อม\n\nแหล่งข้อมูล: Swogger และคณะ (2022), “Understanding Kratom Use: A Guide for Healthcare Providers,” Frontiers in Pharmacology\n\nหลังพ้นระยะเฉียบพลัน\nข้อมูลรายงานตนเองจากมนุษย์ที่คู่มืออ้างถึงระบุว่าอาการถอนมักหายภายในประมาณ 1–3 วันสำหรับคนส่วนใหญ่ที่หยุดใช้ เมื่อครบหนึ่งสัปดาห์ อาการทางกายเฉียบพลัน — ปวดกล้ามเนื้อ เหงื่อออก และคลื่นไส้ — มักทุเลาลงในคนส่วนใหญ่ สิ่งที่ยังอาจเหลือมักเป็นด้านจิตใจมากกว่า เช่น อ่อนเพลีย นอนหลับไม่ต่อเนื่อง และอารมณ์ตก ขณะที่ตัวรับโอปิออยด์ที่เคยถูกกระท่อมกระตุ้นกำลังปรับกลับเข้ากับสัญญาณตามธรรมชาติของร่างกาย\n\nความเสี่ยงที่แท้จริง\nคู่มือยังระบุว่ามีคนส่วนน้อยที่เลิกกระท่อมได้ยากมาก โดยผู้ที่ใช้มากและใช้มานานรายงานอาการถอนที่รุนแรงและยาวนานกว่า สัปดาห์นี้เป็นช่วงหนึ่งที่พบการกลับไปใช้ซ้ำได้บ่อย และความทนต่อสารลดลงเร็ว การกลับไปใช้ขนาดเดิม โดยเฉพาะหากมีโอปิออยด์เกี่ยวข้อง จึงอาจเป็นอันตรายจริง';

  @override
  String get kratomReferenceDay14 =>
      'สองสัปดาห์โดยไม่ใช้กระท่อม\n\nแหล่งข้อมูล: National Institute on Drug Abuse (NIDA), “Kratom”\n\nนอกช่วงเวลาที่มีข้อมูลศึกษา\nข้อมูลแบบควบคุมในมนุษย์เกี่ยวกับช่วงเวลาอาการถอนกระท่อมโดยทั่วไปครอบคลุมเพียงสองสามวันแรก จึงยังไม่มีงานวิจัยที่น่าเชื่อถือพอจะกำหนดสองสัปดาห์เป็นจุดฟื้นตัวเฉพาะ สิ่งที่บันทึกไว้คือภาพรวมที่กว้างกว่า: กระท่อมออกฤทธิ์ต่อตัวรับโอปิออยด์ชนิดเดียวกับโอปิออยด์แบบดั้งเดิม และเมื่อหยุดใช้เป็นประจำ ตัวรับเหล่านี้จะค่อย ๆ คืนความไวต่อสัญญาณตามธรรมชาติของร่างกาย\n\nสิ่งที่ผู้คนมักรายงาน\n• ความอยากอาหารและพลังงานมักดีขึ้น\n• การนอนหลับมักสม่ำเสมอขึ้น\n• อารมณ์มักคงที่ขึ้น แม้ยังผันผวนได้\n\nความอยากใช้ยังอาจถูกกระตุ้นด้วยความเครียดและสิ่งกระตุ้นที่คุ้นเคย จึงยังมีประโยชน์ที่จะมีแผนรับมือ';

  @override
  String get kratomReferenceDay30 =>
      'หนึ่งเดือนโดยไม่ใช้กระท่อม\n\nแหล่งข้อมูล: National Institute on Drug Abuse (NIDA), “Kratom”\n\nระบบรางวัลกำลังฟื้นตัว\nNIDA อธิบายว่ากระท่อมออกฤทธิ์ต่อตัวรับโอปิออยด์ในสมอง และการพึ่งพากับอาการถอนเป็นความเสี่ยงที่ได้รับการยอมรับจากการใช้เป็นประจำ ยังไม่มีการศึกษาเฉพาะที่กำหนดหนึ่งเดือนเป็นจุดฟื้นตัว แต่รูปแบบทั่วไปของการพึ่งพาที่เกี่ยวกับตัวรับโอปิออยด์คือ การตอบสนองของสมองต่อความสุขในชีวิตประจำวันค่อย ๆ กลับสู่ภาวะปกติเมื่อหยุดใช้อย่างต่อเนื่อง\n\nหนึ่งเดือนสร้างอะไรได้บ้าง\nหนึ่งเดือนโดยไม่ใช้กระท่อมคือหนึ่งเดือนของการนอน อาหาร และกิจวัตรที่สม่ำเสมอ เข้ามาแทนเวลาและแรงที่การใช้เคยต้องการ ความอยากใช้มักเกิดน้อยลงและจัดการง่ายขึ้น แม้ช่วงความเครียดสูงยังเป็นช่วงที่เปราะบางที่สุด';

  @override
  String get kratomReferenceDay90 =>
      'สามเดือนโดยไม่ใช้กระท่อม\n\nแหล่งข้อมูล: National Institute on Drug Abuse (NIDA), “Kratom”\n\nชีวิตประจำวันมั่นคงขึ้น\nกระท่อมออกฤทธิ์ต่อตัวรับโอปิออยด์ ดังนั้นสามเดือนโดยไม่ใช้จึงให้ระบบรางวัลและความเครียดของสมองมีเวลาต่อเนื่องในการสงบลง หลายคนรายงานว่าคิดได้ชัดขึ้นและมีแรงจูงใจสม่ำเสมอขึ้นเมื่อห่างจากช่วงที่ยังใช้\n\nเหตุใดจึงสำคัญ\nยิ่งเวลาผ่านจากการใช้ครั้งล่าสุดนานขึ้น แรงดึงดูดของกระท่อมในชีวิตประจำวันก็มักลดลง ทำให้หมุดหมายนี้เป็นฐานที่มั่นคงสำหรับการฟื้นตัวระยะยาว';

  @override
  String get kratomReferenceDay365 =>
      'หนึ่งปีโดยไม่ใช้กระท่อม\n\nแหล่งข้อมูล: National Institute on Drug Abuse (NIDA), “Kratom”\n\nผ่านช่วงถอนเฉียบพลันมานานแล้ว\nNIDA ไม่ได้เผยแพร่เส้นเวลาฟื้นตัวจากกระท่อมแบบเฉพาะสำหรับหนึ่งปี แต่การหยุดใช้อย่างต่อเนื่องหนึ่งปีอยู่ไกลเกินช่วงอาการถอนเฉียบพลันและอาการทางจิตใจระยะแรกที่บันทึกไว้ในงานวิจัยกระท่อม สำหรับคนส่วนใหญ่ที่มาถึงจุดนี้ ความอยากใช้มักเกิดน้อยและจัดการได้ง่ายขึ้นมาก\n\nภาพรวมที่ใหญ่กว่า\nหนึ่งปีโดยไม่ใช้กระท่อมสะท้อนการเปลี่ยนแปลงสำคัญด้านสุขภาพ การเงิน และการกำหนดทิศทางชีวิต การยังเชื่อมต่อกับแรงสนับสนุนช่วยปกป้องความก้าวหน้านี้';

  @override
  String get kratomReferenceDay730 =>
      'สองปีโดยไม่ใช้กระท่อม\n\nแหล่งที่มา: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nหลักฐานบอกอะไร\nบททบทวนกล่าวถึงภาวะพึ่งพากระท่อม ความเสี่ยงต่อการกลับไปใช้ และแนวทางดูแลระยะยาว พร้อมระบุว่ายังไม่มีแนวทางที่เป็นมาตรฐานสำหรับการคงการงดกระท่อมในระยะยาว หลักฐานไม่ได้กำหนดวาระนี้ว่าเป็นจุดสิ้นสุดทางชีววิทยาของการฟื้นตัว\n\nความหมายของวาระนี้\nเหมาะที่จะมองวาระนี้เป็นการฉลองการเปลี่ยนแปลงที่รักษาไว้ได้ ไม่ใช่เส้นตายทางการแพทย์ กิจวัตร การสนับสนุน และการตัดสินใจที่รักษาไว้ตลอดหลายปีล้วนเป็นความสำเร็จที่มีความหมายในตัวเอง';

  @override
  String get kratomReferenceDay1095 =>
      'สามปีโดยไม่ใช้กระท่อม\n\nแหล่งที่มา: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nหลักฐานบอกอะไร\nบททบทวนกล่าวถึงภาวะพึ่งพากระท่อม ความเสี่ยงต่อการกลับไปใช้ และแนวทางดูแลระยะยาว พร้อมระบุว่ายังไม่มีแนวทางที่เป็นมาตรฐานสำหรับการคงการงดกระท่อมในระยะยาว หลักฐานไม่ได้กำหนดวาระนี้ว่าเป็นจุดสิ้นสุดทางชีววิทยาของการฟื้นตัว\n\nความหมายของวาระนี้\nเหมาะที่จะมองวาระนี้เป็นการฉลองการเปลี่ยนแปลงที่รักษาไว้ได้ ไม่ใช่เส้นตายทางการแพทย์ กิจวัตร การสนับสนุน และการตัดสินใจที่รักษาไว้ตลอดหลายปีล้วนเป็นความสำเร็จที่มีความหมายในตัวเอง';

  @override
  String get kratomReferenceDay1460 =>
      'สี่ปีโดยไม่ใช้กระท่อม\n\nแหล่งที่มา: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nหลักฐานบอกอะไร\nบททบทวนกล่าวถึงภาวะพึ่งพากระท่อม ความเสี่ยงต่อการกลับไปใช้ และแนวทางดูแลระยะยาว พร้อมระบุว่ายังไม่มีแนวทางที่เป็นมาตรฐานสำหรับการคงการงดกระท่อมในระยะยาว หลักฐานไม่ได้กำหนดวาระนี้ว่าเป็นจุดสิ้นสุดทางชีววิทยาของการฟื้นตัว\n\nความหมายของวาระนี้\nเหมาะที่จะมองวาระนี้เป็นการฉลองการเปลี่ยนแปลงที่รักษาไว้ได้ ไม่ใช่เส้นตายทางการแพทย์ กิจวัตร การสนับสนุน และการตัดสินใจที่รักษาไว้ตลอดหลายปีล้วนเป็นความสำเร็จที่มีความหมายในตัวเอง';

  @override
  String get kratomReferenceDay1825 =>
      'ห้าปีโดยไม่ใช้กระท่อม\n\nแหล่งที่มา: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nหลักฐานบอกอะไร\nบททบทวนกล่าวถึงภาวะพึ่งพากระท่อม ความเสี่ยงต่อการกลับไปใช้ และแนวทางดูแลระยะยาว พร้อมระบุว่ายังไม่มีแนวทางที่เป็นมาตรฐานสำหรับการคงการงดกระท่อมในระยะยาว หลักฐานไม่ได้กำหนดวาระนี้ว่าเป็นจุดสิ้นสุดทางชีววิทยาของการฟื้นตัว\n\nความหมายของวาระนี้\nเหมาะที่จะมองวาระนี้เป็นการฉลองการเปลี่ยนแปลงที่รักษาไว้ได้ ไม่ใช่เส้นตายทางการแพทย์ กิจวัตร การสนับสนุน และการตัดสินใจที่รักษาไว้ตลอดหลายปีล้วนเป็นความสำเร็จที่มีความหมายในตัวเอง';

  @override
  String get maoiReferenceDay3 =>
      'การหยุดชะงักของ MAOI: ระยะที่มีความเสี่ยงสูงสุด\n\nที่มา: Dilsaver (1988) การวิจัยเกี่ยวกับปฏิกิริยาการถอน MAOI\n\nคำเตือนด้านความปลอดภัยที่สำคัญ\nMAOIs มีความเสี่ยงที่ร้ายแรงที่สุดในการหยุดยาในกลุ่มยาต้านอาการซึมเศร้าการหยุดกะทันหัน โดยเฉพาะฟีเนลซีนและทรานิลไซโปรมีน อาจทำให้เกิดปฏิกิริยารุนแรง ได้แก่:\n• ความวิตกกังวลและความปั่นป่วนอย่างรุนแรง\n• พูดถูกกดดันและกระสับกระส่าย\n• นอนไม่หลับหรือง่วงนอน\n• อาการประสาทหลอน\n• อาการเพ้อและโรคจิตแบบหวาดระแวง\n\nหากคุณมีอาการเหล่านี้ ให้ไปพบแพทย์ทันที\n\nMAOI ทำงานอย่างไร\nMAOI ทำงานโดยการผูกมัดและปิดการใช้งานเอนไซม์ monoamine oxidase อย่างถาวร (MAO-A และ MAO-B)โดยปกติเอนไซม์เหล่านี้จะสลายเซโรโทนิน นอร์เอพิเนฟริน โดปามีน และไทรามีนในสมองและลำไส้เนื่องจากตัวเอนไซม์ถูกทำลายมากกว่าแค่ถูกบล็อก การฟื้นตัวจึงขึ้นอยู่กับร่างกายที่ผลิตเอนไซม์ใหม่ มากกว่าขึ้นอยู่กับความเร็วของยาในการล้างกระแสเลือด';

  @override
  String get maoiReferenceDay7 =>
      'หนึ่งสัปดาห์หลังจาก MAOI: การสังเคราะห์เอนไซม์ MAO กำลังดำเนินการ\n\nที่มา: \"สารยับยั้งโมโนเอมีนออกซิเดส (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nกระบวนการกู้คืนเอนไซม์\nซึ่งแตกต่างจาก SSRIs, SNRIs และ TCAs ซึ่งยับยั้งการดูดซึมสารเคมีในสมองแบบย้อนกลับได้ MAOIs ที่ไม่สามารถย้อนกลับได้ (phenelzine, tranylcypromine) จะทำลายโมเลกุลของเอนไซม์ monoamine oxidase อย่างถาวรการชะล้างทางคลินิกจึงขึ้นอยู่กับความเร็วที่ร่างกายสามารถสังเคราะห์เอนไซม์ใหม่ทั้งหมดได้ ประมาณ 2 สัปดาห์ แทนที่จะขึ้นอยู่กับความเร็วของตัวยาในการล้างกระแสเลือด\n\nเกิดอะไรขึ้นในหนึ่งสัปดาห์\n• การสังเคราะห์เอนไซม์ MAO-A และ MAO-B อยู่ในระหว่างดำเนินการอย่างดี โดยประมาณกลางคันของหน้าต่างการสังเคราะห์ใหม่ ~2 สัปดาห์\n• ระยะความเสี่ยงเฉียบพลันที่อธิบายไว้ในวันที่ 3 กำลังจะผ่านไป แม้ว่าการดูแลทางการแพทย์อย่างใกล้ชิดยังคงเป็นสิ่งสำคัญ\n\nข้อควรระวังด้านอาหาร\nการรักษาด้วย MAOI จำเป็นต้องรับประทานอาหารที่มีไทรามีนต่ำ เนื่องจากเอนไซม์เหล่านี้มักจะสลายไทรามีนและป้องกันไม่ให้กระตุ้นให้เกิดภาวะความดันโลหิตสูงคำแนะนำคือให้ปฏิบัติตามข้อจำกัดด้านอาหารอย่างต่อเนื่องผ่านหน้าต่างการสังเคราะห์ใหม่นี้ แพทย์ที่สั่งยาจะแนะนำเมื่อปลอดภัยที่จะผ่อนคลายอาการเหล่านั้น';

  @override
  String get maoiReferenceDay14 =>
      'สองสัปดาห์หลังจาก MAOIs: กิจกรรมของเอนไซม์ MAO ได้รับการฟื้นฟูอย่างมาก\n\nที่มา: Fritz และคณะ(2526), จิตเวชศาสตร์ชีวภาพ\n\nเครื่องหมายสองสัปดาห์ที่สำคัญ\nสองสัปดาห์เป็นกรอบเวลาการชะล้างทางคลินิกมาตรฐานสำหรับการฟื้นฟูเอนไซม์ MAO หลังจากหยุด MAOI ชนิดออกฤทธิ์แบบย้อนกลับไม่ได้ เช่น ทรานิลไซโปรมีนหรือฟีเนลซีนจากการศึกษา tranylcypromine การวิจัยนี้พบว่ากิจกรรมการเร่งปฏิกิริยาของเกล็ดเลือด MAO-B ซึ่งลดลงอย่างรวดเร็วภายในหนึ่งวันหลังการให้ยา จะฟื้นตัวเป็นปกติภายในเวลาประมาณสองสัปดาห์ เนื่องจากร่างกายจะแทนที่เกล็ดเลือดที่ได้รับผลกระทบจากยาด้วยเกล็ดเลือดสดที่มีเอนไซม์ที่ออกฤทธิ์ แม้ว่าระดับโปรตีน MAO-B ทั้งหมดจะไม่เปลี่ยนแปลงก็ตาม\n\nการฟื้นตัวของเอนไซม์ MAO\n• กิจกรรมของเกล็ดเลือด MAO-B ได้รับการฟื้นตัวอย่างมีนัยสำคัญเมื่อถึงจุดนี้\n• สมอง MAO-A และ MAO-B ซึ่งเป็นไปตามไทม์ไลน์การสังเคราะห์ใหม่ที่คล้ายกันในวงกว้าง ก็ได้รับการฟื้นฟูเป็นส่วนใหญ่เช่นกัน\n• เมแทบอลิซึมของไทรามีนกลับมาเป็นปกติอีกครั้ง — โดยทั่วไปคุณสามารถผ่อนคลายข้อจำกัดด้านอาหารของ MAOI ได้โดยการปรึกษากับผู้สั่งจ่ายยาของคุณ\n\nสมดุลเคมีในสมองกลับคืน\nเมื่อการทำงานของเอนไซม์ MAO ฟื้นตัวขึ้น ระบบเคมีในสมองที่ MAOI ได้รับผลกระทบก็เริ่มอยู่ภายใต้การควบคุมตามธรรมชาติ:\n• Serotonin, norepinephrine และ dopamine จะไม่ถูกเพิ่มสูงขึ้นโดยการยับยั้ง MAO อีกต่อไป\n• ภาวะภูมิไวเกินของตัวรับโมโนเอมีน (เกิดจากระดับสารเคมีในสมองที่เพิ่มขึ้นอย่างเรื้อรังของ MAOI) กำลังเริ่มหายไป\n• การควบคุมอารมณ์และพลังงานตามธรรมชาติกำลังกลับมา';

  @override
  String get maoiReferenceDay30 =>
      'หนึ่งเดือนหลังจาก MAOIs: การปรับสมดุลระบบเคมีและสมอง\n\nที่มา: \"สารยับยั้งโมโนเอมีนออกซิเดส (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nการประเมินหนึ่งเดือน\nหนึ่งเดือนหลังจากการหยุดใช้ MAOI ก็เลยช่วงการสังเคราะห์เอนไซม์ MAO ใหม่ประมาณ 2 สัปดาห์ที่อธิบายไว้ในแหล่งนี้ไปแล้ว ดังนั้นเมื่อถึงจุดนี้ กิจกรรมของเอนไซม์ MAO ก็ฟื้นตัวเต็มที่ และระบบเคมีในสมองอยู่ภายใต้การควบคุมตามธรรมชาติทั้งหมด\n\nสิ่งที่ได้คืนมาในหนึ่งเดือน\n• กิจกรรมของเอนไซม์ MAO สมบูรณ์: ทั้ง MAO-A และ MAO-B ทำงานได้อย่างสมบูรณ์\n• ข้อจำกัดด้านอาหารได้รับการแก้ไขแล้ว: การรับประทานอาหารตามปกติโดยไม่มีข้อจำกัดด้านไทรามีน\n• การเสื่อมของเซโรโทนินตามธรรมชาติ: วงจรการหมุนเวียนของเซโรโทนินตามปกติของสมองกลับคืนมา\n• การควบคุมแคทีโคลามีนตามธรรมชาติ: ระดับโดปามีนและนอร์เอพิเนฟรินควบคุมโดยกิจกรรม MAO ตามธรรมชาติ\n\nข้อควรระวังเรื่องปฏิกิริยาระหว่างยา\nMAOIs เกี่ยวข้องกับปฏิกิริยาที่คุกคามถึงชีวิตกับยาเซโรโทนินความเสี่ยงในการโต้ตอบเหล่านี้ได้รับการแก้ไขแล้วภายในเวลาหนึ่งเดือนอย่างไรก็ตาม ควรแจ้งให้ผู้สั่งจ่ายยาและเภสัชกรทราบถึงการใช้ MAOI ก่อนหน้านี้เสมอ เมื่อมีการสั่งยาใหม่';

  @override
  String get maoiReferenceDay90 =>
      'สามเดือนหลังหยุด MAOI: พ้นระยะถอนยาเฉียบพลัน\n\nแหล่งข้อมูล: \"Antidepressant Withdrawal Syndrome\", Therapeutics Letter 112 (2018), Therapeutics Initiative, NCBI Bookshelf\n\nอาการถอนยาในยาต้านซึมเศร้าหลายกลุ่ม\nการทบทวนหลักฐานนี้ถือว่าอาการถอนยาต้านซึมเศร้าเป็นปรากฏการณ์จริงที่เกี่ยวข้องกับภาวะทนยาและการพึ่งพายา หลักฐานโดยละเอียดเน้นที่ SSRI และ SNRI เป็นหลัก แต่มีการยอมรับอาการถอนยาในยาต้านซึมเศร้าหลายกลุ่ม รวมถึงหลังหยุด MAOI อาการ \"มักเริ่มภายในไม่กี่วันหลังหยุดยา\" และ \"ส่วนใหญ่… หายภายใน 2 สัปดาห์\" แม้บางรายจะนานกว่านั้น\n\nเมื่อถึงสามเดือน\nเมื่อครบสามเดือน ระยะถอนยาเฉียบพลันผ่านไปนานแล้วสำหรับคนส่วนใหญ่ และร่างกายได้ปรับตัวมานานให้ควบคุมโมโนเอมีนโดยไม่มีการยับยั้ง MAO\n\nสัญญาณการฟื้นตัวและ \"การตอบสนองของตัวรับ\"\nการยืนยันว่าตัวรับเซโรโทนิน นอร์เอพิเนฟริน และโดปามีนทั้งหมด \"กลับมาตอบสนองเต็มที่ภายในสามเดือน\" เกินกว่าที่หลักฐานระบุได้ สิ่งที่เชื่อถือได้คือระยะถอนยามักผ่านไปแล้ว และสำหรับคนส่วนใหญ่ อารมณ์ พลังงาน และช่วงอารมณ์กำลังคงที่ขึ้นภายใต้การส่งสัญญาณของสมองตามธรรมชาติที่ควบคุมตัวเอง\n\nอาการถอนยาหรือการกลับเป็นซ้ำ\nTherapeutics Letter เน้นให้แยกอาการถอนยาออกจากการกลับมาของภาวะเดิม หากอาการยังคงอยู่เมื่อครบสามเดือน ควรทบทวนกับผู้สั่งจ่ายยาแทนที่จะสรุปว่าเป็นอาการถอนยาเพียงอย่างเดียว';

  @override
  String get maoiReferenceDay180 =>
      'หกเดือนหลังหยุด MAOI: การฟื้นตัวระยะยาว\n\nแหล่งข้อมูล: Zwiebel & Viguera (2022), Cleveland Clinic Journal of Medicine\n\nการประเมินที่หกเดือน\nบททบทวนนี้อธิบายว่ายาต้านซึมเศร้าทำงานส่วนหนึ่งโดยทำให้ตัวรับโมโนเอมีนลดการตอบสนองลงตามเวลา และเมื่อหยุดยา การเปลี่ยนแปลงนี้อาจใช้เวลาหลายสัปดาห์ถึงหลายเดือนจึงจะย้อนกลับ ซึ่งช้ากว่าการสร้างเอนไซม์ MAO ใหม่ที่ใช้เวลาราวสองสัปดาห์\n\nเมื่อถึงหกเดือน\nหกเดือนอยู่เลยช่วงปรับตัวของตัวรับที่กินเวลาหลายสัปดาห์ถึงหลายเดือนสำหรับคนส่วนใหญ่มากแล้ว ขณะที่กิจกรรมของเอนไซม์กลับเป็นปกติภายในเดือนแรก งานวิจัยไม่ได้กำหนดเวลาที่แน่นอนแบบวันต่อวันว่าตัวรับเซโรโทนิน นอร์เอพิเนฟริน และโดปามีนจะกลับมาตอบสนองเต็มที่เมื่อใด สิ่งที่เชื่อถือได้คือเมื่อถึงหกเดือน คนส่วนใหญ่ทำงานด้วยการส่งสัญญาณของสมองตามธรรมชาติที่ควบคุมตัวเอง\n\nหมายเหตุเรื่องฟีนเอทิลเอมีน\nMAOI ยังยับยั้งการสลายฟีนเอทิลเอมีน (PEA) ซึ่งเป็น trace amine ที่เกี่ยวข้องกับอารมณ์และพลังงาน คาดว่าเมแทบอลิซึมของมันจะกลับเป็นปกติไปพร้อมกับการฟื้นตัวของเอนไซม์ MAO โดยรวม แต่เช่นเดียวกับการกลับมาตอบสนองของตัวรับ งานวิจัยไม่ได้กำหนดกรอบเวลาที่แม่นยำเฉพาะสำหรับ PEA';

  @override
  String get maoiReferenceDay365 =>
      'หนึ่งปีหลังหยุด MAOI: หนึ่งปีแห่งการฟื้นตัว\n\nแหล่งข้อมูล: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nหนึ่งปี: ความสำเร็จสำคัญ\nการครบหนึ่งปีหลังหยุด MAOI เป็นหมุดหมายที่มีความหมายมาก การหยุด MAOI ต้องดูแลเป็นพิเศษเพราะกลไกการออกฤทธิ์แบบย้อนกลับไม่ได้ อาหารไทรามีนต่ำที่เคร่งครัด และข้อควรระวังเรื่องปฏิกิริยาระหว่างยาที่แตกต่างจากยาต้านซึมเศร้ากลุ่มอื่น\n\nสิ่งที่หนึ่งปีนี้หมายถึง\n• หนึ่งปีเต็มของกิจกรรม monoamine oxidase ตามธรรมชาติที่ควบคุมตัวเอง หลังการสร้างเอนไซม์ใหม่เสร็จภายในเดือนแรก\n• แสดงให้เห็นว่าสามารถรักษาความเป็นอยู่ที่ดีโดยไม่ต้องมีการยับยั้ง MAO จากยา\n• เป็นช่วงเวลาที่ยาวนานพอให้มั่นใจว่าความเสี่ยงเฉียบพลันจากการหยุดยาในวันที่ 3 ผ่านไปแล้ว\n\nหมายเหตุเรื่อง MAOI\nMAOI ยังมีประสิทธิภาพเด่นในภาวะดื้อต่อการรักษาบางชนิดและภาวะซึมเศร้าแบบ atypical การหยุดยาได้สำเร็จไม่ได้ลดคุณค่าของยา แต่สะท้อนความสามารถของสมองในการฟื้นตัวและความสามารถของผู้ป่วยในการผ่านกระบวนการทางการแพทย์ที่ต้องใช้ความระมัดระวังมาก ข้อควรระวังระยะยาวข้อหนึ่งคือควรแจ้งผู้สั่งจ่ายยาหรือวิสัญญีแพทย์รายใหม่เกี่ยวกับประวัติการใช้ MAOI ต่อไป เพราะปฏิกิริยาระหว่างยาบางอย่างยังควรได้รับการระบุไว้ในระยะยาว';

  @override
  String get marijuanaReferenceDay1 =>
      'การถอนกัญชา: วันแรก\n\nที่มา: \"กลุ่มอาการถอนกัญชา: ข้อมูลเชิงลึกในปัจจุบัน\" การใช้สารเสพติดและการฟื้นฟูสมรรถภาพ (2017) บน PubMed Central\n\nการถอนกัญชามีจริง\nการทบทวนโดยผู้ทรงคุณวุฒินี้ระบุว่ากลุ่มอาการถอนกัญชา (CWS) เป็นภาวะทางคลินิกที่ได้รับการตรวจสอบอย่างดี ซึ่งเกิดขึ้นในประมาณ 90% ของผู้ที่ได้รับการวินิจฉัยว่าติดกัญชาหลังจากที่หยุดใช้ความรุนแรงสูงสุดโดยเฉลี่ยเทียบได้กับกลุ่มอาการถอนยาสูบ\n\nเหตุใดอาการถอนจึงเกิดขึ้น\nTHC ทำหน้าที่ในระบบเอนโดแคนนาบินอยด์ ซึ่งเป็นตัวรับ CB1 ที่เกี่ยวข้องกับอารมณ์ ความอยากอาหาร การนอนหลับ ความจำ และความเครียดด้วยการใช้งานเรื้อรัง สมองจะควบคุมระบบนี้ลงเมื่อกัญชาหยุด กัญชาจะใช้งานไม่ได้ชั่วคราวการทบทวนบันทึกว่าตัวรับ CB1 กลับสู่การทำงานปกติภายในประมาณสี่สัปดาห์หลังจากหยุดใช้กัญชา\n\nเริ่มเป็นวันแรก\nเอกสารการตรวจสอบระบุว่าอาการทางกายภาพมักจะปรากฏขึ้นก่อน — ภายใน 1–3 วันนับจากการใช้ครั้งสุดท้าย — ในขณะที่อาการทางจิตจะเกิดขึ้นในช่วง 2–10 วันอาการเริ่มแรก ได้แก่:\n• หงุดหงิด วิตกกังวล และกระสับกระส่าย\n• นอนหลับยาก\n• ความอยากอาหารลดลง\n• ความตึงเครียดทางร่างกาย เหงื่อออก หรือหนาวสั่น\n• อารมณ์ซึมเศร้า\n\nความรุนแรง\nCWS ไม่เป็นอันตรายทางการแพทย์ และอาการต่างๆ มักจะไม่รุนแรงถึงปานกลาง แต่การทบทวนตั้งข้อสังเกตว่าอาการเหล่านี้น่าวิตกมากพอที่จะกระตุ้นให้เกิดอาการกำเริบอีก ซึ่งเป็นเหตุผลว่าทำไมการทำความเข้าใจไทม์ไลน์จึงมีความสำคัญ';

  @override
  String get marijuanaReferenceDay3 =>
      'เส้นเวลาการถอนกัญชา: วันแรก ๆ\n\nที่มา: \"ระยะเวลาของอาการถอนกัญชา DSM-5 ในผู้เสพสารเสพติดหลายชนิด\" BMC Psychiatry (2013) บน PubMed Central\n\nหลักสูตรเวลาที่วัดได้\nการศึกษานี้ติดตามอาการถอนกัญชา DSM-5 ในผู้ป่วย 90 รายในช่วงสี่สัปดาห์ ทำให้เกิดภาพที่ชัดเจนที่สุดว่าอาการเกิดขึ้นและลดลงอย่างไรความรุนแรงโดยรวมเป็นไปตามเส้นโค้ง: เพิ่มขึ้น แล้วลดลงในช่วงสัปดาห์ต่อมา\n\nสิ่งที่พีคส์ในช่วงต้น\nอาการที่ก่อกวนทางร่างกายมากที่สุดหลายอย่างจะรุนแรงขึ้นภายในสองสามวันแรกหลังจากหยุด:\n• อาการนอนไม่หลับ — สูงสุดประมาณวันที่ 1\n• อาการประหม่า — สูงสุดประมาณวันที่ 4\n• อารมณ์ซึมเศร้าและอาการทางกายภาพ — มีอาการสูงสุดประมาณวันที่ 5\n• กระสับกระส่าย — สูงสุดประมาณวันที่ 6\n\nอะไรจะเกิดขึ้นในภายหลัง\nผลการศึกษาพบว่ามีอาการบางอย่างเกิดขึ้นและสูงสุดช้ากว่าสัปดาห์แรก:\n• ความฝันอันไม่พึงประสงค์ที่ชัดเจน — สูงสุดประมาณวันที่ 11\n• อาการหงุดหงิดและโกรธ — สูงสุดประมาณวันที่ 14\n\nการนอนหลับและกัญชา\nความฝันที่ล่าช้าและสดใสสะท้อนถึงการฟื้นตัวของ REM: กัญชาระงับการนอนหลับ REM ในระหว่างการใช้งาน และสมองจะชดเชยมากเกินไปเมื่อหยุดผู้เขียนโต้แย้งว่าอาการนี้เป็นเรื่องปกติมากพอที่จะอยู่ในเกณฑ์การถอนตัวอย่างเป็นทางการ\n\nTakeaway สำหรับวันที่สาม\nในวันที่สาม คุณจะเข้าสู่ช่วงจุดสูงสุดทางกายภาพในช่วงแรก อาการนอนไม่หลับ ความกังวลใจ และกระสับกระส่าย แทบจะแย่ที่สุดแล้วเส้นโค้งที่สม่ำเสมอและคาดเดาได้นั้นทำให้มั่นใจได้: อาการเหล่านี้มีทิศทางที่ทราบอยู่แล้วและลดลงจากจุดนี้';

  @override
  String get marijuanaReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่มีกัญชา: เลวร้ายที่สุด\n\nที่มา: \"กลุ่มอาการถอนกัญชา: ข้อมูลเชิงลึกในปัจจุบัน\" การใช้สารเสพติดและการฟื้นฟูสมรรถภาพ (2017) บน PubMed Central\n\nโดยที่หนึ่งสัปดาห์อยู่ในซินโดรม\nการทบทวนนี้บันทึกว่ากลุ่มอาการถอนกัญชามักจะกินเวลานานถึงสามสัปดาห์ โดยช่วงเวลาที่น่าวิตกที่สุดอยู่ในช่วงระหว่างสัปดาห์แรกถึงสัปดาห์ที่สามในหนึ่งสัปดาห์ อาการทางกายภาพที่เกิดขึ้นในช่วงแรกๆ เช่น นอนไม่หลับ เบื่ออาหาร กระสับกระส่าย มักจะผ่านพ้นจุดสูงสุดและผ่อนคลายลงแล้ว\n\nสิ่งที่ยังคงลงตัว\nการทบทวนนี้จะแยกแยะอาการทางร่างกายที่เกิดขึ้นในช่วงแรกออกจากอาการทางจิตที่เกิดขึ้นในภายหลังในหนึ่งสัปดาห์:\n• อาการไม่สบายทางร่างกายและความอยากอาหารดีขึ้นอย่างมาก\n• การนอนหลับยังคงถูกรบกวนสำหรับหลายๆ คน โดยความฝันที่ชัดเจน (REM rebound) มักจะถึงจุดสูงสุดในช่วงนี้\n• อาการหงุดหงิดและอารมณ์อาจยังคงอยู่ในระดับสูง เนื่องจากอาการเหล่านี้มักจะรุนแรงขึ้นในช่วงสองสัปดาห์แรก\n\nชีววิทยาของการฟื้นฟู\nภายใต้การเปลี่ยนแปลงเหล่านี้ การทบทวนตั้งข้อสังเกตว่าตัวรับ CB1 ที่ลดลงจะกลับมาทำงานตามปกติภายในประมาณสี่สัปดาห์หลังจากหยุดใช้กัญชาหนึ่งสัปดาห์ต่อมา กฎระเบียบใหม่ดังกล่าวกำลังดำเนินการไปด้วยดี ระบบกำลังฟื้นตัวแม้ว่าอาการบางอย่างจะยังคงอยู่ก็ตาม\n\nซื้อกลับบ้าน\nการไปถึงหนึ่งสัปดาห์หมายถึงจุดสูงสุดทางกายภาพอันเฉียบพลันอยู่ข้างหลังคุณอาการการนอนหลับและอารมณ์ที่เหลืออยู่เป็นส่วนหนึ่งของกลุ่มอาการที่ทราบแน่ชัดและมีขอบเขตจำกัด ซึ่งจะค่อยๆ หายไปในอีก 2-3 สัปดาห์ข้างหน้า';

  @override
  String get marijuanaReferenceDay14 =>
      'สองสัปดาห์โดยไม่มีกัญชา: การถอนตัวแบบเฉียบพลันสิ้นสุดลง\n\nที่มา: Budney, AJ และคณะ(2003) — การศึกษาแบบทบทวนโดยผู้ทรงคุณวุฒิเกี่ยวกับหลักสูตรเวลาถอนกัญชา\n\nผลการวิจัย\nการศึกษาที่ได้รับการตรวจสอบโดยผู้ทรงคุณวุฒินี้บันทึกระยะเวลาของอาการถอนกัญชาในผู้ใช้ทั่วไปอย่างเป็นระบบผลการวิจัยพบว่ากลุ่มอาการถอนยาเฉียบพลันจะถึงจุดสูงสุดภายในสัปดาห์แรก และจะหายไปเองภายใน 2 สัปดาห์หลังจากหยุดแสดงอาการส่วนใหญ่\n\nสิ่งที่แก้ไขได้ภายใน 2 สัปดาห์\nการศึกษาบันทึกไว้ว่าภายใน 14 วัน อาการต่อไปนี้หายไปอย่างมากในผู้เข้าร่วมการศึกษา:\n• ความรู้สึกไม่สบายทางร่างกายและอาการทางร่างกาย\n• รบกวนความอยากอาหาร\n• รบกวนการนอนหลับมากที่สุด\n• หงุดหงิดและวิตกกังวลถึงขีดสุด\n\nสิ่งที่อาจคงอยู่นานกว่า 2 สัปดาห์\nการวิจัยยังระบุถึงอาการที่ยังคงมีอยู่เกินเครื่องหมายสองสัปดาห์ในผู้ใช้บางราย:\n• อารมณ์ซึมเศร้า\n• มีปัญหาเรื่องสมาธิ\n• คุณภาพการนอนหลับ (แม้ว่าจะดีขึ้นก็ตาม)\n\nความสำคัญของเครื่องหมาย 2 สัปดาห์\nการผ่านเครื่องหมายสองสัปดาห์ไปนั้นมีความสำคัญ เนื่องจากหมายความว่าอาการถอนตัวแบบเฉียบพลันนั้นเกือบจะสมบูรณ์แล้วความท้าทายที่นอกเหนือจากประเด็นนี้ส่วนใหญ่เกี่ยวข้องกับการฟื้นฟูสมองในระยะยาว และการจัดการสาเหตุเบื้องหลังของการใช้กัญชา มากกว่าการตอบสนองทางสรีรวิทยาเฉียบพลันต่อการหยุด';

  @override
  String get marijuanaReferenceDay30 =>
      'หนึ่งเดือนโดยไม่มีกัญชา: ฟังก์ชั่นหน่วยความจำดีขึ้น\n\nที่มา: Pope และคณะ(2544) จดหมายเหตุของจิตเวชศาสตร์ทั่วไป\n\nกัญชากับความทรงจำ: ปัญหา\nการศึกษานี้ติดตามผู้ใช้กัญชาจำนวนมากและระยะยาวตลอด 28 วันของการงดเว้นที่ได้รับการยืนยัน และเปรียบเทียบผลการทดสอบการคิดและความจำกับผู้ใช้ที่ไม่รุนแรงและผู้ไม่ใช้ในช่วงเริ่มต้นของการหยุดใช้กัญชา และอีกครั้งในวันที่ 1 และ 7 ผู้ใช้จำนวนมากทำงานได้แย่กว่าการควบคุมการเรียกคืนรายการคำศัพท์ ซึ่งเป็นการขาดดุลที่ติดตามด้วยระดับสาร THC ในปัสสาวะ ซึ่งสะท้อนถึงการสัมผัสยาล่าสุดมากกว่าการใช้ตลอดชีวิต\n\nข่าวดี: ฟื้นตัวภายในวันที่ 28\nภายในวันที่ 28 ผู้ใช้จำนวนมาก ผู้ใช้ขนาดเล็ก และผู้ที่ไม่ใช่ผู้ใช้ดำเนินการแทบจะเหมือนกันในการทดสอบการคิดและความจำของการศึกษานี้นอกจากนี้ยังไม่มีความสัมพันธ์ที่มีนัยสำคัญระหว่างการใช้กัญชาตลอดอายุการใช้งานกับการทดสอบประสิทธิภาพ ณ จุดนั้น\n\nสิ่งนี้หมายความว่าอย่างไรใน 30 วัน\n• การเรียนรู้ด้วยวาจาและการจดจำได้กลับสู่ระดับกลุ่มควบคุมแล้ว\n• การขาดดุลคงเหลือที่พบในสัปดาห์แรกได้รับการแก้ไขแล้ว\n• การขาดดุลที่เหลืออยู่ก่อนหน้านี้เชื่อมโยงกับความเสี่ยงที่เกิดขึ้นล่าสุด ไม่ใช่ความเสียหายถาวร\n\nสิ่งที่แสดงหลักฐาน\nเมื่อถึงวันที่ 28 ผู้ใช้จำนวนมากแทบจะแยกไม่ออกจากผู้ใช้ขนาดเล็กและผู้ไม่ใช้ในการทดสอบการคิดและความจำชุดเต็มของการศึกษานี้การขาดดุลการเรียนรู้ด้วยวาจาและการจดจำที่พบในสัปดาห์แรกได้ฟื้นตัวสู่ระดับกลุ่มควบคุมแล้ว';

  @override
  String get marijuanaReferenceDay60 =>
      'สองเดือนโดยไม่มีกัญชา: ความเข้มข้นเพิ่มขึ้น\n\nที่มา: Roten และคณะ(2015) พฤติกรรมเสพติด\n\nคำถามวิจัย\nการศึกษาเพื่อการเลิกกัญชาในเยาวชนนี้ติดตามคะแนนการทดสอบความจำและความคิดควบคู่ไปกับการทดสอบปัสสาวะในช่วงเวลาประมาณสองเดือน โดยเปรียบเทียบผู้ใช้ที่ยังคงใช้กัญชาต่อไปกับผู้ที่หยุดใช้เมื่อเร็วๆ นี้หรือยังคงหยุดใช้กัญชาอยู่\n\nข้อค้นพบที่สำคัญ\nการหยุดใช้กัญชาอย่างต่อเนื่องสัมพันธ์กับการปรับปรุงที่สำคัญใน:\n• คะแนนหน่วยความจำคอมโพสิต\n• หน่วยความจำทางวาจาโดยเฉพาะ — โดเมนที่ได้รับผลกระทบมากที่สุด\n• ประสิทธิภาพการเคลื่อนไหวและความเร็วปฏิกิริยา\n\nเมื่อสองเดือน\nจากการงดเว้นอย่างต่อเนื่องประมาณแปดสัปดาห์ คะแนนประสิทธิภาพด้านความจำ การเคลื่อนไหว และความเร็วปฏิกิริยาได้เพิ่มขึ้นอย่างวัดผลได้เหนือจุดที่พวกเขานั่งในระหว่างการใช้งาน โดยติดตามอย่างใกล้ชิดโดยได้รับการยืนยันว่าไม่ได้ใช้งาน มากกว่าที่จะอยู่คนเดียวตามลำพัง\n\nการศึกษานี้แสดงให้เห็นอะไร\nในวัยรุ่นและผู้ใหญ่วัยหนุ่มสาวที่ติดกัญชา การหยุดใช้กัญชาอย่างต่อเนื่องทำให้หน่วยความจำรวม ความจำทางวาจา และประสิทธิภาพการเคลื่อนไหวและความเร็วปฏิกิริยาเพิ่มขึ้นอย่างมีนัยสำคัญในช่วงเวลาการรักษาประมาณสองเดือน';

  @override
  String get marijuanaReferenceDay90 =>
      'สามเดือนที่ไม่มีกัญชา: ความมั่นคงทางอารมณ์กลับมา\n\nที่มา: คอนเนอร์ และคณะ(2022), Addiction — การทบทวนทางคลินิกเกี่ยวกับการถอนกัญชา\n\nเส้นเวลาการถอนกัญชาจริง ๆ เป็นอย่างไร\nการทบทวนนี้จะอธิบายอาการถอนกัญชาซึ่งโดยทั่วไปจะเริ่มใน 24–48 ชั่วโมงหลังจากการหยุดและถึงจุดสูงสุดประมาณวันที่ 2–6ความโกรธ ความก้าวร้าว และอารมณ์หดหู่อาจเกิดขึ้นได้เร็วถึงหนึ่งสัปดาห์ แต่โดยทั่วไปจะสูงสุดหลังจากหยุดใช้กัญชาไปประมาณสองสัปดาห์การรบกวนการนอนหลับโดยเฉพาะสามารถคงอยู่ได้นานกว่าอาการอื่น\n\nที่ซึ่งสามเดือนนั่งอยู่\nภายในสามเดือน คุณจะอยู่นอกเหนือหลักสูตรการถอนตัวที่บันทึกไว้มาก โดยทั่วไปอาการจะเริ่มภายใน 24–48 ชั่วโมง อาการจะรุนแรงสูงสุดประมาณวันที่ 2–6 และแม้กระทั่งอาการทางอารมณ์และการนอนหลับที่ช้าลงจะรุนแรงขึ้นภายในสัปดาห์ต่อๆ ไปเก้าสิบวันช่วยให้อารมณ์ที่หดหู่และการนอนหลับพักผ่อนเป็นเวลาหลายเดือน\n\nหมายเหตุเกี่ยวกับระบบเอนโดแคนนาบินอยด์\nการวิจัยการถอนกัญชายังแสดงให้เห็นว่าตัวรับ CB1 ที่ลดลงจะกลับมาทำงานตามปกติภายในเวลาประมาณสี่สัปดาห์หลังจากหยุดใช้กัญชาเมื่อถึง 90 วัน คุณจะอยู่นอกกรอบเวลาการกู้คืนตัวรับนั้นมาก\n\nมองไปข้างหน้า\nการทบทวนยังกล่าวถึงการพยากรณ์โรคหลังการล้างพิษและการป้องกันการกำเริบของโรค โดยเน้นย้ำว่าการสนับสนุนอย่างต่อเนื่องและกลยุทธ์การรับมือมีความสำคัญเกินกว่ากรอบเวลาการถอนตัวแบบเฉียบพลัน';

  @override
  String get marijuanaReferenceDay180 =>
      'หกเดือนโดยไม่มีกัญชา: การฟื้นฟูการวางแผนและการตัดสินใจ\n\nที่มา: Crean, Crane & Mason (2011), วารสารการแพทย์ติดยาเสพติด\n\nการวางแผนและการตัดสินใจหลังกัญชา\nการทบทวนนี้ตรวจสอบความสนใจ การตัดสินใจ การควบคุมตนเอง ความจำในการทำงาน และความคล่องแคล่วทางวาจาตั้งแต่ชั่วโมงแรกหลังการใช้ ผ่านการหยุดใช้กัญชาในระยะยาวภายในหกเดือน คุณจะอยู่ไกลเกินกว่าผลกระทบระยะสั้นและเข้าสู่ช่วงฟื้นตัว\n\nสิ่งที่การวิจัยพบ\nปัญหาหลายประการที่เกี่ยวข้องกับการใช้งานหนักลดลงด้วยการหยุดใช้กัญชาอย่างต่อเนื่อง โดยการศึกษาบางชิ้นพบว่าสามารถฟื้นตัวได้ภายใน 28 วันบริเวณที่ฟื้นตัวได้ช้าที่สุดหลังจากใช้งานหนักและเริ่มมีอาการตั้งแต่เนิ่นๆ ได้แก่:\n• การตัดสินใจและการกล้าเสี่ยง — ทำเครื่องหมายโดยเฉพาะว่าเป็นโดเมนที่การขาดดุลอาจคงอยู่ในระยะยาวในผู้ใช้จำนวนมากและเรื้อรัง\n• ทักษะการใช้เหตุผลและวาจาเชิงนามธรรม — โดยเฉพาะในผู้ใหญ่ที่เริ่มใช้ก่อนอายุ 17 ปี\n\nการฟื้นตัวตั้งแต่เนิ่นๆ\nหกเดือนอยู่ไกลเกินกว่าผลกระทบระยะสั้นในการทบทวนนี้การวางแผน การตัดสินใจ และการให้เหตุผลจะปรับปรุงให้ดีขึ้นด้วยการงดเว้นอย่างต่อเนื่อง ทำให้การงดเว้นอย่างต่อเนื่องเป็นหนทางที่แข็งแกร่งที่สุดในการฟื้นตัวต่อไป\n\nภาพที่กว้างขึ้น\nสำหรับผู้ใหญ่ที่เริ่มมีอาการและใช้ยาเพียงเล็กน้อย แนวโน้มจะดีขึ้น ผู้คนจำนวนมากในช่วง 6 เดือนรายงานว่ามีความคิดที่ชัดเจนขึ้น การตัดสินใจที่มั่นคงมากขึ้น และความรู้สึกในการชี้ทิศทางตนเองมากขึ้นประโยชน์สูงสุดมาจากการไม่ละเว้น โดยเฉพาะหลังจากใช้งานหนักหรือเริ่มมีอาการตั้งแต่เนิ่นๆ';

  @override
  String get marijuanaReferenceDay365 =>
      'หนึ่งปีที่ไม่มีกัญชา โครงสร้างสมองจะฟื้นตัว\n\nที่มา: \"อันตรายของ Hippocampal การป้องกัน และการฟื้นตัวหลังจากการใช้กัญชาเป็นประจำ\" Translational Psychiatry (2016) บน PubMed Central\n\nการเปลี่ยนแปลงโครงสร้างจากกัญชา\nการศึกษาด้วยการสแกนสมองนี้ตรวจสอบฮิบโปแคมปัส ซึ่งเป็นพื้นที่สมองที่เป็นศูนย์กลางของหน่วยความจำในผู้ใช้ปัจจุบัน ผู้ใช้เดิม และผู้ที่ไม่ใช่ผู้ใช้ผู้ใช้ปัจจุบันที่ไม่ได้รับ CBD มีฮิบโปแคมปัสเล็กกว่าประมาณ 11% และเครื่องหมายสุขภาพเซลล์สมองต่ำกว่ากลุ่มควบคุมประมาณ 15%\n\nการค้นพบที่สำคัญ: การฟื้นฟูด้วยการหยุดใช้กัญชา\nการวิเคราะห์แบบ Curve-fitting รองรับโมเดล \"การป้องกันและการกู้คืน\"สิ่งสำคัญที่สุดคือ ผู้ใช้เก่าซึ่งละเว้นเป็นเวลาเฉลี่ยประมาณ 29 เดือน ไม่ได้แตกต่างจากการควบคุมการไม่ใช้งานมาตรการวัดความสมบูรณ์ใดๆผู้เขียนสรุปว่าอันตรายต่อพื้นที่ความจำที่เกี่ยวข้องกับ THC \"สามารถฟื้นตัวได้ด้วยการงดเว้นเป็นระยะเวลานาน\"\n\nการฟื้นฟูสมองในระยะเวลาหนึ่งปีหรือมากกว่านั้น\nเมื่อหนึ่งปีปลอดกัญชา ระบบความจำของสมองก็เข้าสู่การฟื้นฟูได้ดี ขนาดของฮิปโปแคมปัสและสุขภาพของเซลล์สมองกำลังกลับสู่ภาวะปกติ ช่วยสนับสนุนความจำและการควบคุมอารมณ์\n\nสัญญาณการกู้คืน\nผู้ใช้เก่าที่งดเว้นเป็นเวลาประมาณ 29 เดือนจะจับคู่ผู้ที่ไม่ใช่ผู้ใช้ตามมาตรการด้านสุขภาพของฮิบโปแคมปัสของการศึกษาในหนึ่งปี ระบบหน่วยความจำกำลังเคลื่อนไปตามเส้นทางการกู้คืนที่บันทึกไว้สู่ภาวะปกติ';

  @override
  String get mdmaReferenceDay1 =>
      'หลังใช้ MDMA: ช่วงคัมดาวน์\n\nที่มา: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nทำไมอารมณ์จึงตก\nMDMA กระตุ้นให้มีการหลั่งเซโรโทนินจำนวนมาก และมีผลต่อโดปามีนด้วย หลังจากนั้นเซโรโทนินที่พร้อมใช้งานในสมองจะลดลงชั่วคราว งานทบทวนนี้อธิบายภาวะอารมณ์ตกหรือ “midweek blues” ที่ตรวจพบทั้งในผู้ใช้ใหม่และผู้มีประสบการณ์ 2–5 วันหลังใช้\n\nสิ่งที่ช่วยได้\n• ดื่มน้ำและกินอาหารที่มีคุณค่า\n• นอนหลับ\n• ให้เวลาแก่ตัวเอง — ภาวะตกนี้เป็นช่วงชั่วคราว ไม่ใช่สภาพถาวร\n\nคัมดาวน์หลังใช้ครั้งเดียวต่างจากอาการถอนที่เกี่ยวข้องกับภาวะพึ่งพา งานทบทวนเดียวกันระบุว่าแบบหลังอาจมีความอยากใช้ซ้ำ แต่ไม่ได้มีอาการทางกายที่รุนแรงเป็นลักษณะเด่น';

  @override
  String get mdmaReferenceDay3 =>
      'ไม่กี่วันหลังใช้ MDMA\n\nที่มา: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nช่วง “midweek blues”\nนี่ใกล้เคียงกับช่วงที่งานทบทวนเรียกว่า “midweek blues” คืออารมณ์ที่ลดลง 2–5 วันหลังใช้ ซึ่งพบทั้งในผู้ใช้ใหม่และผู้มีประสบการณ์ และสัมพันธ์กับการลดลงของเซโรโทนินในระยะสั้นมากกว่าการเปลี่ยนแปลงถาวร\n\nสิ่งที่เริ่มดีขึ้น\n• อารมณ์มักเริ่มยกขึ้นจากจุดต่ำสุด\n• พลังงานเริ่มกลับมา\n• การนอนเริ่มกลับสู่ปกติ';

  @override
  String get mdmaReferenceDay7 =>
      'หนึ่งสัปดาห์หลังใช้ MDMA\n\nที่มา: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nพ้นช่วง “midweek blues”\nสำหรับคนส่วนใหญ่ หนึ่งสัปดาห์เลยช่วง 2–5 วันที่งานทบทวนเชื่อมโยงกับคัมดาวน์เฉียบพลันแล้ว ดังนั้นอารมณ์มักกลับเข้าใกล้ปกติ งานทบทวนระบุว่าผู้ที่ใช้หนักหรือใช้ซ้ำอาจยังมีความอยากใช้ต่อเนื่องในรูปแบบของภาวะพึ่งพา แต่ไม่ได้อธิบายว่ามีอาการถอนทางกายที่เด่นชัด\n\nเมื่อใดควรขอความช่วยเหลือ\nหากอารมณ์ตก ความวิตกกังวล หรือปัญหาการนอนยังคงอยู่หลังหนึ่งสัปดาห์ อาจเป็นมากกว่าคัมดาวน์ทั่วไปและควรคุยกับผู้เชี่ยวชาญ';

  @override
  String get mdmaReferenceDay14 =>
      'สองสัปดาห์โดยไม่ใช้ MDMA\n\nที่มา: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nช่วงเวลาการฟื้นตัว\nสำหรับคัมดาวน์หลังใช้ครั้งเดียว สองสัปดาห์ถือว่าเลยช่วงอารมณ์ตก 2–5 วันที่งานทบทวนบันทึกไว้มากแล้ว จึงควรเห็นอารมณ์ การนอน และสมาธิที่คงที่ขึ้น หลังการใช้ที่หนักหรือซ้ำ การฟื้นตัวยังดำเนินต่อหลังคัมดาวน์ และงานภาพสมองในผู้ที่งดใช้พบว่าความสามารถในการนำเซโรโทนินกลับมาใช้เพิ่มขึ้นเมื่อหยุดใช้ต่อเนื่อง\n\nสิ่งนี้หมายถึงอะไรสำหรับคุณ\nหากใช้เพียงเป็นครั้งคราว ช่วงที่หนักที่สุดน่าจะผ่านไปแล้ว หากใช้บ่อยหรือหนัก ให้เวลากับตัวเอง เพราะการฟื้นตัวของการส่งสัญญาณเซโรโทนินเต็มที่ใช้เวลานานกว่าสองสัปดาห์และจะกล่าวถึงในหมุดหมายถัดไป';

  @override
  String get mdmaReferenceDay30 =>
      'หนึ่งเดือนโดยไม่ใช้ MDMA\n\nที่มา: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" PubMed\n\nหนึ่งเดือนอยู่ตรงไหนของการฟื้นตัว\nคัมดาวน์เฉียบพลันและอาการถอนระยะแรกผ่านไปนานแล้ว อารมณ์ ความคิด และความจำมักนิ่งขึ้น งานภาพสมองแสดงว่า MDMA ลดความสามารถของสมองในการจัดการเซโรโทนิน และความสามารถนี้ฟื้นตัวเมื่อหยุดใช้ต่อเนื่อง\n\nสัญญาณการฟื้นตัว\nงานวิจัยเดียวกันพบว่าความสามารถในการนำเซโรโทนินกลับมาใช้ฟื้นตัวเมื่อหยุดใช้ต่อเนื่อง อารมณ์และการทำงานของระบบเซโรโทนินดีขึ้นก่อน ขณะที่ความจำมีจังหวะการฟื้นตัวของตัวเอง — การงดใช้ต่อเนื่องช่วยสนับสนุนทั้งสองด้าน';

  @override
  String get mdmaReferenceDay90 =>
      'สามเดือนโดยไม่ใช้ MDMA\n\nที่มา: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" PubMed\n\nการฟื้นตัวยังดำเนินต่อ\nเมื่อหยุดใช้ต่อเนื่อง ระบบเซโรโทนินของสมองยังคงฟื้นตัว โดยเฉพาะในบริเวณสมองส่วนลึก อารมณ์และการนอนมักคงที่ในช่วงนี้\n\nสัญญาณการฟื้นตัว\nการงดใช้ต่อเนื่องสนับสนุนการฟื้นตัวของตัวขนส่งเซโรโทนินในหลายบริเวณของสมอง ขณะที่อารมณ์และการนอนยังคงนิ่ง และการฟื้นตัวด้านความคิดกับความจำดำเนินต่อไป';

  @override
  String get mdmaReferenceDay365 =>
      'หนึ่งปีโดยไม่ใช้ MDMA\n\nที่มา: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" PubMed\n\nหนึ่งปีต่อมา\nหลังงดใช้หนึ่งปี สมองมีเวลานานสำหรับการฟื้นตัวของระบบเซโรโทนิน และอารมณ์มักคงที่\n\nสัญญาณการฟื้นตัว\nการงดใช้ครบหนึ่งปีเปิดช่วงเวลาฟื้นตัวที่ยาวให้ระบบเซโรโทนิน งานภาพสมองแสดงว่าความสามารถในการนำเซโรโทนินกลับมาใช้เพิ่มขึ้นตามระยะเวลาที่งดใช้ ทำให้การฟื้นตัวของระบบนี้เป็นสัญญาณทางชีวภาพที่ชัดเจนในช่วงนี้';

  @override
  String get methReferenceDay1 =>
      'การถอนเมทแอมเฟตามีน: 24 ชั่วโมงแรก\n\nแหล่งที่มา: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), PubMed\n\nช่วงทรุด\nเมทแอมเฟตามีนกระตุ้นให้โดปามีนหลั่งออกมาจำนวนมาก เมื่อหยุดใช้ ระบบนี้จึงอยู่ในภาวะพร่อง งานวิจัยนี้ติดตามอาการถอนยาทุกวันในช่วงสามสัปดาห์แรกหลังหยุดใช้ และพบว่าความรุนแรงโดยรวมสูงที่สุดภายใน 24 ชั่วโมงหลังใช้ครั้งสุดท้าย ซึ่งเป็นช่วง “ทรุด” จากการกระตุ้นอย่างรุนแรงสู่ความเหนื่อยล้าทั้งทางกายและจิตใจอย่างฉับพลัน\n\nอาการในวันแรก\nอาการที่งานวิจัยพบว่ารุนแรงที่สุดในช่วงนี้ ได้แก่:\n• เหนื่อยล้ามากและนอนมากขึ้น (hypersomnia)\n• ความอยากอาหารเพิ่มขึ้น เพราะเมทแอมเฟตามีนกดความอยากอาหารอย่างมาก\n• อารมณ์ซึมเศร้าและความสุขลดลง\n• ความอยากใช้ยาอย่างรุนแรง\n• วิตกกังวลและหงุดหงิด\n\nความปลอดภัยทางกาย\nภาวะถอนเมทแอมเฟตามีนโดยทั่วไปไม่เป็นอันตรายถึงชีวิต แต่อาการด้านซึมเศร้าที่วัดในงานวิจัยอาจรุนแรงในระยะแรกและอาจรวมถึงความคิดฆ่าตัวตาย จึงควรได้รับการดูแลทางการแพทย์ โดยเฉพาะในผู้ที่เคยใช้หนัก\n\nเริ่มผ่อนลง\nข้อค้นพบที่ให้กำลังใจคืออาการรุนแรงที่สุดในช่วงเริ่มต้นแล้วค่อย ๆ ลดลง หลังผ่านจุดสูงสุดใน 24 ชั่วโมงแรก อาการจะลดลงอย่างต่อเนื่องในวันถัด ๆ ไป — ช่วงที่ยากที่สุดอยู่ตรงจุดเริ่มต้น';

  @override
  String get methReferenceDay3 =>
      'การถอนเมทแอมเฟตามีน: วันที่สาม — ยังอยู่ในระยะเฉียบพลัน\n\nแหล่งที่มา: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), PubMed\n\nผ่านจุดสูงสุดแล้ว\nงานวิจัยพบว่าความรุนแรงของอาการถอนยาโดยรวมสูงสุดภายใน 24 ชั่วโมงแรก แล้วลดลงค่อนข้างเป็นเส้นตรงตลอดระยะเฉียบพลันประมาณ 7–10 วัน เมื่อถึงวันที่สาม คุณผ่านจุดสูงสุดแล้ว แต่ยังอยู่ในระยะเฉียบพลันและอาการยังเด่นชัดแม้แนวโน้มจะลดลง\n\nอาการวันที่สาม\nอาการที่งานวิจัยติดตามและยังสำคัญในช่วงนี้ ได้แก่:\n• ซึมเศร้าและความรู้สึกเพลิดเพลินลดลง\n• ความอยากใช้ยาอย่างรุนแรง\n• มีปัญหาในการจดจ่อและคิดให้ชัด\n• การนอนผิดปกติ ทั้งนอนไม่หลับสลับกับนอนมากเกินไป\n• ความเหนื่อยล้าที่ยังต่อเนื่อง\n\nทำไมจึงรู้สึกแบบนี้\nความรุนแรงของการถอนเมทแอมเฟตามีนสะท้อนการรบกวนระบบโดปามีนอย่างมาก อาการด้านซึมเศร้าที่งานวิจัยวัดเด่นชัดที่สุดในช่วงวันแรก ๆ ที่สำคัญคือ งานวิจัยพบว่าความรุนแรงโดยรวม “ลดลงจนใกล้ระดับกลุ่มควบคุมเมื่อสิ้นสุดสัปดาห์แรกของการหยุดใช้”\n\nช่วงนี้จะผ่านไป\nช่วงที่ยากที่สุดคือสองสามวันแรก และข้อมูลแสดงว่าอาการลดลงอย่างต่อเนื่องหลังจากนั้น การเข้าใจว่านี่เป็นภาวะชั่วคราวของสมองและระบบประสาท ไม่ใช่สภาพถาวร อาจช่วยให้ผ่านช่วงนี้ไปได้';

  @override
  String get methReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่ใช้เมทแอมเฟตามีน: ระยะเฉียบพลันสิ้นสุด\n\nแหล่งที่มา: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), PubMed\n\nสิ้นสุดระยะเฉียบพลัน\nนี่เป็นหนึ่งในข้อค้นพบที่ให้กำลังใจที่สุด งานวิจัยรายงานว่าความรุนแรงของอาการถอนยาโดยรวม รวมถึงอาการด้านซึมเศร้าที่ติดตาม “ลดลงจนใกล้ระดับกลุ่มควบคุมเมื่อสิ้นสุดสัปดาห์แรกของการหยุดใช้” ซึ่งเป็นจุดสิ้นสุดของระยะเฉียบพลัน ช่วงที่หนักที่สุดผ่านไปแล้ว\n\nสองระยะของการถอนยา\nผู้วิจัยอธิบายการถอนเมทแอมเฟตามีนว่า:\n• ระยะเฉียบพลันประมาณ 7–10 วัน ซึ่งความรุนแรงของอาการลดลงอย่างต่อเนื่องจากจุดสูงสุดในช่วงต้น\n• ระยะกึ่งเฉียบพลันอย่างน้อยอีกสองสัปดาห์ โดยอาการจะเบาลงแต่ยังอาจคงอยู่\n\nสิ่งที่อาจยังเหลือในวันที่ 7\nเมื่อเข้าสู่ระยะกึ่งเฉียบพลัน ความท้าทายหลักจะเป็นด้านจิตใจมากกว่าช่วงทรุดเฉียบพลัน:\n• อารมณ์ต่ำ แต่ดีขึ้นมากจากวันแรก ๆ\n• ความอยากใช้ยา โดยเฉพาะเมื่อเจอสิ่งกระตุ้น\n• สมาธิและความจำยังอยู่ระหว่างฟื้นตัว\n• การนอนยังค่อย ๆ ปรับตัว\n\nการฟื้นตัวทางกายดำเนินต่อ\nเมื่อระยะเฉียบพลันสิ้นสุด ความอยากอาหารกลับมาและพลังงานค่อย ๆ เพิ่มขึ้น ขณะที่ร่างกายฟื้นตัวจากผลของเมทแอมเฟตามีนต่อการนอน โภชนาการ และระบบหัวใจและหลอดเลือด';

  @override
  String get methReferenceDay30 =>
      'หนึ่งเดือนโดยไม่ใช้เมทแอมเฟตามีน: อารมณ์ดีขึ้น แต่ความอยากยังอยู่\n\nแหล่งที่มา: Zorick et al., \"Withdrawal symptoms in abstinent methamphetamine-dependent subjects,\" Addiction (2010), PubMed Central\n\nติดตามห้าสัปดาห์แรก\nงานวิจัยนี้ติดตามผู้เข้าร่วมที่พึ่งพาเมทแอมเฟตามีนและหยุดใช้ได้นานถึงห้าสัปดาห์ เทียบกับกลุ่มควบคุมสุขภาพดี จึงให้ภาพค่อนข้างชัดเจนของช่วงหนึ่งเดือน\n\nสิ่งที่ดีขึ้นในหนึ่งเดือน\n• อาการซึมเศร้า “ลดลงอย่างมากในสองสัปดาห์แรกของการหยุดใช้จนอยู่ในระดับต่ำที่คงที่” และเมื่อครบสี่สัปดาห์ก็เข้าใกล้ระดับของกลุ่มควบคุมสุขภาพดี แม้ยังไม่เท่ากันทางสถิติ\n• อาการทางจิตเวชและอาการคล้ายโรคจิตลดลงสู่ระดับต่ำเมื่อสิ้นสุดสัปดาห์ที่สอง\nดังนั้นเมื่อครบ 30 วัน อาการซึมเศร้ารุนแรงของการถอนยาในช่วงแรกจึงลดลงไปมาก — เป็นการดีขึ้นที่วัดได้จริง\n\nสิ่งที่ยังคงอยู่\nงานวิจัยชัดเจนว่าอาการหนึ่งอยู่ได้นานกว่าอย่างอื่น: ความอยากใช้ยา “ยังคงอยู่ในระดับที่ลดลงตลอดห้าสัปดาห์ของการหยุดใช้” ความอยากอ่อนลงจากสัปดาห์แรกแต่ยังไม่หาย จึงยังควรมีการสนับสนุนต่อเนื่อง\n\nใจความสำคัญ\nเมื่อครบหนึ่งเดือน ระบบสมองที่เกี่ยวข้องกับอารมณ์ฟื้นตัวพอให้ชีวิตประจำวันรู้สึกดีขึ้นกว่าช่วงถอนยาแรก ๆ มาก ความอยากที่ยังหลงเหลือเป็นส่วนหนึ่งของระยะนี้ ไม่ใช่สัญญาณของความล้มเหลว';

  @override
  String get methReferenceDay90 =>
      'สามเดือนโดยไม่ใช้เมทแอมเฟตามีน: การฟื้นตัวเริ่มแล้ว — ให้เวลากับมัน\n\nแหล่งที่มา: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\nเกี่ยวกับงานวิจัยนี้\nงานวิจัยภาพสมองชิ้นสำคัญนี้ตรวจผู้ใช้เมทแอมเฟตามีนสองครั้ง — หลังหยุดใช้ประมาณสามเดือนและอีกครั้งราว 14 เดือน — เพื่อดูว่าระบบโดปามีนฟื้นตัวอย่างไร\n\nสามเดือนอยู่ตรงไหน\nเมื่อครบสามเดือน ระยะถอนยาแรก ๆ ผ่านไปนานแล้วและการฟื้นตัวที่ลึกขึ้นของระบบโดปามีนกำลังดำเนินต่อ งานวิจัยเดียวกันพบภายหลังว่าโปรตีนที่นำโดปามีนกลับมาใช้ใหม่ในบริเวณรางวัลและการเคลื่อนไหวเพิ่มขึ้นประมาณ 16%–19% หลังหยุดใช้ 12–17 เดือน\n\nสิ่งนี้หมายถึงอะไร\nเมื่อครบ 90 วัน อาการถอนยาเฉียบพลันอยู่ไกลข้างหลัง อารมณ์และการนอนดีขึ้น และการทำบำบัดอาจได้ผลมากขึ้น แต่การฟื้นตัวเชิงลึกของระบบโดปามีนเป็นกระบวนการที่ยาวกว่าซึ่งดำเนินต่อในปีถัดไป หากแรงจูงใจหรือความรู้สึกเพลิดเพลินยังไม่เต็มที่ในเดือนที่สาม ก็สอดคล้องกับแนวทางฟื้นตัวในงานวิจัยและไม่ใช่ความล้มเหลว\n\nเหตุผลที่ควรให้เวลา\nงานวิจัยเดียวกันพบว่ายิ่งหยุดใช้นาน การฟื้นตัวของตัวขนส่งโดปามีนที่วัดได้ก็ยิ่งมาก สามเดือนเป็นรากฐาน และความก้าวหน้ายังดำเนินต่อได้';

  @override
  String get methReferenceDay180 =>
      'หกเดือนโดยไม่ใช้เมทแอมเฟตามีน: หัวใจสามารถฟื้นตัวได้\n\nแหล่งที่มา: \"Stopping Drug Abuse Can Reverse Related Heart Damage,\" American College of Cardiology (2017), รายงานการศึกษาใน JACC: Heart Failure\n\nเมทแอมเฟตามีนกับหัวใจ\nเมทแอมเฟตามีนเป็นหนึ่งในสารเสพติดที่เป็นพิษต่อหัวใจอย่างมาก อาจทำให้ความดันโลหิตสูงรุนแรงและหัวใจเต้นผิดจังหวะ และเมื่อใช้ไปนานอาจเกิดภาวะกล้ามเนื้อหัวใจผิดปกติที่เกี่ยวข้องกับเมทแอมเฟตามีน ซึ่งทำให้กล้ามเนื้อหัวใจอ่อนแรงและนำไปสู่ภาวะหัวใจล้มเหลว\n\nสิ่งที่งานวิจัยพบ\nAmerican College of Cardiology รายงานผู้ป่วยภาวะกล้ามเนื้อหัวใจผิดปกติที่เกี่ยวข้องกับเมทแอมเฟตามีน ซึ่งทุกคนมีความสามารถในการสูบฉีดของหัวใจลดลงมาก ข้อค้นพบหลักที่ให้ความหวังคือ การหยุดใช้ “สามารถย้อนความเสียหายที่ยาทำต่อหัวใจและปรับปรุงการทำงานของหัวใจได้” ผู้ที่หยุดใช้มีผลลัพธ์ดีกว่าผู้ที่ใช้ต่ออย่างชัดเจน และผู้วิจัยเน้นว่าการตรวจพบเร็ว “อาจป้องกันการเสื่อมลงของภาวะกล้ามเนื้อหัวใจผิดปกติเพิ่มเติมได้”\n\nทำไมหกเดือนจึงสำคัญ\nแต่ละเดือนที่ไม่ใช้เมทแอมเฟตามีนช่วยหยุดการได้รับพิษซ้ำต่อหัวใจและเปิดโอกาสให้กล้ามเนื้อหัวใจฟื้นตัว เมื่อครบหกเดือน ระบบหัวใจและหลอดเลือดได้พักจากการทำร้ายซ้ำเป็นเวลานาน — ซึ่งสอดคล้องกับเงื่อนไขที่งานวิจัยพบการดีขึ้น\n\nสัญญาณการฟื้นตัว\nหลักฐานให้ภาพที่น่าหวัง: การหยุดเมทแอมเฟตามีนสามารถย้อนความเสียหายของหัวใจที่เกี่ยวข้องกับยาและปรับปรุงการทำงานของหัวใจได้ หกเดือนโดยไม่รับสารกระตุ้นซ้ำทำให้หัวใจมีช่วงเวลาสำคัญสำหรับการฟื้นตัว';

  @override
  String get methReferenceDay365 =>
      'หนึ่งปีโดยไม่ใช้เมทแอมเฟตามีน: สมองฟื้นตัวอย่างวัดได้\n\nแหล่งที่มา: Wang et al., \"Partial Recovery of Brain Metabolism in Methamphetamine Abusers After Protracted Abstinence,\" American Journal of Psychiatry (2004), PubMed\n\nสิ่งที่ภาพสมองแสดง\nงานวิจัยนี้ตรวจผู้ใช้เมทแอมเฟตามีนในช่วงต้นของการหยุดใช้และอีกครั้งหลัง 12–17 เดือน พบการฟื้นตัวของสมองจริง โดยบางบริเวณฟื้นเร็วกว่าบริเวณอื่น\n\nข่าวดี: สมองส่วนลึกและการคิดฟื้นตัว\nทาลามัส ซึ่งเป็นศูนย์ส่งต่อสัญญาณลึกในสมอง เริ่มใช้พลังงานใกล้เคียงปกติมากขึ้นเมื่อหยุดใช้นานขึ้น การฟื้นตัวนี้สัมพันธ์กับการเคลื่อนไหวและความจำด้านภาษาที่ดีขึ้น จึงเห็นได้ว่าการเปลี่ยนแปลงในภาพสมองเชื่อมโยงกับการทำงานจริง\n\nวงจรรางวัลฟื้นช้ากว่า\nเมื่อครบ 12–17 เดือน ศูนย์ส่งต่อสัญญาณส่วนลึกของสมองฟื้นตัวอย่างชัดเจนและสัมพันธ์กับการเคลื่อนไหวและความจำด้านภาษาที่ดีขึ้น ระบบรางวัลและแรงจูงใจก็ยังคงแข็งแรงขึ้น ทำให้ภาพรวมหนึ่งปีเป็นการฟื้นตัวมากของการคิดและความจำ\n\nความหมายเมื่อครบหนึ่งปี\nหลังหนึ่งปี การคิดและความจำอาจดีขึ้นมากเมื่อเทียบกับช่วงต้นของการฟื้นตัว — เป็นการเปลี่ยนแปลงที่ชัดเจนและวัดได้ หากแรงจูงใจหรือความสามารถในการรู้สึกเพลิดเพลินยังตามหลังอยู่บ้าง ก็สอดคล้องกับผลวิจัยและไม่ใช่ความล้มเหลวส่วนตัว: วงจรรางวัลอาจฟื้นช้ากว่าและความแตกต่างบางอย่างอาจคงอยู่เกินหนึ่งปี';

  @override
  String get methReferenceDay420 =>
      '14 เดือนโดยไม่ใช้เมทแอมเฟตามีน: ตัวชี้วัดโดปามีนฟื้นกลับ\n\nแหล่งที่มา: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\nข้อค้นพบหลัก\nงานวิจัยภาพสมองชิ้นสำคัญนี้ตรวจผู้ใช้เมทแอมเฟตามีนในช่วงต้นของการหยุดใช้และอีกครั้งหลังประมาณ 12–17 เดือน โปรตีนที่นำโดปามีนกลับมาใช้ใหม่ในบริเวณรางวัลและการเคลื่อนไหวเพิ่มขึ้นประมาณ 16%–19% และถึงระดับที่ไม่แตกต่างอย่างมีนัยสำคัญจากกลุ่มควบคุมสุขภาพดีอีกต่อไป การหยุดใช้นานขึ้นสัมพันธ์กับการฟื้นตัวที่มากขึ้น\n\nเหตุใด DAT จึงสำคัญ\nโปรตีนเหล่านี้นำโดปามีนกลับมาใช้หลังถูกปล่อยออกมา เมทแอมเฟตามีนทำให้โปรตีนเหล่านี้ลดลงและรบกวนการควบคุมระบบโดปามีน การเพิ่มกลับขึ้นมาราว 14 เดือนจึงเป็นสัญญาณการฟื้นตัวที่แท้จริงและวัดได้\n\nสัญญาณการฟื้นตัว\nหลัง 12–17 เดือน โปรตีนที่นำโดปามีนกลับมาใช้ใหม่ในบริเวณรางวัลและการเคลื่อนไหวเพิ่มขึ้นประมาณ 16%–19% และถึงระดับของกลุ่มควบคุมสุขภาพดี ระบบโดปามีนจึงฟื้นกลับสู่ภาวะปกติอย่างวัดได้ ขณะที่การคิด ความจำ และการเคลื่อนไหวยังสามารถดีขึ้นต่อไป\n\nความหมายเมื่อครบ 14 เดือน\nระบบโดปามีนกำลังกลับสู่ภาวะปกติอย่างวัดได้ — เป็นเหตุผลจริงสำหรับความหวัง แต่การฟื้นตัวของการทำงานทั้งหมด เช่น ความจำ แรงจูงใจ และการควบคุมการเคลื่อนไหวละเอียด อาจช้ากว่าการเปลี่ยนแปลงในภาพสมองและยังดีขึ้นต่อเมื่อหยุดใช้ต่อเนื่อง';

  @override
  String get methReferenceDay730 =>
      'สองปีโดยไม่ใช้เมทแอมเฟตามีน: การคิดและอารมณ์ยังดีขึ้นต่อ\n\nแหล่งที่มา: Iudicello et al., \"Longer Term Improvement in Neurocognitive Functioning and Affective Distress Among Methamphetamine Users Who Achieve Stable Abstinence,\" Journal of Clinical and Experimental Neuropsychology (2010), PubMed Central\n\nการฟื้นตัวที่ต่อเนื่องเกินหนึ่งปี\nงานวิจัยนี้ติดตามผู้ใช้เมทแอมเฟตามีนประมาณ 13 เดือน และเปรียบเทียบผู้ที่หยุดใช้ได้อย่างสม่ำเสมอกับผู้ที่ยังใช้ต่อและกลุ่มควบคุมสุขภาพดี การหยุดใช้อย่างต่อเนื่องช่วยให้การทำงานด้านการคิดโดยรวมดีขึ้นและความทุกข์ทางอารมณ์ลดลง โดยความก้าวหน้ายังคงต่อเนื่องเกินหนึ่งปี\n\nสิ่งที่ดีขึ้น\n• การทำงานด้านการคิดโดยรวมของผู้ที่หยุดใช้อย่างสม่ำเสมอขึ้นมาถึงระดับของกลุ่มควบคุมสุขภาพดี ขณะที่ผู้ที่ยังใช้ต่อยังมีความบกพร่องอย่างมีนัยสำคัญ\n• การดีขึ้นมากที่สุดอยู่ที่ความเร็วในการประมวลผลและความสามารถด้านการเคลื่อนไหว โดยเฉพาะผู้ที่มีความบกพร่องมากในตอนเริ่มต้น\n• อารมณ์ดีขึ้นชัดเจน: มีเพียงผู้ที่หยุดใช้อย่างสม่ำเสมอที่มีภาวะซึมเศร้าและอารมณ์โดยรวมดีขึ้นอย่างมีนัยสำคัญ\n\nสัญญาณการฟื้นตัว\nผู้ที่หยุดใช้อย่างสม่ำเสมอมีการทำงานด้านการคิดโดยรวมถึงระดับของกลุ่มควบคุมสุขภาพดี และรายงานความทุกข์ทางอารมณ์น้อยลง การเรียนรู้ด้วยภาษา ความจำใช้งาน การวางแผน และสมาธิยังอาจดีขึ้นต่อหลังปีแรก ดังนั้นแนวโน้มการฟื้นตัวจึงต่อเนื่องเข้าสู่ปีที่สอง\n\nเมื่อครบสองปี\nสาระจากหลักฐานคือ การหยุดใช้อย่างต่อเนื่องยังให้ผลดีไกลเกินปีแรก — การคิดชัดขึ้น อารมณ์ดีขึ้น และการทำงานโดยรวมดีขึ้นเรื่อย ๆ แม้บางด้านอาจต้องใช้เวลานานกว่าในการฟื้นตัว';

  @override
  String get methMilestone1095Title => '3 ปี - การฟื้นตัวที่ยั่งยืน';

  @override
  String get methMilestone1095Description =>
      'สามปีที่ไม่ใช้เมทแอมเฟตามีนคือการเปลี่ยนแปลงต่อเนื่องที่วัดกันเป็นปี ไม่ใช่เป็นสัปดาห์ คุณค่าของความสำเร็จอยู่ที่ความยั่งยืนนี้เอง เพราะกิจวัตรและแรงสนับสนุนในการฟื้นตัวมีเวลาอีกหนึ่งปีเต็มในการหยั่งราก';

  @override
  String get methReferenceDay1095 =>
      '3 ปี - การฟื้นตัวที่ยั่งยืน\n\nแหล่งที่มา: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\nการทบทวนอย่างเป็นระบบและการวิเคราะห์อภิมานปี 2026 รวมงานวิจัยอิสระ 68 ชิ้น ผู้เข้าร่วม 9,045 คน การวิเคราะห์แนวโน้มตามระยะงดใช้ครอบคลุมเพียงช่วงเวลาสูงสุด 280 วัน และความเชื่อมั่นของหลักฐานในแต่ละด้านถูกจัดว่าต่ำมาก หลักฐานนี้จึงไม่สามารถกำหนดเส้นตายทางชีวภาพของการฟื้นตัวในวันครบรอบนี้ได้\n\nสามปีที่ไม่ใช้เมทแอมเฟตามีนคือการเปลี่ยนแปลงต่อเนื่องที่วัดกันเป็นปี ไม่ใช่เป็นสัปดาห์ คุณค่าของความสำเร็จอยู่ที่ความยั่งยืนนี้เอง เพราะกิจวัตรและแรงสนับสนุนในการฟื้นตัวมีเวลาอีกหนึ่งปีเต็มในการหยั่งราก';

  @override
  String get methMilestone1460Title => '4 ปี - รากฐานที่มั่นคง';

  @override
  String get methMilestone1460Description =>
      'สี่ปีคือช่วงเวลาของการเปลี่ยนแปลงที่มั่นคง งานวิจัยไม่ได้กำหนดเส้นชัยของการฟื้นตัวของสมองที่สี่ปี ดังนั้นหมุดหมายนี้จึงเฉลิมฉลองอีกหนึ่งปีเต็มที่คุณรักษาสิ่งที่สร้างมา';

  @override
  String get methReferenceDay1460 =>
      '4 ปี - รากฐานที่มั่นคง\n\nแหล่งที่มา: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\nการทบทวนอย่างเป็นระบบและการวิเคราะห์อภิมานปี 2026 รวมงานวิจัยอิสระ 68 ชิ้น ผู้เข้าร่วม 9,045 คน การวิเคราะห์แนวโน้มตามระยะงดใช้ครอบคลุมเพียงช่วงเวลาสูงสุด 280 วัน และความเชื่อมั่นของหลักฐานในแต่ละด้านถูกจัดว่าต่ำมาก หลักฐานนี้จึงไม่สามารถกำหนดเส้นตายทางชีวภาพของการฟื้นตัวในวันครบรอบนี้ได้\n\nสี่ปีคือช่วงเวลาของการเปลี่ยนแปลงที่มั่นคง งานวิจัยไม่ได้กำหนดเส้นชัยของการฟื้นตัวของสมองที่สี่ปี ดังนั้นหมุดหมายนี้จึงเฉลิมฉลองอีกหนึ่งปีเต็มที่คุณรักษาสิ่งที่สร้างมา';

  @override
  String get methMilestone1825Title => '5 ปี - การเปลี่ยนแปลงยั่งยืน';

  @override
  String get methMilestone1825Description =>
      'ห้าปีที่ไม่ใช้เมทแอมเฟตามีนเป็นหมุดหมายระยะยาวที่สำคัญ วิทยาศาสตร์ไม่อาจรับรองจุดสิ้นสุดทางชีวภาพที่ห้าปีได้ สิ่งที่แน่นอนคือการเปลี่ยนแปลงต่อเนื่องห้าปีที่ควรค่าแก่การเฉลิมฉลอง';

  @override
  String get methReferenceDay1825 =>
      '5 ปี - การเปลี่ยนแปลงยั่งยืน\n\nแหล่งที่มา: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\nการทบทวนอย่างเป็นระบบและการวิเคราะห์อภิมานปี 2026 รวมงานวิจัยอิสระ 68 ชิ้น ผู้เข้าร่วม 9,045 คน การวิเคราะห์แนวโน้มตามระยะงดใช้ครอบคลุมเพียงช่วงเวลาสูงสุด 280 วัน และความเชื่อมั่นของหลักฐานในแต่ละด้านถูกจัดว่าต่ำมาก หลักฐานนี้จึงไม่สามารถกำหนดเส้นตายทางชีวภาพของการฟื้นตัวในวันครบรอบนี้ได้\n\nห้าปีที่ไม่ใช้เมทแอมเฟตามีนเป็นหมุดหมายระยะยาวที่สำคัญ วิทยาศาสตร์ไม่อาจรับรองจุดสิ้นสุดทางชีวภาพที่ห้าปีได้ สิ่งที่แน่นอนคือการเปลี่ยนแปลงต่อเนื่องห้าปีที่ควรค่าแก่การเฉลิมฉลอง';

  @override
  String get nitrousOxideReferenceDay1 =>
      'วันแรก: ก๊าซหมดแล้ว แต่ยังต้องใส่ใจ B12\n\nที่มา: Knuf & Maani, “Nitrous Oxide,” StatPearls (NCBI Bookshelf)\n\nก๊าซออกจากร่างกายเร็วแค่ไหน\nไนตรัสออกไซด์ออกฤทธิ์เร็วภายใน 2–5 นาที และถูกกำจัดออกจากร่างกายอย่างรวดเร็วหลังหยุดสูดดม เมื่อถึงวันนี้ ตัวก๊าซเองไม่เหลืออยู่ในร่างกายแล้ว\n\nความเสี่ยงที่แท้จริงไม่ใช่ก๊าซที่ยังค้างอยู่\nหลังหยุดใช้ สิ่งสำคัญคือผลที่การได้รับซ้ำ ๆ อาจก่อไว้แล้ว ไนตรัสออกไซด์ทำให้เอนไซม์ methionine synthase ซึ่งต้องพึ่งวิตามิน B12 หยุดทำงาน StatPearls ระบุว่าการได้รับซ้ำทั้งจากงานหรือการใช้เพื่อสันทนาการอาจทำให้เกิดภาวะโลหิตจางชนิดเมกาโลบลาสติก ความผิดปกติของสมองและเส้นประสาท และในบางกรณีที่พบไม่บ่อยอาจเกิดความเสื่อมของไขสันหลัง\n\nหากเคยใช้หนักหรือใช้บ่อย\nยังไม่มีหลักฐานว่าไนตรัสออกไซด์ทำให้เกิดกลุ่มอาการถอนทางกายแบบเดียวกับโอปิออยด์หรือแอลกอฮอล์ ดังนั้นวันแรกไม่ใช่เรื่องที่ร่างกายเรียกร้องยา แต่คือการเริ่มสังเกตอาการที่เกี่ยวข้องกับ B12 ซึ่งจะกล่าวถึงในหมุดหมายถัดไป และไปตรวจหากมีอาการเกิดขึ้น';

  @override
  String get nitrousOxideReferenceDay3 =>
      '72 ชั่วโมง: ไม่มีการถอนตัว แต่ให้สังเกตอาการทางประสาท\n\nที่มา: Knuf & Maani, StatPearls;ทิคาเรีย และคณะ(2026), คิวเรียส\n\nไนตรัสออกไซด์ต่างจากฝิ่นหรือแอลกอฮอล์ตรงที่ไม่มีการบันทึกว่าทำให้เกิดอาการถอนตัวทางกายภาพสิ่งกระตุ้นในระยะนี้คือนิสัยและความอยาก ไม่ใช่ร่างกายเรียกร้องให้ยาทำงาน\n\nระวังสิ่งเหล่านี้\nการทบทวนอย่างเป็นระบบในกรณีที่มีไนตรัสออกไซด์เพื่อการพักผ่อนหย่อนใจจำนวน 1,809 ราย (Tikaria et al., 2026) พบว่าอาการของสมองและเส้นประสาท โดยเฉพาะการรู้สึกเสียวซ่าหรืออาการชา (อาชา) เป็นสัญญาณที่พบบ่อยที่สุดของอันตรายที่เกี่ยวข้องกับวิตามินบี 12 ซึ่งมักจะปรากฏแม้ว่าการตรวจเลือดแบบมาตรฐานจะดูปกติก็ตามมีรายงานปัญหาการเดินและความอ่อนแอด้วย\n\nหากคุณสังเกตเห็นสิ่งเหล่านี้\nไปพบแพทย์.การทบทวนเดียวกันพบว่าการตรวจเลือดมาตรฐาน (ฮีโมโกลบิน เซรั่ม B12) พลาดส่วนแบ่งที่สำคัญของผู้ป่วยที่ได้รับผลกระทบ การทดสอบกรดเมทิลมาโลนิก (MMA) และโฮโมซิสเทอีนมีความไวมากกว่า และควรขอเป็นพิเศษหากคุณเปิดเผยการใช้ไนตรัสออกไซด์';

  @override
  String get nitrousOxideReferenceDay7 =>
      'หนึ่งสัปดาห์: หากเคยใช้หนัก ควรตรวจ\n\nที่มา: Tikaria et al. (2026), “The Toxic Legacy of Recreational Nitrous Oxide Use,” Cureus\n\nหลักฐานบอกอะไร\nการทบทวนอย่างเป็นระบบนี้พบว่าภาวะขาดวิตามิน B12 จากไนตรัสออกไซด์มักเป็นแบบ “functional” คือระดับ B12 ในซีรัมดูปกติในผู้ป่วยที่ได้รับผลกระทบราวครึ่งหนึ่ง แม้จะมีความเสียหายต่อสมองและเส้นประสาทจริง ขณะที่ homocysteine และ MMA ผิดปกติบ่อยกว่ามาก โดยพบใน 84% และ 73% ของผู้ที่ได้รับการตรวจตามลำดับ จึงเป็นตัวบ่งชี้ที่น่าเชื่อถือกว่า\n\nควรทำอย่างไร\nหากเคยใช้หนักหรือใช้บ่อย หนึ่งสัปดาห์หลังหยุดเป็นช่วงเวลาที่เหมาะสมในการพบแพทย์และขอตรวจ homocysteine กับ MMA โดยเฉพาะ ไม่ใช่ตรวจ B12 มาตรฐานอย่างเดียว โดยเฉพาะหากมีอาการเสียวซ่า ชา ทรงตัวลำบาก หรืออ่อนแรงโดยหาสาเหตุไม่ได้\n\nมีรายงานการดีขึ้นของอาการทางระบบประสาทหลังหยุดไนตรัสออกไซด์และรักษาด้วยวิตามิน B12 อยู่บ่อยครั้ง ชุดข้อมูลทางคลินิกขนาดใหญ่รายงานว่าผู้ป่วยที่ติดตามส่วนใหญ่ดีขึ้นบางส่วนหรือทั้งหมด และการฟื้นตัวอาจดำเนินต่อในช่วงหลายเดือนแรกหลังการรักษา';

  @override
  String get nitrousOxideReferenceDay14 =>
      'สองสัปดาห์: อาการทางสมองและเส้นประสาทควรติดตามผล\n\nที่มา: Tikaria และคณะ(2026), คิวเรียส;คนุฟ & มาอานี, สเตทเพิร์ลส์\n\nสิ่งที่ได้รับรายงาน\nรายงานกรณีและซีรีส์ที่ตรวจสอบโดย Tikaria และคณะอธิบายความเสียหายของเส้นประสาทที่เกี่ยวข้องกับไนตรัสออกไซด์ซึ่งแสดงเป็นการสูญเสียประสาทสัมผัส การเดินผิดปกติ และบางครั้งความอ่อนแอที่ส่งผลต่อการเดิน - การค้นพบนี้อาจคล้ายกับสภาพสมองและเส้นประสาทของ other และบางครั้งก็อาจพลาดหากไม่ได้กล่าวถึงการใช้ไนตรัสออกไซด์กับแพทย์\n\nสัญญาณการกู้คืนบนไทม์ไลน์\nแหล่งที่มาทั้งสองแห่งไม่ได้รายงานว่าโดยปกติจะใช้เวลาฟื้นตัวนานเท่าใดเมื่อหยุดใช้และรักษาข้อบกพร่องใดๆ แล้วรายงานผู้ป่วยอธิบายถึงผลลัพธ์ที่หลากหลาย ตั้งแต่การฟื้นตัวเต็มที่ไปจนถึงการขาดดุลที่ยั่งยืน ขึ้นอยู่กับความเสียหายที่เกิดขึ้นก่อนการวินิจฉัยเป็นส่วนใหญ่สิ่งที่สอดคล้องกันในวรรณกรรมก็คือการรักษาตั้งแต่เนิ่นๆ นำไปสู่ผลลัพธ์ที่ดีกว่า\n\nหากคุณยังไม่ได้รับการตรวจสอบ\nการหยุดสองสัปดาห์ยังเป็นเวลาที่ดีที่จะไปเจาะเลือด แม้ว่าจะไม่มีอาการใดๆก็ตาม โดยเฉพาะโฮโมซิสเทอีนและ MMA แทนที่จะใช้เซรั่มบี 12 เพียงอย่างเดียว';

  @override
  String get nitrousOxideReferenceDay30 =>
      'หนึ่งเดือน: นิสัยและความอยาก ไม่ใช่การพึ่งพาทางกายภาพ\n\nที่มา: Knuf & Maani, \"ไนตรัสออกไซด์\" StatPearls (ชั้นวางหนังสือ NCBI)\n\nที่คุณยืนอยู่\nStatPearls ไม่ได้อธิบายว่าไนตรัสออกไซด์ทำให้เกิดอาการพึ่งพาทางกายภาพ ดังนั้นการหยุดหนึ่งเดือนหมายถึงการกระตุ้นที่ยืดเยื้อใดๆ เกี่ยวข้องกับนิสัย บริบททางสังคม หรือความเบื่อหน่าย มากกว่าที่ร่างกายจะปรับตัวกับการไม่มียา\n\nคำถาม B12\nหากคุณได้รับการทดสอบและรักษาอาการขาดวิตามินบี 12 เป็นเวลาหนึ่งเดือนที่แพทย์จะตรวจสอบว่าระดับของคุณและอาการต่างๆ ตอบสนองหรือไม่หากคุณไม่ได้รับการทดสอบและใช้งานอย่างหนัก ก็ยังคุ้มค่าที่จะถาม\n\nสิ่งที่ได้รับการคุ้มครอง\nทุกเดือนที่คุณไม่ได้ใช้คือหนึ่งเดือนที่คุณไม่ได้เพิ่มการยับยั้งการสังเคราะห์เมไทโอนีนที่มีอยู่หรือความเสี่ยงต่อสมองและเส้นประสาทที่มาพร้อมกับมัน';

  @override
  String get nitrousOxideReferenceDay90 =>
      'สามเดือน: หากยังไม่ได้ติดตาม ตอนนี้ควรตรวจซ้ำ\n\nที่มา: Tikaria et al. (2026), “The Toxic Legacy of Recreational Nitrous Oxide Use,” Cureus\n\nสิ่งที่เรารู้และสิ่งที่ยังไม่รู้\nหลักฐานส่วนใหญ่มาจากรายงานผู้ป่วยและชุดผู้ป่วย ไม่ใช่งานวิจัยควบคุมเรื่องการฟื้นตัว จึงยังไม่มีกรอบเวลาที่เชื่อถือได้ว่าควรคาดให้อาการดีขึ้นอย่างไรโดยเฉพาะเมื่อครบสามเดือน ผลลัพธ์แตกต่างกันมาก บางรายที่มีภาวะขาดไม่รุนแรงและตรวจพบเร็วอาจฟื้นได้เต็มที่ ขณะที่การวินิจฉัยล่าช้าหรือความเสียหายของเส้นประสาทรุนแรงกว่าอาจทำให้มีอาการคงอยู่\n\nสิ่งที่ทำได้ตอนนี้\nหากเคยมีอาการทางสมองหรือเส้นประสาทแต่ยังไม่ได้ตรวจเลือดติดตามหรือพบผู้เชี่ยวชาญ การหยุดใช้ครบสามเดือนเป็นช่วงเวลาที่เหมาะสม หากได้รับการรักษาและกำลังดีขึ้น ก็เป็นเวลาที่ควรยืนยันกับแพทย์ว่าแนวโน้มดังกล่าวยังดำเนินต่อ\n\nการไม่กลับไปใช้สำคัญที่สุด\nข้อสรุปหนึ่งที่สอดคล้องกันคือ การได้รับไนตรัสออกไซด์ต่อไปจะยังทำให้ B12 ถูกยับยั้งและเพิ่มความเสี่ยง การไม่ใช้ต่อคือปัจจัยปกป้องที่สำคัญที่สุด';

  @override
  String get nitrousOxideReferenceDay365 =>
      'หนึ่งปี: การปกป้องที่ดีที่สุดคือไม่กลับไปใช้\n\nที่มา: Knuf & Maani, StatPearls; Tikaria et al. (2026), Cureus\n\nหลักฐานไปได้ไกลแค่ไหนจริง ๆ\nไม่มีแหล่งใดรับรองกรอบเวลาการฟื้นตัวที่แน่นอน วรรณกรรมเกี่ยวกับไนตรัสออกไซด์และภาวะขาด B12 เกือบทั้งหมดมาจากรายงานผู้ป่วยรายบุคคล ไม่ใช่งานติดตามระยะยาว สิ่งที่ทราบชัดคือกลไก: ไนตรัสออกไซด์ทำให้วิตามิน B12 ถูกยับยั้งทุกครั้งที่ใช้ และการหยุดใช้จะยุติการได้รับสารที่ก่ออันตรายต่อเนื่องนี้\n\nหากเคยมีอาการจากภาวะขาด\nรายงานผู้ป่วยแสดงผลลัพธ์ที่หลากหลาย ตั้งแต่ฟื้นเต็มที่จนถึงมีอาการทางเส้นประสาทคงอยู่ โดยขึ้นอยู่มากกับระดับความเสียหายและความรวดเร็วในการรักษา หากยังมีอาการหลังหนึ่งปี นั่นเป็นเหตุผลให้ติดตามกับแพทย์ระบบประสาทต่อ ไม่ได้หมายความว่าจะดีขึ้นไม่ได้ เพราะการฟื้นของเส้นประสาทอาจดำเนินต่อได้เป็นเวลานาน\n\nสิ่งที่แน่นอน\nหนึ่งปีโดยไม่มีไนตรัสออกไซด์คือหนึ่งปีโดยไม่มีการยับยั้ง methionine synthase เพิ่มเติม นี่คือข้อสรุปที่ทั้งสองแหล่งสนับสนุน';

  @override
  String get opioidReferenceDay1 =>
      'การถอนโอปิออยด์: วันแรก\n\nที่มา: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), NCBI Bookshelf\n\n⚠ หมายเหตุด้านความปลอดภัย\nการถอนโอปิออยด์แทบไม่ทำให้เสียชีวิตในผู้ที่มีสุขภาพดีอย่างอื่น แต่สามารถก่อให้เกิดความทุกข์ทางกายอย่างรุนแรงและมีความเสี่ยงสูงต่อการกลับไปใช้ การกลับไปใช้หลังช่วงงดใช้เป็นอันตรายอย่างยิ่ง เพราะความทนต่อยาลดลงอย่างรวดเร็ว — การใช้ขนาดเท่าเดิมก่อนหยุดอาจทำให้เกิดการใช้ยาเกินขนาดจนเสียชีวิตได้ จึงแนะนำอย่างยิ่งให้มีการดูแลทางการแพทย์และการรักษาด้วยยากลุ่ม opioid agonist\n\nอาการถอนเริ่มเมื่อใด\nตารางเวลาของ WHO แตกต่างกันตามชนิดของโอปิออยด์:\n• โอปิออยด์ออกฤทธิ์สั้น (เฮโรอีน, ออกซีโคโดน): เริ่ม 8–24 ชั่วโมงหลังใช้ครั้งสุดท้าย ระยะเวลา 4–10 วัน\n• โอปิออยด์ออกฤทธิ์ยาว (เมทาโดน): เริ่ม 12–48 ชั่วโมง ระยะเวลา 10–20 วัน\n\nอาการในวันแรก\nWHO ระบุอาการระยะแรกของการถอนโอปิออยด์ไว้ เช่น:\n• วิตกกังวลและกระสับกระส่าย\n• กล้ามเนื้อเกร็งและปวดเมื่อย\n• น้ำตาและน้ำมูกไหล\n• หาวและเหงื่อออก\n• นอนไม่หลับ ร่วมกับอาการร้อนวูบวาบและหนาว\n• คลื่นไส้ในระยะแรก\n\nทำไมจึงรู้สึกทรมานมาก\nระบบโอปิออยด์ในร่างกายเกี่ยวข้องกับความเจ็บปวด ความเครียด ความเป็นอยู่ทางอารมณ์ และความสบายพื้นฐาน การใช้โอปิออยด์ระยะยาวกดการผลิตสารโอปิออยด์ตามธรรมชาติของร่างกาย เช่น เอ็นดอร์ฟิน เมื่อหยุดยา ร่างกายต้องปรับตัวโดยไม่มีการกระตุ้นแบบเดิม จึงอาจรู้สึกปวด วิตกกังวล และไม่สบายอย่างมาก WHO แนะนำการดูแลประคับประคอง รวมถึงดื่มน้ำวันละ 2–3 ลิตรและติดตามอาการวันละ 3–4 ครั้ง';

  @override
  String get opioidReferenceDay7 =>
      'หนึ่งสัปดาห์โดยไม่ใช้โอปิออยด์: อาการรุนแรงเริ่มลดลง\n\nที่มา: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), NCBI Bookshelf\n\nจุดสูงสุดและการลดลง\nWHO ระบุว่าการถอนโอปิออยด์ออกฤทธิ์สั้นมักกินเวลาประมาณ 4–10 วัน อาการจะรุนแรงขึ้นในช่วงแรกแล้วค่อย ๆ ลดลง ภายในปลายสัปดาห์แรก:\n• อาเจียนและท้องเสียมักลดลงมาก\n• กล้ามเนื้อเกร็งรุนแรงน้อยลง\n• ความทุกข์ทางกายลดลงอย่างเห็นได้ชัด\n\nสิ่งที่ยังอาจมีในวันที่ 7\nแม้อาการทางกายเฉียบพลันดีขึ้นแล้ว ปัญหาสำคัญบางอย่างอาจยังคงอยู่:\n• นอนไม่หลับ — ปัญหาการนอนเป็นหนึ่งในอาการถอนโอปิออยด์ที่อยู่นาน\n• อารมณ์ซึมและความรู้สึกด้านชา\n• อ่อนเพลียและไม่มีแรง\n• ความอยากใช้โอปิออยด์\n• ความวิตกกังวล\n\nหลังระยะถอนเฉียบพลัน\nหลังช่วงถอนระยะแรก ปัญหาการนอน อารมณ์ที่เปลี่ยนไป และความอยากใช้ยาอาจเกิดเป็นระยะต่ออีกหลายสัปดาห์หรือหลายเดือน การสนับสนุนอย่างต่อเนื่องยังมีความสำคัญในระยะฟื้นตัวที่ยาวขึ้นนี้\n\nการรักษาด้วยยากลุ่ม opioid agonist\nWHO ระบุว่าเมทาโดนและบูพรีนอร์ฟีนเป็นการรักษาที่มีประสิทธิผล ช่วยลดความรุนแรงของอาการถอนและสนับสนุนการฟื้นตัว ยาเหล่านี้ยังลดการเสียชีวิตจากความผิดปกติจากการใช้โอปิออยด์ และหลายคนใช้ยาเหล่านี้ในช่วงต้นของการฟื้นตัวระยะยาว';

  @override
  String get opioidReferenceDay14 =>
      'สองสัปดาห์โดยไม่ใช้โอปิออยด์: การนอนเริ่มดีขึ้น\n\nที่มา: งานวิจัยทางเภสัชวิทยาที่ผ่านการทบทวนโดยผู้ทรงคุณวุฒิเกี่ยวกับโอปิออยด์และการนอน\n\nความสัมพันธ์ระหว่างโอปิออยด์กับการนอน\nงานวิจัยนี้อธิบายความสัมพันธ์แบบสองทางระหว่างการใช้โอปิออยด์กับปัญหาการนอน โดยพบว่าโอปิออยด์รบกวนโครงสร้างการนอนปกติได้หลายวิธี:\n• ลดการนอนหลับลึกแบบคลื่นช้า\n• รบกวนการนอนช่วง REM\n• ทำให้เกิดความผิดปกติของการหายใจขณะหลับ เช่น central sleep apnea\n• รบกวนการควบคุมจังหวะชีวภาพประจำวัน\n\nวงจรที่ส่งผลกันไปมา\nโอปิออยด์ทำให้การนอนแย่ลง ขณะที่การนอนไม่ดีเพิ่มความไวต่อความเจ็บปวดและความอยากใช้ยา ซึ่งอาจผลักให้กลับไปใช้โอปิออยด์มากขึ้น การออกจากภาวะพึ่งพาโอปิออยด์จึงรวมถึงการตัดวงจรปัญหาการนอนนี้ด้วย\n\nการนอนหลังสองสัปดาห์\nหลังงดโอปิออยด์ 14 วัน การนอนเริ่มกลับสู่ปกติ:\n• central sleep apnea (ถ้ามี) อาจดีขึ้นภายในไม่กี่วัน\n• การนอนหลับลึกแบบคลื่นช้าเริ่มฟื้น\n• สัดส่วนการนอน REM เริ่มกลับสู่ปกติ\n• การเริ่มหลับมีความสม่ำเสมอมากขึ้น\n\nการนอนยังเป็นความท้าทายสำคัญสำหรับหลายคนหลังสองสัปดาห์ แต่แนวโน้มโดยรวมดีขึ้น การนอนที่ดีขึ้นช่วยเรื่องอารมณ์ ลดความอยากใช้ยา และสนับสนุนความคิดที่ชัดเจนในช่วงฟื้นตัว';

  @override
  String get opioidReferenceDay30 =>
      'หนึ่งเดือนโดยไม่ใช้โอปิออยด์: ความคิดและความจำเริ่มฟื้น\n\nที่มา: Mayo Clinic\n\nทำความเข้าใจความผิดปกติจากการใช้โอปิออยด์\nMayo Clinic อธิบายว่าโอปิออยด์จับกับตัวรับทั่วสมองและร่างกาย ทำให้ลดปวด รู้สึกเคลิ้ม และง่วง เมื่อใช้ซ้ำ ๆ สมองตอบสนองน้อยลงและสร้างสารที่คล้ายโอปิออยด์ตามธรรมชาติน้อยลง จึงเกิดการพึ่งพาทางกาย\n\nความคิดและความจำหลังหนึ่งเดือน\nเมื่อครบ 30 วัน ความคิดและความจำอาจฟื้นอย่างเห็นได้ชัด อาการสมองล้ารุนแรงเริ่มจางลง และสมองส่วนหน้าที่เกี่ยวข้องกับการวางแผนและการควบคุมตนเองเริ่มฟื้น:\n• การตัดสินใจดีขึ้น\n• working memory ฟื้นตัว\n• ความเร็วในการประมวลผลดีขึ้น\n• สมาธิสม่ำเสมอขึ้น\n\nระบบเอ็นดอร์ฟิน\nหลังหนึ่งเดือน ระบบเอ็นดอร์ฟินตามธรรมชาติของสมองกำลังฟื้นตัว สมองสร้างสารที่คล้ายโอปิออยด์ของตัวเองมากขึ้นและตอบสนองได้ใกล้เคียงปกติมากขึ้น ความรู้สึกด้านชาและความทนต่อความเจ็บปวดที่ลดลงอาจค่อย ๆ ดีขึ้น\n\nการป้องกันการกลับไปใช้\nMayo Clinic เน้นว่าการงดใช้หนึ่งเดือนไม่ได้หมายความว่าความเสี่ยงกลับไปใช้หมดไป ความทนต่อยาลดลงมากแล้ว จึงมีความเสี่ยงใช้ยาเกินขนาดอย่างรุนแรงหากกลับไปใช้ขนาดเดิม';

  @override
  String get opioidReferenceDay60 =>
      'สองเดือนโดยไม่ใช้โอปิออยด์: วงจรความเครียดในสมองเริ่มสงบลง\n\nที่มา: \"Neuroplasticity of the extended amygdala in opioid withdrawal and prolonged opioid abstinence,\" Frontiers in Pharmacology (2023)\n\nความรู้สึกด้านลบมาจากไหน\nบทความทบทวนนี้อธิบายว่าการใช้โอปิออยด์ระยะยาวเปลี่ยนวงจรความเครียดและความกลัวในสมองอย่างไร ระหว่างการถอนยา วงจรเหล่านี้ทำงานมากเกินไป ขณะที่สัญญาณโดปามีนในวงจรรางวัลลดลง การเปลี่ยนแปลงร่วมกันนี้ช่วยอธิบายความวิตก อารมณ์ต่ำ และความอยากใช้ยาในช่วงต้นของการฟื้นตัว\n\nทำไมสองเดือนจึงอาจรู้สึกดีขึ้น\nสิ่งสำคัญคือ งานทบทวนระบุว่าการเปลี่ยนแปลงบางส่วนย้อนกลับได้ ในสัตว์ทดลอง การลดลงของความหนาแน่นของ dendritic spines ใน shell ของ nucleus accumbens ถูกอธิบายว่าเป็น \"การลดลงที่คงอยู่นานแต่ย้อนกลับได้\" และค่อย ๆ กลับไปใกล้ค่าก่อนใช้ยาในช่วงไม่กี่สัปดาห์ เมื่อวงจรความเครียดและรางวัลปรับสมดุลใหม่ พื้นฐานทางชีวภาพของความปั่นป่วนทางอารมณ์ช่วงต้นของการฟื้นตัวก็อาจลดลง\n\nสัญญาณของการฟื้นตัว\nการเปลี่ยนแปลงของ dendritic spine และวงจรความเครียดที่ย้อนกลับได้แสดงให้เห็นกระบวนการฟื้นตัวทางชีวภาพจริง วงจรที่ขับภาวะอารมณ์ด้านลบจากการพึ่งพาค่อย ๆ เคลื่อนกลับไปสู่สภาพก่อนใช้สารในช่วงงดใช้';

  @override
  String get opioidReferenceDay90 =>
      'สามเดือนโดยไม่ใช้โอปิออยด์: ระบบรางวัลเริ่มฟื้นตัว\n\nที่มา: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies,\" Drug and Alcohol Dependence (2022), PubMed Central\n\nโดปามีนและโอปิออยด์\nโอปิออยด์กระตุ้นการหลั่งโดปามีนในระบบรางวัลของสมอง การใช้ระยะยาวอาจทำให้ระบบนี้ลดการตอบสนอง ในงานสแกนสมองหนึ่งชิ้น โปรตีนที่ขนส่งโดปามีนต่ำกว่าระดับของกลุ่มสุขภาพดีประมาณ 30% ในช่วงเริ่มต้น ซึ่งช่วยอธิบายการสูญเสียความรู้สึกเพลิดเพลินที่พบในความผิดปกติจากการใช้โอปิออยด์และช่วงต้นของการฟื้นตัว\n\nการฟื้นตัวเป็นแบบค่อยเป็นค่อยไป\nบทความทบทวนรวบรวมการศึกษาระยะยาวที่สแกนคนเดิมซ้ำระหว่างช่วงงดใช้ ความผิดปกติของ dopamine transporter ดีขึ้นประมาณ 20% ในช่วง 6–12 เดือนของการงดใช้ และความผิดปกติบางอย่างของ gray matter และ white matter บริเวณสมองส่วนหน้าที่พบช่วงถอนระยะแรกไม่สามารถตรวจพบได้หลังประมาณหนึ่งเดือน ที่สามเดือนคุณยังอยู่ในช่วงต้นของเส้นทางฟื้นตัว ระบบรางวัลและสมองส่วนหน้าดีขึ้นอย่างวัดได้แต่ยังไม่ฟื้นเต็มที่\n\nสิ่งที่อาจสังเกตได้\nเมื่อวงจรเหล่านี้ฟื้น หลายคนราววันที่ 90 สังเกตว่า:\n• สนุกกับกิจกรรม อาหาร และความสัมพันธ์ได้มากขึ้น\n• ความอยากใช้ยาลดลงเมื่อเทียบกับช่วงต้น\n• คิดชัดเจนและตัดสินใจได้ดีขึ้น\n\nสัญญาณของการฟื้นตัว\nการถ่ายภาพสมองแบบติดตามในมนุษย์แสดงว่า dopamine transporter availability เพิ่มขึ้นในช่วง 6–12 เดือนของการงดใช้ ขณะที่ความผิดปกติของ gray matter และ white matter บริเวณสมองส่วนหน้าเริ่มกลับสู่ปกติก่อนหน้านั้น ที่ 90 วันมีสัญญาณการฟื้นตัวของสมองที่วัดได้แล้ว';

  @override
  String get opioidReferenceDay180 =>
      'หกเดือนโดยไม่ใช้โอปิออยด์: ระบบภูมิคุ้มกันเริ่มฟื้น\n\nที่มา: \"Effects of opioid tolerance and withdrawal on the immune system,\" Journal of Neuroimmune Pharmacology (2006), PubMed\n\nโอปิออยด์กับระบบภูมิคุ้มกัน\nบทความทบทวนนี้แสดงว่าการใช้โอปิออยด์ระยะยาวอาจทำให้ระบบภูมิคุ้มกันอ่อนแอลงหลายทาง:\n• ผลโดยตรงของโอปิออยด์ต่อเซลล์ภูมิคุ้มกัน (T cells, NK cells, macrophages)\n• การรบกวนสารส่งสัญญาณของระบบภูมิคุ้มกัน\n• การรบกวนแกน hypothalamic-pituitary-adrenal (HPA)\n• ความไวต่อการติดเชื้อเพิ่มขึ้น\n\nสัญญาณของการฟื้นตัว\nโอปิออยด์ระยะยาวกดการทำงานของระบบภูมิคุ้มกันหลายส่วน หลังหกเดือนโดยไม่ใช้โอปิออยด์ การกดอย่างต่อเนื่องนั้นหายไปมาครึ่งปีแล้ว และระบบภูมิคุ้มกันมีเวลาปรับกลับไปใกล้การทำงานปกติ\n\nหกเดือนหมายถึงอะไร\nหกเดือนโดยไม่ใช้โอปิออยด์ทำให้เซลล์ภูมิคุ้มกัน การส่งสัญญาณภูมิคุ้มกัน และระบบความเครียดของร่างกายมีเวลาฟื้นตัวอย่างต่อเนื่อง\n\nทำไมยังสำคัญ\nเรื่องนี้สำคัญเป็นพิเศษสำหรับผู้ที่เคยฉีดโอปิออยด์ เพราะมีความเสี่ยงการติดเชื้อเพิ่มเติม เช่น HIV และไวรัสตับอักเสบซี การหยุดโอปิออยด์ การมีโภชนาการที่ดีขึ้น และการงดใช้อย่างต่อเนื่องช่วยสร้างสภาพแวดล้อมที่ดีต่อการฟื้นตัวของภูมิคุ้มกัน';

  @override
  String get opioidReferenceDay365 =>
      'หนึ่งปีโดยไม่ใช้โอปิออยด์: โครงสร้างและเคมีของสมองกำลังฟื้น\n\nที่มา: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies,\" Drug and Alcohol Dependence (2022), PubMed Central\n\nการถ่ายภาพสมองในมนุษย์แสดงอะไร\nบทความทบทวนนี้รวบรวมการศึกษาที่สแกนคนเดิมซึ่งมีความผิดปกติจากการใช้โอปิออยด์มากกว่าหนึ่งครั้งระหว่างช่วงงดใช้ ผลโดยรวมชี้ไปทางการฟื้นตัว:\n• โปรตีนที่ขนส่งโดปามีนในบริเวณระบบรางวัลและการเคลื่อนไหว ซึ่งต่ำกว่าปกติประมาณ 30% ตอนเริ่มต้น เพิ่มขึ้นประมาณ 20% ในช่วง 6–12 เดือนโดยไม่ใช้โอปิออยด์\n• ความผิดปกติของ gray matter ในสมองส่วนหน้าที่พบช่วงถอนระยะแรกไม่สามารถตรวจพบได้หลังงดใช้ประมาณหนึ่งเดือน\n• white matter บริเวณสมองส่วนหน้าและ cingulate รวมถึงกิจกรรมของสมองส่วนหน้าขณะพัก เริ่มกลับสู่ปกติภายในเดือนแรก\n\nหนึ่งปีอยู่ตรงไหน\nเมื่อครบ 12 เดือน คุณอยู่ที่หรือเลยช่วงเวลายาวที่สุดที่การศึกษาเหล่านี้วัด ระบบโดปามีนมีเวลาฟื้นมากที่สุด และวงจรสมองส่วนหน้าที่ช่วยเรื่องการควบคุมตนเองและการตัดสินใจฟื้นมาหลายเดือน ซึ่งสอดคล้องกับความคิดที่ชัดขึ้น ความอยากใช้ยาที่อ่อนลง และอารมณ์ที่มั่นคงขึ้นซึ่งหลายคนบรรยายเมื่อครบหนึ่งปี\n\nสัญญาณของการฟื้นตัว\nที่หนึ่งปี หลักฐานจากการถ่ายภาพสมองในมนุษย์ชี้ไปทางการฟื้นตัวอย่างชัดเจน dopamine transporter availability เพิ่มขึ้นในช่วง 6–12 เดือน ขณะที่ความผิดปกติของโครงสร้างและการทำงานบริเวณสมองส่วนหน้ามีเวลาหลายเดือนในการกลับสู่ภาวะปกติ';

  @override
  String get opioidReferenceDay730 =>
      'สองปีโดยไม่ใช้โอปิออยด์: รากฐานที่มั่นคง\n\nที่มา: \"Treatment of Opioid Use Disorder,\" Centers for Disease Control and Prevention (CDC)\n\nภาวะเรื้อรังที่จัดการได้\nCDC อธิบายความผิดปกติจากการใช้โอปิออยด์ว่าเป็น \"โรคเรื้อรังที่อาจเกิดกับใครก็ได้\" และเป็น \"ภาวะทางการแพทย์ ไม่ใช่ความล้มเหลวทางศีลธรรม\" การฟื้นตัวอย่างต่อเนื่องสองปีหมายถึงคุณได้ผ่านหนึ่งในช่วงที่เปราะบางที่สุดของภาวะนี้มาแล้ว\n\nสิ่งที่ CDC ระบุว่าได้ผล\nคำแนะนำของ CDC เน้นการรักษาที่ช่วยคงความมั่นคงในระยะยาว:\n• ยาสำหรับความผิดปกติจากการใช้โอปิออยด์ — บูพรีนอร์ฟีน เมทาโดน และนัลเทรกโซน — ซึ่ง CDC ระบุว่ามีประสิทธิผลสูง\n• ใช้ยาร่วมกับการบำบัดพฤติกรรมและการให้คำปรึกษา\n• ระยะเวลาการรักษาที่ปรับให้เหมาะกับแต่ละคน\nCDC ระบุว่ายาเหล่านี้ช่วย \"ทำให้เคมีในสมองกลับสู่ภาวะปกติ\" และลดความอยากใช้ยา\n\nอยู่อย่างปลอดภัย\nCDC แนะนำให้ผู้ที่อยู่ในระยะฟื้นตัวพูดคุยกับแพทย์เรื่องความเสี่ยงกลับไปใช้และการใช้ยาเกินขนาด รวมถึงมีนาล็อกโซนไว้ ความทนต่อยาลดลงระหว่างช่วงงดใช้ ดังนั้นการกลับไปใช้โอปิออยด์หลังเว้นมานานจึงอันตรายเป็นพิเศษ การเข้าใจความเสี่ยงนี้เป็นส่วนหนึ่งของการปกป้องสิ่งที่คุณสร้างมา\n\nสองปี\nCDC ชี้ชัดว่าการฟื้นตัวมักเป็นกระบวนการระยะยาว ไม่ใช่เส้นชัย สองปีไม่ใช่จุดจบของการเดินทาง แต่เป็นรากฐานที่มั่นคงและเป็นสัญญาณชัดว่าทิศทางที่คุณกำลังใช้ได้ผล';

  @override
  String get opioidReferenceDay1095 =>
      'สามปี - การฟื้นตัวที่ยั่งยืน\n\nแหล่งข้อมูล: ศูนย์ควบคุมและป้องกันโรคสหรัฐฯ (CDC), “การรักษาภาวะผิดปกติจากการใช้โอปิออยด์”\n\nแนวทางอธิบายภาวะนี้ว่าเป็นโรคเรื้อรังที่รักษาได้ การรักษาอาจมีหลายรูปแบบและหลายระยะเวลา และการใช้ยาเป็นทางเลือกที่มีหลักฐานรองรับ\n\nแนวทางไม่ได้กำหนดจุดสิ้นสุดทางชีวภาพที่สามปี หมุดหมายนี้ฉลอง 1,095 วันของการฟื้นตัวอย่างต่อเนื่อง';

  @override
  String get opioidReferenceDay1460 =>
      'สี่ปี - รากฐานที่มั่นคง\n\nแหล่งข้อมูล: ศูนย์ควบคุมและป้องกันโรคสหรัฐฯ (CDC), “การรักษาภาวะผิดปกติจากการใช้โอปิออยด์”\n\nแนวทางระบุว่าการฟื้นตัวเป็นไปได้และการรักษาควรปรับตามแต่ละคน โดยไม่มีกรอบเวลาเดียวสำหรับทุกคน\n\nสี่ปีไม่ใช่เส้นชัยทางชีวภาพ แต่เป็นหลักฐานของการเปลี่ยนแปลงที่รักษาไว้ได้อย่างมั่นคง';

  @override
  String get opioidReferenceDay1825 =>
      'ห้าปี - ครึ่งทศวรรษ\n\nแหล่งข้อมูล: ศูนย์ควบคุมและป้องกันโรคสหรัฐฯ (CDC), “การรักษาภาวะผิดปกติจากการใช้โอปิออยด์”\n\nแนวทางมองการฟื้นตัวเป็นกระบวนการเฉพาะบุคคล และไม่ได้กำหนดวันครบรอบที่การรักษาต้องสิ้นสุดหรือการฟื้นตัวต้องสมบูรณ์ทางชีวภาพ\n\nห้าปีคือครึ่งทศวรรษของการเปลี่ยนแปลงอย่างต่อเนื่อง ความสำเร็จนี้มีคุณค่าในตัวเอง';

  @override
  String get pornographyReferenceDay1 =>
      'วันแรก: เริ่มกลับมาควบคุมได้\n\nแหล่งที่มา: Kraus et al., Compulsive sexual behaviour disorder in the ICD-11, World Psychiatry (2018).\n\nประเด็นสำคัญทางคลินิกไม่ใช่การใช้สื่อลามกเพียงอย่างเดียว ภาวะพฤติกรรมทางเพศแบบบังคับถูกนิยามจากความยากอย่างต่อเนื่องในการควบคุมพฤติกรรมทางเพศซ้ำ ๆ เมื่อรูปแบบนั้นก่อให้เกิดความทุกข์หรือกระทบการใช้ชีวิตอย่างมีนัยสำคัญ การใช้สื่อลามกที่เป็นปัญหาอาจเป็นหนึ่งรูปแบบของปัญหาที่กว้างกว่านี้\n\nดังนั้นวันแรกจึงเป็นสิ่งที่จับต้องได้ ไม่ใช่เรื่องลึกลับ คุณได้หยุดพฤติกรรมที่ตัดสินใจแล้วว่าควบคุมไม่ได้ หนึ่งวันไม่ได้พิสูจน์ว่าสมองหรือเส้นประสาท “รีเซ็ต” แต่ช่วยให้คุณเริ่มเห็นจริง ๆ ว่าแรงกระตุ้นเกิดเมื่อไร สถานการณ์ใดกระตุ้น และคุณทำอะไรแทนได้บ้าง\n\nหากการใช้ของคุณไม่ได้ก่อความทุกข์ กระทบการใช้ชีวิต หรือควบคุมได้ยาก กรอบทางคลินิกของ CSBD อาจไม่ตรงกับคุณ หมุดหมายเหล่านี้มีไว้สำหรับผู้ที่ตั้งใจเปลี่ยนการใช้ที่เป็นปัญหาหรือมีลักษณะบังคับ.';

  @override
  String get pornographyReferenceDay3 =>
      'วันที่สาม: รู้จักลักษณะของแรงกระตุ้น\n\nแหล่งที่มา: Lewczuk et al., Withdrawal and tolerance as related to compulsive sexual behavior disorder and problematic pornography use, Journal of Behavioral Addictions (2022).\n\nในการศึกษาตัวอย่างผู้ใหญ่ชาวโปแลนด์ 1,541 คนที่ลงทะเบียนแผนไว้ล่วงหน้าและเป็นตัวแทนระดับประเทศ ประสบการณ์คล้ายอาการถอนที่รายงานด้วยตนเองอย่างรุนแรงสัมพันธ์กับความรุนแรงของ CSBD และการใช้สื่อลามกที่เป็นปัญหามากขึ้น ในผู้ที่มีการใช้เป็นปัญหา ประสบการณ์ที่พบบ่อย ได้แก่ ความคิดทางเพศที่หยุดยาก ความต้องการที่ควบคุมยาก ความตื่นตัวเพิ่มขึ้น ความหงุดหงิด อารมณ์เปลี่ยน และปัญหาการนอน\n\nความกระสับกระส่าย ความคิดทางเพศที่รบกวนใจ แรงกระตุ้นแรง และความหงุดหงิดมีรายงานในผู้ที่มีปัญหารุนแรงกว่า หากเกิดขึ้นราววันที่สาม ให้มองว่าเป็นรูปแบบคล้ายอาการถอนที่เกิดขึ้นจริงและจัดการตัวกระตุ้น\n\nจดว่าแรงกระตุ้นใดเกิดขึ้นจริง อะไรเกิดก่อนหน้า และการตอบสนองแบบใดช่วยได้ การเปลี่ยนแปลงจะจัดการง่ายขึ้นเมื่อเราเรียกชื่อตัวกระตุ้นได้ แทนที่จะมองเป็นเหตุการณ์ลึกลับในสมอง.';

  @override
  String get pornographyReferenceDay7 =>
      'หนึ่งสัปดาห์: สิ่งที่การศึกษาแบบสุ่มเรื่องการงดพบ\n\nแหล่งที่มา: Effects of a 7-Day Pornography Abstinence Period on Withdrawal-Related Symptoms in Regular Pornography Users, Archives of Sexual Behavior (2023).\n\nนักวิจัยสุ่มผู้ใช้สื่อลามกเป็นประจำ 176 คนให้พยายามงดเป็นเวลาเจ็ดวันหรือใช้ต่อไปตามปกติ ในตัวอย่างทั้งหมด การงดไม่ได้ทำให้ความอยาก อารมณ์ด้านลบ หรืออาการถอนเพิ่มขึ้นโดยรวมอย่างมีนัยสำคัญ\n\nการวิเคราะห์เชิงสำรวจพบความอยากเพิ่มขึ้นในผู้ที่มีทั้งคะแนนการใช้เป็นปัญหาสูงและดูสื่อลามกทุกวันก่อนการศึกษา ผลนี้ยังต้องทำซ้ำ แต่มีประโยชน์ เพราะสัปดาห์แรกที่ยากอาจเกิดขึ้นจริงในผู้ที่มีปัญหารุนแรงกว่า ขณะที่การทดลองนี้ไม่สนับสนุนว่าทุกคนจะมี “กลุ่มอาการถอนสื่อลามก”\n\nหากคุณผ่านหนึ่งสัปดาห์มาได้ ตอนนี้คุณมีข้อมูลเกี่ยวกับรูปแบบของตัวเองที่ดีกว่าไทม์ไลน์ทั่วไปบนอินเทอร์เน็ตแล้ว.';

  @override
  String get pornographyReferenceDay14 =>
      'สองสัปดาห์: ระบุตัวกระตุ้นที่สำคัญจริง\n\nแหล่งที่มา: Biopsychosocial Determinants of Problematic Pornography Use: A Systematic Review (2023).\n\nบททบทวนนี้สรุปงานวิจัย 66 ชิ้นและพบว่าการใช้สื่อลามกที่เป็นปัญหาเกี่ยวข้องกับปัจจัยหลายด้านร่วมกัน ไม่ใช่กลไกโดปามีนแบบง่ายเพียงอย่างเดียว ปัจจัยทางจิตใจและสังคมที่พบซ้ำ ๆ ได้แก่ ความอยาก ความเครียด การหลีกเลี่ยง ความเหงา การเห็นคุณค่าในตนเอง ความเชื่อเชิงลบ และรูปแบบการรับมือ\n\nสองสัปดาห์ทำให้คุณได้พบทั้งวันทำงาน วันหยุด ความเบื่อ ความเครียด ความเป็นส่วนตัว อุปกรณ์ และบริบทอื่นที่อาจกระตุ้นรูปแบบเดิม ใช้ข้อมูลนี้ หากความเครียดเป็นตัวกระตุ้น ให้เตรียมวิธีรับมือ หากความเหงาเป็นตัวกระตุ้น ให้เพิ่มการติดต่อกับคนอื่น หากการเข้าถึงง่ายเป็นตัวกระตุ้น ให้ปรับสภาพแวดล้อม\n\nหลักฐานสนับสนุนการจัดการปัจจัยที่ขับการใช้ที่เป็นปัญหา ไม่ได้บอกว่าทุกคนต้องเดินตามนาฬิกาชีวภาพแบบเดียวกัน.';

  @override
  String get pornographyReferenceDay30 =>
      'หนึ่งเดือน: การควบคุมสำคัญกว่าความถี่เพียงอย่างเดียว\n\nแหล่งที่มา: Bőthe et al., Are sexual functioning problems associated with frequent pornography use and/or problematic pornography use?, Addictive Behaviors (2021).\n\nในตัวอย่างชุมชนผู้ใหญ่ 14,581 คน การใช้สื่อลามกที่เป็นปัญหามีความสัมพันธ์เชิงบวกระดับปานกลางกับปัญหาการทำงานทางเพศทั้งในผู้ชายและผู้หญิง ขณะที่ความถี่ในการใช้เพียงอย่างเดียวมีความสัมพันธ์เชิงลบเล็กน้อยกับปัญหาเหล่านั้น\n\nความแตกต่างนี้สำคัญ หลักฐานไม่ได้สนับสนุนการบอกผู้ใช้สื่อลามกทุกคนว่าความถี่ในการดูเพียงอย่างเดียวทำลายการทำงานทางเพศ เป้าหมายที่เกี่ยวข้องทางคลินิกมากกว่าคือการสูญเสียการควบคุมและปัญหารอบรูปแบบนั้น\n\nเมื่อครบหนึ่งเดือน ให้เปรียบเทียบชีวิตตอนนี้กับตอนเริ่ม: ความหมกมุ่น เวลาที่เสียไป ความสามารถในการหยุด การทำงานทางเพศ ความขัดแย้งในความสัมพันธ์ และความทุกข์ การเปลี่ยนแปลงเหล่านี้สำคัญกว่าการรอ “รีเซ็ตสมอง” ในวันที่ 30.';

  @override
  String get pornographyReferenceDay90 =>
      'สามเดือน: การเปลี่ยนแปลงที่ยั่งยืนเป็นไปได้\n\nแหล่งที่มา: Crosby & Twohig, Acceptance and Commitment Therapy for Problematic Internet Pornography Use: A Randomized Trial, Behavior Therapy (2016).\n\nการทดลองแบบสุ่มขนาดเล็กนี้เปรียบเทียบโปรแกรม ACT 12 ครั้งกับกลุ่มรอในผู้ชายวัยผู้ใหญ่ 28 คน เมื่อจบการรักษา การดูสื่อลามกลดลงมากกว่าอย่างชัดเจนในกลุ่ม ACT และการลดลงจำนวนมากยังคงอยู่ในการติดตามผลสามเดือน\n\nงานวิจัยนี้ไม่ได้พิสูจน์ว่าการงด 90 วันเพียงอย่างเดียวให้ผลเหมือนกัน และกลุ่มตัวอย่างมีขนาดเล็กและไม่หลากหลายมาก แต่แสดงสิ่งสำคัญว่า การใช้สื่อลามกที่เป็นปัญหาสามารถเปลี่ยนได้ และทักษะอย่างเป็นระบบสามารถสร้างการเปลี่ยนแปลงที่ต่อเนื่องพ้นช่วงรักษาได้\n\nหากความก้าวหน้าของคุณยังพึ่งการฝืนตัวเองเป็นหลัก สามเดือนเป็นจุดที่ดีในการเสริมระบบรอบตัว เช่น แผนรับมือตัวกระตุ้น ยอมรับแรงกระตุ้นโดยไม่ทำตาม เพิ่มอุปสรรคต่อการเข้าถึง ความรับผิดชอบต่อผู้อื่น และการบำบัดเมื่อจำเป็น.';

  @override
  String get pornographyReferenceDay180 =>
      'หกเดือน: การควบคุมอาการระยะยาวคงอยู่ได้\n\nแหล่งที่มา: Hallberg et al., A Randomized Controlled Study of Group-Administered Cognitive Behavioral Therapy for Hypersexual Disorder in Men, Journal of Sexual Medicine (2019).\n\nในผู้ชาย 137 คนที่มีพฤติกรรมทางเพศควบคุมยาก CBT แบบกลุ่มเจ็ดสัปดาห์ลดอาการพฤติกรรมทางเพศมากเกินควบคุมและความบีบบังคับทางเพศได้มากกว่ากลุ่มรอ พร้อมกับสุขภาวะทางจิตที่ดีขึ้น ผลการรักษายังคงมั่นคงในการติดตามผลทั้งสามและหกเดือน\n\nการศึกษานี้ครอบคลุมภาวะพฤติกรรมทางเพศมากเกินควบคุมในภาพกว้าง ไม่ใช่การงดสื่อลามกเพียงอย่างเดียว จึงไม่ควรตีความว่าแต่ละคน “ฟื้นตัวทางชีวภาพ” เมื่อครบหกเดือน สิ่งที่หลักฐานรองรับและมีประโยชน์กว่าคือ การดีขึ้นของพฤติกรรมทางเพศแบบบังคับสามารถคงอยู่ได้นานระดับนี้\n\nดังนั้นหกเดือนคือหมุดหมายของการรักษาการเปลี่ยนแปลงไว้ คงกิจวัตรที่ช่วยให้ควบคุมได้ง่ายขึ้น แทนที่จะมองว่าวันนี้เป็นเหตุให้เลิกใช้สิ่งเหล่านั้น.';

  @override
  String get pornographyReferenceDay365 =>
      'หนึ่งปี: หลักฐานของการเปลี่ยนแปลงพฤติกรรมที่ยั่งยืน\n\nแหล่งที่มา: One-year follow-up effects of an acceptance-based treatment for hypersexuality (2026).\n\nในการติดตามผลหนึ่งปี ผู้เข้าร่วมการรักษาที่เน้นการยอมรับไม่ได้กลับไปสู่ระดับพฤติกรรมทางเพศมากเกินควบคุมก่อนการรักษา ผู้เขียนอธิบายว่าผลนี้เป็นหลักฐานเบื้องต้นของประโยชน์ที่ยั่งยืนและมีความหมายทางคลินิก โดยการรับรู้ว่าควบคุมความอยากได้เป็นหนึ่งในกระบวนการที่ติดตามตามเวลา\n\nนี่คือหลักฐานติดตามผลหลังการรักษา ไม่ใช่ข้อพิสูจน์ว่าสมองจะ “รีเซ็ต” ในหนึ่งปี ข้อสรุปที่มีความหมายกว่าคือ การควบคุมที่สำคัญทางคลินิกสามารถอยู่ได้หนึ่งปี ไม่ได้หายไปทันทีเมื่อการแทรกแซงช่วงแรกจบ\n\nหนึ่งปีของการเปลี่ยนแปลงที่คุณรักษาไว้ยังเป็นชุดข้อมูลส่วนตัวขนาดใหญ่ เปรียบเทียบการควบคุม ความทุกข์ การใช้ชีวิต ความสัมพันธ์ และการใช้เวลาตอนนี้กับตอนเริ่ม สิ่งเหล่านี้คือผลลัพธ์ที่สำคัญทางคลินิก.';

  @override
  String get pornographyReferenceDay730 =>
      'สองปี: ควบคุมได้มั่นคง\n\nแหล่งที่มา: Ince และคณะ (2026) บททบทวนเกี่ยวกับภาวะพฤติกรรมทางเพศแบบบังคับและการใช้สื่อลามกที่เป็นปัญหา\n\nงานวิจัยมองปัญหาเหล่านี้ว่าซับซ้อนและแตกต่างกันในแต่ละคน โดยพิจารณาการควบคุม ความทุกข์ การใช้ชีวิต และบริบท ไม่ได้กำหนดเกณฑ์การฟื้นตัวทางชีวภาพแบบเดียวกันที่สองปี\n\nดังนั้นสองปีจึงสะท้อนการคงไว้ซึ่งการเปลี่ยนแปลงที่มั่นคง การควบคุมที่ต่อเนื่องและการใช้ชีวิตที่ดีขึ้นเป็นผลลัพธ์ที่มีความหมายในตัวเอง';

  @override
  String get pornographyReferenceDay1095 =>
      'สามปี: การเปลี่ยนแปลงมั่นคง\n\nแหล่งที่มา: Ince และคณะ (2026) บททบทวนเกี่ยวกับภาวะพฤติกรรมทางเพศแบบบังคับและการใช้สื่อลามกที่เป็นปัญหา\n\nหลักฐานปัจจุบันไม่ได้กำหนดจุดสิ้นสุดทางชีวภาพที่สามปี การประเมินทางคลินิกยังคงมองการควบคุม ความทุกข์ การบกพร่อง บริบท และการใช้ชีวิต\n\nสามปีสะท้อนความทนทานของการเปลี่ยนแปลง การเปลี่ยนแปลงที่อยู่ได้แม้กิจวัตรและสถานการณ์เปลี่ยนไปก็ควรได้รับการรักษาไว้';

  @override
  String get pornographyReferenceDay1460 =>
      'สี่ปี: การเปลี่ยนแปลงยั่งยืน\n\nแหล่งที่มา: Ince และคณะ (2026) บททบทวนเกี่ยวกับภาวะพฤติกรรมทางเพศแบบบังคับและการใช้สื่อลามกที่เป็นปัญหา\n\nหลักฐานเน้นความแตกต่างระหว่างบุคคลและบริบท และไม่ได้สนับสนุนจุดสากลที่การฟื้นตัวทางชีวภาพจะเสร็จสมบูรณ์เมื่อครบสี่ปี\n\nถึงอย่างนั้น สี่ปีสามารถแสดงถึงการรักษาการเปลี่ยนแปลงที่ลึกและมั่นคง หากรูปแบบเดิมไม่ครอบงำการตัดสินใจหรือรบกวนความสัมพันธ์และการใช้ชีวิต นั่นคือผลลัพธ์ระยะยาวที่มีความหมาย';

  @override
  String get pornographyReferenceDay1825 =>
      'ห้าปี: ผลลัพธ์คือการควบคุมระยะยาว\n\nแหล่งที่มา: Compulsive sexual behavior disorder and problematic pornography use: a comprehensive interdisciplinary expert-informed review (2026).\n\nบททบทวนสมัยใหม่มอง CSBD และการใช้สื่อลามกที่เป็นปัญหาเป็นปัญหาซับซ้อนที่เกี่ยวข้องกับการควบคุม ความทุกข์ การใช้ชีวิต บริบท และความแตกต่างระหว่างบุคคล ไม่มีเกณฑ์ที่ผ่านการยืนยันว่าสมองและระบบประสาทจะ “รีเซ็ต” เมื่อครบห้าปี\n\nแต่ห้าปีไม่ใช่หมุดหมายที่ว่างเปล่า นี่คือ 1,825 วันที่คุณรักษาทิศทางพฤติกรรมที่เลือกไว้ เพราะปัญหาทางคลินิกคือการสูญเสียการควบคุมอย่างต่อเนื่องร่วมกับความทุกข์หรือการใช้ชีวิตที่บกพร่อง การรักษาการควบคุมและกลับมาใช้ชีวิตได้ดีตลอดหลายปีจึงเป็นผลลัพธ์ที่มีความหมายในตัวเอง\n\nในระยะนี้ คำถามที่มีประโยชน์ไม่ใช่ว่าสมองของคุณถึงเปอร์เซ็นต์ “การเดินสายใหม่” ที่สมมติขึ้นหรือยัง แต่คือรูปแบบเดิมยังควบคุมการตัดสินใจหรือรบกวนชีวิตที่คุณต้องการหรือไม่ หากไม่แล้ว นั่นคือความสำเร็จระยะยาวที่แท้จริง.';

  @override
  String get smokingReferenceDay1 =>
      'วันแรก: ประโยชน์เริ่มทันที\n\nที่มา: NHS Better Health\n\nประโยชน์เริ่มขึ้นภายในไม่กี่นาที ไม่ใช่หลายวัน ทันทีที่หยุดรับควัน ร่างกายก็เริ่มกลับสู่ภาวะปกติ\n\nสิ่งที่เกิดขึ้นวันนี้\n• 20 นาที: ชีพจรเริ่มกลับสู่ปกติ\n• 8 ชั่วโมง: คาร์บอนมอนอกไซด์ในเลือดลดลงครึ่งหนึ่ง และระดับออกซิเจนเริ่มฟื้นตัว\n• 48 ชั่วโมง: คาร์บอนมอนอกไซด์ลดลงถึงระดับของผู้ไม่สูบบุหรี่\n\nคาร์บอนมอนอกไซด์จับกับเม็ดเลือดแดงได้แน่นกว่าออกซิเจน จึงแย่งพื้นที่ของออกซิเจนในเลือด อวัยวะทุกส่วนเคยได้รับออกซิเจนน้อยกว่าที่ควร และภายในสองวันกระบวนการนี้ก็เริ่มย้อนกลับ\n\nอาการถอนนิโคตินเริ่มในวันแรก\n• ความอยากสูบ — แต่ละครั้งมักนานประมาณ 3–5 นาที\n• หงุดหงิดและมีสมาธิยาก\n• อยากอาหารมากขึ้น\n\nอาการเหล่านี้เป็นเพียงชั่วคราวและจัดการได้ NHS Better Health มีความช่วยเหลือฟรี รวมถึงแอปและคำแนะนำจากเภสัชกร';

  @override
  String get smokingReferenceDay3 =>
      'วันที่สาม: จุดสูงสุดของอาการถอนนิโคติน\n\nที่มา: McLaughlin, Dani และ De Biasi\n\nเมื่อครบ 72 ชั่วโมง นิโคตินจะออกจากร่างกาย สมองสร้างตัวรับนิโคตินเพิ่มขึ้นตลอดช่วงที่สูบบุหรี่ และเมื่อได้รับการกระตุ้นน้อยลงจึงเกิดอาการถอนนิโคติน\n\nอาการที่รุนแรงที่สุด\n• ความอยากสูบ — มักรุนแรงที่สุดในตอนนี้\n• หงุดหงิด คับข้องใจ และกระสับกระส่าย\n• มีสมาธิยาก\n• วิตกกังวล\n• ปวดศีรษะ\n• อยากอาหารมากขึ้น\n• ไอ (ทางเดินหายใจกำลังทำความสะอาดตัวเอง — เป็นสัญญาณที่ดี)\n\nวันนี้มักรู้สึกยากที่สุด จากจุดนี้อาการจะค่อย ๆ บรรเทาลงเมื่อสมองปรับตัวใหม่\n\nการบำบัดทดแทนนิโคติน (NRT), วาเรนิคลีน และบูโพรพิออนช่วยลดความรุนแรงของอาการถอนนิโคตินในช่วงนี้ได้อย่างมีนัยสำคัญ';

  @override
  String get smokingReferenceDay7 =>
      'หนึ่งสัปดาห์: การกลับมาของรสชาติและกลิ่น\n\nที่มา: NHS Better Health\n\nการเลิกสูบบุหรี่ได้หนึ่งสัปดาห์เป็นตัวทำนายความสำเร็จในระยะยาว ผู้คนที่ผ่านสัปดาห์แรกไปได้มีแนวโน้มที่จะเลิกบุหรี่ถาวรมากกว่า\n\nสิ่งที่ได้คืนมา\n• อาหารมีรสชาติอร่อยยิ่งขึ้น\n• กลิ่นหอมสดใสยิ่งขึ้น\n• การหายใจง่ายขึ้น — ทางเดินหายใจโล่งขึ้น\n• การไหลเวียนดีขึ้น\n• ผิวมีความชุ่มชื้นดีขึ้น\n\nการสูบบุหรี่ทำลายตัวรับรสและกลิ่นโดยตรงภายในไม่กี่วันหลังจากหยุด พวกเขาก็เริ่มฟื้นตัว\n\nการถอนนิโคตินแบบเฉียบพลันกำลังผ่อนคลายลงความอยากทางกายภาพจะสั้นลงและเกิดขึ้นน้อยลงความอยากที่เกิดจากการกระตุ้นอาจยังคงอยู่ แต่ความเร่งด่วนทางร่างกายที่เลวร้ายที่สุดอยู่เบื้องหลังคุณ';

  @override
  String get smokingReferenceDay14 =>
      'สองสัปดาห์: การไหลเวียนดีขึ้น\n\nที่มา: NHS Better Health\n\nภายใน 2-12 สัปดาห์หลังจากหยุด การไหลเวียนโลหิตจะดีขึ้นนิโคตินทำให้หลอดเลือดแคบลงทุกครั้งที่สูบบุหรี่หากไม่มีมัน หลอดเลือดจะผ่อนคลายและเลือดจะไหลเวียนได้อย่างอิสระมากขึ้น\n\nนี่หมายถึงอะไร\n• การไหลเวียนของเลือดไปยังมือ เท้า และเนื้อเยื่อส่วนปลายดีขึ้น\n• หลายๆ คนสังเกตว่ามือและเท้าอุ่นขึ้น\n• การเดินและขึ้นบันไดเริ่มรู้สึกง่ายขึ้น\n\nเมื่อคาร์บอนมอนอกไซด์ถูกกำจัดออกจากเลือดไปแล้วในวันแรกและการไหลเวียนดีขึ้น ออกซิเจนจะเข้าถึงกล้ามเนื้อได้อย่างมีประสิทธิภาพมากขึ้น\n\nเยื่อบุทางเดินหายใจกำลังฟื้นตัวและดันน้ำมูกที่สะสมอยู่ออกมาหากคุณไอมากกว่าปกติ นั่นเป็นสัญญาณของการฟื้นตัว ไม่ใช่อาการพ่ายแพ้';

  @override
  String get smokingReferenceDay30 =>
      'หนึ่งเดือน: การทำงานของปอดดีขึ้น\n\nที่มา: NHS Better Health\n\nการหายใจง่ายขึ้นและการทำงานของปอดดีขึ้น โดยอาจเพิ่มขึ้นได้ถึง 10% ในช่วง 3 ถึง 9 เดือน เมื่อครบหนึ่งเดือน คุณอยู่ในช่วงการฟื้นตัวนี้แล้ว\n\nสิ่งที่เกิดขึ้นในปอด\n• ซีเลียงอกกลับมาและกำจัดเมือกได้มีประสิทธิภาพขึ้น\n• การอักเสบของทางเดินหายใจเริ่มลดลง\n• อาการไอเรื้อรังของผู้สูบบุหรี่เริ่มจางลง\n• ความทนทานต่อการออกกำลังกายดีขึ้น\n\nอาการไอ หายใจมีเสียงหวีด และปัญหาการหายใจจะดีขึ้นเมื่อการทำงานของปอดเพิ่มขึ้น หนึ่งเดือนเป็นจุดสำคัญบนเส้นทางการฟื้นตัวนี้';

  @override
  String get smokingReferenceDay90 =>
      'สามเดือน: ความเสี่ยงจากภาวะหัวใจวายลดลง\n\nที่มา: PMC — ผลกระทบต่อหัวใจและหลอดเลือดจากการสูบบุหรี่และการเลิกบุหรี่ (2024)\n\nการสูบบุหรี่ทำลายหัวใจและหลอดเลือดแดงได้หลายวิธี: เร่งการสะสมของคราบจุลินทรีย์ในหลอดเลือด ส่งเสริมการแข็งตัวของเลือด เพิ่มความดันโลหิต และทำลายเยื่อบุหลอดเลือดแดงผลการแข็งตัวของเลือดและส่งเสริมการแข็งตัวของเลือดจะย้อนกลับภายในไม่กี่วันหลังจากหยุด และการทบทวนนี้รายงานการลดลงของอาการหัวใจวายและโรคหลอดเลือดสมองลดลงอย่างเห็นได้ชัดภายในปีแรกของการเลิกบุหรี่\n\nตอนนี้มีอะไรปรับปรุงบ้าง\n• ปัจจัยการแข็งตัวของเลือดกำลังเข้าสู่ภาวะปกติ\n• ความดันโลหิตและอัตราการเต้นของหัวใจคงที่\n• การลดลงอย่างรวดเร็วที่สุดในช่วงแรกของความเสี่ยงต่อการเกิดโรคหลอดเลือดหัวใจเฉียบพลันกำลังดำเนินไปด้วยดี\n\nประโยชน์ที่ออกฤทธิ์ช้ากว่า — ย้อนกลับไปหลายปีของการสะสมของคราบพลัคในหลอดเลือด — ใช้เวลานานกว่าและครอบคลุมในเหตุการณ์สำคัญในภายหลังทุกเดือนที่ปลอดบุหรี่จะช่วยฟื้นฟู';

  @override
  String get smokingReferenceDay180 =>
      'หกเดือน: เซลล์ภูมิคุ้มกันในปอดฟื้นตัว\n\nที่มา: Smoke-free period and recovery of alveolar immune-cell function (PubMed)\n\nการสูบบุหรี่สามารถกดการทำงานของแมคโครฟาจถุงลม ซึ่งเป็นเซลล์ภูมิคุ้มกันลึกในปอดที่กลืนและฆ่าแบคทีเรีย\n\nสิ่งที่การศึกษาวัด\nนักวิจัยเปรียบเทียบผู้ไม่เคยสูบบุหรี่ 15 คน ผู้สูบบุหรี่ปัจจุบัน 15 คน และอดีตผู้สูบบุหรี่ 41 คนที่เลิกมาแล้ว 2 เดือน, 3–5 เดือน หรือ 6–12 เดือน ระหว่างการดมยาสลบ\n\nสัญญาณการฟื้นตัวที่วัดได้\nระหว่างการดมยาสลบ การลดลงของการกินเชื้อและความสามารถฆ่าแบคทีเรียของแมคโครฟาจถุงลมมากกว่า 1.5–3 เท่าในผู้สูบบุหรี่ปัจจุบันและผู้ที่เลิกมาได้สองเดือน เมื่อเทียบกับผู้ไม่เคยสูบ หลังเลิก 3–12 เดือน การตอบสนองต้านจุลชีพใกล้เคียงกับรูปแบบของผู้ไม่เคยสูบมากกว่าตอนสองเดือน\n\nการส่งสัญญาณการอักเสบฟื้นตัวช้ากว่า โดยยังพบความแตกต่างของการตอบสนองไซโตไคน์จนถึงหกเดือน หกเดือนคือหมุดหมายจริงของการฟื้นตัวด้านภูมิคุ้มกันปอด และการฟื้นตัวยังดำเนินต่อไป';

  @override
  String get smokingReferenceDay365 =>
      'หนึ่งปี: ความเสี่ยงหัวใจวายลดลงอย่างมาก\n\nที่มา: PMC — Smoking Cessation and Stroke Outcome; CDC, Benefits of Quitting Smoking\n\nการสูบบุหรี่เพิ่มความเสี่ยงโรคหลอดเลือดสมองประมาณสองเท่า เพราะเร่งการสะสมของคราบในหลอดเลือด เพิ่มการแข็งตัวของเลือด ทำให้ความดันโลหิตสูงขึ้น และทำลายหลอดเลือดสมอง เส้นเวลาของ CDC ระบุว่าความเสี่ยงหัวใจวายลดลงอย่างมากในช่วง 1–2 ปีหลังเลิกสูบ — เมื่อครบหนึ่งปี คุณอยู่ที่ช่วงต้นของกรอบเวลานี้\n\nลำดับการฟื้นตัว\nการที่ความเสี่ยงโรคหลอดเลือดสมองจะกลับสู่ระดับปกติเต็มที่ต้องใช้เวลานานกว่า งานวิจัยโรคหลอดเลือดสมองที่อ้างถึงติดตามผู้ที่เลิกสูบเป็นระยะมัธยฐานเกือบห้าปี และพบอัตราโรคหลอดเลือดสมองต่ำกว่าผู้ที่ยังสูบอย่างมีนัยสำคัญ ข้อมูล CDC ระบุว่าความเสี่ยงส่วนเกินของโรคหลอดเลือดหัวใจลดลงครึ่งหนึ่งในช่วง 3–6 ปี และความเสี่ยงโรคหลอดเลือดสมองลดลงต่อเนื่องในช่วง 5–10 ปี\n\nหนึ่งปียังคงเป็นหลักชัยทางการแพทย์ที่แท้จริง — ช่วงที่ความเสี่ยงเฉียบพลันลดลงเร็วที่สุดอยู่เบื้องหลังแล้ว ขณะที่ประโยชน์ระยะยาวต่อหัวใจ หลอดเลือด และความเสี่ยงมะเร็งยังคงเพิ่มขึ้นต่อไปอีกหลายปี';

  @override
  String get smokingReferenceDay730 =>
      'สองปี: ประโยชน์ต่อหัวใจและหลอดเลือดยังคงเพิ่มขึ้น\n\nแหล่งที่มา: CDC ประโยชน์ของการเลิกสูบบุหรี่\n\nCDC ระบุว่าความเสี่ยงหัวใจวายลดลงอย่างมากภายใน 1–2 ปีหลังเลิกสูบ สองปีคือปลายช่วงที่หลักฐานระบุ ไม่ใช่การเปลี่ยนแปลงฉับพลันในวันใดวันหนึ่ง\n\nแนวโน้มระยะยาวยังดำเนินต่อไป ความเสี่ยงส่วนเกินของโรคหลอดเลือดหัวใจลดลงต่อเนื่องและลดลงครึ่งหนึ่งในช่วง 3–6 ปี สองปีที่ไม่สูบบุหรี่จึงเป็นความสำเร็จที่ควรภูมิใจโดยไม่ต้องกำหนดวันเปลี่ยนแปลงทางชีวภาพแบบตายตัว';

  @override
  String get smokingReferenceDay1095 =>
      'สามปี: เริ่มช่วงที่หัวใจได้ประโยชน์\n\nแหล่งที่มา: CDC ประโยชน์ของการเลิกสูบบุหรี่\n\nCDC ระบุว่าความเสี่ยงส่วนเกินของโรคหลอดเลือดหัวใจลดลงครึ่งหนึ่งในช่วง 3–6 ปีหลังเลิกสูบ สามปีคือจุดเริ่มของช่วงนี้\n\nหลักฐานอธิบายเป็นช่วงเวลา ไม่ใช่เส้นแบ่งแบบทันที เมื่อครบสามปี การลดความเสี่ยงต่อหัวใจและหลอดเลือดในระยะยาวได้ดำเนินมาอย่างชัดเจนและยังคงเพิ่มพูนต่อไป';

  @override
  String get smokingReferenceDay1460 =>
      'สี่ปี: ประโยชน์ต่อหัวใจยังเพิ่มขึ้น\n\nแหล่งที่มา: CDC ประโยชน์ของการเลิกสูบบุหรี่\n\nสี่ปีที่ไม่สูบบุหรี่อยู่ในช่วง 3–6 ปีตามข้อมูล CDC ซึ่งความเสี่ยงส่วนเกินของโรคหลอดเลือดหัวใจลดลงครึ่งหนึ่งเมื่อเทียบกับการสูบบุหรี่ต่อไป\n\nการใช้ช่วงเวลานี้ช่วยหลีกเลี่ยงการอ้างว่าร่างกายเปลี่ยนทันทีเมื่อครบสี่ปี ขณะเดียวกันก็ยืนยันช่วงการฟื้นตัวของหัวใจและหลอดเลือดที่มีหลักฐานทางการแพทย์รองรับ';

  @override
  String get smokingReferenceDay1825 =>
      'ห้าปี: ชัยชนะครั้งใหญ่ต่อความเสี่ยงมะเร็งเริ่มขึ้น\n\nที่มา: CDC, Benefits of Quitting Smoking\n\nห้าปีคือจุดเริ่มต้นของช่วงสำคัญที่ความเสี่ยงลดลงอย่างมาก\n\nหลักชัย 5–10 ปี\n• ความเสี่ยงส่วนเกินของมะเร็งช่องปาก คอ และกล่องเสียง: ลดลงครึ่งหนึ่ง\n• ความเสี่ยงโรคหลอดเลือดสมอง: ลดลง\n\nสิ่งที่ยังรออยู่\n• ราว 10 ปี: ความเสี่ยงมะเร็งกระเพาะปัสสาวะ หลอดอาหาร และไตลดลง\n• 10–15 ปี: ความเสี่ยงส่วนเกินของมะเร็งปอดลดลงครึ่งหนึ่ง\n• 15 ปี: ความเสี่ยงโรคหลอดเลือดหัวใจเข้าใกล้ระดับของผู้ที่ไม่สูบบุหรี่\n• 20 ปี: ความเสี่ยงมะเร็งช่องปาก คอ และกล่องเสียงเข้าใกล้ระดับของผู้ที่ไม่สูบบุหรี่ และความเสี่ยงส่วนเกินของมะเร็งปากมดลูกลดลงประมาณครึ่งหนึ่ง\n\nห้าปีที่ไม่สูบบุหรี่คือหลักชัยครั้งใหญ่ — คุณมาถึงช่วงที่การลดความเสี่ยงมะเร็งและโรคหลอดเลือดสมองครั้งสำคัญเริ่มเกิดผล และยังมีชัยชนะใหญ่ ๆ รออยู่ข้างหน้า';

  @override
  String get snriReferenceDay3 =>
      'การหยุด SNRI: ช่วงวันแรก\n\nแหล่งข้อมูล: Harvard Health Publishing\n\nหมายเหตุด้านความปลอดภัย\nควรหยุด SNRI ภายใต้การดูแลของแพทย์และลดขนาดยาอย่างค่อยเป็นค่อยไปเท่านั้น โดยเฉพาะ venlafaxine (Effexor) มีครึ่งชีวิตสั้นมากประมาณ 5 ชั่วโมง ยาจึงออกจากร่างกายเร็วและอาการหยุดยาอาจเกิดขึ้นรุนแรงและฉับพลัน\n\nเหตุใด SNRI จึงอาจหยุดยากกว่า SSRI\nSNRI มีผลต่อสารสื่อประสาทที่เกี่ยวข้องกับอารมณ์สองระบบ คือเซโรโทนินและนอร์อะดรีนาลีน เมื่อหยุดยา ทั้งสองระบบจึงต้องปรับตัวใหม่ อาการหยุดยามักรุนแรงกว่า SSRI:\n• อาการคล้ายไข้หวัด (เหนื่อย เหงื่อออก ปวดกล้ามเนื้อ)\n• นอนไม่หลับและการนอนผิดปกติ\n• คลื่นไส้ — มักเด่นกว่าการหยุด SSRI\n• เสียสมดุลและเวียนศีรษะ\n• ความผิดปกติทางประสาทสัมผัส — อาการ “brain zaps” อาจรุนแรงมากกับ venlafaxine\n• ตื่นตัวมากเกินไป หงุดหงิด และวิตกกังวล\n\nเปรียบเทียบ SNRI\nvenlafaxine มีรูปแบบการหยุดยาที่ยากเป็นพิเศษเพราะครึ่งชีวิตสั้น ส่วน duloxetine (Cymbalta) มักหยุดง่ายกว่าเล็กน้อยเพราะมีครึ่งชีวิตยาวกว่าประมาณ 12 ชั่วโมง และ desvenlafaxine อยู่กึ่งกลางระหว่างสองชนิดนี้';

  @override
  String get snriReferenceDay7 =>
      'หนึ่งสัปดาห์หลังหยุด SNRI: สองระบบกำลังปรับตัว\n\nแหล่งข้อมูล: NHS — การหยุดยาต้านซึมเศร้า (คำแนะนำทั่วไปเกี่ยวกับยาต้านซึมเศร้า; กลไกเกี่ยวกับนอร์อะดรีนาลีนด้านล่างอ้างอิงเภสัชวิทยาทั่วไปของ SNRI ไม่ใช่รายละเอียดเฉพาะ SNRI จากหน้า NHS)\n\nความท้าทายของสองระบบ\nต่างจากยาต้านซึมเศร้าหลายชนิด SNRI มีผลต่อทั้งเซโรโทนินและนอร์อะดรีนาลีน ภายในหนึ่งสัปดาห์ ทั้งสองระบบยังอยู่ระหว่างการปรับตัว\n\nผลของระบบนอร์อะดรีนาลีน\nนอร์อะดรีนาลีนเกี่ยวข้องกับการตอบสนองสู้หรือหนี การควบคุมความดันโลหิต และระดับพลังงาน ระหว่างการปรับตัว:\n• ความดันโลหิตอาจผันผวน\n• ความวิตกกังวลอาจรู้สึกเป็นอาการทางกายมากขึ้น เช่น ใจเต้นเร็วหรือเหงื่อออก\n• ระดับพลังงานอาจไม่สม่ำเสมอ\n\nผลของระบบเซโรโทนิน\nในเวลาเดียวกัน ระบบเซโรโทนินก็กำลังปรับตัวและอาจทำให้เกิดอาการหยุดยาที่พบได้ทั่วไป การที่สองระบบปรับตัวพร้อมกันอาจทำให้สัปดาห์แรกยากเป็นพิเศษ\n\nในด้านร่างกาย มักเห็นความดันโลหิตคงที่ขึ้นและเวียนศีรษะเมื่อลุกยืนน้อยลง ส่วนอารมณ์ยังแปรปรวนมากกว่าช่วง 30 วัน แต่ไม่ร่วงลงอย่างรวดเร็วเหมือนช่วงแรก';

  @override
  String get snriReferenceDay14 =>
      'สองสัปดาห์หลังหยุด SNRI: อาการทางกายลดลง\n\nแหล่งข้อมูล: Davies & Read (2019), Addictive Behaviors\n\nสถานะเมื่อครบสองสัปดาห์\nสำหรับคนส่วนใหญ่ที่ลดขนาดยาอย่างเหมาะสม ระยะอาการทางกายเฉียบพลันจะลดลงมากภายในสองสัปดาห์:\n• อาการ brain zaps ลดลงมากหรือหายไป\n• คลื่นไส้และอาการคล้ายไข้หวัดลดลง\n• เวียนศีรษะและปัญหาการทรงตัวดีขึ้น\n• ความดันโลหิตและอัตราการเต้นหัวใจค่อยๆ คงที่เมื่อระบบนอร์อะดรีนาลีนปรับตัว\n\nอาการที่อาจยังคงอยู่\n• ความไวทางอารมณ์และอารมณ์แปรปรวน\n• ความวิตกกังวล — ซึ่งระบบนอร์อะดรีนาลีนมีอิทธิพลมาก\n• ความเหนื่อยล้า เพราะนอร์อะดรีนาลีนมีบทบาทต่อความตื่นตัวและพลังงาน\n\nบริบทงานวิจัย\nการทบทวนอย่างเป็นระบบของ Davies & Read (2019) ใน Addictive Behaviors ระบุว่าอาการหยุด SNRI อยู่ในกลุ่มที่รุนแรงกว่ายาต้านซึมเศร้าหลายประเภท และ venlafaxine เกี่ยวข้องกับอัตราอาการหยุดยาที่มีนัยสำคัญสูงเป็นพิเศษ';

  @override
  String get snriReferenceDay30 =>
      'หนึ่งเดือนหลังหยุด SNRI: สองระบบเริ่มคงที่\n\nแหล่งข้อมูล: Davies & Read (2019), Addictive Behaviors — การทบทวนอย่างเป็นระบบเรื่องอุบัติการณ์ ความรุนแรง และระยะเวลาของอาการหยุดยาต้านซึมเศร้า\n\nระยะเริ่มคงที่\nหนึ่งเดือนเป็นช่วงสำคัญของการปรับตัวของเซโรโทนินและนอร์อะดรีนาลีน งานทบทวนพบว่าแม้คนส่วนน้อยจำนวนไม่น้อยจะมีอาการนานกว่าสองสามสัปดาห์ แต่คนส่วนใหญ่ผ่านช่วงอาการทางกายที่เฉียบพลันและรุนแรงที่สุดไปแล้ว\n\nสิ่งที่มักดีขึ้นภายในหนึ่งเดือน\n• อาการทางกายจากการหยุดยา เช่น brain zaps คลื่นไส้ และเวียนศีรษะ ลดลงในคนส่วนใหญ่\n• ความดันโลหิตกลับเข้าใกล้ระดับปกติ\n• คุณภาพการนอนดีขึ้นและรูปแบบ REM ค่อยๆ กลับมา\n• ระดับพลังงานเริ่มคงที่เมื่อนอร์อะดรีนาลีนปรับสมดุล\n\nอาการทื่อทางอารมณ์ลดลง\nหลายคนรายงานว่าอาการทื่อทางอารมณ์เริ่มลดลงในช่วงนี้ ผู้ใช้ SNRI บางคนรู้สึกว่าอารมณ์ “แบน” ลง เมื่อยาออกจากร่างกายและสมองปรับตัว ช่วงและความไวของอารมณ์มักกลับมา';

  @override
  String get snriReferenceDay90 =>
      'สามเดือนหลังหยุด SNRI: พ้นช่วงถอนยาตามปกติ\n\nแหล่งที่มา: Fava และคณะ (2018), \"Withdrawal Symptoms after Serotonin-Noradrenaline Reuptake Inhibitor Discontinuation: Systematic Review\", Psychotherapy and Psychosomatics\n\nอาการถอนยา SNRI โดยทั่วไปเป็นอย่างไร\nจากรายงาน 61 ฉบับ — รวมการทดลองแบบสุ่มมีกลุ่มควบคุมและปกปิดสองฝ่าย 22 ฉบับ — พบอาการถอนยาหลังหยุด SNRI ทุกชนิดที่ศึกษา อาการมักเริ่มภายในไม่กี่วันหลังหยุดยาและกินเวลาหลายสัปดาห์ แม้จะค่อย ๆ ลดขนาดยา โดยรายงานต่าง ๆ พบความชุกของอาการถอนยาสูงกว่าสำหรับ venlafaxine\n\nทำไมวันที่ 90 จึงสำคัญ\nเก้าสิบวันเลยช่วงปกติที่กินเวลาหลายสัปดาห์ไปมาก การถึงสามเดือนหมายความว่าช่วงถอนยา SNRI ตามปกติอยู่ข้างหลังแล้ว\n\nบางคนอาจมีอาการนานกว่านี้\nการทบทวนยังพบอาการที่เริ่มช้าหรืออยู่นานกว่า หากยังมีอาการสำคัญอยู่ในเดือนที่สาม ให้ปรึกษาผู้สั่งยาของคุณ';

  @override
  String get snriReferenceDay180 =>
      'หกเดือนหลังหยุด SNRI: การฟื้นตัวของสมองและระบบประสาท\n\nสัญญาณการฟื้นตัวเมื่อครบหกเดือน\nหกเดือนหลังจากลดและหยุดยาเสร็จภายใต้การดูแลของแพทย์ ช่วงอาการหยุด SNRI ที่รุนแรงในระยะแรกอยู่ไกลออกไปแล้ว อารมณ์ การนอน สมรรถภาพทางเพศ และความคิดที่ชัดเจนมีเวลาหลายเดือนในการฟื้นตัว:\n• ระบบเซโรโทนิน: ฟื้นตัวไปมาก\n• ระบบนอร์อะดรีนาลีน: ปรับเข้าสู่ภาวะปกติ และระบบตอบสนองต่อความเครียดคงที่ขึ้น\n• โครงสร้างการนอน: คาดว่าจะฟื้นตัวเต็มที่\n• สมรรถภาพทางเพศ: ฟื้นตัวเป็นส่วนใหญ่ในคนส่วนใหญ่ (ความผิดปกติทางเพศเป็นผลข้างเคียงที่พบได้ของ SNRI แต่บางคนอาจยังมีอาการต่อเนื่องและควรปรึกษาผู้สั่งยา)\n\nความยืดหยุ่นต่อความเครียด\nหลายคนเมื่อครบหกเดือนรายงานว่าสามารถรับมือกับความเครียดประจำวันได้ดีขึ้นอย่างชัดเจน ขณะที่บทบาทของนอร์อะดรีนาลีนต่อความตื่นตัวและการตอบสนองต่อความเครียด — ซึ่ง SNRI มีอิทธิพลอย่างมาก — กลับเข้าใกล้ระดับธรรมชาติ';

  @override
  String get snriReferenceDay365 =>
      'หนึ่งปีหลังหยุด SNRI: การฟื้นตัวที่มั่นคง\n\nหนึ่งปี: การปรับตัวระยะยาวของสองระบบ\nหนึ่งปีหลังจากลดและหยุด SNRI เสร็จ ระบบเซโรโทนินและนอร์อะดรีนาลีนมีเวลายาวนานในการปรับตัวและคงที่\n\nหลักฐานสนับสนุนอะไรจริงเมื่อครบหนึ่งปี\nบททบทวน Therapeutics Letter ระบุว่าอาการหยุดยาที่มีการบันทึกไว้ “มักเริ่มภายในไม่กี่วันหลังหยุดยา” และส่วนใหญ่หายภายในประมาณสองสัปดาห์ ไม่มีการศึกษาควบคุมที่ติดตามคนโดยเฉพาะเมื่อครบหนึ่งปีหลังหยุด SNRI ภาพทางคลินิกในวงกว้างที่ระยะนี้สนับสนุนว่า:\n• คนส่วนใหญ่ที่ลดขนาดยาอย่างเหมาะสมและได้รับการสนับสนุนด้านจิตใจยังคงมีอาการคงที่\n• อาการทื่อทางอารมณ์และความผิดปกติทางเพศที่เกี่ยวข้องกับ SNRI หายไปในคนส่วนใหญ่\n• ความคิดที่ชัดเจน รวมถึงความสามารถในการมีสมาธิ ได้รับการคงไว้ด้วยการทำงานตามธรรมชาติของสมอง\n\nความหมายของหมุดหมายนี้\nการหยุด SNRI สำเร็จ — โดยเฉพาะ venlafaxine — เป็นความสำเร็จที่สำคัญ ความรุนแรงที่อาจเกิดขึ้นระหว่างการหยุดยาและความพยายามในการจัดการภายใต้การดูแลของแพทย์สะท้อนถึงความยืดหยุ่นอย่างมาก';

  @override
  String get socialMediaReferenceDay1 =>
      'ก้าวถอยหลังจากโซเชียลมีเดีย: วันแรก\n\nที่มา: Lambert และคณะ \"การหยุดพักจากโซเชียลมีเดียหนึ่งสัปดาห์ช่วยเพิ่มความเป็นอยู่ที่ดี อาการซึมเศร้า และความวิตกกังวล: การทดลองแบบสุ่มที่มีกลุ่มควบคุม\" จิตวิทยาไซเบอร์ พฤติกรรม และเครือข่ายทางสังคม (2022) บน PubMed\n\nสิ่งที่แสดงหลักฐาน\nในการศึกษาที่มีการควบคุมอย่างเข้มงวดนี้ ผู้คนจะถูกสุ่มให้หยุดพักจาก Facebook, Instagram, Twitter และ TikTok เป็นเวลาหนึ่งสัปดาห์ หรือให้ใช้งานต่อไปตามปกติกลุ่มพักมีการปรับปรุงความเป็นอยู่ที่ดีขึ้นอย่างมีนัยสำคัญ ภาวะซึมเศร้าและความวิตกกังวลลดลงนั่นเป็นหลักฐานจริงที่ควบคุมได้ซึ่งการถอยกลับช่วยได้\n\nสิ่งที่แสดงหลักฐาน\nการใช้โซเชียลมีเดียโดยบีบบังคับมีความเชื่อมโยงอย่างมากกับอารมณ์ที่ลดลงและความวิตกกังวลที่สูงขึ้น และการทดลองแบบสุ่มแสดงให้เห็นว่าการจงใจตัดออกสามารถปรับปรุงความเป็นอยู่ที่ดี ในขณะเดียวกันก็ลดอาการซึมเศร้าและวิตกกังวลภายในหนึ่งสัปดาห์\n\nวันแรก: สิ่งที่คาดหวัง\n• กระวนกระวายใจและอยากตรวจสอบ\n• การแจ้งเตือน \'Phantom\' — รู้สึกถึงกระแสที่ไม่เคยเกิดขึ้น\n• ความเบื่อหน่ายเมื่อคุณปรับตัวเข้ากับสิ่งเร้าที่น้อยลงอย่างต่อเนื่อง\nสิ่งเหล่านี้เป็นความรู้สึกเกี่ยวกับนิสัยตามปกติและเกิดขึ้นชั่วคราวการตระหนักถึงรูปแบบเป็นขั้นตอนแรกในการเปลี่ยนแปลง';

  @override
  String get socialMediaReferenceDay3 =>
      'สามวันโดยไม่มีโซเชียลมีเดีย: ความวิตกกังวลและอารมณ์\n\nที่มา: Lambert และคณะ \"การหยุดพักจากโซเชียลมีเดียหนึ่งสัปดาห์ช่วยเพิ่มความเป็นอยู่ที่ดี อาการซึมเศร้า และความวิตกกังวล: การทดลองแบบสุ่มที่มีกลุ่มควบคุม\" จิตวิทยาไซเบอร์ พฤติกรรม และเครือข่ายทางสังคม (2022) บน PubMed\n\nเหตุใดการหยุดพักจึงช่วยให้อารมณ์ดีขึ้น\nในการทดลองที่มีการควบคุมนี้ ผู้ที่ได้รับการสุ่มให้หยุดพักจากโซเชียลมีเดียเป็นเวลาหนึ่งสัปดาห์ ทำให้สัปดาห์นั้นสิ้นสุดลงด้วยความวิตกกังวลและภาวะซึมเศร้าที่ลดลง และมีความเป็นอยู่ที่ดีขึ้นมากกว่าผู้ที่เลื่อนดูเนื้อหาอย่างต่อเนื่องความทุกข์ยากในแต่ละวันจากการใช้งานหนักๆ ส่วนใหญ่มาจากการเปรียบเทียบทางสังคม — การวัดชีวิตจริงของคุณเทียบกับวงล้อไฮไลท์ที่รวบรวมไว้ของผู้อื่น — และจากการดึงความกลัวที่จะพลาดในระดับต่ำ\n\nเกิดอะไรขึ้นประมาณ 72 ชั่วโมง\nในช่วงต้นของการพัก นิสัยเดิมยังเรียกร้องความสนใจ:\n• มีความต้องการอย่างมากในการตรวจสอบ ซึ่งมักเกิดขึ้นจากช่วงเวลาที่เป็นกิจวัตร (ตื่น รอต่อแถว)\n• หงุดหงิดและกระสับกระส่ายอยู่บ้าง\n• สำหรับบางคน ความวิตกกังวลที่เกิดจากการเปรียบเทียบจะผ่อนคลายลงเป็นครั้งแรก\n• นิสัยการเลื่อนก่อนนอนเริ่มคลายตัว\n\nกับดักการเปรียบเทียบคลายออก\nหากไม่มีฟีดไฮไลต์ของผู้คนอื่น อย่างต่อเนื่อง การเปรียบเทียบที่กระตุ้นให้เกิดความวิตกกังวลเกี่ยวกับโซเชียลมีเดียจะมีแรงส่งน้อยลง ผลการทดลองชี้ให้เห็นว่าภายในสิ้นสัปดาห์แรก การเปลี่ยนแปลงในช่วงแรกๆ เหล่านี้จะทำให้อารมณ์ดีขึ้นอย่างวัดผลได้ ดังนั้นความรู้สึกไม่สบายใน 3 วันจึงเป็นส่วนที่ยากของการเปลี่ยนแปลงที่ได้ผล';

  @override
  String get socialMediaReferenceDay7 =>
      'หนึ่งสัปดาห์ที่ไม่มีโซเชียลมีเดีย: ผลตอบแทนที่วัดได้\n\nที่มา: Lambert และคณะ \"การหยุดพักจากโซเชียลมีเดียหนึ่งสัปดาห์ช่วยเพิ่มความเป็นอยู่ที่ดี อาการซึมเศร้า และความวิตกกังวล: การทดลองแบบสุ่มที่มีกลุ่มควบคุม\" จิตวิทยาไซเบอร์ พฤติกรรม และเครือข่ายทางสังคม (2022) บน PubMed\n\nหนึ่งสัปดาห์พอดี - และได้ผล\nนี่คือหลักชัยสำคัญที่การวิจัยพูดคุยโดยตรงที่สุด: การแทรกแซงของการทดลองคือการหยุดพักหนึ่งสัปดาห์เมื่อเทียบกับผู้ที่ใช้โซเชียลมีเดียอย่างต่อเนื่อง กลุ่มแบ่งมีความเป็นอยู่ที่ดีขึ้นอย่างมีนัยสำคัญ รวมถึงภาวะซึมเศร้าและความวิตกกังวลลดลงอย่างมากหลังจากผ่านไปเพียงเจ็ดวันการเข้าถึงหนึ่งสัปดาห์ก็มาถึงจุดที่การศึกษาแบบมีการควบคุมพบว่ามีประโยชน์อย่างแท้จริง\n\nสิ่งที่คนทั่วไปสังเกตเห็น\nนอกเหนือจากการเพิ่มอารมณ์ที่วัดได้ ผู้คนมักรายงานว่า:\n• มีเวลามากขึ้น — หลายคนแปลกใจว่าพวกเขาใช้ไปมากขนาดไหน\n• มีสมาธิง่ายขึ้น เนื่องจากนิสัยการเปลี่ยนความสนใจอย่างต่อเนื่องคลายตัวลง\n• ช่วงเย็นที่สงบขึ้นและนอนหลับได้ง่ายขึ้นโดยไม่ต้องเลื่อนเตียงก่อนเข้านอน\nผลลัพธ์เหล่านี้สอดคล้องกับการปรับปรุงวัดความเป็นอยู่ที่ดีขึ้นในวงกว้างในการทดลอง\n\nดำเนินต่อไป\nหนึ่งสัปดาห์ถือเป็นเหตุการณ์สำคัญที่แท้จริงและมีหลักฐานสนับสนุนประโยชน์ของอารมณ์ เวลา และความสนใจมีแนวโน้มที่จะลึกซึ้งยิ่งขึ้นตามรูปแบบการรักษาสุขภาพที่ดียิ่งนานขึ้น';

  @override
  String get socialMediaReferenceDay14 =>
      'สองสัปดาห์โดยไม่มีโซเชียลมีเดีย: กำไรสองสัปดาห์\n\nที่มา: Coyne & Woodruff, \"การหยุดพัก: ผลของการมีส่วนร่วมในการดีท็อกซ์ทางดิจิทัลบนโซเชียลมีเดียสองสัปดาห์... ในหมู่คนหนุ่มสาว\" พฤติกรรมศาสตร์ (2023) บน PubMed Central\n\nเกี่ยวกับการศึกษาวิจัยครั้งนี้\nคนหนุ่มสาวจำกัดการใช้โซเชียลมีเดียไว้ที่ประมาณ 30 นาทีต่อวันเป็นเวลาสองสัปดาห์ โดยมีการติดตามการใช้งานบนโทรศัพท์ของพวกเขาอย่างเป็นกลาง (ลดลงประมาณ 78%)ผู้เข้าร่วมลดการใช้โซเชียลมีเดียลงประมาณ 78% ทำให้เหตุการณ์สำคัญนี้เป็นการทดสอบในโลกแห่งความเป็นจริงโดยตรงว่าจะเกิดอะไรขึ้นเมื่อลดการใช้งานลงอย่างมากเป็นเวลาสองสัปดาห์\n\nสิ่งที่ปรับปรุง\nในช่วงสองสัปดาห์ ผู้เข้าร่วมมีการปรับปรุงใน:\n• การนอนหลับ — ทั้งระยะเวลาและคุณภาพ\n• ความพอใจในการใช้ชีวิต\n• ความเครียด\n• การรับรู้เรื่องสุขภาพ\n• คะแนนตามระดับการติดสมาร์ทโฟนและโซเชียลมีเดีย\nผลกำไรที่วัดได้เป็นรูปธรรม: การนอนหลับนานขึ้นและดีขึ้น ความเครียดลดลง ความพึงพอใจในชีวิตที่สูงขึ้นและการรับรู้ความเป็นอยู่ที่ดี และคะแนนการติดสมาร์ทโฟน/โซเชียลมีเดียลดลง\n\nระวังการถอยหลัง\nนักวิจัยยังสังเกตเห็นว่ามีการใช้การคืบคลานกลับไปยังระดับก่อนหน้าในภายหลังสองสัปดาห์ถือเป็นกำไรที่แท้จริง แต่มันเน้นย้ำว่าเหตุใดการวางแผนโดยเจตนา ไม่ใช่แค่การหยุดพักชั่วคราว เท่านั้น จึงเป็นสิ่งที่รักษาผลประโยชน์เอาไว้';

  @override
  String get socialMediaReferenceDay30 =>
      'หนึ่งเดือนที่ไม่มีโซเชียลมีเดีย: การเชื่อมต่อที่แท้จริงลึกซึ้งยิ่งขึ้น\n\nที่มา: Coyne & Woodruff, \"การหยุดพัก: ผลของการมีส่วนร่วมในการดีท็อกซ์ทางดิจิทัลบนโซเชียลมีเดียสองสัปดาห์... ในหมู่คนหนุ่มสาว\" พฤติกรรมศาสตร์ (2023) บน PubMed Central\n\nการเชื่อมต่อสามารถปรับปรุงได้เมื่อคุณก้าวถอยหลัง\nฟังดูขัดแย้งกัน แต่ในการศึกษานี้ การตัดโซเชียลมีเดียออกไปมีความเกี่ยวข้องกับการปรับปรุงความสัมพันธ์ที่สนับสนุน ควบคู่ไปกับความพึงพอใจในชีวิตที่ดีขึ้นและความเครียดที่ลดลงเวลาและความใส่ใจที่เคยไปอยู่กับฟีดจึงกลับมาให้คนที่อยู่ในชีวิตจริงของคุณ\n\nสิ่งที่หนึ่งเดือนมีแนวโน้มที่จะนำมา\nภายใน 30 วัน หลายคนพบว่า:\n• บทสนทนานำเสนอมากขึ้นและถูกขัดจังหวะน้อยลง\n• มีความสนใจในกิจกรรมและงานอดิเรกในโลกแห่งความเป็นจริงมากขึ้น\n• ภาพลักษณ์ของตัวเองโดยอาศัยจำนวนไลค์ ความคิดเห็น และจำนวนผู้ติดตามน้อยลง\n\nสัญญาณของการเปลี่ยนแปลง\nภายในหนึ่งเดือน คุณได้รักษารูปแบบการมีสุขภาพดีขึ้นเป็นสองเท่าของกรอบเวลาการแทรกแซงของการศึกษาการนอนหลับ ความเครียด ความพึงพอใจในชีวิต สุขภาพ และความสัมพันธ์ที่เพิ่มขึ้นที่วัดได้ในช่วงสองสัปดาห์นั้น มีเวลาอีกสองสัปดาห์ในการรวมเข้ากับกิจวัตรประจำวัน\n\nใช้เวลาที่ได้คืนให้คุ้ม\nตั้งเป้าที่จะเติมเต็มเวลาว่างด้วยกิจกรรมที่สร้างการเชื่อมต่อและการเติมเต็มอย่างแท้จริง แทนที่จะแค่สลับหน้าจอหนึ่งไปอีกหน้าจอหนึ่ง';

  @override
  String get socialMediaReferenceDay60 =>
      'สองเดือนโดยไม่มีโซเชียลมีเดีย: หลักฐานสนับสนุนอะไร\n\nที่มา: Ramadhan และคณะ \"ผลกระทบของการดีท็อกซ์โซเชียลมีเดียแบบดิจิทัลต่อสุขภาพจิต: การทบทวนอย่างเป็นระบบและการวิเคราะห์เมตา\" Narra J (2024) บน PubMed Central\n\nภาพรวมที่น่าเชื่อถือที่สุด\nนักวิจัยรวมผลลัพธ์จากการศึกษา 10 เรื่อง รวมถึงการทดลองแบบควบคุม 7 เรื่องผลลัพธ์ที่ชัดเจนที่สุดคืออาการซึมเศร้าลดลงอย่างมีนัยสำคัญ หลังจากที่ผู้คนเลิกใช้โซเชียลมีเดีย\n\nผลลัพธ์ที่แข็งแกร่งที่สุด\nการวิจัยแบบผสมผสานพบว่าอาการซึมเศร้าลดลงอย่างเห็นได้ชัดภายในสองเดือน คุณจะรักษาระดับการเข้าถึงข้อมูลดิจิทัลที่ลดลงแบบเดียวกับที่สร้างประโยชน์ต่อสุขภาพจิต\n\nสองเดือนจะเป็นอย่างไร\nด้วยการเปรียบเทียบรายวันที่น้อยลงและการเสริมแรงที่ขับเคลื่อนด้วยฟีดน้อยลง ภาพลักษณ์ของตัวเองจึงมีเหตุผลน้อยลงมากในการขึ้นอยู่กับจำนวนไลค์ ความคิดเห็น หรือจำนวนผู้ติดตาม ในขณะที่หลักฐานที่รวบรวมได้ชัดเจนที่สุดชี้ไปที่อาการซึมเศร้าที่ลดลง\n\nข้อสรุปเชิงปฏิบัติ\nหลักฐานสนับสนุนการเปลี่ยนแปลงที่ตั้งใจและทำต่อเนื่องใช้จุดสองเดือนเพื่อรักษาขีดจำกัดโดยเจตนาไว้แทนที่จะเลื่อนกลับไป และเพื่อลงทุนในแหล่งความหมายและการเชื่อมโยงแบบออฟไลน์';

  @override
  String get socialMediaReferenceDay90 =>
      'สามเดือนที่ไม่มีโซเชียลมีเดีย: ความปกติใหม่\n\nที่มา: Coyne & Woodruff, \"การหยุดพัก: ผลของการมีส่วนร่วมในการดีท็อกซ์ทางดิจิทัลบนโซเชียลมีเดียสองสัปดาห์... ในหมู่คนหนุ่มสาว\" พฤติกรรมศาสตร์ (2023) บน PubMed Central\n\nการนอนหลับคือความโดดเด่น\nผลการวิจัยที่ชัดเจนที่สุดของการศึกษาครั้งนี้คือการนอนหลับที่ดีขึ้น ทั้งระยะเวลาและคุณภาพ เมื่อผู้เข้าร่วมตัดการใช้โซเชียลมีเดียทันทีเมื่อเวลาผ่านไปสามเดือนของรูปแบบการมีสุขภาพดีอย่างยั่งยืน ม้วนหนังสือตอนดึกที่เคยกินเพื่อการนอนหลับได้หยุดแข่งขันกับการพักผ่อนมานานแล้ว และการนอนหลับที่ดีขึ้นมีแนวโน้มที่จะช่วยยกระดับอารมณ์ สมาธิ และพลังงานไปด้วย\n\nปรับปรุงอะไรอีกบ้าง\nการศึกษาเดียวกันนี้พบว่าความเครียด ความพึงพอใจในชีวิต การรับรู้ด้านสุขภาพ และความสัมพันธ์ที่สนับสนุนเพิ่มขึ้นเมื่อผ่านไปสามเดือน สิ่งเหล่านี้จะไม่ใช่สิ่งแปลกใหม่อีกต่อไป พวกเขามีเวลาปรับตัวเข้าสู่ภาวะปกติใหม่\n\nสัญญาณการฟื้นตัวของกลไก\nการตัดโซเชียลมีเดียทำให้ระยะเวลาการนอนหลับและคุณภาพการนอนหลับดีขึ้นอย่างมากในการศึกษาการแทรกแซงการรักษารูปแบบนั้นไว้เป็นเวลาสามเดือนจะเปลี่ยนการนอนดึกให้กลายเป็นนิสัยการนอนหลับที่ยั่งยืน\n\nการปรากฏตัวและความสัมพันธ์\nด้วยการสะท้อนให้เติมเต็มทุกช่วงเวลาที่เงียบสงบด้วยโทรศัพท์ที่อ่อนแอลงมาก การอยู่ในการสนทนา การรับประทานอาหาร และการหยุดทำงาน — จะเกิดขึ้นอย่างเป็นธรรมชาติมากขึ้น และความสัมพันธ์ที่คุณลงทุนในช่วงสามเดือนมีแนวโน้มที่จะรู้สึกแข็งแกร่งขึ้น';

  @override
  String get socialMediaReferenceDay180 =>
      'หกเดือนที่ลดโซเชียลมีเดียอย่างมาก: สิ่งที่งานวิจัยวัดได้\n\nที่มา: Ramadhan และคณะ \"ผลกระทบของการดีท็อกซ์โซเชียลมีเดียแบบดิจิทัลต่อสุขภาพจิต: การทบทวนอย่างเป็นระบบและการวิเคราะห์เมตา\" Narra J (2024) บน PubMed Central\n\nการวิเคราะห์เมตาเพิ่มอะไร\nเมื่อรวมการศึกษา 10 ชิ้น รวมถึงการทดลองควบคุม 7 ชิ้น นักวิจัยพบว่าอาการซึมเศร้าลดลงอย่างเห็นได้ชัด หลังจากที่ผู้คนลดหรือหยุดโซเชียลมีเดียชั่วคราว\n\nสิ่งที่พบจริง\n• อาการซึมเศร้า: การลดลงที่มีนัยสำคัญทางสถิติ (ผลประโยชน์ที่ชัดเจนและสม่ำเสมอที่สุด)\n• ความพึงพอใจในชีวิต: ไม่มีผลกระทบที่มีนัยสำคัญ\n• ความเครียด: ไม่มีผลกระทบที่มีนัยสำคัญ\n• สุขภาพจิตโดยรวม: ไม่มีผลกระทบที่มีนัยสำคัญ\nผลลัพธ์ที่รวบรวมได้ชัดเจนที่สุด: ดีท็อกซ์แบบดิจิทัลลดอาการซึมเศร้าได้อย่างมาก\n\nเหตุใดคุณจึงยังรู้สึกถึงผลประโยชน์ในวงกว้าง\nหกเดือนของการลดการสัมผัสฟีดจะทำให้เกิดประโยชน์ในทางปฏิบัติที่เห็นได้จากการแทรกแซงที่สั้นลง: มีเวลามากขึ้น การเช็กแบบบังคับตัวเองน้อยลง และการลดการสัมผัสทางดิจิทัลที่เกี่ยวข้องกับอาการซึมเศร้าอย่างยั่งยืน\n\nควบคุมฟีด\nประโยชน์สูงสุดมาจากการทำลายการใช้งานที่หนักหน่วง เฉื่อยชา และบีบบังคับภายในหกเดือน การควบคุมโซเชียลมีเดียโดยเจตนาถือเป็นค่าเริ่มต้นใหม่ แทนที่จะเป็นฟีดที่ควบคุมความสนใจของคุณ';

  @override
  String get socialMediaReferenceDay365 =>
      'หนึ่งปีที่ไม่มีโซเชียลมีเดีย: ความสัมพันธ์ที่ได้รับการเจรจาใหม่\n\nที่มา: Ramadhan และคณะ \"ผลกระทบของการดีท็อกซ์โซเชียลมีเดียแบบดิจิทัลต่อสุขภาพจิต: การทบทวนอย่างเป็นระบบและการวิเคราะห์เมตา\" Narra J (2024) บน PubMed Central\n\nหนึ่งปีแห่งการเปลี่ยนแปลงที่ยั่งยืน\nการวิจัยที่ผสมผสานกันอย่างลงตัวที่สุดแสดงให้เห็นว่าการถอยห่างจากโซเชียลมีเดียสามารถลดอาการซึมเศร้าได้หนึ่งปีเต็มหมายความว่ารูปแบบการรับข้อมูลดิจิทัลที่ลดลงกลายเป็นเรื่องปกติของคุณมากกว่าการพักระยะสั้นๆ\n\nหนึ่งปีสร้างอะไร\nหนึ่งปีเต็มจะทำให้คุณมีเวลาหลายร้อยชั่วโมงสำหรับความสัมพันธ์ที่แท้จริง งานอดิเรก ทักษะ การไตร่ตรอง และความคิดสร้างสรรค์การเช็กอัตโนมัติมีเวลาหนึ่งปีเต็มในการอ่อนแรง ในขณะที่กิจวัตรออฟไลน์เหล่านั้นมีเวลาหนึ่งปีเต็มในการเสริมกำลัง\n\nผลประโยชน์ที่ยั่งยืน\nสุขภาพจิตที่วัดได้ชัดเจนที่สุดคืออาการซึมเศร้าที่ลดลงประโยชน์ที่ได้รับในทางปฏิบัติ ได้แก่ เวลามากขึ้น การหยุดชะงักน้อยลง และการเช็กแบบบังคับตัวเองน้อยลง จะทำให้คุณควบคุมฟีดได้ทุกวัน\n\nอะไรจะเกิดขึ้นต่อไป\nปีแห่งการเปลี่ยนแปลงโดยเจตนาได้รีเซ็ตความสัมพันธ์ไม่ว่าคุณจะกลับไปใช้โดยตั้งใจอย่างจำกัด หรือเลิกใช้งานโดยสิ้นเชิง วงจรบังคับได้ถูกทำลายลง และนั่นคือชัยชนะที่ยั่งยืน';

  @override
  String get ssriReferenceDay3 =>
      'การหยุด SSRI: วันแรก ๆ\n\nที่มา: Harvard Health Publishing\n\nหมายเหตุด้านความปลอดภัยที่สำคัญ\nควรหยุด SSRI ภายใต้การดูแลของแพทย์และค่อย ๆ ลดขนาดยาเท่านั้น การหยุดทันที — โดยเฉพาะหลังใช้มานาน — ทำให้อาการถอนยารุนแรงขึ้นอย่างมาก\n\nกลุ่มอาการหยุด SSRI คืออะไร?\nเป็นภาวะทางการแพทย์ที่มีหลักฐานชัดเจนและอาจเกิดเมื่อหยุด SSRI หรือลดขนาดยามาก แพทย์ใช้ตัวย่อ FINISH เพื่อสรุปอาการที่พบบ่อย:\n• อาการคล้ายไข้หวัด (อ่อนเพลีย เหงื่อออก ปวดกล้ามเนื้อ)\n• นอนไม่หลับและการนอนผิดปกติ\n• คลื่นไส้\n• เสียการทรงตัวและเวียนศีรษะ\n• ความผิดปกติทางประสาทสัมผัส — โดยเฉพาะความรู้สึกคล้ายไฟช็อตในศีรษะ (“brain zaps”)\n• ตื่นตัวมากเกิน หงุดหงิด และวิตกกังวล\n\nครึ่งชีวิตของยามีผล\nฟลูออกซีทีน (Prozac) มีครึ่งชีวิตยาวมาก 4–6 วัน ระดับยาจึงลดลงตามธรรมชาติอย่างช้า ๆ และอาการหยุดยามักเบากว่า พาร็อกซีทีน (Paxil) มีครึ่งชีวิตสั้นที่สุดในกลุ่ม SSRI ที่ใช้ทั่วไปและมักทำให้อาการหยุดรุนแรงกว่า เซอร์ทราลีน ซิตาโลแพรม และเอสซิตาโลแพรมอยู่ระหว่างสองกลุ่มนี้';

  @override
  String get ssriReferenceDay7 =>
      'หนึ่งสัปดาห์หลังหยุด SSRI: ระยะเฉียบพลัน\n\nที่มา: NHS — Stopping or coming off antidepressants\n\nระยะเฉียบพลันของการหยุดยา\nNHS ระบุว่าอาการหยุดยาต้านซึมเศร้าส่วนใหญ่เริ่มภายในห้าวันหลังหยุด และในคนส่วนใหญ่อาจอยู่ได้นานถึงหกสัปดาห์ เมื่อครบหนึ่งสัปดาห์ อาการทางกายเฉียบพลันมักเด่นชัด และในผู้ที่ค่อย ๆ ลดขนาดยามักเริ่มมีแนวโน้มลดลง\n\nสิ่งที่อาจพบในหนึ่งสัปดาห์\n• อาการทางกาย เช่น คลื่นไส้ เวียนศีรษะ และอาการคล้ายไข้หวัด อาจรุนแรงแต่ควรเริ่มทุเลา\n• ปัญหาการนอน เช่น ฝันชัดหรือหลับยาก พบได้บ่อย\n• อารมณ์แปรปรวนและเปลี่ยนเร็วพบได้บ่อยในช่วงนี้\n• Brain zaps อาจยังมีอยู่ แต่โดยทั่วไปความถี่จะเริ่มลดลง\n\nบทบาทของการค่อย ๆ ลดขนาดยา\nNHS แนะนำอย่างยิ่งให้ลดขนาดยาอย่างช้า ๆ — สำหรับผู้ใช้ระยะยาวอาจใช้เวลาหลายเดือน — เพื่อลดอาการหยุดยา Royal College of Psychiatrists ก็แนะนำการลดขนาดยาอย่างค่อยเป็นค่อยไปมาก ๆ และอาจใช้ยารูปแบบน้ำเมื่อเหมาะสมสำหรับผู้ที่ใช้ SSRI มานาน';

  @override
  String get ssriReferenceDay14 =>
      'สองสัปดาห์หลังหยุด SSRI: อาการทางกายลดลง\n\nที่มา: Davies & Read (2019), Addictive Behaviors — “A systematic review into the incidence, severity and duration of antidepressant withdrawal effects”\n\nผลการวิจัย\nการทบทวนอย่างเป็นระบบนี้พบว่าประมาณ 56% ของผู้ที่หยุดยาต้านซึมเศร้ามีอาการถอนยา และ 46% ของกลุ่มนี้บอกว่าอาการรุนแรง สำหรับหลายคนที่ค่อย ๆ ลดขนาดยาอย่างเหมาะสม ระยะเฉียบพลันมักคลี่คลายไปมากภายในสองสัปดาห์:\n• Brain zaps ลดลงมากหรือหายไป\n• คลื่นไส้และอาการคล้ายไข้หวัดลดลง\n• เวียนศีรษะและปัญหาการทรงตัวดีขึ้น\n• การนอนเริ่มกลับเป็นปกติ\n\nแยกอาการหยุดยากับการกำเริบ\nอาการที่เกิดภายในไม่กี่วันหลังหยุดและตรงกับรูปแบบ FINISH มีแนวโน้มเป็นกลุ่มอาการหยุดยา ส่วนอาการที่เกิดหลัง 2–4 สัปดาห์และคล้ายโรคเดิมที่รักษาอยู่ มีแนวโน้มเป็นการกำเริบมากกว่า ควรติดตามความแตกต่างนี้ร่วมกับผู้สั่งยา';

  @override
  String get ssriReferenceDay30 =>
      'หนึ่งเดือนหลังหยุด SSRI: ระยะคงที่\n\nที่มา: Haddad PM (2001), Drug Safety — “Antidepressant Discontinuation Syndromes”\n\nระยะคงที่\nบททบทวนอธิบายว่าอาการหยุดยามักเริ่มเร็ว ภายในไม่กี่วันหลังหยุดหรือลดยาต้านซึมเศร้า และปฏิกิริยาส่วนใหญ่ไม่รุนแรง อยู่ไม่นาน และหายได้โดยไม่ต้องรักษาเฉพาะ หนึ่งเดือนเป็นช่วงเปลี่ยนจากระยะเฉียบพลันสู่ความคงที่ สำหรับหลายคนที่ค่อย ๆ ลดขนาดยาจนครบ อาการเฉียบพลันส่วนใหญ่ลดลงแล้ว\n\nการเปลี่ยนแปลงทางอารมณ์เมื่อครบหนึ่งเดือน\nอารมณ์อาจเปลี่ยนต่างกันในแต่ละคนและควรติดตาม:\n• บางคนรู้สึกอารมณ์ “แบนลง” ชั่วคราวระหว่างที่สมองปรับตัว — โดยทั่วไปจะดีขึ้น\n• บางคนกลับรู้สึกถึงอารมณ์ที่ชัดเจนกว่าที่เคยรู้สึกมาหลายปี\n• ระดับความวิตกกังวลแตกต่างมากตามแต่ละคนและภาวะพื้นฐาน\n\nคุณค่าของการสนับสนุนที่ไม่ใช้ยา\nการบำบัดด้วยการพูดคุย เช่น CBT และการบำบัดทางจิตวิทยาที่มีหลักฐานรองรับอื่น ๆ มีประสิทธิผลต่อหลายภาวะที่ใช้ SSRI รักษา ช่วงหนึ่งเดือนเป็นเวลาที่ดีในการตรวจว่ามีการสนับสนุนที่เหมาะสมแล้ว';

  @override
  String get ssriReferenceDay90 =>
      'สามเดือน: เส้นทางอาการถอนเข้าสู่จุดเปลี่ยน\n\nแหล่งที่มา: Duffy และคณะ, \"Antidepressant medication to prevent depression relapse in primary care: the ANTLER RCT,\" Health Technology Assessment (2021)\n\nวัดที่ 12 สัปดาห์\nANTLER สุ่มผู้ป่วยปฐมภูมิ 478 คนที่ใช้ยาต้านซึมเศร้ามาอย่างน้อย 9 เดือนและรู้สึกดีพอที่จะพิจารณาหยุดยา ผู้เข้าร่วมใช้ citalopram, sertraline, fluoxetine หรือ mirtazapine ความแตกต่างของอาการถอนระหว่างกลุ่มที่หยุดยาและกลุ่มที่ใช้ยาต่อมากที่สุดที่ 12 สัปดาห์ และน้อยลงในการติดตามครั้งหลัง ๆ\n\nทำไมจึงเหมาะเป็นหมุดหมายของ SSRI\nยาที่ศึกษาสามในสี่ชนิด — citalopram, sertraline และ fluoxetine — เป็น SSRI สรุปภาษาง่ายของงานวิจัยระบุว่าอาการถอนที่เพิ่มขึ้นหลังหยุดยาส่วนใหญ่อยู่ในช่วง 3–4 เดือนแรก\n\nสามเดือนอย่างแข็งแกร่ง\nวันที่ 90 อยู่ตรงจุดเปลี่ยนที่วัดได้นี้ หลังจากจุดนี้ความแตกต่างของอาการถอนลดลง ทำให้สามเดือนเป็นหมุดหมายการฟื้นตัวที่เป็นรูปธรรม หากอาการซึมเศร้าหรือวิตกกังวลกลับมารุนแรง ให้ติดต่อผู้สั่งยาตั้งแต่เนิ่น ๆ';

  @override
  String get ssriReferenceDay180 =>
      'หกเดือนหลังหยุดยาต้านซึมเศร้า: 65% ยังคงสบายดี\n\nที่มา: Volkmann และคณะ (2026), European Archives of Psychiatry and Clinical Neuroscience\n\nผลลัพธ์ที่ชัดเจนในหกเดือน\nการศึกษาติดตามผู้ที่โรคซึมเศร้ารุนแรงอยู่ในภาวะสงบขณะหยุดยาต้านซึมเศร้า จากผู้เข้าร่วม 83 คนที่มีข้อมูลผลลัพธ์ครบหกเดือน 54 คน — 65% — ยังคงสบายดี ขณะที่ 29 คนมีอาการกำเริบ\n\nเหตุผลที่หลักหมายนี้สำคัญ\nผลลัพธ์ที่วัดได้จริงในหกเดือนทำให้ช่วงเวลานี้เป็นหลักหมายของความมั่นคงระยะยาว การศึกษายังประเมินอาการถอนยาแยกจากการกำเริบ ช่วยให้แยกสองภาวะนี้ได้ดีขึ้น\n\nหากอาการซึมเศร้ากลับมาอย่างชัดเจน ให้ติดต่อผู้สั่งยาตั้งแต่เนิ่น ๆ';

  @override
  String get ssriReferenceDay365 =>
      'หนึ่งปีหลังใช้ยาต้านซึมเศร้าระยะยาว: ANTLER วัดอะไรจริง ๆ\n\nแหล่งที่มา: Duffy และคณะ (2021), Health Technology Assessment — การทดลอง ANTLER\n\nสิ่งที่การทดลองพบจริง\nANTLER สุ่มผู้ใหญ่ 478 คนในระบบปฐมภูมิของสหราชอาณาจักร ซึ่งมีอาการดีพอที่จะพิจารณาหยุดยาต้านซึมเศร้าที่ใช้ระยะยาว เมื่อครบ 52 สัปดาห์ กลุ่มหยุดยามีการกำเริบ 56% เทียบกับ 39% ในกลุ่มรักษาต่อเนื่อง อัตราอันตรายของการกำเริบตามเวลาสูงขึ้นประมาณสองเท่า (HR 2.06) แต่สัดส่วนการกำเริบที่สังเกตได้ภายในหนึ่งปีคือ 56% เทียบกับ 39% ไม่ใช่สองเท่า\n\nภาพรวมทั้งหมด\nการหยุดยาไม่ใช่ทางตัน: 44% ไม่เกิดการกำเริบตลอดการทดลอง 52 สัปดาห์ อย่างไรก็ตาม ผลเฉลี่ยสนับสนุนการรักษาต่อเนื่องมากกว่า โดยกลุ่มหยุดยามีอาการถอนยามากกว่าและมีปีชีวิตปรับคุณภาพน้อยกว่าในช่วง 12 เดือน ผู้ที่ถูกจัดให้อยู่กลุ่มหยุดยา 39% กลับไปใช้ยาต้านซึมเศร้าตัวเดิม\n\nหมุดหมายหนึ่งปีของคุณ\nหากคุณหยุดยาครบหนึ่งปีและยังรู้สึกดี นั่นคือความสำเร็จครั้งใหญ่ ANTLER ไม่ได้บอกว่าทุกคนควรใช้ยาต่อหรือทุกคนควรหยุด แต่แสดงให้เห็นว่าความเสี่ยงของการกำเริบและการตัดสินใจรักษาควรได้รับการติดตามเป็นรายบุคคล หากจำเป็น การกลับมาใช้ยาอีกครั้งเป็นการตัดสินใจทางคลินิก ไม่ใช่ความล้มเหลว';

  @override
  String get steroidsReferenceDay1 =>
      'หยุดอะนาโบลิกสเตียรอยด์: ช่วงวันแรก\n\nแหล่งที่มา: \"Common symptoms associated with usage and cessation of anabolic androgenic steroids in men,\" Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nระยะเฉียบพลัน\nงานทบทวนนี้อธิบายอาการหลังหยุด AAS ว่ามีสองระยะ ระยะแรกเกิดจากการกระตุ้นระบบประสาทซิมพาเทติกมากกว่าระดับฮอร์โมน มักเริ่มภายใน 1–2 วันหลังหยุด และอาจมี:\n• ปวดศีรษะ\n• มือสั่นหรือสั่น\n• ใจสั่น\n• คลื่นไส้\n\nเหตุใดจึงเกิดอาการ\nอะนาโบลิกสเตียรอยด์ยังกดการสร้างเทสโทสเตอโรนของร่างกาย สมองรับรู้สเตียรอยด์แล้วลดสัญญาณฮอร์โมนที่ปกติกระตุ้นการสร้างเทสโทสเตอโรน การกดนี้ยังคงอยู่ช่วงหนึ่งหลังหยุด และนำไปสู่ระยะที่สองซึ่งยาวนานกว่าและอธิบายในหมุดหมายถัดไป\n\nข้อควรระวัง\nภาวะซึมเศร้าอาจเกิดขึ้นระหว่างหยุดสเตียรอยด์และอาจรุนแรงได้ ควรพบแพทย์ และหากมีความคิดทำร้ายตนเองให้ขอความช่วยเหลือฉุกเฉินทันที แพทย์มักช่วยดูแลการฟื้นตัว และบางกรณีอาจใช้ยาเพื่อช่วยพยุงอาการ.';

  @override
  String get steroidsReferenceDay14 =>
      'สองสัปดาห์หลังหยุดอะนาโบลิกสเตียรอยด์\n\nแหล่งที่มา: \"Common symptoms associated with usage and cessation of anabolic androgenic steroids in men,\" Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nระยะที่ยาวนานขึ้นเริ่มเด่นชัด\nเมื่อผ่านสองสัปดาห์ อาการจากระบบประสาทซิมพาเทติกในช่วงวันแรกมักลดลงแล้ว ระยะที่สองซึ่งเกี่ยวข้องกับภาวะขาดเทสโทสเตอโรนต่อเนื่องจะเด่นขึ้น:\n• เหนื่อยล้าและอารมณ์ตก\n• ปวดกล้ามเนื้อ\n• ความต้องการทางเพศลดลง\n• นอนไม่หลับและอยากกลับไปใช้\n\nฮอร์โมนยังอยู่ในช่วงต่ำ\nการสร้างเทสโทสเตอโรนตามธรรมชาติใช้เวลาฟื้นมากกว่าสองสัปดาห์มาก ดังนั้นช่วงนี้ยังถือว่าอยู่ในกระบวนการที่คาดได้ ไม่ได้หมายความว่ามีสิ่งผิดปกติเสมอไป\n\nกับดักที่พบบ่อย\nผู้ชายบางคนกลับไปใช้สเตียรอยด์เพื่อหลีกเลี่ยงช่วงนี้โดยเฉพาะ ซึ่งทำให้กระบวนการฟื้นตัวเริ่มใหม่แทนที่จะจบลง การช่วยเหลือจากแพทย์หรือที่ปรึกษาสามารถช่วยให้ผ่านช่วงนี้ได้โดยไม่ต้องกลับไปใช้สเตียรอยด์อีก.';

  @override
  String get steroidsReferenceDay30 =>
      'หนึ่งเดือนหลังหยุดอะนาโบลิกสเตียรอยด์\n\nแหล่งที่มา: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" บน PubMed\n\nการฟื้นตัวเริ่มขึ้น\nหลังหยุดใช้ สัญญาณฮอร์โมนที่บอกให้อัณฑะสร้างเทสโทสเตอโรนจะเริ่มกลับมาทำงาน งานวิจัยระบุว่าการฟื้นตัวส่วนใหญ่เกิดในช่วงประมาณสามถึงหกเดือน ดังนั้นเมื่อครบหนึ่งเดือนกระบวนการนี้จึงเริ่มขึ้นแล้ว.\n\nสิ่งที่คาดได้\nอารมณ์ต่ำ ความต้องการทางเพศลดลง และพลังงานต่ำอาจยังคงอยู่ขณะที่ฮอร์โมนค่อย ๆ สูงขึ้น ระยะเวลาฟื้นตัวขึ้นอยู่กับอายุ รวมถึงความหนักและระยะเวลาของการใช้เดิม.';

  @override
  String get steroidsReferenceDay90 =>
      'สามเดือนหลังหยุดอะนาโบลิกสเตียรอยด์\n\nแหล่งที่มา: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" บน PubMed\n\nช่วงที่เหมาะกับการตรวจเลือด\nเมื่อครบสามเดือน ระบบฮอร์โมนมีเวลาพอที่จะแสดงการฟื้นตัวอย่างมีนัยสำคัญ จึงเป็นช่วงที่เหมาะจะถามแพทย์เรื่องตรวจเทสโทสเตอโรนและฮอร์โมนที่ควบคุมการสร้างมัน.\n\nสิ่งที่คาดได้\nในผู้ชายหลายคน ระดับฮอร์โมนเมื่อครบสามเดือนกำลังสูงขึ้นแต่ยังไม่กลับสู่ปกติทั้งหมด อารมณ์และความต้องการทางเพศอาจดีขึ้นก่อนที่เทสโทสเตอโรนจะฟื้นเต็มที่ ขนาดอัณฑะและการสร้างอสุจิฟื้นช้ากว่าและอาจดีขึ้นต่อในปีถัดไป หากมีภาวะเต้านมโตในผู้ชาย มักไม่หายเองหากไม่ได้รับการรักษาเฉพาะ.';

  @override
  String get steroidsReferenceDay180 =>
      'หกเดือนหลังหยุดอะนาโบลิกสเตียรอยด์\n\nแหล่งที่มา: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" บน PubMed\n\nหลักฐานชี้ไปทางไหน\nงานทบทวนรายงานว่า LH และ FSH ซึ่งเป็นฮอร์โมนที่ส่งสัญญาณให้อัณฑะสร้างเทสโทสเตอโรน มักฟื้นตัวภายในประมาณสามถึงหกเดือน เมื่อครบหกเดือน การฟื้นตัวของเทสโทสเตอโรนเองก็มักดำเนินไปมากแล้ว.\n\nหากยังมีอาการอยู่\nถ้าหลังหกเดือนยังมีอาการที่สอดคล้องกับเทสโทสเตอโรนต่ำ แพทย์ต่อมไร้ท่อสามารถตรวจหาสาเหตุและพูดคุยเรื่องการรักษา แทนที่จะปล่อยให้รอต่อไปอย่างเดียว.';

  @override
  String get steroidsReferenceDay365 =>
      'หนึ่งปีโดยไม่ใช้อนาบอลิกสเตียรอยด์\n\nแหล่งที่มา: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\nหนึ่งปีที่ปลอดสเตียรอยด์\nการฟื้นตัวหลัง AAS แตกต่างกันมาก งานทบทวนรายงานว่าเทสโทสเตอโรนฟื้นตัวเกือบสมบูรณ์ในช่วงหลายเดือน โกนาโดโทรปินฟื้นตัวในราวสามถึงหกเดือน และขนาดอัณฑะกับการสร้างอสุจิอาจฟื้นตัวต่อเนื่องหลายเดือนถึงหลายปี ส่วนการฟื้นตัวทางจิตใจคาดการณ์ได้ยากกว่า\n\nหนึ่งปีมีความหมาย\nครบหนึ่งปีโดยไม่ใช้สเตียรอยด์เป็นหมุดหมายใหญ่มาก แต่ไม่ใช่กำหนดเวลาสากลที่ฮอร์โมนของทุกคนต้องกลับเป็นปกติ หากอาการเทสโทสเตอโรนต่ำยังคงอยู่ การประเมินโดยผู้เชี่ยวชาญช่วยดูได้ว่าการฟื้นตัวไปถึงไหนแล้ว';

  @override
  String get steroidsReferenceDay730 =>
      'สองปีโดยไม่ใช้อนาบอลิกสเตียรอยด์\n\nแหล่งที่มา: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\nสองปีที่แข็งแกร่ง\nสองปีโดยไม่ใช้สเตียรอยด์เป็นช่วงเวลายาวนานที่ไม่มีการรับสารซ้ำ การฟื้นตัวขึ้นอยู่กับปัจจัยต่าง ๆ เช่น อายุและระดับการใช้แอนโดรเจนก่อนหน้า และไม่มีเส้นชัยสองปีแบบเดียวกันสำหรับทุกคนที่ฮอร์โมนต้องกลับเป็นปกติ\n\nเส้นทางระยะยาว\nงานทบทวนรายงานว่าเทสโทสเตอโรนฟื้นตัวในช่วงหลายเดือน และโกนาโดโทรปินในราวสามถึงหกเดือน ขณะที่ขนาดอัณฑะและการสร้างอสุจิอาจฟื้นตัวต่อได้เป็นเวลาหลายเดือนถึงหลายปี อาการเทสโทสเตอโรนต่ำที่คงอยู่ควรได้รับการประเมินจากผู้เชี่ยวชาญ ไม่ใช่แก้ด้วยการกลับไปใช้สเตียรอยด์อีกหนึ่งรอบ';

  @override
  String get tcaReferenceDay3 =>
      'การหยุด TCA: วันแรก ๆ — การเด้งกลับของระบบโคลิเนอร์จิก\n\nแหล่งที่มา: Dilsaver, Feinberg & Greden (1983), American Journal of Psychiatry — \'Antidepressant withdrawal symptoms treated with anticholinergic agents\' (รายงานผู้ป่วย 3 ราย)\n\nทำไมการหยุด TCA จึงอาจรู้สึกต่างออกไป\nTCA หลายชนิดมีฤทธิ์ต้านโคลิเนอร์จิกร่วมกับการออกฤทธิ์ต่อเซโรโทนินและนอร์อะดรีนาลีน ในผู้ป่วยที่รายงานไว้ 3 ราย อาการถอนยาหลังหยุดทันทีหรือลดยาอย่างรวดเร็วตอบสนองต่อยาต้านโคลิเนอร์จิก ทำให้ผู้เขียนเสนอว่าภาวะโคลิเนอร์จิกส่วนกลางทำงานมากเกินเป็นหนึ่งในกลไก\n\nอาการถอน TCA ที่มีรายงาน\n• คลื่นไส้ อาเจียน ท้องเสีย ปวดท้อง และเบื่ออาหาร\n• นอนไม่หลับหรือมีปัญหาการนอนอื่น ๆ\n• วิตกกังวล กระสับกระส่าย และหงุดหงิด\n• ปวดศีรษะและอาการทางกายอื่น ๆ\n\nจังหวะเวลาแตกต่างกัน\nอาการถอนยาอาจมาเร็ว โดยเฉพาะหลังหยุดทันทีหรือลดยาอย่างรวดเร็ว รายงานผู้ป่วย 3 รายนี้สนับสนุนการเด้งกลับของระบบโคลิเนอร์จิกว่าเป็นหนึ่งในกลไก งานวิจัยนี้ไม่ได้ออกแบบมาเพื่อกำหนดตารางอาการแบบวันต่อวันหรือเปรียบเทียบ TCA แต่ละชนิดตามความรุนแรงของการเด้งกลับ.';

  @override
  String get tcaReferenceDay7 =>
      'หนึ่งสัปดาห์หลังหยุด TCA: ผ่านช่วงแรกมาแล้ว\n\nหนึ่งสัปดาห์หมายถึงอะไร\nแนวทาง NHS ระบุว่าอาการถอนยาต้านซึมเศร้ามักเริ่มภายในไม่กี่วันและกินเวลาหลายสัปดาห์ บางคนอาจมีอาการรุนแรงหรืออาการนานหลายเดือนหรือมากกว่านั้น\n\nอาการที่ยังอาจเกิดขึ้น\n• ปวดศีรษะและปวดกล้ามเนื้อ\n• คลื่นไส้และเหงื่อออก\n• หัวใจเต้นเร็ว สั่น ตุบแรง หรือเหมือนเต้นข้ามจังหวะ\n• เวียนศีรษะหรือทรงตัวไม่มั่นคง\n• ปัญหาการนอน ฝันแปลก และเหนื่อยล้า\n• กระสับกระส่าย หงุดหงิด วิตกกังวล อารมณ์ต่ำ หรือคิดได้ยาก\n\nเจ็ดวันคือความก้าวหน้า\nหนึ่งสัปดาห์เต็มโดยไม่มี TCA เป็นเรื่องที่ควรฉลอง แนวทาง NHS อธิบายว่าอาการถอนยาอาจกินเวลาหลายวันถึงหลายสัปดาห์ และบางครั้งนานกว่านั้น ดังนั้นอาการที่เกี่ยวกับอัตราการเต้นหัวใจ การย่อยอาหาร การนอน และการทำงานอัตโนมัติอื่น ๆ อาจค่อย ๆ สงบลงในจังหวะที่ต่างกัน.';

  @override
  String get tcaReferenceDay14 =>
      'สองสัปดาห์หลังหยุด TCA: ช่วงถอนยาเฉียบพลันมักเริ่มเบาลง\n\nช่วงเฉียบพลันโดยทั่วไป\nบททบทวนทางคลินิกเกี่ยวกับกลุ่มอาการหยุดยาต้านซึมเศร้าระบุว่าอาการทั่วไป — รวมถึงอาการคล้ายไข้หวัด นอนไม่หลับ คลื่นไส้ เสียสมดุล อาการทางประสาทสัมผัส และภาวะตื่นตัวสูง — มักกินเวลาหนึ่งถึงสองสัปดาห์\n\nวันที่ 14 หมายถึงอะไร\nเมื่อครบสองสัปดาห์ หลายคนกำลังเข้าสู่ปลายช่วงถอนยาเฉียบพลันแบบคลาสสิก อาการระลอกแรกมักเบาลงอย่างชัดเจนในช่วงนี้\n\n14 วันโดยไม่มี TCA\nนี่ทำให้วันที่ 14 เป็นหมุดหมายการฟื้นตัวที่ชัดเจน: คลื่นการถอนยาเฉียบพลันมักเริ่มแตกตัว และช่วงแรกที่หนักที่สุดเริ่มผ่านพ้นไป';

  @override
  String get tcaReferenceDay30 =>
      'หนึ่งเดือนหลังหยุด TCA: อาการถอนยาเฉียบพลันมักสงบลงแล้ว\n\nช่วงเฉียบพลันโดยทั่วไป\nWarner และคณะรายงานว่าอาการหยุดยาต้านซึมเศร้ามักไม่รุนแรงและกินเวลาหนึ่งถึงสองสัปดาห์ โดยมี TCA รวมอยู่ในข้อมูลอย่างชัดเจน และปัญหาการทรงตัวหรือการเคลื่อนไหวอาจเป็นลักษณะที่พบเด่นหลังหยุด TCA\n\nวันที่ 30 หมายถึงอะไร\nเมื่อครบหนึ่งเดือน คนส่วนใหญ่มักพ้นช่วงเฉียบพลันทั่วไปไปมากแล้ว อาการคล้ายไข้หวัด คลื่นไส้ เสียการทรงตัว นอนไม่หลับ ความผิดปกติทางประสาทสัมผัส และภาวะตื่นตัวมากเกินไปมักลดลงมากหรือหายไป\n\nสามสิบวันที่แข็งแกร่ง\nหนึ่งเดือนโดยไม่มี TCA คือหมุดหมายการฟื้นตัวที่ชัดเจน: ช่วงถอนยาเฉียบพลันแบบคลาสสิกมักอยู่ข้างหลังคุณแล้ว';

  @override
  String get tcaReferenceDay90 =>
      'สามเดือนหลังหยุด TCA: ช่วงถอนยาเฉียบพลันผ่านไปนานแล้ว\n\nช่วงเฉียบพลันโดยทั่วไป\nWarner และคณะรายงานว่าอาการหยุดยาต้านซึมเศร้ามักไม่รุนแรงและกินเวลาหนึ่งถึงสองสัปดาห์ โดยมี TCA รวมอยู่ในข้อมูลอย่างชัดเจน และปัญหาการทรงตัวหรือการเคลื่อนไหวอาจเป็นลักษณะที่พบเด่นหลังหยุด TCA\n\nวันที่ 90 หมายถึงอะไร\nเมื่อครบ 90 วัน คุณผ่านพ้นขอบบนของช่วงเฉียบพลันโดยทั่วไปมาแล้วมากกว่าสิบสัปดาห์ หากคุณเคยมีอาการระยะแรกแบบคลาสสิก เช่น อาการคล้ายไข้หวัด คลื่นไส้ เสียการทรงตัว นอนไม่หลับ ความผิดปกติทางประสาทสัมผัส และภาวะตื่นตัวมากเกินไป อาการเหล่านี้มักลดลงมากหรือหายไปนานแล้ว\n\nเก้าสิบวันที่แข็งแกร่ง\nสามเดือนโดยไม่มี TCA คือหมุดหมายการฟื้นตัวที่ชัดเจน: ช่วงถอนยาเฉียบพลันมักผ่านไปนานแล้ว หากอาการซึมเศร้าที่สำคัญกลับมา ให้ติดต่อแพทย์ของคุณตั้งแต่เนิ่น ๆ';

  @override
  String get tcaReferenceDay180 =>
      'หกเดือนหลังหยุดยาต้านซึมเศร้า: คนส่วนใหญ่ยังไม่กลับเป็นซ้ำ\n\nจุดตรวจการกลับเป็นซ้ำที่หกเดือน\nการวิเคราะห์อภิมานปี 2024 รวมการทดลองแบบสุ่ม 35 การทดลองเกี่ยวกับการหยุดยาต้านซึมเศร้าในผู้ที่ได้รับการรักษาโรคซึมเศร้ารุนแรง อัตราการกลับเป็นซ้ำรวมหลังหยุดยาที่หกเดือนอยู่ที่ 34.81% ซึ่งเท่ากับประมาณ 65% ที่ยังไม่กลับเป็นซ้ำ ณ จุดนั้น\n\nผลลัพธ์ระยะยาวที่วัดได้จริง\nการวิเคราะห์เดียวกันพบอัตราการกลับเป็นซ้ำ 45.12% ที่ 12 เดือน หกเดือนจึงเป็นจุดสำคัญของความมั่นคง: ผู้เข้าร่วมส่วนใหญ่ในข้อมูลรวมยังไม่กลับเป็นซ้ำในตอนนั้น\n\nปกป้องความก้าวหน้า\nหากอาการซึมเศร้าเริ่มกลับมา ให้ติดต่อบุคลากรทางการแพทย์ตั้งแต่เนิ่นๆ การมาถึงหกเดือนเป็นช่วงความมั่นคงที่ยิ่งใหญ่และควรรักษาไว้';

  @override
  String get tcaReferenceDay365 =>
      'หนึ่งปีหลังหยุดยาต้านซึมเศร้า: คนส่วนใหญ่ยังไม่กลับเป็นซ้ำ\n\nจุดตรวจที่ 12 เดือน\nการวิเคราะห์อภิมานปี 2024 รวมการทดลองแบบสุ่มเกี่ยวกับการหยุดยาต้านซึมเศร้า 35 การทดลองในผู้ที่รักษาโรคซึมเศร้ารุนแรง อัตราการกลับเป็นซ้ำรวมหลังหยุดยาที่ 12 เดือนคือ 45.12% — เท่ากับว่าประมาณ 55% ยังไม่กลับเป็นซ้ำเมื่อครบหนึ่งปี\n\nหนึ่งปีเต็มแห่งความมั่นคง\nการวิเคราะห์เดียวกันพบอัตราการกลับเป็นซ้ำ 34.81% ที่หกเดือน เมื่อครบ 12 เดือน ผู้เข้าร่วมส่วนใหญ่ในการทดลองที่รวมกันยังไม่กลับเป็นซ้ำ หนึ่งปีเต็มโดยไม่กลับเป็นซ้ำคือหมุดหมายสำคัญของความมั่นคงระยะยาว\n\nรักษาความก้าวหน้าไว้\nหากอาการซึมเศร้าเริ่มกลับมา ให้ติดต่อผู้ดูแลรักษาแต่เนิ่น ๆ การมาถึงหนึ่งปีเต็มเป็นความสำเร็จครั้งสำคัญที่ควรรักษาไว้';

