  @override
  String get vapingDay1Description =>
      'วันแรกที่ไม่สูบบุหรี่ไฟฟ้า หากบุหรี่ไฟฟ้าที่คุณใช้มีนิโคติน อาการอยาก หงุดหงิด กระสับกระส่าย อารมณ์ตก นอนยาก หรือสมาธิไม่ดีอาจเป็นอาการถอนนิโคติน — ไม่ใช่เหตุผลให้เติมนิโคตินกลับเข้าไป ไม่ว่าแบบไหน คุณกำลังตัดวงจรการสูบนี้แล้ว';

  @override
  String get vapingDay3Description =>
      'สามวันปลอดบุหรี่ไฟฟ้า ในการศึกษาทางคลินิกของอดีตผู้สูบบุหรี่ที่ใช้บุหรี่ไฟฟ้าทุกวัน คะแนนอาการถอนเฉลี่ยขึ้นสูงสุดในวันที่ 1 หรือ 2 แล้วลดลงตลอดสี่วันถัดมาของการงด ตอนนี้คุณเลยช่วงพีคระยะแรกที่พบในการศึกษานั้นมาแล้ว ความอยากยังโผล่มาได้ แต่ไม่ได้เป็นคนคุมพวงมาลัย';

  @override
  String get vapingDay7Description =>
      'ครบเจ็ดวันโดยไม่สูดละอองบุหรี่ไฟฟ้า เท่ากับหนึ่งสัปดาห์ที่ไม่มีการรับสารจากการสูบใหม่ ทั้งนิโคติน อนุภาคขนาดเล็กมาก โลหะหนัก สารอินทรีย์ระเหยง่าย และสารอันตรายอื่นที่ละอองอาจมีอยู่ สตรีคสะอาด — ไปต่อ';

  @override
  String vapingLongStreakDescription(int days) {
    return '$days วันโดยไม่สูดละอองบุหรี่ไฟฟ้าอีก เท่ากับ $days วันที่ไม่มีการรับสารอันตรายใหม่จากการสูบที่ละอองอาจมีอยู่ หากบุหรี่ไฟฟ้าที่คุณใช้มีนิโคติน ก็เป็น $days วันที่ไม่ได้เสริมการพึ่งพานั้นด้วย สตรีคใหญ่แล้ว — เดินหน้าต่อ';
  }

  @override
  String get vapingMilestone730Title => '2 ปี: แกร่งโดยไม่สูบ';

  @override
  String get vapingMilestone730Description =>
      'ครบ 2 ปีโดยไม่สูบบุหรี่ไฟฟ้า CDC ระบุว่าการพึ่งพานิโคตินอาจทำให้การเลิกยาก และผลต่อสุขภาพระยะยาวของการสูบบุหรี่ไฟฟ้ายังอยู่ระหว่างการศึกษา สิ่งที่ยืนยันได้คือความต่อเนื่องนี้เอง: 730 วันโดยไม่กลับไปสูบอีก';

  @override
  String get vapingMilestone1095Title => '3 ปี: แรงส่งที่มั่นคง';

  @override
  String get vapingMilestone1095Description =>
      'ครบ 3 ปีโดยไม่สูบบุหรี่ไฟฟ้า คุณรักษาการเปลี่ยนแปลงที่ยากนี้มา 1,095 วัน CDC ไม่ได้กำหนดเกณฑ์การฟื้นตัวทางชีวภาพที่ 3 ปี จึงฉลองสิ่งที่หลักฐานรองรับจริง: การอยู่ห่างจากการสูบอย่างต่อเนื่อง';

  @override
  String get vapingMilestone1460Title => '4 ปี: รากฐานที่แข็งแรง';

  @override
  String get vapingMilestone1460Description =>
      'ครบ 4 ปีโดยไม่สูบบุหรี่ไฟฟ้า นั่นคือ 1,460 วันที่ไม่ได้ตอกย้ำนิสัยการสูบอีก วิทยาศาสตร์ยังไม่มีกรอบเวลาการฟื้นตัวระยะยาวแบบเดียวที่ใช้ได้กับทุกคน แต่การเปลี่ยนแปลงที่ยืนยาวนี้เกิดขึ้นจริงและควรฉลอง';

  @override
  String get vapingMilestone1825Title => '5 ปี: หมุดหมายสำคัญ';

  @override
  String get vapingMilestone1825Description =>
      'ครบ 5 ปีโดยไม่สูบบุหรี่ไฟฟ้า ห้าปีโดยไม่กลับไปสูบเป็นความสำเร็จระยะยาวครั้งใหญ่ หลักฐานของ CDC ไม่ได้กำหนดให้ 5 ปีเป็นเกณฑ์การฟื้นตัวทางการแพทย์ หมุดหมายคือการเปลี่ยนแปลงที่คุณสร้างและรักษาไว้';

  @override
  String get vapingLongTermReference =>
      'การสูบบุหรี่ไฟฟ้า การเลิก และหลักฐานระยะยาว\n\nแหล่งที่มา: CDC — Vaping and Quitting; CDC — Health Effects of Vaping\n\nCDC ระบุว่าผู้ที่สูบบุหรี่ไฟฟ้าอาจพึ่งพานิโคติน การเลิกอาจทำให้เกิดอาการถอนนิโคติน และวิธีที่ดีที่สุดในการช่วยให้คนเลิกยังอยู่ระหว่างการศึกษา ผลต่อสุขภาพระยะยาวของบุหรี่ไฟฟ้าก็ยังอยู่ระหว่างการศึกษาเช่นกัน\n\nแหล่งข้อมูลเหล่านี้ไม่ได้กำหนดเกณฑ์การฟื้นตัวทางชีวภาพที่ 2, 3, 4 หรือ 5 ปีหลังเลิก ดังนั้น Quitter จึงใช้วันเหล่านี้เป็นวันครบรอบของความก้าวหน้าที่ไม่สูบอย่างต่อเนื่อง ไม่ใช่จุดสิ้นสุดทางการแพทย์';

  @override
  String get vapingWithdrawalReference =>
      'การงดบุหรี่ไฟฟ้าและอาการถอน\n\nแหล่งที่มา: Hughes และคณะ, Nicotine & Tobacco Research (2020)\n\nในอดีตผู้สูบบุหรี่ 109 คนที่ใช้บุหรี่ไฟฟ้าทุกวัน การงดที่ยืนยันทางชีวภาพเป็นเวลา 6 วันทำให้อาการถอนนิโคตินและความอยากเพิ่มขึ้น อาการมีรูปแบบขึ้นแล้วลงตามลักษณะการถอน โดยเพิ่มชัดในสองวันแรกของการงด งานวิจัยนี้ยืนยันว่าอาการถอนจากบุหรี่ไฟฟ้ามีจริง แต่ไม่ได้กำหนดนาฬิกาการฟื้นตัวรายวันที่ใช้ได้กับทุกคน';

  @override
  String get vapingHealthReference =>
      'การสูบบุหรี่ไฟฟ้าทำให้รับสารอะไรบ้าง\n\nแหล่งที่มา: CDC — Health Effects of Vaping\n\nCDC ระบุว่าบุหรี่ไฟฟ้าส่วนใหญ่มีนิโคตินที่ทำให้เสพติด ละอองอาจมีนิโคติน สารก่อมะเร็ง โลหะหนัก เช่น นิกเกิล ดีบุก และตะกั่ว อนุภาคเล็กที่เข้าสู่ปอดลึก สารอินทรีย์ระเหยง่าย และสารแต่งกลิ่นบางชนิดที่เป็นอันตราย อาการถอนนิโคตินอาจรวมถึงหงุดหงิด วิตกหรือกระสับกระส่าย อารมณ์ตก ปัญหาการนอนและสมาธิ หิว และอยากนิโคติน โดยอาการจะค่อย ๆ ลดลงตามเวลา ผลระยะยาวของการสูบบุหรี่ไฟฟ้ายังอยู่ระหว่างการศึกษา ดังนั้น Quitter จึงฉลองการงดจริง แทนการยืมไทม์ไลน์ของบุหรี่สำหรับคาร์บอนมอนอกไซด์ ทาร์ มะเร็ง หรือความเสี่ยงหัวใจ';

  @override
  String get adderallMilestone730Title => 'สองปี: การเปลี่ยนแปลงที่ยั่งยืน';

  @override
  String get adderallMilestone730Description =>
      'สองปีโดยไม่ใช้ Adderall ในทางที่ผิดคือการเปลี่ยนแปลงที่ยั่งยืน ไม่ใช่แค่ช่วงสั้น ๆ คุณได้สร้างกิจวัตรและทางเลือกที่ช่วยพาคุณเดินหน้าต่อได้';

  @override
  String get adderallReferenceDay730 =>
      'สองปีโดยไม่ใช้ Adderall ในทางที่ผิด: ความก้าวหน้าที่ยั่งยืน\n\nแหล่งที่มา: SAMHSA, Treatment of Stimulant Use Disorders\n\nคู่มือของ SAMHSA ครอบคลุมสารกระตุ้นกลุ่มแอมเฟตามีน รวมถึงการใช้ยากระตุ้นตามใบสั่งแพทย์ในทางที่ผิด และสนับสนุนการดูแลเพื่อการฟื้นตัวที่อิงหลักฐาน โดยไม่ได้กำหนดว่าเมื่อครบสองปีจะเกิดการ “รีเซ็ต” ทางชีววิทยา\n\nถึงอย่างนั้น สองปีก็ยังเป็นความสำเร็จครั้งใหญ่ คุณรักษาการเปลี่ยนแปลงไว้ได้เป็นเวลานาน จงฉลองความมั่นคงที่สร้างขึ้นและทำสิ่งที่ได้ผลต่อไป';

  @override
  String get adderallMilestone1095Title => 'สามปี: รากฐานที่มั่นคง';

  @override
  String get adderallMilestone1095Description =>
      'สามปีคือความก้าวหน้าระยะยาวที่คุณสร้างขึ้นทีละวัน จงดูแลชีวิต นิสัย และแรงสนับสนุนที่ทำให้สิ่งนี้เกิดขึ้นต่อไป';

  @override
  String get adderallReferenceDay1095 =>
      'สามปีโดยไม่ใช้ Adderall ในทางที่ผิด: การฟื้นตัวที่เดินหน้าต่อ\n\nแหล่งที่มา: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA สนับสนุนการรักษาที่อิงหลักฐานและการฟื้นตัวระยะยาวจากความผิดปกติจากการใช้สารกระตุ้น รวมถึงปัญหาที่เกี่ยวข้องกับยากระตุ้นตามใบสั่งแพทย์ คู่มือไม่ได้อ้างว่าการเปลี่ยนแปลงเฉพาะอย่างในสมองเสร็จสิ้นเมื่อครบสามปี\n\nสามปีสะท้อนการเปลี่ยนแปลงที่ยืนยาวผ่านทั้งวันธรรมดาและวันที่ยาก รักษากิจวัตร ความสัมพันธ์ และแรงสนับสนุนที่พาคุณมาถึงจุดนี้ไว้';

  @override
  String get adderallMilestone1460Title => 'สี่ปี: รากที่หยั่งลึก';

  @override
  String get adderallMilestone1460Description =>
      'สี่ปีแสดงถึงความสม่ำเสมอที่น่าทึ่ง หมุดหมายนี้ฉลองการอยู่ห่างจากการใช้ในทางที่ผิดอย่างต่อเนื่องและความมั่นคงที่คุณสร้างขึ้นรอบตัว';

  @override
  String get adderallReferenceDay1460 =>
      'สี่ปีโดยไม่ใช้ Adderall ในทางที่ผิด: การเปลี่ยนแปลงระยะยาวในชีวิตจริง\n\nแหล่งที่มา: SAMHSA, Treatment of Stimulant Use Disorders\n\nคู่มือของ SAMHSA เน้นการรักษาและการสนับสนุนที่ช่วยให้ผู้คนบรรลุการฟื้นตัวระยะยาว ไม่ได้กำหนดว่าสี่ปีคือเส้นชัยทางการแพทย์ ดังนั้นหมุดหมายนี้จึงฉลองความก้าวหน้าที่ต่อเนื่อง ไม่ใช่คำสัญญาด้านสุขภาพที่แต่งขึ้น\n\nสี่ปีแสดงถึงความสม่ำเสมอในช่วงเวลาที่ยาวนานจริง ๆ จงรักษาโครงสร้างและผู้คนที่ช่วยให้ความก้าวหน้าของคุณมั่นคง';

  @override
  String get adderallMilestone1825Title => 'ห้าปี: ชัยชนะครั้งใหญ่';

  @override
  String get adderallMilestone1825Description =>
      'ห้าปีควรค่าแก่การฉลอง คุณรักษาทิศทางใหม่ไว้ตลอด 1,825 วัน และสะสมประสบการณ์หลายปีที่แสดงว่าการเปลี่ยนแปลงอยู่ได้ยาวนาน';

  @override
  String get adderallReferenceDay1825 =>
      'ห้าปีโดยไม่ใช้ Adderall ในทางที่ผิด: ครึ่งทศวรรษแห่งความก้าวหน้า\n\nแหล่งที่มา: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA ยอมรับว่าการฟื้นตัวระยะยาวเป็นเป้าหมายสำคัญของการดูแลความผิดปกติจากการใช้สารกระตุ้น คู่มือไม่ได้สัญญาว่าจะเกิดเหตุการณ์ทางชีววิทยาพิเศษเมื่อครบห้าปี และหมุดหมายนี้ก็ไม่จำเป็นต้องมีคำสัญญาเช่นนั้นจึงจะมีความหมาย\n\nห้าปีคือ 1,825 วันที่รักษาทิศทางใหม่ไว้ นี่คือประสบการณ์จริงจำนวนมากที่แสดงว่าการเปลี่ยนแปลงของคุณยืนยาวได้ จงฉลองและทำสิ่งที่ทำให้มันเป็นไปได้ต่อไป';

  @override
  String get alcoholMilestone730Title => '2 ปี: ก้าวหน้าอย่างยั่งยืน';

  @override
  String get alcoholMilestone730Description =>
      'สองปีที่ไม่ดื่มแอลกอฮอล์อยู่ในช่วง 1–5 ปีที่ NIAAA ใช้เป็นระยะต่อเนื่องในการวิจัยการฟื้นตัว นี่คือความสำเร็จใหญ่ที่ควรรักษาไว้';

  @override
  String get alcoholReferenceDay730 =>
      'สองปีที่ไม่ดื่มแอลกอฮอล์: ก้าวหน้าอย่างยั่งยืน\n\nแหล่งข้อมูล: NIAAA, Recovery Research Definitions\n\nNIAAA ใช้ช่วง 1–5 ปีเป็นหมวดระยะต่อเนื่องสำหรับการทุเลาของภาวะผิดปกติจากการใช้แอลกอฮอล์และการหยุดดื่มหนักเมื่อรักษาไว้ได้ตามเวลา การไม่ดื่มเลยเข้มกว่าขีดจำกัดการดื่ม แต่การงดเพียงอย่างเดียวไม่ได้ยืนยันเกณฑ์การทุเลาทางคลินิกทั้งหมด\n\nสองปีคือ 730 วันที่รักษาการเปลี่ยนแปลงไว้ได้ จงฉลองความสม่ำเสมอนี้และดูแลกิจวัตร ความสัมพันธ์ และการสนับสนุนที่ช่วยให้มันยืนยาว';

  @override
  String get alcoholMilestone1095Title => '3 ปี: ฐานที่แข็งแรงขึ้น';

  @override
  String get alcoholMilestone1095Description =>
      'สามปีที่ไม่ดื่มแอลกอฮอล์คือการเปลี่ยนแปลงระยะยาว 1,095 วัน NIAAA จัดระยะนี้ไว้ในช่วงต่อเนื่องของงานวิจัยการฟื้นตัว';

  @override
  String get alcoholReferenceDay1095 =>
      'สามปีที่ไม่ดื่มแอลกอฮอล์: ฐานที่แข็งแรงขึ้น\n\nแหล่งข้อมูล: NIAAA, Recovery Research Definitions\n\nNIAAA ใช้ช่วง 1–5 ปีเป็นหมวดระยะต่อเนื่องสำหรับการทุเลาของภาวะผิดปกติจากการใช้แอลกอฮอล์และการหยุดดื่มหนัก ไม่ได้อ้างว่ามีการรีเซ็ตทางชีวภาพพิเศษเมื่อครบสามปี\n\nสามปีคือ 1,095 วันที่เสริมสร้างรูปแบบชีวิตใหม่ ความสม่ำเสมอนี้มีคุณค่าในตัวเอง และการสนับสนุนที่พาคุณมาถึงจุดนี้ก็ควรรักษาไว้';

  @override
  String get alcoholMilestone1460Title => '4 ปี: การเปลี่ยนแปลงที่ยืนยาว';

  @override
  String get alcoholMilestone1460Description =>
      'สี่ปีที่ไม่ดื่มแอลกอฮอล์แสดงถึงการเปลี่ยนแปลงที่รักษาไว้ได้นานจริง ๆ จุดสำคัญคือความยั่งยืน ไม่ใช่เส้นตายทางการแพทย์ที่แต่งขึ้น';

  @override
  String get alcoholReferenceDay1460 =>
      'สี่ปีที่ไม่ดื่มแอลกอฮอล์: การเปลี่ยนแปลงที่ยืนยาว\n\nแหล่งข้อมูล: NIAAA, Recovery Research Definitions\n\nสี่ปียังอยู่ในช่วงต่อเนื่อง 1–5 ปีที่ NIAAA ใช้ในการวิจัย กรอบนี้กล่าวถึงการทุเลาและการหยุดดื่มหนักที่คงอยู่ ไม่ได้บอกว่าร่างกายหรือสมองของทุกคนจะถึงเส้นชัยเดียวกันในวันเดียวกัน\n\nสี่ปีที่ไม่ดื่มแอลกอฮอล์คือการเปลี่ยนแปลงที่ผ่านวันธรรมดา ความเครียด ฤดูกาล และเหตุการณ์สำคัญมาได้ ความยั่งยืนเองคือความสำเร็จ';

  @override
  String get alcoholMilestone1825Title => '5 ปี: หมุดหมายครั้งใหญ่';

  @override
  String get alcoholMilestone1825Description =>
      'ห้าปีที่ไม่ดื่มแอลกอฮอล์ถึงขอบบนของช่วงต่อเนื่อง 1–5 ปีของ NIAAA ส่วนหมวดเสถียรเริ่มเมื่อเกินห้าปีเท่านั้น';

  @override
  String get alcoholReferenceDay1825 =>
      'ห้าปีที่ไม่ดื่มแอลกอฮอล์: หมุดหมายครั้งใหญ่\n\nแหล่งข้อมูล: NIAAA, Recovery Research Definitions\n\nNIAAA เรียกช่วง 1–5 ปีว่าเป็นระยะต่อเนื่อง และใช้คำว่าเสถียรเมื่อเกิน 5 ปี ดังนั้นครบ 5 ปีพอดียังอยู่ที่ปลายสุดของช่วงต่อเนื่อง กรอบนี้ยังรวมการทุเลาของอาการ AUD ด้วย จึงไม่ควรถือว่าการงดดื่มเพียงอย่างเดียวเป็นการวินิจฉัยทางคลินิก\n\nห้าปีที่ไม่ดื่มแอลกอฮอล์คือ 1,825 วันที่รักษาการเปลี่ยนแปลงไว้ได้ ครึ่งทศวรรษสมควรได้รับการยอมรับอย่างแท้จริงโดยไม่ต้องสร้างเส้นชัยทางการแพทย์ที่หลักฐานไม่รองรับ';

  @override
  String get ghbMilestone730Title => '2 ปี: ก้าวหน้าอย่างมั่นคง';

  @override
  String get ghbMilestone730Description =>
      'สองปีที่ไม่มี GHB คือ 730 วันของการเปลี่ยนแปลงที่ต่อเนื่อง SAMHSA อธิบายว่าการฟื้นตัวเป็นกระบวนการต่อเนื่องและเฉพาะบุคคล หมุดหมายนี้จึงเฉลิมฉลองความสม่ำเสมอ ไม่ใช่เส้นชัยทางการแพทย์แบบเดียวสำหรับทุกคน';

  @override
  String get ghbReferenceDay730 =>
      'สองปีที่ไม่มี GHB: ก้าวหน้าอย่างมั่นคง\n\nแหล่งที่มา: SAMHSA การฟื้นตัวและการสนับสนุนการฟื้นตัว\n\nSAMHSA อธิบายการฟื้นตัวว่าเป็นกระบวนการเปลี่ยนแปลงที่ต่อเนื่องและเฉพาะบุคคล และไม่ได้กำหนดจุดสิ้นสุดทางชีววิทยาเฉพาะของ GHB สำหรับวาระเหล่านี้\n\nสองปีคือ 730 วันที่รักษาทิศทางใหม่ไว้ ความสม่ำเสมอ รวมถึงผู้คน กิจวัตร และแรงสนับสนุนที่ช่วยประคองเส้นทางนี้สมควรได้รับการยอมรับ';

  @override
  String get ghbMilestone1095Title => '3 ปี: รากฐานแข็งแรงขึ้น';

  @override
  String get ghbMilestone1095Description =>
      'สามปีที่ไม่มี GHB คือ 1,095 วันของการเปลี่ยนแปลงที่รักษาไว้ การฟื้นตัวแตกต่างกันไปในแต่ละคน หมุดหมายนี้ให้คุณค่ากับความมั่นคงที่สร้างขึ้น ไม่ใช่กำหนดเวลาทางชีววิทยาที่แต่งขึ้น';

  @override
  String get ghbReferenceDay1095 =>
      'สามปีที่ไม่มี GHB: รากฐานแข็งแรงขึ้น\n\nแหล่งที่มา: SAMHSA การฟื้นตัวและการสนับสนุนการฟื้นตัว\n\nSAMHSA อธิบายการฟื้นตัวว่าเป็นกระบวนการเปลี่ยนแปลงที่ต่อเนื่องและเฉพาะบุคคล และไม่ได้กำหนดจุดสิ้นสุดทางชีววิทยาเฉพาะของ GHB สำหรับวาระเหล่านี้\n\nสามปีคือ 1,095 วันที่รักษาการเปลี่ยนแปลงไว้ เป็นหลักฐานสำคัญของความมั่นคงและการดูแลสิ่งที่ช่วยหนุนการฟื้นตัว';

  @override
