  @override
  String get ghbMilestone1460Description =>
      'สี่ปีที่ไม่มี GHB คือ 1,460 วันของการเปลี่ยนแปลงที่ยั่งยืน คุณค่าของความสำเร็จอยู่ที่ความต่อเนื่อง รวมถึงกิจวัตร ความสัมพันธ์ และแรงสนับสนุนที่ช่วยให้เดินหน้าต่อ';

  @override
  String get ghbReferenceDay1460 =>
      'สี่ปีที่ไม่มี GHB: การเปลี่ยนแปลงที่ยั่งยืน\n\nแหล่งที่มา: SAMHSA การฟื้นตัวและการสนับสนุนการฟื้นตัว\n\nSAMHSA อธิบายการฟื้นตัวว่าเป็นกระบวนการเปลี่ยนแปลงที่ต่อเนื่องและเฉพาะบุคคล และไม่ได้กำหนดจุดสิ้นสุดทางชีววิทยาเฉพาะของ GHB สำหรับวาระเหล่านี้\n\nสี่ปีคือ 1,460 วันที่นำการเปลี่ยนแปลงผ่านชีวิตประจำวัน ความยั่งยืนในตัวมันเองคือความสำเร็จที่ควรเฉลิมฉลอง';

  @override
