  @override
  String get ghbReferenceDay1825 =>
      'ห้าปีที่ไม่มี GHB: หมุดหมายสำคัญ\n\nแหล่งที่มา: SAMHSA การฟื้นตัวและการสนับสนุนการฟื้นตัว\n\nSAMHSA อธิบายการฟื้นตัวว่าเป็นกระบวนการเปลี่ยนแปลงที่ต่อเนื่องและเฉพาะบุคคล และไม่ได้กำหนดจุดสิ้นสุดทางชีววิทยาเฉพาะของ GHB สำหรับวาระเหล่านี้\n\nห้าปีคือ 1,825 วันที่รักษาการเปลี่ยนแปลงไว้ ครึ่งทศวรรษของความมุ่งมั่นอย่างต่อเนื่องสมควรได้รับการยอมรับอย่างแท้จริง';

  @override
  String get inhalantsMilestone1095Title => 'สามปี: รากฐานที่มั่นคง';

  @override
