      'สามปีที่ห่างจากสารระเหยคือความก้าวหน้าที่ต่อเนื่อง งานวิจัยสนับสนุนการฟื้นตัวระยะยาว แต่ไม่ได้กำหนดเส้นแบ่งทางชีวภาพเฉพาะที่ปีที่สาม';

  @override
  String get inhalantsMilestone1460Title => 'สี่ปี: ก้าวต่ออย่างมั่นคง';

  @override
  String get inhalantsMilestone1460Description =>
      'สี่ปีเป็นช่วงสำคัญอีกช่วงของการฟื้นตัว หลักฐานสนับสนุนการงดใช้อย่างต่อเนื่อง ไม่ใช่เส้นชัยสากลของการฟื้นตัวของสมองในปีที่สี่';

  @override
  String get inhalantsMilestone1825Title => 'ห้าปี: รากฐานแข็งแรง';

  @override
  String get inhalantsMilestone1825Description =>
      'ห้าปีคือความก้าวหน้าที่ยั่งยืนและควรค่าแก่การฉลอง การงดใช้ระยะยาวอาจสนับสนุนการฟื้นตัว โดยผลลัพธ์ยังขึ้นกับชนิดและความรุนแรงของการบาดเจ็บเดิม';

  @override
  String get inhalantsReferenceDay1095 =>
      'สามปีโดยไม่ใช้สารระเหย\n\nแหล่งที่มา: Cairney และคณะ, «การศึกษาเชิงคาดการณ์การเปลี่ยนแปลงทางประสาทและการรู้คิด 15 ปีหลังการใช้สารระเหยเรื้อรัง», Addiction (2013), PubMed\n\nหลังผ่านสองปี\nการศึกษาพบการฟื้นตัวอย่างมากหลังงดใช้สองปีในผู้เข้าร่วมที่ไม่มีภาวะสมองจากพิษตะกั่ว และติดตามกลุ่มเดิมถึง 15 ปี โดยไม่ได้กำหนดเกณฑ์ทางชีวภาพเฉพาะที่ปีที่สาม\n\nความก้าวหน้าสามปี\nสามปีหมายถึงการงดใช้อย่างต่อเนื่อง การฟื้นตัวระยะยาวอาจดำเนินต่อไป ส่วนผลลัพธ์ขึ้นกับการได้รับสารและการบาดเจ็บเดิม ภาวะสมองจากพิษตะกั่วอาจทิ้งความบกพร่องถาวรได้';

  @override
  String get inhalantsReferenceDay1460 =>
      'สี่ปีโดยไม่ใช้สารระเหย\n\nแหล่งที่มา: Cairney และคณะ, «การศึกษาเชิงคาดการณ์การเปลี่ยนแปลงทางประสาทและการรู้คิด 15 ปีหลังการใช้สารระเหยเรื้อรัง», Addiction (2013), PubMed\n\nการฟื้นตัวระยะยาว\nในกลุ่มที่ไม่มีภาวะสมองจากพิษตะกั่ว คะแนนส่วนใหญ่กลับสู่ช่วงปกติภายในสองปี และมีการประเมินอีกครั้งที่ 15 ปี งานวิจัยไม่ได้กำหนดเหตุการณ์ฟื้นตัวเฉพาะสำหรับปีที่สี่\n\nสี่ปีของระยะห่าง\nสี่ปีเพิ่มการงดใช้อย่างต่อเนื่องอีกหนึ่งปีเต็มและเสริมรากฐานการฟื้นตัว ผลลัพธ์แตกต่างกันได้ โดยเฉพาะเมื่อเคยมีการบาดเจ็บทางระบบประสาทรุนแรง';

  @override
  String get inhalantsReferenceDay1825 =>
      'ห้าปีโดยไม่ใช้สารระเหย\n\nแหล่งที่มา: Cairney และคณะ, «การศึกษาเชิงคาดการณ์การเปลี่ยนแปลงทางประสาทและการรู้คิด 15 ปีหลังการใช้สารระเหยเรื้อรัง», Addiction (2013), PubMed\n\nหมุดหมายระยะยาว\nการศึกษาสนับสนุนความเป็นไปได้ของการฟื้นตัวด้านระบบประสาทและการรู้คิดอย่างมากเมื่อมีการงดใช้ระยะยาวและไม่มีภาวะสมองจากพิษตะกั่ว จุดประเมินอยู่ที่สองและ 15 ปี จึงไม่ได้ถือว่าห้าปีเป็นเส้นชัยทางชีวภาพสากล\n\nห้าปีที่สร้างมา\nห้าปีคือความก้าวหน้าที่ยั่งยืนและเป็นช่วงชีวิตยาวนานที่ห่างจากสารระเหย หลักฐานสนับสนุนการฟื้นตัวระยะยาว พร้อมยอมรับว่าการบาดเจ็บรุนแรงจากตะกั่วอาจคงอยู่';

  @override
  String get maoiMilestone730Title => 'สองปี: เส้นทางมั่นคง';

  @override
  String get maoiMilestone730Description =>
      'สองปีหลังหยุดยา MAOI เป็นช่วงเวลายาวนานของการเปลี่ยนแปลงที่รักษาไว้ได้ งานวิจัยเรื่องการหยุด tranylcypromine อธิบายความเสี่ยงเฉียบพลันจากการหยุดยา แต่ไม่ได้กำหนดว่าสองปีเป็นจุดสิ้นสุดทางชีวภาพพิเศษ หมุดหมายนี้จึงฉลองความสม่ำเสมอ การสนับสนุน และกิจวัตรที่พามาถึงจุดนี้';

  @override
  String get maoiMilestone1095Title => 'สามปี: ความก้าวหน้ายั่งยืน';

  @override
  String get maoiMilestone1095Description =>
      'สามปีหมายถึงอีกหนึ่งปีเต็มที่รักษาทิศทางที่เลือกไว้ งานวิจัยการหยุด MAOI ไม่ได้กำหนดเกณฑ์การฟื้นตัวทางสรีรวิทยาที่สามปี ความสำเร็จคือรูปแบบการตัดสินใจและการสนับสนุนที่คงอยู่ในชีวิตประจำวัน';

  @override
  String get maoiMilestone1460Title => 'สี่ปี: ความต่อเนื่องมั่นคง';

  @override
  String get maoiMilestone1460Description =>
      'สี่ปีคือการทำต่อเนื่องผ่านการเปลี่ยนแปลง ความเครียด และกิจวัตรต่าง ๆ งานวิจัยเกี่ยวกับ MAOI ไม่ได้ระบุเส้นชัยทางการแพทย์สากลที่สี่ปี หมุดหมายนี้ยกย่องความต่อเนื่องที่รักษาไว้ได้';

  @override
  String get maoiMilestone1825Title => 'ห้าปี: การเปลี่ยนแปลงยั่งยืน';

  @override
  String get maoiMilestone1825Description =>
      'ห้าปีเป็นหมุดหมายระยะยาวที่สำคัญ หลักฐานเรื่องการหยุด MAOI เน้นความเสี่ยงจากการหยุดและการหยุดอย่างปลอดภัย ไม่ได้กำหนดวันหายขาดที่ห้าปี ความสำเร็จคือระยะเวลา นิสัย และแรงสนับสนุนที่รักษาไว้ได้';

  @override
  String get maoiReferenceDay730 =>
      'สองปีหลังหยุด MAOI\n\nแหล่งข้อมูล: Gahr และคณะ (2013) การทบทวนอย่างเป็นระบบเกี่ยวกับอาการถอนและการหยุด tranylcypromine\n\nงานทบทวนบันทึกกลุ่มอาการที่อาจรุนแรงหลังหยุดยาอย่างกะทันหัน แต่ไม่ได้กำหนดว่าสองปีเป็นเกณฑ์การฟื้นตัวทางชีวภาพพิเศษ ดังนั้นวันครบรอบนี้หมายถึงการเปลี่ยนแปลง การสนับสนุน และกิจวัตรที่ต่อเนื่อง ไม่ใช่เส้นชัยทางการแพทย์';

  @override
  String get maoiReferenceDay1095 =>
      'สามปีหลังหยุด MAOI\n\nแหล่งข้อมูล: Gahr และคณะ (2013) การทบทวนอย่างเป็นระบบเกี่ยวกับอาการถอนและการหยุด tranylcypromine\n\nงานทบทวนอธิบายอาการถอนและการหยุดยาในระยะเฉียบพลัน แต่ไม่ได้กำหนดจุดฟื้นตัวทางสรีรวิทยาที่สามปี สามปีจึงฉลองอีกหนึ่งปีเต็มที่รักษาทิศทางเดิมและการสนับสนุนที่ช่วยให้ทำได้ต่อเนื่อง';

  @override
  String get maoiReferenceDay1460 =>
      'สี่ปีหลังหยุด MAOI\n\nแหล่งข้อมูล: Gahr และคณะ (2013) การทบทวนอย่างเป็นระบบเกี่ยวกับอาการถอนและการหยุด tranylcypromine\n\nหลักฐานที่เผยแพร่ไม่ได้ระบุจุดสิ้นสุดทางชีวภาพสากลที่สี่ปี หมุดหมายนี้สะท้อนความสม่ำเสมอผ่านการเปลี่ยนแปลง ความเครียด และกิจวัตร โดยไม่สร้างกำหนดเวลาทางคลินิกขึ้นมาเอง';

  @override
  String get maoiReferenceDay1825 =>
      'ห้าปีหลังหยุด MAOI\n\nแหล่งข้อมูล: Gahr และคณะ (2013) การทบทวนอย่างเป็นระบบเกี่ยวกับอาการถอนและการหยุด tranylcypromine\n\nวรรณกรรมกล่าวถึงความเสี่ยงจากการหยุดและวิธีหยุดอย่างปลอดภัย ไม่ได้กำหนดว่าห้าปีเป็นวันหายขาดหรือเส้นชัยทางชีวภาพสากล ถึงอย่างนั้น เวลา นิสัย และแรงสนับสนุนที่รักษาไว้ตลอด 1,825 วันก็เป็นหมุดหมายใหญ่';

  @override
  String get marijuanaMilestone730Title => '2 ปี: รากฐานแข็งแรง';

  @override
  String get marijuanaMilestone730Description =>
      'สองปีโดยไม่ใช้กัญชาเป็นช่วงเวลายาวนานของการเปลี่ยนแปลงที่รักษาไว้ได้ SAMHSA แนะนำการดูแลที่เหมาะกับแต่ละคนและช่วงชีวิต แทนการใช้กรอบเวลาฟื้นตัวแบบเดียวกับทุกคน หมุดหมายนี้ฉลองกิจวัตรและแรงสนับสนุนที่พาคุณมาถึงตรงนี้';

  @override
  String get marijuanaReferenceDay730 =>
      'สองปีโดยไม่ใช้กัญชา\n\nแหล่งที่มา: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nSAMHSA ระบุว่าความผิดปกติจากการใช้กัญชาแตกต่างกันตามบุคคลและช่วงชีวิต จึงแนะนำการดูแลเฉพาะบุคคลที่อิงหลักฐาน และไม่ได้กำหนดเกณฑ์การฟื้นตัวทางชีวภาพร่วมกันที่สองปี\n\nดังนั้นสองปีจึงหมายถึงการเปลี่ยนแปลง กิจวัตร และแรงสนับสนุนที่ต่อเนื่อง ไม่ใช่เส้นชัยทางการแพทย์';

  @override
  String get marijuanaMilestone1095Title => '3 ปี: ก้าวต่ออย่างมั่นคง';

  @override
  String get marijuanaMilestone1095Description =>
      'สามปีสะท้อนแรงส่งที่ต่อเนื่อง ความผิดปกติจากการใช้กัญชาไม่ได้มีเส้นทางเหมือนกันในทุกคน และ SAMHSA ไม่ได้กำหนดจุดสิ้นสุดทางชีวภาพร่วมกันที่สามปี ความสำเร็จคืออีกหนึ่งปีเต็มของการตัดสินใจและแรงสนับสนุนที่มั่นคง';

  @override
  String get marijuanaReferenceDay1095 =>
      'สามปีโดยไม่ใช้กัญชา\n\nแหล่งที่มา: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nแนวทางนี้เน้นว่าความเสี่ยง อาการ และความต้องการการรักษาที่เกี่ยวกับกัญชาแตกต่างกันระหว่างบุคคลและช่วงชีวิต และไม่ได้กำหนดจุดสิ้นสุดทางชีวภาพร่วมกันที่สามปี\n\nสามปีฉลองการตัดสินใจที่ยืนยาวและแรงสนับสนุนที่ช่วยให้การตัดสินใจนั้นคงอยู่';

