  @override
  String get marijuanaReferenceDay1460 =>
      'สี่ปีโดยไม่ใช้กัญชา\n\nแหล่งที่มา: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nSAMHSA แนะนำการดูแลเฉพาะบุคคลที่อิงหลักฐาน เพราะความผิดปกติจากการใช้กัญชาไม่ได้ดำเนินไปแบบเดียวกันในทุกคน แนวทางไม่ได้กำหนดเกณฑ์ฟื้นตัวร่วมกันที่สี่ปี\n\nสี่ปีสะท้อนความต่อเนื่องแม้กิจวัตร ความเครียด และช่วงชีวิตเปลี่ยนไป ความสม่ำเสมอนี้คือหมุดหมาย';

  @override
  String get marijuanaMilestone1825Title => '5 ปี: ความก้าวหน้ายั่งยืน';

  @override
  String get marijuanaMilestone1825Description =>
      'ห้าปีเป็นความสำเร็จระยะยาวครั้งใหญ่ SAMHSA ไม่ได้กำหนดวันหายขาดที่ห้าปีสำหรับความผิดปกติจากการใช้กัญชา หมุดหมายคือครึ่งทศวรรษของทิศทาง กิจวัตรที่ฝึกไว้ และแรงสนับสนุนที่ต่อเนื่อง';

  @override
  String get marijuanaReferenceDay1825 =>
      'ห้าปีโดยไม่ใช้กัญชา\n\nแหล่งที่มา: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nแนวทางของ SAMHSA สนับสนุนการดูแลที่เหมาะกับแต่ละช่วงชีวิต และไม่ได้กำหนดวันหายขาดที่ห้าปีหรือจุดสิ้นสุดทางชีวภาพร่วมกันสำหรับความผิดปกติจากการใช้กัญชา\n\nห้าปีเป็นความสำเร็จระยะยาวครั้งใหญ่: ครึ่งทศวรรษของทิศทาง กิจวัตรที่ฝึกไว้ และแรงสนับสนุนที่ต่อเนื่อง';

  @override
  String get mdmaMilestone730Title => '2 ปี: รากฐานมั่นคง';

  @override
  String get mdmaMilestone730Description =>
      'สองปีที่ไม่ใช้ MDMA สะท้อนการเปลี่ยนแปลงที่ต่อเนื่อง งานทบทวนที่ดีที่สุดในปัจจุบันไม่ได้กำหนดว่าสองปีคือจุดฟื้นตัวทางชีวภาพ จึงควรฉลองความสม่ำเสมอ กิจวัตร และแรงสนับสนุน โดยไม่สร้างเส้นชัยทางการแพทย์ขึ้นมาเอง';

  @override
  String get mdmaReferenceDay730 =>
      'สองปีที่ไม่ใช้ MDMA\n\nแหล่งข้อมูล: Ung และคณะ (2026) การทบทวนอย่างเป็นระบบและอภิมานผลด้านการรู้คิดระยะยาวหลังงด MDMA อย่างต่อเนื่อง\n\nงานทบทวนรวมการศึกษาที่งดอย่างน้อยหกเดือน ประเมินว่าหลักฐานมีคุณภาพต่ำ และไม่พบว่าการงดนานขึ้นทำนายการฟื้นตัวด้านการเรียนรู้หรือความจำได้อย่างน่าเชื่อถือ จึงไม่ได้กำหนดว่าสองปีเป็นจุดฟื้นตัวทางชีวภาพสากล\n\nสองปียังคงเป็นหมุดหมายสำคัญของการเปลี่ยนแปลงที่ต่อเนื่อง ซึ่งเกิดจากการตัดสินใจซ้ำ ๆ ไม่ใช่วันที่ทางการแพทย์กำหนดไว้';

  @override
  String get mdmaMilestone1095Title => '3 ปี: แรงส่งต่อเนื่อง';

  @override
  String get mdmaMilestone1095Description =>
      'สามปีคืออีกหนึ่งปีเต็มของแรงส่งที่ต่อเนื่อง งานวิจัยไม่ได้กำหนดจุดสิ้นสุดด้านการรู้คิดแบบสากลที่สามปี ความสำเร็จคือการรักษาทิศทางไว้ในชีวิตประจำวัน';

  @override
  String get mdmaReferenceDay1095 =>
      'สามปีที่ไม่ใช้ MDMA\n\nแหล่งข้อมูล: Ung และคณะ (2026) การทบทวนอย่างเป็นระบบและอภิมานการงด MDMA อย่างต่อเนื่อง\n\nการศึกษาที่มีอยู่ไม่ได้ระบุว่าที่สามปีผลด้านการรู้คิดจะหายไปในทุกคน งานทบทวนไม่พบความสัมพันธ์ที่น่าเชื่อถือระหว่างการงดนานขึ้นกับการฟื้นตัวด้านการเรียนรู้หรือความจำมากขึ้น และประเมินหลักฐานว่ามีคุณภาพต่ำ\n\nสามปีจึงเป็นการฉลองแรงส่งและความสม่ำเสมอที่ยั่งยืน โดยไม่อ้างเส้นตายทางชีวภาพที่ไม่มีหลักฐานรองรับ';

  @override
  String get mdmaMilestone1460Title => '4 ปี: รากลึกมั่นคง';

  @override
  String get mdmaMilestone1460Description =>
