  @override
  String get mdmaReferenceDay1460 =>
      'สี่ปีที่ไม่ใช้ MDMA\n\nแหล่งข้อมูล: Ung และคณะ (2026) การทบทวนอย่างเป็นระบบและอภิมานการงด MDMA อย่างต่อเนื่อง\n\nงานวิจัยยังมีจำกัดและไม่ได้กำหนดว่าสี่ปีเป็นเกณฑ์ฟื้นตัวสากล ความแตกต่างบางอย่างที่วัดได้อาจยังคงอยู่ และงานทบทวนเตือนว่าหลักฐานพื้นฐานมีคุณภาพต่ำ\n\nสี่ปีเป็นหมุดหมายของการเปลี่ยนแปลงที่หยั่งรากผ่านกิจวัตร ความกดดัน และช่วงชีวิตที่เปลี่ยนไป ความต่อเนื่องนั้นคือความสำเร็จ';

