  @override
  String get mdmaReferenceDay1825 =>
      'ห้าปีที่ไม่ใช้ MDMA\n\nแหล่งข้อมูล: Ung และคณะ (2026) การทบทวนอย่างเป็นระบบและอภิมานการงด MDMA อย่างต่อเนื่อง\n\nหลักฐานปัจจุบันไม่รองรับการมองว่าห้าปีเป็นวันที่หายขาดหรือเส้นชัยด้านการรู้คิดแบบสากล งานทบทวนพบหลักฐานที่จำกัดและคุณภาพต่ำ และไม่พบรูปแบบที่น่าเชื่อถือว่าการงดนานขึ้นทำให้การเรียนรู้หรือความจำฟื้นมากขึ้น\n\nห้าปียังคงเป็นหมุดหมายระยะยาวที่สำคัญ ครึ่งทศวรรษของทิศทางที่รักษาไว้มีคุณค่าในตัวมันเอง';

