  @override
  String get nitrousOxideReferenceDay730 =>
      'สองปี - ความก้าวหน้ายังอยู่\n\nแหล่งข้อมูล: Marsden, Sharma และ Rotella (2022) การทบทวนอย่างเป็นระบบเกี่ยวกับการใช้ไนตรัสออกไซด์เรื้อรัง\n\nการทบทวนพบว่าปัญหาทางระบบประสาทเป็นลักษณะสำคัญของการใช้เรื้อรัง การให้วิตามิน B12 ทดแทนเป็นการรักษาหลัก และการฟื้นตัวบางส่วนเป็นผลลัพธ์ที่รายงานบ่อยที่สุด โดยไม่ได้กำหนดกรอบเวลาการฟื้นตัวหลายปีแบบสากล\n\nสองปีโดยไม่ใช้ไนตรัสออกไซด์คือ 730 วันที่ไม่มีการได้รับสารซ้ำ ผลลัพธ์ทางระบบประสาทแตกต่างกัน และมักมีรายงานการฟื้นตัวบางส่วนหลังหยุดใช้และรักษา ดังนั้นหมุดหมายนี้จึงฉลองการปกป้องที่ต่อเนื่อง ไม่ใช่กำหนดเส้นชัยทางการแพทย์';

  @override
  String get nitrousOxideMilestone1095Title => 'สามปี - รากฐานแน่นขึ้น';

  @override
