  @override
  String get nitrousOxideReferenceDay1460 =>
      'สี่ปี - การเปลี่ยนแปลงยั่งยืน\n\nแหล่งข้อมูล: Marsden, Sharma และ Rotella (2022) การทบทวนอย่างเป็นระบบเกี่ยวกับการใช้ไนตรัสออกไซด์เรื้อรัง\n\nการทบทวนพบว่าปัญหาทางระบบประสาทเป็นลักษณะสำคัญของการใช้เรื้อรัง การให้วิตามิน B12 ทดแทนเป็นการรักษาหลัก และการฟื้นตัวบางส่วนเป็นผลลัพธ์ที่รายงานบ่อยที่สุด โดยไม่ได้กำหนดกรอบเวลาการฟื้นตัวหลายปีแบบสากล\n\nสี่ปีหมายถึงอีกหนึ่งปีเต็มที่ปกป้องความก้าวหน้าที่สร้างไว้ งานศึกษาไนตรัสออกไซด์พบการฟื้นตัวที่แตกต่างกันและบางกรณียังมีความบกพร่องคงอยู่ ไม่ใช่เส้นชัยสากลที่สี่ปี';

