  @override
  String get socialMediaReferenceDay730 =>
      'สองปีที่โซเชียลมีเดียอยู่ในที่ของมัน\n\nแหล่งอ้างอิง: Ramadhan และคณะ, “Impacts of digital social media detox for mental health: A systematic review and meta-analysis”, Narra J (2024), PubMed PMID 39280291\n\nงานอภิมานรวม 10 การศึกษาเกี่ยวกับการลดหรือหยุดใช้สื่อดิจิทัล โดยรวมอาการซึมเศร้าลดลง แต่ผลรวมต่อความพึงพอใจในชีวิต ความเครียด และสุขภาวะทางจิตโดยรวมไม่แตกต่างอย่างมีนัยสำคัญทางสถิติ\n\nงานวิจัยเหล่านี้ไม่ได้กำหนดเกณฑ์สุขภาพที่สองปี วันที่ 730 คือการฉลองสองปีของการเลือกใช้ดิจิทัลอย่างตั้งใจ ไม่ใช่เส้นตายของการรีเซ็ตทางชีวภาพ';

