      'สามปีคือ 1,095 วันที่วางโซเชียลมีเดียไว้ในตำแหน่งที่เหมาะสม กิจวัตร ความสัมพันธ์ และเวลาว่างของคุณมีเวลาหลายปีเติบโตรอบการตัดสินใจที่ตั้งใจ';

  @override
  String get socialMediaReferenceDay1095 =>
      'สามปี: ความสนใจตามเงื่อนไขของคุณ\n\nแหล่งอ้างอิง: Ramadhan และคณะ, “Impacts of digital social media detox for mental health: A systematic review and meta-analysis”, Narra J (2024), PubMed PMID 39280291\n\nงานอภิมานรวม 10 การศึกษาเกี่ยวกับการลดหรือหยุดใช้สื่อดิจิทัล โดยรวมอาการซึมเศร้าลดลง แต่ผลรวมต่อความพึงพอใจในชีวิต ความเครียด และสุขภาวะทางจิตโดยรวมไม่แตกต่างอย่างมีนัยสำคัญทางสถิติ\n\nงานวิจัยไม่ได้กำหนด 1,095 วันเป็นจุดสิ้นสุดด้านสุขภาพจิตหรือระบบประสาท หมุดหมายนี้ฉลองสามปีของนิสัยดิจิทัลที่คุณเลือกอย่างตั้งใจ';

  @override
  String get socialMediaMilestone1460Title => '4 ปี: ตั้งใจจนเป็นธรรมชาติ';

  @override
  String get socialMediaMilestone1460Description =>
      'สี่ปีของการเปลี่ยนแปลงที่ต่อเนื่องไม่ใช่การทดลองอีกต่อไป นิสัยนี้ผ่านทั้งความเปลี่ยนแปลง ความเครียด ความเบื่อ และกิจวัตรใหม่ ๆ มาได้ ความสม่ำเสมอนี้เองคือความสำเร็จ';

  @override
  String get socialMediaReferenceDay1460 =>
      'สี่ปี: ความตั้งใจกลายเป็นค่าเริ่มต้น\n\nแหล่งอ้างอิง: Ramadhan และคณะ, “Impacts of digital social media detox for mental health: A systematic review and meta-analysis”, Narra J (2024), PubMed PMID 39280291\n\nงานอภิมานรวม 10 การศึกษาเกี่ยวกับการลดหรือหยุดใช้สื่อดิจิทัล โดยรวมอาการซึมเศร้าลดลง แต่ผลรวมต่อความพึงพอใจในชีวิต ความเครียด และสุขภาวะทางจิตโดยรวมไม่แตกต่างอย่างมีนัยสำคัญทางสถิติ\n\nบททบทวนไม่ได้ทดสอบผลลัพธ์ที่สี่ปี วันที่ 1,460 จึงเป็นวันครบรอบด้านพฤติกรรม: สี่ปีที่รักษาขอบเขตที่ดีต่อชีวิตประจำวันมากขึ้น';

  @override
  String get socialMediaMilestone1825Title => '5 ปี: ชีวิตนอกฟีด';

  @override
  String get socialMediaMilestone1825Description =>
      'ห้าปีคือครึ่งทศวรรษของชีวิตดิจิทัลที่ตั้งใจ คุณรักษาขอบเขตนี้นานพอจนกลายเป็นส่วนหนึ่งของวิถีชีวิต ไม่ใช่สิ่งที่ยังต้องพิสูจน์';

  @override
  String get socialMediaReferenceDay1825 =>
      'ห้าปี: ชีวิตนอกฟีด\n\nแหล่งอ้างอิง: Ramadhan และคณะ, “Impacts of digital social media detox for mental health: A systematic review and meta-analysis”, Narra J (2024), PubMed PMID 39280291\n\nงานอภิมานรวม 10 การศึกษาเกี่ยวกับการลดหรือหยุดใช้สื่อดิจิทัล โดยรวมอาการซึมเศร้าลดลง แต่ผลรวมต่อความพึงพอใจในชีวิต ความเครียด และสุขภาวะทางจิตโดยรวมไม่แตกต่างอย่างมีนัยสำคัญทางสถิติ\n\nบททบทวนไม่ได้กำหนดผลลัพธ์ที่ห้าปี วันที่ 1,825 คือครึ่งทศวรรษของการเลือกใช้ดิจิทัลอย่างตั้งใจ โดยไม่ต้องสร้างเส้นเวลาการ “รีเซ็ตสมอง” ขึ้นมาเอง';

  @override
  String get ssriMilestone730Title => '2 ปี: ก้าวหน้าอย่างมั่นคง';

  @override
  String get ssriMilestone730Description =>
      'สองปีหลังหยุด SSRI เป็นหมุดหมายส่วนตัวที่สำคัญ ประสบการณ์ถอนยาแตกต่างกันมาก จึงควรฉลองความก้าวหน้าที่รักษาไว้ได้โดยไม่อ้างว่ามีเส้นตายทางชีวภาพเดียวสำหรับการฟื้นตัว';

  @override
  String get ssriReferenceDay730 =>
      'สองปีหลัง SSRI: ก้าวหน้าอย่างมั่นคง\n\nแหล่งข้อมูล: Royal College of Psychiatrists — Stopping antidepressants\n\nคำแนะนำระบุว่าโดยทั่วไปไม่ควรหยุดยาต้านซึมเศร้าทันที และควรปรับการลดขนาดยาให้เหมาะกับแต่ละคน อาการถอนยาแตกต่างกันได้มาก\n\nคำแนะนำไม่ได้กำหนดว่าสองปีคือเกณฑ์การฟื้นตัวทางชีวภาพหลัง SSRI วันที่ 730 คือการฉลองสองปีของความก้าวหน้าที่ต่อเนื่อง';

  @override
  String get ssriMilestone1095Title => '3 ปี: รักษาความก้าวหน้า';

  @override
  String get ssriMilestone1095Description =>
      'สามปีหลังค่อย ๆ ลดและหยุด SSRI เป็นช่วงเวลาที่ยาวนาน หมุดหมายนี้ยกย่องความมั่นคง กิจวัตร และแรงสนับสนุนที่ช่วยรักษาความก้าวหน้า โดยแนวทางทางคลินิกไม่ได้กำหนดเกณฑ์พิเศษในวันนี้';

  @override
  String get ssriReferenceDay1095 =>
      'สามปีหลัง SSRI: รักษาความก้าวหน้า\n\nแหล่งข้อมูล: Royal College of Psychiatrists — Stopping antidepressants\n\nคำแนะนำอธิบายว่าการถอนยามีความแตกต่างระหว่างบุคคล ความเร็วในการลดขนาดยาขึ้นกับปัจจัย เช่น ระยะเวลาที่ใช้ยาและอาการจากการลดครั้งก่อน\n\nสามปีไม่ใช่เส้นตายการฟื้นตัวของ SSRI ที่ใช้กับทุกคน วันที่ 1095 ยกย่องความก้าวหน้าที่รักษาไว้สามปี';

  @override
  String get ssriMilestone1460Title => '4 ปี: พื้นฐานแข็งแรงขึ้น';

  @override
  String get ssriMilestone1460Description =>
      'สี่ปีสะท้อนความก้าวหน้าที่ยั่งยืนซึ่งสร้างขึ้นตามเวลา การถอนยาและการฟื้นตัวแตกต่างกันในแต่ละคน หมุดหมายนี้จึงฉลองความสม่ำเสมอโดยไม่สร้างตารางเวลาทางระบบประสาทแบบตายตัว';

  @override
  String get ssriReferenceDay1460 =>
      'สี่ปีหลัง SSRI: พื้นฐานแข็งแรงขึ้น\n\nแหล่งข้อมูล: Royal College of Psychiatrists — Stopping antidepressants\n\nคำแนะนำเสนอให้ลดขนาดยาอย่างค่อยเป็นค่อยไปและเฉพาะบุคคล เพราะความรุนแรงและระยะเวลาของอาการถอนยาแตกต่างกัน บางคนอาจต้องใช้เวลาหลายเดือนหรือนานกว่า\n\nหลักฐานนี้ไม่ได้ทำให้สี่ปีเป็นจุดสิ้นสุดทางระบบประสาท วันที่ 1460 ฉลองสี่ปีของการเปลี่ยนแปลงที่ยั่งยืน';

  @override
  String get ssriMilestone1825Title => '5 ปี: หมุดหมายสำคัญ';

  @override
  String get ssriMilestone1825Description =>
      'ห้าปีเป็นหมุดหมายส่วนตัวที่สำคัญ เป็นครึ่งทศวรรษของความก้าวหน้าที่ยั่งยืนหลังหยุด SSRI แนวทางทางคลินิกไม่ได้กำหนดเกณฑ์การฟื้นตัวห้าปีที่ใช้กับทุกคน';

  @override
  String get ssriReferenceDay1825 =>
      'ห้าปีหลัง SSRI: หมุดหมายสำคัญ\n\nแหล่งข้อมูล: Royal College of Psychiatrists — Stopping antidepressants\n\nคำแนะนำเน้นการลดขนาดยาอย่างปลอดภัยและเหมาะกับแต่ละคน รวมถึงการตอบสนองต่ออาการ ไม่ได้กำหนดตารางฟื้นตัวเดียวสำหรับทุกคน\n\nไม่มีเกณฑ์การฟื้นตัวห้าปีของ SSRI ที่อ้างอิงหลักฐานในคำแนะนำนี้ วันที่ 1825 ยังคงเป็นวันครบรอบที่สำคัญ';

  @override
  String get steroidsMilestone1095Title => '3 ปี — รากฐานที่มั่นคง';

  @override
  String get steroidsMilestone1095Description =>
      'สามปีโดยไม่ใช้สเตียรอยด์คือความสม่ำเสมอที่ยิ่งใหญ่ การฟื้นตัวหลัง AAS แตกต่างกันในแต่ละคน หมุดหมายนี้จึงฉลองเวลาที่รักษาไว้ได้ ไม่ใช่เส้นชัยทางชีววิทยาที่สมมติขึ้น';

  @override
  String get steroidsReferenceDay1095 =>
      'สามปีหลังหยุดสเตียรอยด์อนาโบลิก\n\nแหล่งที่มา: Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review, Endocrine Connections (2023)\n\nสามปีแห่งระยะห่าง\nการฟื้นตัวหลัง AAS แตกต่างกันมาก งานทบทวนรายงานว่าฮอร์โมนเทสโทสเตอโรนและโกนาโดโทรปินมักฟื้นตัวในช่วงหลายเดือน ส่วนขนาดอัณฑะและการสร้างอสุจิอาจใช้เวลาหลายเดือนถึงหลายปี การฟื้นตัวด้านจิตใจคาดการณ์ได้ยากกว่า\n\nความหมายของหมุดหมายนี้\nงานทบทวนไม่ได้กำหนดว่าสามปีคือจุดสิ้นสุดทางชีววิทยา หมุดหมายนี้บันทึกสามปีโดยไม่มีการสัมผัสซ้ำ อาการด้านฮอร์โมน ภาวะเจริญพันธุ์ อารมณ์ หรือการทำงานทางเพศที่ยังคงอยู่ควรได้รับการประเมินทางการแพทย์';

  @override
  String get steroidsMilestone1460Title => '4 ปี — ก้าวต่ออย่างมั่นคง';

  @override
  String get steroidsMilestone1460Description =>
      'สี่ปีโดยไม่มีรอบใหม่คือความก้าวหน้าที่มั่นคง หลักฐานไม่ได้กำหนดเกณฑ์การฟื้นตัวที่สี่ปี หมุดหมายนี้ฉลองระยะห่างจาก AAS ที่รักษาไว้และความพยายามเบื้องหลัง';

  @override
  String get steroidsReferenceDay1460 =>
      'สี่ปีหลังหยุดสเตียรอยด์อนาโบลิก\n\nแหล่งที่มา: Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review, Endocrine Connections (2023)\n\nสี่ปีแห่งความสม่ำเสมอ\nการฟื้นตัวหลัง AAS ไม่ได้เดินตามนาฬิกาเดียว งานทบทวนอธิบายว่าการฟื้นตัวทางร่างกาย ระบบสืบพันธุ์ จิตใจ และชีวเคมีเกิดขึ้นในช่วงเวลาต่างกัน และบางการเปลี่ยนแปลงอาจใช้เวลาหลายเดือนถึงหลายปี\n\nไม่มีเส้นตายที่แต่งขึ้น\nไม่มีเกณฑ์การฟื้นตัวสี่ปีที่มีหลักฐานรองรับ สี่ปีโดยไม่มีรอบใหม่ยังคงเป็นความสำเร็จที่สำคัญ อาการที่ยังอยู่ควรได้รับการประเมินทางคลินิกตามอาการนั้นเอง';

  @override
  String get steroidsMilestone1825Title => '5 ปี — ความสำเร็จระยะยาว';

  @override
  String get steroidsMilestone1825Description =>
      'ห้าปีโดยไม่ใช้สเตียรอยด์คือความสำเร็จระยะยาวครั้งใหญ่ การฟื้นตัวอาจไม่สม่ำเสมอและบางปัญหาอาจยังอยู่ แต่ห้าปีโดยไม่มีการสัมผัสซ้ำสมควรได้รับการฉลอง';

  @override
  String get steroidsReferenceDay1825 =>
      'ห้าปีหลังหยุดสเตียรอยด์อนาโบลิก\n\nแหล่งที่มา: Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review, Endocrine Connections (2023)\n\nห้าปีคือหมุดหมายใหญ่\nหลักฐานแสดงว่าการฟื้นตัวหลัง AAS แตกต่างกันมาก การเปลี่ยนแปลงของฮอร์โมนหลายอย่างดีขึ้นเร็วกว่านั้นมาก ส่วนผลต่อระบบสืบพันธุ์หรือจิตใจอาจยาวนานและคาดการณ์ได้ยากกว่า\n\nห้าปีโดยไม่มีการสัมผัสซ้ำ\nงานทบทวนไม่ได้กำหนดว่าห้าปีคือจุดสิ้นสุดทางชีววิทยา ห้าปีโดยไม่ใช้สเตียรอยด์ควรได้รับการฉลองจากการเปลี่ยนแปลงที่รักษาไว้ได้เอง และอาการที่ยังคงอยู่ก็ควรได้รับการประเมินทางการแพทย์ต่อไป';
}
